<?php
declare(strict_types=1);

/**
 * Definitions-only native Channel component. The direct CLI remains refused.
 * No App/vendor, credentials, DB/Redis, HTTP child or Channel process is started.
 * All connection state, packets and observer arguments stay in private RAM.
 *
 * observeChannel() must be defined in this same future frozen producer file and
 * return exactly ['native'=>seven proc_get_status fields, 'group'=>the original
 * harness leader_pid/pgid/sid/leader_starttime registration]. This component
 * independently joins real /proc group members, LISTEN inode and owned fd.
 * The complete producer, shared child qualifier and business oracle are pending.
 */
function nhep_expect(bool $value, string $code): void
{
    if (!$value) throw new RuntimeException($code);
}

function nhep_channel_gate(array $qualified, Closure $observeChannel): array
{
    foreach (['nhe_child_qualify', 'nhe_file', 'nhe_keys', 'nhe_tree', 'nhe_includes',
        'nhe_business_self_id', 'audit_app_proc_stat', 'audit_app_group_members'] as $function) {
        nhep_expect(function_exists($function), 'NHE_CHANNEL_COMPLETE_SHARED_QUALIFICATION_REQUIRED');
    }
    nhep_expect(__FILE__ === '/run/nonempty/legacy-history-producer.php' && PHP_SAPI === 'cli'
        && PHP_INT_SIZE >= 8 && is_array($qualified['freeze_pin'] ?? null)
        && is_array($qualified['context'] ?? null) && is_array($qualified['authority'] ?? null),
        'NHE_CHANNEL_REAL_QUALIFIED_PRODUCER_REQUIRED');
    $freeze = json_decode(nhe_file('/run/audit/preparation-source-binding.json', $qualified['freeze_pin']),
        true, 128, JSON_THROW_ON_ERROR);
    $context = $qualified['context']; $authority = $qualified['authority'];
    nhep_expect(($freeze['schema'] ?? null) === 1 && ($freeze['status'] ?? null) === 'CLEAN_SOURCE_FROZEN_ONLY'
        && ($freeze['nonempty_history'] ?? null) === $authority
        && ($authority['legacy_source_sha'] ?? null) === '477732e3e03ed4ba1dbb6b44a94dbba75f7e1978'
        && ($context['source_sha'] ?? null) === ($freeze['source_sha'] ?? null)
        && ($context['source_sha'] ?? null) === getenv('AUDIT_SOURCE_SHA')
        && preg_match('/\A[a-f0-9]{40}\z/D', (string) $context['source_sha']) === 1
        && ($context['run_id'] ?? null) === getenv('AUDIT_RUN_ID')
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', (string) $context['run_id']) === 1
        && ($context['freeze_sha256'] ?? null) === $qualified['freeze_pin']['sha256']
        && is_string($qualified['context_raw'] ?? null), 'NHE_CHANNEL_CURRENT_AND_LEGACY_SOURCE_RUN_JOIN');
    nhe_file('/run/audit/actual-run-context.json', ['path' => '/run/audit/actual-run-context.json',
        'bytes' => strlen($qualified['context_raw']), 'sha256' => hash('sha256', $qualified['context_raw'])]);
    nhep_expect(json_decode($qualified['context_raw'], true, 64, JSON_THROW_ON_ERROR) === $context,
        'NHE_CHANNEL_ORIGINAL_QUALIFIED_CONTEXT');
    $reflection = new ReflectionFunction($observeChannel);
    nhep_expect(!$reflection->isInternal() && $reflection->getFileName() === __FILE__,
        'NHE_CHANNEL_REAL_FROZEN_PRODUCER_OBSERVER');
    $controls = $authority['control_files'] ?? null;
    nhep_expect(is_array($controls) && array_is_list($controls) && $controls !== [], 'NHE_CHANNEL_FULL_CONTROL_ROWS');
    $paths = []; $own = false;
    foreach ($controls as $pin) {
        nhep_expect(is_array($pin) && is_string($pin['path'] ?? null), 'NHE_CHANNEL_CONTROL_DESCRIPTOR');
        nhe_file($pin['path'], $pin); $paths[] = $pin['path']; $own = $own || $pin['path'] === __FILE__;
    }
    $sorted = $paths; sort($sorted, SORT_STRING);
    nhep_expect($own && $paths === $sorted && count(array_unique($paths, SORT_STRING)) === count($paths),
        'NHE_CHANNEL_SELF_IN_COMPLETE_SORTED_FROZEN_CONTROL');
    foreach (['/legacy-source', '/legacy-workspace'] as $root) {
        nhe_tree($root, $authority['legacy_source_files'], $authority['legacy_source_directories']);
    }
    nhe_includes($qualified); $self = nhe_business_self_id($qualified);
    nhep_expect(is_int($self) && $self > 0 && $self <= 4294967295, 'NHE_CHANNEL_REAL_INITIALIZER_SELF_ID');
    return ['run_id' => $context['run_id'], 'self_operated_mer_id' => $self];
}

/** Read-only native ownership proof; never read environ/cmdline or send signals. */
function nhep_channel_observe(Closure $observeChannel, ?array $original = null): array
{
    $observed = $observeChannel();
    nhep_expect(is_array($observed), 'NHE_CHANNEL_NATIVE_OBSERVER_REQUIRED');
    nhe_keys($observed, ['native', 'group'], 'NHE_CHANNEL_OBSERVER_KEYS');
    $native = $observed['native']; $group = $observed['group'];
    nhep_expect(is_array($native) && is_array($group), 'NHE_CHANNEL_NATIVE_NOT_BOOLEAN_ACK');
    nhe_keys($native, ['pid', 'running', 'signaled', 'stopped', 'exitcode', 'termsig', 'stopsig'], 'NHE_CHANNEL_NATIVE_SEVEN_KEYS');
    nhe_keys($group, ['leader_pid', 'pgid', 'sid', 'leader_starttime'], 'NHE_CHANNEL_REGISTERED_GROUP_KEYS');
    nhep_expect(is_int($native['pid']) && $native['pid'] > 1 && $native['running'] === true
        && $native['signaled'] === false && $native['stopped'] === false && $native['exitcode'] === -1
        && $native['termsig'] === 0 && $native['stopsig'] === 0
        && $group['leader_pid'] === $native['pid'] && $group['pgid'] === $native['pid'] && $group['sid'] === $native['pid']
        && is_string($group['leader_starttime']) && ctype_digit($group['leader_starttime']), 'NHE_CHANNEL_LIVE_ORIGINAL_SETSID_CHILD');
    $supervisor = audit_app_proc_stat(getmypid()); $leader = audit_app_proc_stat($native['pid']);
    nhep_expect(is_array($supervisor) && is_array($leader) && $leader['ppid'] === getmypid()
        && $leader['starttime'] === $group['leader_starttime'] && $leader['pgid'] === $group['pgid']
        && $leader['sid'] === $group['sid'] && !in_array($leader['state'], ['Z', 'X', 'x'], true),
        'NHE_CHANNEL_ACTUAL_DIRECT_CHILD_IDENTITY');
    $members = audit_app_group_members($group, $supervisor);
    nhep_expect(count($members) === 2, 'NHE_CHANNEL_ONE_MASTER_AND_ONE_REAL_WORKER');
    foreach ($members as $member) nhep_expect(!in_array($member['state'], ['Z', 'X', 'x'], true), 'NHE_CHANNEL_GROUP_ALL_LIVE');
    if ($original !== null) {
        nhep_expect($original['native'] === $native && $original['group'] === $group, 'NHE_CHANNEL_SAME_NATIVE_CHILD_AND_GROUP');
        $identities = static function (array $rows): array {
            return array_map(static fn(array $row): array => array_intersect_key($row,
                array_flip(['pid', 'ppid', 'pgid', 'sid', 'starttime'])), $rows);
        };
        nhep_expect($identities($members) === $identities($original['members']), 'NHE_CHANNEL_NO_WORKER_RESTART_OR_GROUP_REPLACEMENT');
    }
    $tcp = file_get_contents('/proc/net/tcp'); nhep_expect(is_string($tcp), 'NHE_CHANNEL_NATIVE_TCP_TABLE'); $inodes = [];
    foreach (array_slice(explode("\n", trim($tcp)), 1) as $line) {
        $fields = preg_split('/\s+/', trim($line));
        if (count($fields) >= 10 && $fields[1] === '0100007F:9C43' && $fields[3] === '0A') {
            nhep_expect(ctype_digit($fields[9]) && $fields[9] !== '0', 'NHE_CHANNEL_REAL_LISTENER_INODE'); $inodes[] = $fields[9];
        }
    }
    nhep_expect(count($inodes) === 1, 'NHE_CHANNEL_EXACT_LOOPBACK_40003_LISTENER'); $owners = [];
    foreach ($members as $member) {
        $fds = glob('/proc/' . $member['pid'] . '/fd/*'); nhep_expect(is_array($fds), 'NHE_CHANNEL_OWN_GROUP_FD_NAMESPACE');
        foreach ($fds as $fd) if (readlink($fd) === 'socket:[' . $inodes[0] . ']') {
            $owners[] = ['pid' => $member['pid'], 'starttime' => $member['starttime'], 'fd' => (int) basename($fd)];
        }
    }
    nhep_expect($owners !== [], 'NHE_CHANNEL_LISTENER_IN_REGISTERED_GROUP');
    foreach ($members as $member) {
        $again = audit_app_proc_stat($member['pid']);
        nhep_expect(is_array($again) && $again['starttime'] === $member['starttime']
            && $again['pgid'] === $group['pgid'] && $again['sid'] === $group['sid']
            && !in_array($again['state'], ['Z', 'X', 'x'], true), 'NHE_CHANNEL_GROUP_STABLE_DURING_SOCKET_PROOF');
    }
    if ($original !== null) nhep_expect($original['listener']['inode'] === $inodes[0], 'NHE_CHANNEL_SAME_REAL_LISTENER');
    return ['native' => $native, 'group' => $group, 'members' => $members,
        'listener' => ['address' => '127.0.0.1', 'port' => 40003, 'inode' => $inodes[0], 'owners' => $owners]];
}

/** Only waits for the remainder of one frame; a timeout never reconnects/replays. */
function nhep_channel_wait($socket, bool $write, int $deadline): void
{
    nhep_expect(is_resource($socket) && get_resource_type($socket) === 'stream', 'NHE_CHANNEL_OWN_OPEN_STREAM');
    $left = $deadline - hrtime(true); nhep_expect($left > 0, 'NHE_CHANNEL_FRAME_TIMEOUT');
    $seconds = intdiv($left, 1000000000); $micros = intdiv($left % 1000000000, 1000);
    $reads = $write ? [] : [$socket]; $writes = $write ? [$socket] : []; $except = [];
    nhep_expect(stream_select($reads, $writes, $except, $seconds, $micros) === 1, 'NHE_CHANNEL_FRAME_IO_NOT_READY');
}

function nhep_channel_write($socket, array $packet): void
{
    $type = $packet['type'] ?? null;
    nhep_expect(in_array($type, ['subscribe', 'publish', 'unsubscribe'], true)
        && array_keys($packet) === ($type === 'publish' ? ['type', 'channels', 'data'] : ['type', 'channels'])
        && is_array($packet['channels']) && array_is_list($packet['channels']), 'NHE_CHANNEL_ONLY_NATIVE_READINESS_COMMANDS');
    $private = $packet['channels'][$type === 'subscribe' ? 1 : 0] ?? null;
    nhep_expect(is_string($private) && preg_match('/\Anhe-readiness:([0-9]{14}[a-f0-9]{6}):([a-f0-9]{32})\z/D', $private, $identity) === 1
        && $packet['channels'] === ($type === 'subscribe' ? ['crmeb', $private] : [$private]),
        'NHE_CHANNEL_NO_BUSINESS_PUBLISH_OR_EXTRA_CHANNEL');
    if ($type === 'publish') nhep_expect($packet['data'] === ['scope' => 'nonempty_history_channel_readiness',
        'run_id' => $identity[1], 'nonce' => $identity[2]], 'NHE_CHANNEL_ONLY_RUN_NONCE_NONBUSINESS_PROBE');
    $body = serialize($packet); nhep_expect(strlen($body) <= 1048572, 'NHE_CHANNEL_FINITE_OUTGOING_FRAME');
    $wire = pack('N', strlen($body) + 4) . $body; $offset = 0; $deadline = hrtime(true) + 10000000000;
    while ($offset < strlen($wire)) {
        nhep_channel_wait($socket, true, $deadline); $count = fwrite($socket, substr($wire, $offset));
        nhep_expect(is_int($count) && $count > 0, 'NHE_CHANNEL_PARTIAL_FRAME_WRITE_FAILED'); $offset += $count;
    }
}

function nhep_channel_bytes($socket, int $length, int $deadline): string
{
    $raw = '';
    while (strlen($raw) < $length) {
        nhep_channel_wait($socket, false, $deadline); $part = fread($socket, $length - strlen($raw));
        nhep_expect(is_string($part) && $part !== '', 'NHE_CHANNEL_PARTIAL_FRAME_READ_FAILED'); $raw .= $part;
    }
    return $raw;
}

function nhep_channel_frame($socket, string $channel): array
{
    nhep_expect($channel === 'crmeb' || preg_match('/\Anhe-readiness:[0-9]{14}[a-f0-9]{6}:[a-f0-9]{32}\z/D', $channel) === 1,
        'NHE_CHANNEL_FINITE_RECEIVE_CHANNEL');
    $deadline = hrtime(true) + 10000000000; $head = nhep_channel_bytes($socket, 4, $deadline);
    $size = unpack('Ntotal_length', $head)['total_length'];
    nhep_expect(is_int($size) && $size >= 6 && $size <= 1048576, 'NHE_CHANNEL_NATIVE_FRAME_TOTAL_LENGTH');
    $payload = nhep_channel_bytes($socket, $size - 4, $deadline);
    nhep_expect(str_ends_with($payload, "\n"), 'NHE_CHANNEL_ORIGINAL_SERVER_NEWLINE'); $body = substr($payload, 0, -1);
    $packet = unserialize($body, ['allowed_classes' => false, 'max_depth' => 32]);
    nhep_expect(is_array($packet) && array_keys($packet) === ['channel', 'data'] && $packet['channel'] === $channel,
        'NHE_CHANNEL_EXACT_ORIGINAL_PACKET_AND_ALLOWED_CHANNEL');
    $nodes = 0; $plain = static function (mixed $value, int $depth) use (&$plain, &$nodes): void {
        nhep_expect(++$nodes <= 65536 && $depth <= 32, 'NHE_CHANNEL_FINITE_PLAIN_NATIVE_PAYLOAD');
        if (is_array($value)) { foreach ($value as $item) $plain($item, $depth + 1); return; }
        nhep_expect($value === null || is_string($value) || is_int($value) || is_bool($value)
            || (is_float($value) && is_finite($value)), 'NHE_CHANNEL_NO_OBJECT_OR_RESOURCE_PAYLOAD');
    };
    $plain($packet, 0);
    nhep_expect(serialize($packet) === $body, 'NHE_CHANNEL_COMPLETE_NATIVE_SERIALIZATION_WITHOUT_TRAILING_BYTES');
    return $packet;
}

function nhep_channel_open(array $qualified, Closure $observeChannel): array
{
    $identity = nhep_channel_gate($qualified, $observeChannel); $proof = nhep_channel_observe($observeChannel);
    $socket = stream_socket_client('tcp://127.0.0.1:40003', $errno, $error, 10, STREAM_CLIENT_CONNECT);
    unset($errno, $error);
    try {
        nhep_expect(is_resource($socket) && stream_socket_get_name($socket, true) === '127.0.0.1:40003'
            && stream_set_blocking($socket, false), 'NHE_CHANNEL_ONLY_OWNED_LOOPBACK_SOCKET');
        $nonce = bin2hex(random_bytes(16)); $private = 'nhe-readiness:' . $identity['run_id'] . ':' . $nonce;
        $ready = ['scope' => 'nonempty_history_channel_readiness', 'run_id' => $identity['run_id'], 'nonce' => $nonce];
        nhep_channel_write($socket, ['type' => 'subscribe', 'channels' => ['crmeb', $private]]);
        nhep_channel_write($socket, ['type' => 'publish', 'channels' => [$private], 'data' => $ready]);
        $echo = nhep_channel_frame($socket, $private);
        nhep_expect($echo['data'] === $ready, 'NHE_CHANNEL_SAME_SOCKET_REAL_NONBUSINESS_READINESS_ECHO');
        nhep_channel_write($socket, ['type' => 'unsubscribe', 'channels' => [$private]]);
        $proof = nhep_channel_observe($observeChannel, $proof);
        $local = stream_socket_get_name($socket, false);
        nhep_expect(is_string($local) && preg_match('/\A127\.0\.0\.1:[1-9][0-9]{0,4}\z/D', $local) === 1,
            'NHE_CHANNEL_REAL_LOCAL_SOCKET_ENDPOINT');
        return ['socket' => $socket, 'socket_id' => get_resource_id($socket), 'local_endpoint' => $local,
            'observe' => $observeChannel, 'proof' => $proof,
            'run_id' => $identity['run_id'], 'self_operated_mer_id' => $identity['self_operated_mer_id'],
            'readiness_packet' => $echo, 'closed' => false];
    } catch (Throwable $failure) {
        if (is_resource($socket)) {
            try { fclose($socket); } catch (Throwable $closeFailure) { /* Preserve the original failure. */ }
        }
        throw $failure;
    }
}

/** Return the real crmeb packet privately; only the future oracle may accept it. */
function nhep_channel_read(array &$channel): array
{
    nhep_expect(($channel['closed'] ?? null) === false && ($channel['observe'] ?? null) instanceof Closure
        && is_resource($channel['socket'] ?? null) && get_resource_id($channel['socket']) === ($channel['socket_id'] ?? null)
        && stream_socket_get_name($channel['socket'], false) === ($channel['local_endpoint'] ?? null)
        && stream_socket_get_name($channel['socket'], true) === '127.0.0.1:40003',
        'NHE_CHANNEL_OWN_READY_CONNECTION_REQUIRED');
    $channel['proof'] = nhep_channel_observe($channel['observe'], $channel['proof']);
    $packet = nhep_channel_frame($channel['socket'], 'crmeb');
    $channel['proof'] = nhep_channel_observe($channel['observe'], $channel['proof']);
    return $packet;
}

function nhep_channel_close(array &$channel): void
{
    nhep_expect(($channel['closed'] ?? null) === false && is_resource($channel['socket'] ?? null)
        && get_resource_type($channel['socket']) === 'stream'
        && get_resource_id($channel['socket']) === ($channel['socket_id'] ?? null)
        && stream_socket_get_name($channel['socket'], false) === ($channel['local_endpoint'] ?? null)
        && stream_socket_get_name($channel['socket'], true) === '127.0.0.1:40003', 'NHE_CHANNEL_CLOSE_ONLY_ACTUAL_OWN_SOCKET');
    $socket = $channel['socket']; $failure = null;
    try {
        $channel['proof'] = nhep_channel_observe($channel['observe'], $channel['proof']);
    } catch (Throwable $error) {
        $failure = $error;
        throw $error;
    } finally {
        try {
            nhep_expect(fclose($socket), 'NHE_CHANNEL_NORMAL_SOCKET_CLOSE');
            nhep_expect(!is_resource($socket), 'NHE_CHANNEL_ORIGINAL_SOCKET_CLOSED');
            $channel['socket'] = null; $channel['closed'] = true; unset($channel['readiness_packet']);
        } catch (Throwable $closeFailure) {
            if ($failure === null) { throw $closeFailure; }
        }
    }
}

/** Internal fresh qualification, not a caller-supplied acknowledgement. */
function nhep_parent_qualified(array $qualified): array
{
    foreach (['nhe_qualify', 'nhe_file', 'nhe_json', 'nhe_parent_process', 'nhe_includes', 'audit_app_proc_stat'] as $function)
        nhep_expect(function_exists($function), 'NHE_PARENT_COMPLETE_SHARED_QUALIFICATION_REQUIRED');
    nhep_expect(PHP_SAPI === 'cli' && PHP_INT_SIZE >= 8 && PHP_VERSION_ID >= 80200 && PHP_VERSION_ID < 80300
        && __FILE__ === '/run/nonempty/legacy-history-producer.php' && realpath(__FILE__) === __FILE__
        && realpath($_SERVER['SCRIPT_FILENAME'] ?? '') === __FILE__ && getcwd() === '/legacy-workspace/crmeb'
        && is_array($qualified['freeze_pin'] ?? null) && is_array($qualified['process'] ?? null),
        'NHE_REAL_QUALIFIED_DIRECT_PRODUCER_PARENT');
    $actual = nhe_qualify($qualified['freeze_pin'], 'audit-legacy-history-producer');
    foreach (['freeze_pin', 'authority', 'context', 'manifest_raw', 'context_raw', 'created_raw', 'binding_raw',
        'container_id', 'source_stats', 'input_stats'] as $key) {
        nhep_expect(array_key_exists($key, $qualified) && $actual[$key] === $qualified[$key],
            'NHE_PARENT_COMPLETE_ORIGINAL_PROVENANCE_JOIN');
    }
    foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
        nhep_expect(($qualified['process'][$key] ?? null) === $actual['process'][$key], 'NHE_ORIGINAL_PARENT_PROCESS_UNCHANGED');
    nhep_expect($actual['process']['pid'] === getmypid(), 'NHE_ONLY_THIS_ACTUAL_PRODUCER_PARENT');
    $controls = array_column($actual['authority']['control_files'], null, 'path');
    nhep_expect(isset($controls[__FILE__]), 'NHE_PARENT_SELF_IN_ACTUAL_COMPLETE_CONTROL');
    nhe_file(__FILE__, $controls[__FILE__]); nhe_includes($actual);
    return $actual;
}

/** Create the one private native-parent receipt; retain any partial failure. */
function nhep_parent_write(array $qualified): array
{
    $actual = nhep_parent_qualified($qualified); $root = '/legacy-runtime'; $path = $root . '/native-parent.json';
    clearstatcache(true, $root); $directory = @lstat($root);
    nhep_expect(is_array($directory) && is_dir($root) && !is_link($root) && realpath($root) === $root
        && ($directory['mode'] & 07777) === 0700 && $directory['uid'] === posix_geteuid()
        && !file_exists($path) && !is_link($path), 'NHE_PARENT_NEW_RECEIPT_IN_EXISTING_PRIVATE_TMPFS');
    $receipt = ['schema' => 1, 'run_id' => $actual['context']['run_id'], 'source_sha' => $actual['context']['source_sha'],
        'freeze_sha256' => $actual['freeze_pin']['sha256'], 'container_id' => $actual['container_id'],
        'pid' => getmypid(), 'starttime' => $actual['process']['starttime']];
    $raw = nhe_json($receipt); $oldMask = umask(0077);
    try { $stream = @fopen($path, 'xb'); } finally { umask($oldMask); }
    nhep_expect(is_resource($stream), 'NHE_PARENT_CREATE_ONLY_PRIVATE_RECEIPT');
    $failure = null;
    try {
        $opened = fstat($stream); clearstatcache(true, $path); $named = lstat($path);
        nhep_expect(is_array($opened) && is_array($named) && !is_link($path) && realpath($path) === $path
            && ($opened['mode'] & 0170000) === 0100000 && ($opened['mode'] & 07777) === 0600
            && $opened['uid'] === posix_geteuid() && $opened['nlink'] === 1 && $opened['size'] === 0
            && $opened['dev'] === $directory['dev'], 'NHE_PARENT_REAL_PRIVATE_RECEIPT_HANDLE');
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid', 'size', 'mtime', 'ctime'] as $key)
            nhep_expect($named[$key] === $opened[$key], 'NHE_PARENT_RECEIPT_PATH_AND_HANDLE_SAME');
        $offset = 0;
        while ($offset < strlen($raw)) {
            $written = fwrite($stream, substr($raw, $offset));
            nhep_expect(is_int($written) && $written > 0, 'NHE_PARENT_SAME_RECEIPT_COMPLETE_WRITE');
            $offset += $written;
        }
        nhep_expect(fflush($stream), 'NHE_PARENT_RECEIPT_FLUSH');
        $sealed = fstat($stream);
        nhep_expect(is_array($sealed) && $sealed['size'] === strlen($raw), 'NHE_PARENT_RECEIPT_FULL_WRITTEN_BYTES');
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
            nhep_expect($sealed[$key] === $opened[$key], 'NHE_PARENT_RECEIPT_HANDLE_IDENTITY_UNCHANGED');
    } catch (Throwable $error) {
        $failure = $error;
        throw $error;
    } finally {
        try { nhep_expect(fclose($stream), 'NHE_PARENT_RECEIPT_OWN_HANDLE_CLOSED'); }
        catch (Throwable $closeFailure) { if ($failure === null) throw $closeFailure; }
    }
    nhep_expect(nhe_file($path, ['path' => $path, 'bytes' => strlen($raw), 'sha256' => hash('sha256', $raw)]) === $raw,
        'NHE_PARENT_RECEIPT_INDEPENDENT_EXPECTED_BYTES');
    $proof = nhe_parent_process($actual);
    nhep_expect($proof['receipt'] === $receipt, 'NHE_PARENT_RECEIPT_STRICT_READER_FULL_JOIN');
    foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
        nhep_expect($proof['native'][$key] === $actual['process'][$key], 'NHE_PARENT_WRITER_SAME_ACTUAL_PROCESS');
    clearstatcache(true, $path); $after = lstat($path);
    nhep_expect(is_array($after), 'NHE_PARENT_RECEIPT_FINAL_IDENTITY');
    foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid', 'size', 'mtime', 'ctime'] as $key)
        nhep_expect($after[$key] === $sealed[$key], 'NHE_PARENT_RECEIPT_SEALED_HANDLE_FULL_STAT');
    nhe_includes($actual);
    return $receipt;
}

/** PRIVATE native child environment; never serialize or publish this return value. */
function nhep_child_environment(array $qualified): array
{
    $actual = nhep_parent_qualified($qualified); $parent = nhe_parent_process($actual);
    nhep_expect($parent['receipt']['pid'] === getmypid()
        && $parent['receipt']['starttime'] === $actual['process']['starttime'], 'NHE_ENVIRONMENT_ONLY_SAME_RECEIPTED_PARENT');
    $original = getenv();
    nhep_expect(is_array($original), 'NHE_ACTUAL_PARENT_ENVIRONMENT_REQUIRED');
    foreach ($original as $key => $value) nhep_expect(is_string($key) && $key !== '' && !str_contains($key, '=')
        && !str_contains($key, "\0") && is_string($value) && !str_contains($value, "\0"), 'NHE_NATIVE_PARENT_ENVIRONMENT_FIELDS');
    $required = ['AUDIT_ISOLATED' => '1', 'AUDIT_RUN_ID' => $actual['context']['run_id'], 'AUDIT_RUN_DIR' => '/run/audit',
        'AUDIT_REPO_DIR' => '/workspace', 'AUDIT_PROJECT' => $actual['context']['project'],
        'AUDIT_SOURCE_SHA' => $actual['context']['source_sha'], 'AUDIT_GUARD_MODE' => 'read-only'];
    foreach ($required as $key => $value)
        nhep_expect(($original[$key] ?? null) === $value, 'NHE_CHILD_PRESERVES_REAL_QUALIFIED_AUDIT_ENVIRONMENT');
    $environment = $original;
    foreach (['NHE_CHILD_FREEZE_BYTES' => (string)$actual['freeze_pin']['bytes'],
        'NHE_CHILD_FREEZE_SHA256' => $actual['freeze_pin']['sha256']] as $key => $value) {
        nhep_expect(!array_key_exists($key, $original) || $original[$key] === $value, 'NHE_NO_CONFLICTING_PARENT_FREEZE_ENVIRONMENT');
        $environment[$key] = $value;
    }
    nhep_expect(getenv() === $original, 'NHE_ACTUAL_PARENT_ENVIRONMENT_UNCHANGED');
    return $environment;
}

/** Sole status reader for each one original owned handle; terminal is never re-guessed. */
function nhep_child_native(array &$child): array
{
    if (is_array($child['first_terminal'] ?? null)) return $child['first_terminal'];
    nhep_expect(is_resource($child['process'] ?? null), 'NHE_CHILD_ORIGINAL_PROCESS_HANDLE_REQUIRED');
    $raw = proc_get_status($child['process']); $child['last_status_raw'] = $raw;
    nhep_expect(is_array($raw), 'NHE_CHILD_REAL_NATIVE_STATUS');
    $status = array_intersect_key($raw, array_flip(['pid', 'running', 'signaled', 'stopped', 'exitcode', 'termsig', 'stopsig']));
    $child['last_native'] = $status; $child['first_native'] ??= $status;
    if (($status['running'] ?? null) === false) $child['first_terminal'] = $status;
    nhe_keys($status, ['pid', 'running', 'signaled', 'stopped', 'exitcode', 'termsig', 'stopsig'], 'NHE_CHILD_NATIVE_SEVEN_KEYS');
    nhep_expect(is_int($status['pid']) && $status['pid'] > 1 && is_bool($status['running'])
        && is_bool($status['signaled']) && is_bool($status['stopped']) && is_int($status['exitcode'])
        && is_int($status['termsig']) && is_int($status['stopsig']), 'NHE_CHILD_NATIVE_STATUS_TYPES');
    $child['native_pid'] ??= $status['pid'];
    nhep_expect($child['native_pid'] === $status['pid'], 'NHE_CHILD_SAME_ORIGINAL_HANDLE_PID');
    return $status;
}

function nhep_child_group(array &$child, array $status): ?array
{
    if (!$status['running']) return $child['group'];
    $supervisor = audit_app_proc_stat(getmypid());
    foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
        nhep_expect(is_array($supervisor) && $supervisor[$key] === $child['supervisor'][$key], 'NHE_CHILD_SAME_NATIVE_PARENT');
    $leader = audit_app_proc_stat($status['pid']);
    if ($leader === null || $leader['ppid'] !== getmypid() || $leader['pgid'] !== $status['pid']
        || $leader['sid'] !== $status['pid']) return null;
    nhep_expect(!in_array($leader['state'], ['Z', 'X', 'x'], true), 'NHE_CHILD_REGISTER_ONLY_REAL_LIVE_LEADER');
    $executable = @readlink('/proc/' . $leader['pid'] . '/exe');
    if (!is_string($executable) || realpath($executable) !== PHP_BINARY) return null;
    $group = ['leader_pid' => $status['pid'], 'pgid' => $leader['pgid'], 'sid' => $leader['sid'], 'leader_starttime' => $leader['starttime']];
    if ($child['group'] !== null) nhep_expect($child['group'] === $group, 'NHE_CHILD_SAME_REGISTERED_SETSID_GROUP');
    audit_app_group_members($group, $child['supervisor']);
    return $group;
}

/** Any listener on the fixed port counts during stop, including an unexpected address. */
function nhep_child_listener(string $kind): array
{
    nhep_expect(in_array($kind, ['http', 'channel'], true), 'NHE_CHILD_FIXED_LISTENER_KIND');
    $port = $kind === 'http' ? 8000 : 40003; $rows = [];
    foreach (audit_app_tcp_rows() as $row) if ($row['local_port'] === $port && $row['state'] === '0A') {
        nhep_expect(ctype_digit($row['inode']) && $row['inode'] !== '0', 'NHE_CHILD_NATIVE_LISTENER_INODE'); $rows[] = $row;
    }
    return ['open' => $rows !== [], 'rows' => $rows];
}

function nhep_child_observation(array &$children, string $kind): array
{
    nhep_expect(in_array($kind, ['http', 'channel'], true) && isset($children[$kind]), 'NHE_CHILD_REGISTERED_OBSERVATION_KIND');
    $child =& $children[$kind]; $status = nhep_child_native($child);
    nhep_expect($status['running'] === true && $status['signaled'] === false && $status['stopped'] === false
        && $status['exitcode'] === -1 && $status['termsig'] === 0 && $status['stopsig'] === 0
        && is_array($child['group']), 'NHE_CHILD_ORIGINAL_LIVE_REGISTERED_HANDLE');
    nhep_expect(nhep_child_group($child, $status) === $child['group'], 'NHE_CHILD_ORIGINAL_GROUP_STILL_LIVE');
    $listener = nhep_child_listener($kind);
    nhep_expect(count($listener['rows']) === 1, 'NHE_CHILD_EXACT_SINGLE_FIXED_PORT_LISTENER');
    if ($kind === 'channel') {
        $proof = nhep_channel_observe($child['observe'], $child['observation']);
        $workers = array_values(array_filter($proof['members'], static fn(array $row): bool => $row['pid'] !== $status['pid']));
        $owners = array_values(array_unique(array_column($proof['listener']['owners'], 'pid'))); sort($owners, SORT_NUMERIC);
        $pids = array_column($proof['members'], 'pid'); sort($pids, SORT_NUMERIC);
        nhep_expect(count($workers) === 1 && $workers[0]['ppid'] === $status['pid'] && $owners === $pids
            && $proof['listener']['inode'] === $listener['rows'][0]['inode'], 'NHE_CHANNEL_REAL_MASTER_ONE_WORKER_SHARED_LISTENER');
    } else {
        $members = audit_app_group_members($child['group'], $child['supervisor']);
        nhep_expect(count($members) === 1 && $members[0]['pid'] === $status['pid'] && $members[0]['ppid'] === getmypid()
            && !in_array($members[0]['state'], ['Z', 'X', 'x'], true)
            && nhe_proc_command($status['pid']) === array_slice($child['command'], 1), 'NHE_HTTP_SINGLE_FIXED_NATIVE_CHILD');
        $inode = $listener['rows'][0]['inode']; $tcp = file_get_contents('/proc/net/tcp');
        nhep_expect(is_string($tcp), 'NHE_HTTP_NATIVE_IPV4_TCP_TABLE'); $loopback = [];
        foreach (array_slice(explode("\n", trim($tcp)), 1) as $line) {
            $fields = preg_split('/\s+/', trim($line));
            if (count($fields) >= 10 && $fields[1] === '0100007F:1F40' && $fields[3] === '0A') $loopback[] = $fields[9];
        }
        nhep_expect($loopback === [$inode], 'NHE_HTTP_EXACT_LOOPBACK_8000_LISTENER');
        $fds = glob('/proc/' . $status['pid'] . '/fd/*'); nhep_expect(is_array($fds), 'NHE_HTTP_NATIVE_FD_NAMESPACE'); $owners = [];
        foreach ($fds as $fd) if (@readlink($fd) === 'socket:[' . $inode . ']') $owners[] = (int)basename($fd);
        nhep_expect($owners !== [], 'NHE_HTTP_LISTENER_OWNED_BY_ORIGINAL_CHILD');
        $again = audit_app_proc_stat($status['pid']);
        foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
            nhep_expect(is_array($again) && $again[$key] === $members[0][$key], 'NHE_HTTP_IDENTITY_DURING_LISTENER_PROOF');
        nhep_expect(!in_array($again['state'], ['Z', 'X', 'x'], true), 'NHE_HTTP_STILL_LIVE_AFTER_LISTENER_PROOF');
        $proof = ['native' => $status, 'group' => $child['group'], 'members' => $members,
            'listener' => ['address' => '127.0.0.1', 'port' => 8000, 'inode' => $inode, 'owners' => $owners]];
        if ($child['observation'] !== null) {
            foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
                nhep_expect($proof['members'][0][$key] === $child['observation']['members'][0][$key], 'NHE_HTTP_SAME_STABLE_NATIVE_IDENTITY');
            nhep_expect($proof['listener']['inode'] === $child['observation']['listener']['inode'], 'NHE_HTTP_SAME_LISTENER_INODE');
        }
    }
    $child['observation'] = $proof; return $proof;
}

/** One launch only. Keep the actual return and any partially created streams in caller-owned RAM. */
function nhep_child_start(array $qualified, array &$children, string $kind): void
{
    nhep_expect(in_array($kind, ['http', 'channel'], true) && !array_key_exists($kind, $children)
        && array_diff(array_keys($children), ['http', 'channel']) === [], 'NHE_CHILD_NEW_FIXED_ROLE_ONLY');
    foreach (['proc_open', 'proc_get_status', 'proc_close', 'posix_kill', 'pcntl_waitpid', 'audit_app_proc_stat',
        'audit_app_group_members', 'audit_app_tcp_rows'] as $function)
        nhep_expect(function_exists($function), 'NHE_CHILD_NATIVE_LIFECYCLE_FUNCTIONS_REQUIRED');
    $actual = nhep_parent_qualified($qualified); $environment = nhep_child_environment($qualified);
    nhep_expect($kind !== 'http' || !array_key_exists('PHP_CLI_SERVER_WORKERS', $environment), 'NHE_HTTP_NO_ADDITIONAL_SERVER_WORKERS');
    $httpTimeReference = null;
    if ($kind === 'http') {
        nhep_expect(!array_key_exists('TZ', $environment) && !array_key_exists('TZDIR', $environment),
            'NHE_HTTP_ORIGINAL_FRESH_EXEC_ENVIRONMENT_WITHOUT_SYSTEM_TIME_OVERRIDES');
        $httpTimeReference = nhep_http_time_reference();
    }
    $parent = nhe_parent_process($actual);
    nhep_expect($parent['receipt']['pid'] === getmypid() && $parent['receipt']['starttime'] === $actual['process']['starttime'],
        'NHE_CHILD_REAL_PRIVATE_PARENT_RECEIPT_BEFORE_START');
    nhep_expect(!nhep_child_listener($kind)['open'], 'NHE_CHILD_NO_PREEXISTING_FIXED_LISTENER');
    $command = $kind === 'http'
        ? ['setsid', PHP_BINARY, '-S', '127.0.0.1:8000', '-t', '/legacy-workspace/crmeb/public', '/run/nonempty/legacy-history-router.php']
        : ['setsid', PHP_BINARY, '/run/nonempty/legacy-history-channel.php', 'start',
            '--freeze-bytes=' . $actual['freeze_pin']['bytes'], '--freeze-sha256=' . $actual['freeze_pin']['sha256']];
    $directory = '/legacy-runtime'; clearstatcache(true, $directory); $runtime = lstat($directory);
    nhep_expect(is_array($runtime) && is_dir($directory) && !is_link($directory) && realpath($directory) === $directory
        && ($runtime['mode'] & 0777) === 0700 && $runtime['uid'] === posix_geteuid(), 'NHE_CHILD_PRIVATE_0700_RUNTIME');
    $children[$kind] = ['kind' => $kind, 'process' => null, 'group' => null, 'supervisor' => $actual['process'],
        'command' => $command, 'streams' => [], 'first_native' => null, 'last_native' => null, 'first_terminal' => null,
        'native_pid' => null, 'observation' => null, 'term_attempted' => false, 'term_sent' => false,
        'waits' => [], 'closed' => null, 'subscriber' => null, 'run_id' => $actual['context']['run_id'],
        'http_time_reference' => $httpTimeReference, 'phase' => 'private_streams'];
    $child =& $children[$kind];
    $child['observe'] = static function () use (&$children, $kind): array {
        return ['native' => nhep_child_native($children[$kind]), 'group' => $children[$kind]['group']];
    };
    try {
        foreach (['stdout', 'stderr'] as $stream) {
            $path = $directory . '/legacy-' . $kind . '.' . $stream;
            nhep_expect(!file_exists($path) && !is_link($path), 'NHE_CHILD_CREATE_ONLY_PRIVATE_NATIVE_STREAM');
            $mask = umask(0077);
            try { $handle = fopen($path, 'x+b'); } finally { umask($mask); }
            $child['streams'][$stream] = ['path' => $path, 'handle' => $handle, 'created' => is_resource($handle) ? fstat($handle) : false];
            $stat = $child['streams'][$stream]['created']; clearstatcache(true, $path); $named = lstat($path);
            nhep_expect(is_resource($handle) && is_array($stat) && is_array($named) && is_file($path) && !is_link($path)
                && ($stat['mode'] & 0777) === 0600 && $stat['uid'] === posix_geteuid() && $stat['nlink'] === 1
                && $stat['dev'] === $runtime['dev'] && $stat['size'] === 0 && $named === $stat, 'NHE_CHILD_NATIVE_PRIVATE_STREAM_IDENTITY');
        }
        $child['phase'] = 'native_start';
        if ($kind === 'http') nhep_http_time_reference($child['http_time_reference']);
        $process = proc_open($command, [['file', '/dev/null', 'r'], $child['streams']['stdout']['handle'],
            $child['streams']['stderr']['handle']], $pipes, '/legacy-workspace/crmeb', $environment);
        $child['process'] = $process; unset($environment);
        nhep_expect(is_resource($process), 'NHE_CHILD_ACTUAL_PROC_OPEN_RETURN');
        $until = hrtime(true) + 1000000000;
        do {
            $status = nhep_child_native($child); $group = nhep_child_group($child, $status);
            if ($group !== null) { $child['group'] = $group; break; }
            if (!$status['running']) break;
            usleep(5000);
        } while (hrtime(true) < $until);
        nhep_expect(is_array($child['group']), 'NHE_CHILD_REAL_GROUP_OBSERVED_BEFORE_TERMINAL');
        $child['phase'] = 'native_readiness'; $until = hrtime(true) + 5000000000; $ready = false;
        do {
            $status = nhep_child_native($child);
            if (!$status['running']) break;
            $members = audit_app_group_members($child['group'], $child['supervisor']); $listener = nhep_child_listener($kind);
            if (count($members) === ($kind === 'http' ? 1 : 2) && count($listener['rows']) === 1) {
                nhep_child_observation($children, $kind); $ready = true; break;
            }
            usleep(10000);
        } while (hrtime(true) < $until);
        nhep_expect($ready, 'NHE_CHILD_SAME_HANDLE_NATIVE_READINESS_NOT_OBSERVED'); $child['phase'] = 'native_ready';
    } catch (Throwable $failure) {
        $child['failure_class'] = get_class($failure); unset($environment); throw $failure;
    }
}

/** Bind the actual open subscriber once; later stop checks this same resource after fclose. */
function nhep_child_subscriber(array &$children, array &$channel): void
{
    nhep_expect(isset($children['channel']) && $children['channel']['subscriber'] === null
        && $children['channel']['closed'] === null && ($channel['closed'] ?? null) === false
        && ($channel['observe'] ?? null) === $children['channel']['observe']
        && ($channel['run_id'] ?? null) === $children['channel']['run_id']
        && is_resource($channel['socket'] ?? null) && get_resource_type($channel['socket']) === 'stream'
        && get_resource_id($channel['socket']) === ($channel['socket_id'] ?? null)
        && stream_socket_get_name($channel['socket'], false) === ($channel['local_endpoint'] ?? null)
        && stream_socket_get_name($channel['socket'], true) === '127.0.0.1:40003', 'NHE_CHILD_ACTUAL_OWN_SUBSCRIBER_REQUIRED');
    $proof = nhep_child_observation($children, 'channel');
    nhep_expect(($channel['proof']['group'] ?? null) === $proof['group']
        && ($channel['proof']['listener']['inode'] ?? null) === $proof['listener']['inode'], 'NHE_CHILD_SUBSCRIBER_SAME_ORIGINAL_CHANNEL');
    $children['channel']['subscriber'] = ['socket' => $channel['socket'], 'socket_id' => $channel['socket_id'],
        'local_endpoint' => $channel['local_endpoint'], 'state' => &$channel];
}

function nhep_child_streams(array &$child): array
{
    $result = [];
    foreach (['stdout', 'stderr'] as $name) {
        $stream =& $child['streams'][$name]; $path = $stream['path']; clearstatcache(true, $path); $before = lstat($path);
        nhep_expect(is_array($before) && is_file($path) && !is_link($path) && $before['size'] <= 16777216
            && ($before['mode'] & 0777) === 0600 && $before['uid'] === posix_geteuid(), 'NHE_CHILD_COMPLETE_PRIVATE_NATIVE_STREAM');
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
            nhep_expect($before[$key] === $stream['created'][$key], 'NHE_CHILD_SAME_ORIGINAL_NATIVE_STREAM_FILE');
        $raw = file_get_contents($path); clearstatcache(true, $path); $after = lstat($path);
        nhep_expect(is_string($raw) && strlen($raw) === $before['size'] && is_array($after), 'NHE_CHILD_FULL_NATIVE_STREAM_BYTES');
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid', 'size', 'mtime', 'ctime'] as $key)
            nhep_expect($before[$key] === $after[$key], 'NHE_CHILD_COMPLETE_NATIVE_STREAM_STAT9');
        $result[$name] = ['bytes' => strlen($raw), 'sha256' => hash('sha256', $raw)];
        $stream['complete'] = $result[$name]; unset($raw);
        if (is_resource($stream['handle'])) {
            nhep_expect(fstat($stream['handle']) === $after, 'NHE_CHILD_COMPLETE_STREAM_SAME_OWNED_HANDLE');
            nhep_expect(fclose($stream['handle']), 'NHE_CHILD_NORMAL_PARENT_STREAM_HANDLE_CLOSE'); $stream['handle'] = null;
        }
    }
    return $result;
}

function nhep_child_close(array &$children, string $kind): array
{
    nhep_expect(in_array($kind, ['http', 'channel'], true) && isset($children[$kind]), 'NHE_CHILD_ONLY_ORIGINAL_CLOSE_KIND');
    $child =& $children[$kind];
    if ($kind === 'channel') {
        $subscriber = $child['subscriber'];
        nhep_expect(is_array($subscriber) && !is_resource($subscriber['socket']) && gettype($subscriber['socket']) === 'resource (closed)'
            && ($subscriber['state']['closed'] ?? null) === true && ($subscriber['state']['socket'] ?? null) === null
            && $subscriber['state']['socket_id'] === $subscriber['socket_id']
            && $subscriber['state']['local_endpoint'] === $subscriber['local_endpoint'], 'NHE_CHANNEL_OWN_REGISTERED_SUBSCRIBER_ACTUALLY_CLOSED');
        nhep_expect(!isset($children['http']) || (($children['http']['closed']['stopped'] ?? null) === true
            && !nhep_child_listener('http')['open']), 'NHE_CHANNEL_CLOSE_ONLY_AFTER_OWN_HTTP_STOPPED');
    }
    if ($child['closed'] !== null) {
        if ($child['group'] === null) {
            $child['closed']['listener_open'] = nhep_child_listener($kind)['open'];
            return $child['closed'];
        }
        nhep_expect(is_array($child['group']) && audit_app_group_members($child['group'], $child['supervisor']) === []
            && !nhep_child_listener($kind)['open'], 'NHE_CHILD_CACHED_CLOSE_STILL_NATIVE_EMPTY');
        return $child['closed'];
    }
    $child['phase'] = 'normal_close'; $status = nhep_child_native($child);
    if ($child['group'] === null && $status['running']) $child['group'] = nhep_child_group($child, $status);
    $group = $child['group']; $remaining = $group === null ? null : audit_app_group_members($group, $child['supervisor']);
    if ($group !== null && $child['observation'] !== null) foreach ($remaining as $member) {
        $old = array_values(array_filter($child['observation']['members'], static fn(array $row): bool => $row['pid'] === $member['pid']));
        nhep_expect(count($old) === 1, 'NHE_CHILD_NO_FOREIGN_OR_RESTARTED_MEMBER_BEFORE_TERM');
        foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
            nhep_expect($member[$key] === $old[0][$key], 'NHE_CHILD_ORIGINAL_MEMBER_IDENTITY_BEFORE_TERM');
    }
    if ($group !== null && !$child['term_attempted'] && $remaining !== []) {
        $child['term_attempted'] = true; $child['term_sent'] = posix_kill(-$group['pgid'], SIGTERM);
        nhep_expect($child['term_sent'] || audit_app_group_members($group, $child['supervisor']) === [], 'NHE_CHILD_REGISTERED_GROUP_ONE_NORMAL_TERM');
    }
    $until = hrtime(true) + 5000000000;
    do {
        $status = nhep_child_native($child);
        if ($group !== null && $child['first_terminal'] !== null) {
            while (($pid = pcntl_waitpid(-$group['pgid'], $wait, WNOHANG)) > 0) $child['waits'][] = ['pid' => $pid, 'status' => $wait];
        }
        $remaining = $group === null ? null : audit_app_group_members($group, $child['supervisor']); $listener = nhep_child_listener($kind);
        if ($child['first_terminal'] !== null && !$listener['open'] && ($remaining === [] || $group === null)) break;
        if ($group === null) break;
        usleep(20000);
    } while (hrtime(true) < $until);
    $receipt = ['stopped' => $group !== null && $remaining === [] && !$listener['open'] && $child['first_terminal'] !== null,
        'group' => $group, 'remaining_members' => $remaining, 'listener_open' => $listener['open'],
        'first_terminal' => $child['first_terminal'], 'term_attempted' => $child['term_attempted'],
        'stop_signal' => $child['term_sent'] ? SIGTERM : null, 'proc_close_exit' => null, 'streams' => null, 'waits' => $child['waits']];
    if ($child['first_terminal'] === null || ($group !== null && !$receipt['stopped'])) {
        $child['last_close_observation'] = $receipt; return $receipt;
    }
    $exit = proc_close($child['process']); $receipt['proc_close_exit'] = $exit;
    $child['closed'] = $receipt; $child['process'] = null;
    $child['closed']['streams'] = nhep_child_streams($child);
    nhep_expect(is_int($exit) && $child['first_terminal']['running'] === false && $child['first_terminal']['termsig'] !== SIGKILL,
        'NHE_CHILD_ORIGINAL_TERMINAL_AND_PROC_CLOSE_NO_ESCALATION');
    $child['phase'] = 'native_closed'; return $child['closed'];
}

/** Separate final gate; never impose this on HTTP while the Channel is still legitimately live. */
function nhep_children_closed(array &$children): array
{
    $keys = array_keys($children); sort($keys, SORT_STRING);
    nhep_expect($keys === ['channel', 'http'], 'NHE_FINAL_BOTH_ORIGINAL_CHILD_ROLES'); $receipts = [];
    foreach (['http', 'channel'] as $kind) {
        $child =& $children[$kind]; $receipt = nhep_child_close($children, $kind);
        nhep_expect($receipt['stopped'] === true && $child['process'] === null && is_int($receipt['proc_close_exit'])
            && $receipt['first_terminal']['termsig'] !== SIGKILL && is_array($receipt['streams']), 'NHE_FINAL_BOTH_REAL_CHILDREN_CLOSED');
        $receipts[$kind] = $receipt;
    }
    $supervisor = $children['http']['supervisor']; $self = audit_app_proc_stat(getmypid());
    foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
        nhep_expect(is_array($self) && $self[$key] === $supervisor[$key]
            && $self[$key] === $children['channel']['supervisor'][$key], 'NHE_FINAL_SAME_NATIVE_PRODUCER_PARENT');
    $files = glob('/proc/[0-9]*/stat'); nhep_expect(is_array($files) && $files !== [], 'NHE_FINAL_NATIVE_PROCESS_INVENTORY'); $seen = false;
    foreach ($files as $file) {
        $row = audit_app_proc_stat((int)basename(dirname($file))); if ($row === null) continue;
        nhep_expect($row['pid'] === getmypid(), 'NHE_FINAL_NO_OTHER_CONTAINER_PROCESS'); $seen = true;
    }
    nhep_expect($seen && !nhep_child_listener('http')['open'] && !nhep_child_listener('channel')['open'], 'NHE_FINAL_BOTH_LISTENERS_AND_GROUPS_EMPTY');
    return $receipts;
}

/** Observe the actual independent PDO; never change its modes to fit a model. */
function nhep_database_modes(PDO $db): array
{
    $modes = m4m_rows($db, 'SELECT @@SESSION.sql_mode AS session_mode,@@GLOBAL.sql_mode AS global_mode,'
        . '@@SESSION.innodb_strict_mode AS session_innodb,@@GLOBAL.innodb_strict_mode AS global_innodb,'
        . '@@SESSION.information_schema_stats_expiry AS session_stats_expiry,@@GLOBAL.information_schema_stats_expiry AS global_stats_expiry,'
        . '@@SESSION.auto_increment_increment AS session_increment,@@GLOBAL.auto_increment_increment AS global_increment,'
        . '@@SESSION.auto_increment_offset AS session_offset,@@GLOBAL.auto_increment_offset AS global_offset');
    nhep_expect(count($modes) === 1, 'NHE_DATABASE_ACTUAL_COMPLETE_OBSERVER_MODES');
    foreach (['session_innodb', 'global_innodb', 'session_increment', 'global_increment', 'session_offset', 'global_offset'] as $key)
        nhep_expect($modes[0][$key] === 1, 'NHE_DATABASE_NATIVE_STRICT_UNIT_COUNTER_MODES');
    foreach (['session_stats_expiry', 'global_stats_expiry'] as $key)
        nhep_expect($modes[0][$key] === 0, 'NHE_DATABASE_ACTUAL_IMMEDIATE_METADATA_STATISTICS');
    return $modes;
}

/** All 164 tables and original native rows remain private; no App is loaded here. */
function nhep_database_capture(PDO $db, string $runId): array
{
    m4lh_actor_identity($db, $runId); $modes = nhep_database_modes($db);
    $names = $db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN); sort($names, SORT_STRING);
    nhep_expect(count($names) === 164 && count(array_unique($names, SORT_STRING)) === 164,
        'NHE_DATABASE_COMPLETE_ORIGINAL_164_TABLES');
    $database = ['names' => $names, 'modes' => $modes, 'tables' => []]; $allRows = [];
    foreach ($names as $name) {
        nhep_expect(is_string($name) && preg_match('/\A(?:eb_[a-z0-9_]+|audit_sentinel)\z/D', $name) === 1,
            'NHE_DATABASE_ONLY_ACTUAL_OWN_TABLE_NAMESPACE');
        $metadata = m4m_metadata($db, $name); $columns = array_keys($metadata['columns']);
        nhep_expect($columns !== [], 'NHE_DATABASE_COMPLETE_NONEMPTY_COLUMN_ORDER');
        $rows = m4m_rows($db, 'SELECT ' . implode(',', array_map('m4m_quote', $columns)) . ' FROM ' . m4m_quote($name));
        foreach ($rows as $row) nhep_expect(array_keys($row) === $columns, 'NHE_DATABASE_ALL_NATIVE_COLUMNS_IN_ORIGINAL_ORDER');
        usort($rows, static fn(array $a, array $b): int => strcmp(serialize($a), serialize($b)));
        $ddl = $db->query('SHOW CREATE TABLE ' . m4m_quote($name))->fetch(PDO::FETCH_NUM);
        nhep_expect(is_array($ddl) && is_string($ddl[1] ?? null), 'NHE_DATABASE_COMPLETE_ORIGINAL_DDL');
        $database['tables'][$name] = ['metadata' => $metadata, 'ddl' => $ddl[1],
            'projected_columns' => $columns, 'projection' => m4lh_actor_projection($rows)];
        $allRows[$name] = $rows;
    }
    nhep_expect(nhep_database_modes($db) === $modes, 'NHE_DATABASE_OBSERVER_MODES_PRESERVED_DURING_FULL_SCAN');
    return ['database' => $database, 'rows' => $allRows];
}

/** Pure BEFORE + independent full rows model. There is deliberately no AFTER argument. */
function nhep_database_expected(array $before, array $expectedRows, array $insertCounts = []): array
{
    nhe_keys($before, ['database', 'rows'], 'NHE_DATABASE_COMPLETE_BEFORE_MODEL_KEYS');
    nhe_keys($before['database'], ['names', 'modes', 'tables'], 'NHE_DATABASE_ORIGINAL_DATABASE_MODEL_KEYS');
    $names = $before['database']['names']; $sorted = $names; sort($sorted, SORT_STRING);
    nhep_expect(array_is_list($names) && count($names) === 164 && $names === $sorted
        && count(array_unique($names, SORT_STRING)) === 164
        && array_keys($before['database']['tables']) === $names && array_keys($before['rows']) === $names
        && array_diff(array_keys($expectedRows), $names) === []
        && array_diff(array_keys($insertCounts), array_keys($expectedRows)) === [], 'NHE_DATABASE_COMPLETE_BEFORE_AND_EXPLICIT_MODEL_TABLES');
    $expected = $before;
    foreach ($expectedRows as $name => $rows) {
        $old = $before['database']['tables'][$name];
        nhep_expect(is_array($rows) && array_is_list($rows)
            && $old['projected_columns'] === array_keys($old['metadata']['columns']), 'NHE_DATABASE_ORIGINAL_FULL_EXPECTED_ROW_COLUMNS');
        foreach ($rows as $row) nhep_expect(is_array($row) && array_keys($row) === $old['projected_columns'],
            'NHE_DATABASE_EACH_INDEPENDENT_EXPECTED_FULL_ROW');
        usort($rows, static fn(array $a, array $b): int => strcmp(serialize($a), serialize($b)));
        $expected['rows'][$name] = $rows;
        $expected['database']['tables'][$name]['projection'] = m4lh_actor_projection($rows);
        $count = $insertCounts[$name] ?? 0;
        nhep_expect(is_int($count) && $count >= 0 && $count <= 4294967294, 'NHE_DATABASE_INDEPENDENT_NATURAL_INSERT_COUNT');
        if ($count === 0) continue;
        $auto = [];
        foreach ($old['metadata']['columns'] as $column => $definition)
            if ($definition['EXTRA'] === 'auto_increment') $auto[] = $column;
        nhep_expect(count($auto) === 1, 'NHE_DATABASE_COUNTER_ONLY_ON_ORIGINAL_AUTO_INCREMENT_COLUMN');
        $id = m4lh_actor_next($old, $auto[0]); $next = $id + $count;
        nhep_expect($next <= 4294967295, 'NHE_DATABASE_ORIGINAL_NORMAL_BUSINESS_COUNTER_RANGE');
        $counter = $old['metadata']['table']['AUTO_INCREMENT'];
        $expected['database']['tables'][$name]['metadata']['table']['AUTO_INCREMENT'] = is_int($counter) ? $next : (string)$next;
        $expected['database']['tables'][$name]['ddl'] = m4lh_actor_counter_ddl($old['ddl'], $id, $next);
    }
    return $expected;
}


/** Parse only the two actual native TIME decimals; never accept an AFTER state. */
function nhep_redis_time(array $time): array
{
    nhep_expect(array_is_list($time) && count($time) === 2 && is_string($time[0]) && is_string($time[1])
        && preg_match('/\A[1-9][0-9]{0,18}\z/D', $time[0]) === 1
        && preg_match('/\A[0-9]{1,6}\z/D', $time[1]) === 1
        && bccomp($time[1], '999999', 0) <= 0, 'NHE_REDIS_ACTUAL_NATIVE_TIME_DECIMALS');
    return ['time' => $time, 'time_ms' => bcadd(bcmul($time[0], '1000', 0), bcdiv($time[1], '1000', 0), 0)];
}

/** Complete comparison shape; raw keys, values and DUMPs live in a separate private envelope. */
function nhep_redis_snapshot(array $snapshot): void
{
    nhe_keys($snapshot, ['time', 'time_ms', 'keys'], 'NHE_REDIS_COMPLETE_SNAPSHOT_THREE_KEYS');
    nhep_expect(is_array($snapshot['time']) && is_array($snapshot['keys']) && is_string($snapshot['time_ms']),
        'NHE_REDIS_TYPED_COMPLETE_SNAPSHOT');
    $clock = nhep_redis_time($snapshot['time']);
    nhep_expect($snapshot['time_ms'] === $clock['time_ms'], 'NHE_REDIS_INDEPENDENT_TIME_MILLISECOND_ENVELOPE');
    $names = array_keys($snapshot['keys']); $sorted = $names; sort($sorted, SORT_STRING);
    nhep_expect($names === $sorted, 'NHE_REDIS_COMPLETE_SORTED_HASH_KEY_NAMESPACE');
    foreach ($snapshot['keys'] as $keyHash => $row) {
        nhep_expect(is_string($keyHash) && preg_match('/\A[a-f0-9]{64}\z/D', $keyHash) === 1 && is_array($row),
            'NHE_REDIS_COMPLETE_NATIVE_KEY_HASH');
        nhe_keys($row, ['type', 'sha256', 'expires'], 'NHE_REDIS_COMPLETE_TYPE_VALUE_ABSOLUTE_EXPIRY');
        nhep_expect(is_string($row['type']) && $row['type'] !== '' && $row['type'] !== 'none'
            && is_string($row['sha256']) && preg_match('/\A[a-f0-9]{64}\z/D', $row['sha256']) === 1
            && is_int($row['expires']) && ($row['expires'] === -1 || $row['expires'] > 0),
            'NHE_REDIS_NATIVE_TYPE_DIGEST_AND_ABSOLUTE_EXPIRY');
    }
    $sentinel = $snapshot['keys'][hash('sha256', 'audit:sentinel')] ?? null;
    nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1,
        'NHE_REDIS_ORIGINAL_NONEXPIRING_SENTINEL_REQUIRED');
}

/** One EVAL_RO, original client/DB/sentinel. Both return values remain private RAM only. */
function nhep_redis_capture(Redis $redis, string $runId): array
{
    nhep_expect(get_class($redis) === Redis::class && $redis->isConnected()
        && $redis->getHost() === 'audit-redis' && $redis->getPort() === 6379 && $redis->getDBNum() === 0
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $runId) === 1 && $runId === getenv('AUDIT_RUN_ID'),
        'NHE_REDIS_ACTUAL_ORIGINAL_RUN_CLIENT_DB_ZERO');
    $lua = <<<'LUA'
local now = redis.call('TIME')
local names = redis.call('KEYS', '*')
table.sort(names)
local rows = {}
for _, key in ipairs(names) do
    local kind = redis.call('TYPE', key).ok
    local value = false
    if kind == 'string' then
        value = redis.call('GET', key)
    elseif kind == 'hash' then
        value = redis.call('HGETALL', key)
    elseif kind == 'set' then
        value = redis.call('SMEMBERS', key)
    end
    rows[#rows + 1] = {key, kind, redis.call('DUMP', key), redis.call('PEXPIRETIME', key), value}
end
return {now, rows}
LUA;
    $raw = $redis->rawCommand('EVAL_RO', $lua, 0);
    nhep_expect(is_array($raw) && array_is_list($raw) && count($raw) === 2
        && is_array($raw[0]) && is_array($raw[1]) && array_is_list($raw[1]),
        'NHE_REDIS_COMPLETE_SINGLE_ATOMIC_NATIVE_REPLY');
    $clock = nhep_redis_time($raw[0]); $keys = []; $native = []; $previous = null;
    foreach ($raw[1] as $row) {
        nhep_expect(is_array($row) && array_is_list($row) && count($row) === 5 && is_string($row[0])
            && ($previous === null || strcmp($previous, $row[0]) < 0)
            && is_string($row[1]) && $row[1] !== '' && $row[1] !== 'none'
            && is_string($row[2]) && $row[2] !== '' && is_int($row[3]) && ($row[3] === -1 || $row[3] > 0),
            'NHE_REDIS_COMPLETE_ATOMIC_KEY_TYPE_DUMP_AND_DEADLINE');
        [$key, $type, $dump, $expires, $value] = $row; $previous = $key; $keyHash = hash('sha256', $key);
        nhep_expect(!array_key_exists($keyHash, $keys) && !array_key_exists($keyHash, $native),
            'NHE_REDIS_COMPLETE_UNIQUE_ORIGINAL_KEY_IDENTITIES');
        if ($type === 'string') {
            nhep_expect(is_string($value), 'NHE_REDIS_COMPLETE_NATIVE_STRING_BYTES');
        } elseif ($type === 'hash') {
            nhep_expect(is_array($value) && array_is_list($value) && count($value) % 2 === 0,
                'NHE_REDIS_COMPLETE_NATIVE_HASH_PAIRS');
            $pairs = []; $fields = [];
            for ($index = 0; $index < count($value); $index += 2) {
                nhep_expect(is_string($value[$index]) && is_string($value[$index + 1]),
                    'NHE_REDIS_EXACT_NATIVE_HASH_FIELD_AND_VALUE_BYTES');
                $fieldHash = hash('sha256', $value[$index]);
                nhep_expect(!isset($fields[$fieldHash]), 'NHE_REDIS_UNIQUE_ORIGINAL_HASH_FIELDS');
                $fields[$fieldHash] = true; $pairs[] = [$value[$index], $value[$index + 1]];
            }
            usort($pairs, static fn(array $a, array $b): int => strcmp($a[0], $b[0])); $value = $pairs;
            unset($pairs, $fields, $fieldHash);
        } elseif ($type === 'set') {
            nhep_expect(is_array($value) && array_is_list($value), 'NHE_REDIS_COMPLETE_NATIVE_SET');
            foreach ($value as $member) nhep_expect(is_string($member), 'NHE_REDIS_NATIVE_SET_MEMBER_BYTES');
            nhep_expect(count($value) === count(array_unique($value, SORT_STRING)), 'NHE_REDIS_UNIQUE_NATIVE_SET_MEMBERS');
            sort($value, SORT_STRING);
        } else {
            nhep_expect($value === false, 'NHE_REDIS_OTHER_TYPES_RETAIN_COMPLETE_DUMP_ONLY');
        }
        $dumpHash = hash('sha256', $dump);
        $hash = $type === 'set' ? hash('sha256', "set\0" . serialize($value)) : $dumpHash;
        $keys[$keyHash] = ['type' => $type, 'sha256' => $hash, 'expires' => $expires];
        $native[$keyHash] = ['key' => $key, 'type' => $type, 'dump' => $dump, 'dump_sha256' => $dumpHash,
            'expires' => $expires, 'value' => $value];
        unset($key, $type, $dump, $dumpHash, $hash, $expires, $value, $row);
    }
    ksort($keys, SORT_STRING); ksort($native, SORT_STRING);
    $snapshot = $clock + ['keys' => $keys]; nhep_redis_snapshot($snapshot);
    $sentinel = $native[hash('sha256', 'audit:sentinel')] ?? null;
    nhep_expect(is_array($sentinel) && $sentinel['key'] === 'audit:sentinel' && $sentinel['type'] === 'string'
        && $sentinel['value'] === $runId && $sentinel['expires'] === -1,
        'NHE_REDIS_ATOMIC_ORIGINAL_RUN_SENTINEL_VALUE');
    nhep_expect($redis->isConnected() && $redis->getHost() === 'audit-redis'
        && $redis->getPort() === 6379 && $redis->getDBNum() === 0, 'NHE_REDIS_SAME_ORIGINAL_CLIENT_AFTER_ATOMIC_READ');
    unset($raw, $sentinel);
    return ['snapshot' => $snapshot, 'native' => $native];
}

/** Pure BEFORE + independent changes + one real observation TIME; no AFTER argument or native values. */
function nhep_redis_expected(array $before, array $independentChanges, array $actualObservationTime): array
{
    nhep_redis_snapshot($before); $clock = nhep_redis_time($actualObservationTime);
    $beforeUs = bcadd(bcmul($before['time'][0], '1000000', 0), $before['time'][1], 0);
    $actualUs = bcadd(bcmul($clock['time'][0], '1000000', 0), $clock['time'][1], 0);
    nhep_expect(bccomp($actualUs, $beforeUs, 0) >= 0, 'NHE_REDIS_ACTUAL_OBSERVATION_MICROSECOND_CLOCK_MONOTONIC');
    $keys = $before['keys']; $touched = []; $sentinel = hash('sha256', 'audit:sentinel');
    foreach ($independentChanges as $rawKey => $change) {
        nhep_expect(is_string($rawKey) || is_int($rawKey), 'NHE_REDIS_INDEPENDENT_EXACT_RAW_KEY');
        $key = (string)$rawKey; $keyHash = hash('sha256', $key);
        nhep_expect($keyHash !== $sentinel && !isset($touched[$keyHash]), 'NHE_REDIS_NO_SENTINEL_CHANGE_OR_DUPLICATE_MODEL_KEY');
        $touched[$keyHash] = true;
        if ($change === null) {
            unset($keys[$keyHash]);
        } else {
            nhep_expect(is_array($change), 'NHE_REDIS_INDEPENDENT_COMPLETE_CHANGE_NOT_BOOLEAN');
            nhe_keys($change, ['type', 'sha256', 'expires'], 'NHE_REDIS_INDEPENDENT_COMPLETE_TYPE_VALUE_DEADLINE');
            $keys[$keyHash] = ['type' => $change['type'], 'sha256' => $change['sha256'], 'expires' => $change['expires']];
        }
    }
    foreach ($before['keys'] as $keyHash => $row) {
        if (!isset($touched[$keyHash]) && $row['expires'] > 0
            && bccomp($clock['time_ms'], (string)$row['expires'], 0) > 0) unset($keys[$keyHash]);
    }
    ksort($keys, SORT_STRING); $expected = $clock + ['keys' => $keys]; nhep_redis_snapshot($expected);
    nhep_expect($expected['keys'][$sentinel] === $before['keys'][$sentinel], 'NHE_REDIS_ORIGINAL_SENTINEL_COMPLETE_IDENTITY_PRESERVED');
    return $expected;
}

function nhep_file_stat(array $stat): array
{
    $result = [];
    foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid', 'size', 'mtime', 'ctime'] as $key) {
        nhep_expect(array_key_exists($key, $stat) && is_int($stat[$key]), 'NHE_FILE_COMPLETE_NATIVE_STAT_NINE');
        $result[$key] = $stat[$key];
    }
    return $result;
}

/** Complete private observation, including absent roots and every empty directory. */
function nhep_file_tree(string $root): ?array
{
    nhep_expect(in_array($root, ['/run/audit-app', '/run/audit-fixtures', '/legacy-runtime', '/legacy-workspace/crmeb/public',
        '/legacy-workspace/crmeb/runtime'], true), 'NHE_FILE_FIXED_FIVE_OBSERVATION_ROOTS');
    clearstatcache(true, $root);
    if (!file_exists($root)) {
        nhep_expect(!is_link($root), 'NHE_FILE_ABSENT_ROOT_NOT_DANGLING_LINK'); return null;
    }
    nhep_expect(is_dir($root) && !is_link($root) && realpath($root) === $root, 'NHE_FILE_ORIGINAL_REAL_DIRECTORY_ROOT');
    $result = [];
    $walk = static function (string $path, string $relative) use (&$walk, &$result): void {
        clearstatcache(true, $path); $before = lstat($path);
        nhep_expect(is_array($before) && !is_link($path) && realpath($path) === $path, 'NHE_FILE_REAL_ORIGINAL_TREE_ENTRY');
        $stat = nhep_file_stat($before); $kind = $stat['mode'] & 0170000;
        nhep_expect(in_array($kind, [0040000, 0100000], true), 'NHE_FILE_ONLY_DIRECTORY_OR_REGULAR_ENTRY');
        $row = ['kind' => $kind === 0040000 ? 'directory' : 'file', 'stat' => $stat];
        if ($kind === 0100000) {
            nhep_expect($stat['nlink'] === 1 && $stat['size'] >= 0 && $stat['size'] <= 67108864,
                'NHE_FILE_COMPLETE_SINGLE_LINK_FILE_WITHIN_ORIGINAL_LIMIT');
            $raw = file_get_contents($path); clearstatcache(true, $path); $after = lstat($path);
            nhep_expect(is_string($raw) && strlen($raw) === $stat['size'] && is_array($after)
                && !is_link($path) && realpath($path) === $path && nhep_file_stat($after) === $stat,
                'NHE_FILE_COMPLETE_BYTES_AND_ORIGINAL_STAT_STABLE');
            $result[$relative] = $row + ['bytes' => strlen($raw), 'sha256' => hash('sha256', $raw)];
            unset($raw); return;
        }
        $result[$relative] = $row; $names = scandir($path);
        nhep_expect(is_array($names), 'NHE_FILE_COMPLETE_ORIGINAL_DIRECTORY_NAMESPACE');
        foreach ($names as $name) {
            if ($name === '.' || $name === '..') continue;
            nhep_expect(is_string($name) && $name !== '' && !str_contains($name, "\0") && !str_contains($name, '/'),
                'NHE_FILE_REAL_DIRECTORY_LEAF_NAME');
            $walk($path . '/' . $name, $relative === '' ? $name : $relative . '/' . $name);
        }
        clearstatcache(true, $path); $after = lstat($path);
        nhep_expect(is_array($after) && !is_link($path) && realpath($path) === $path
            && nhep_file_stat($after) === $stat && scandir($path) === $names,
            'NHE_FILE_COMPLETE_DIRECTORY_STAT_AND_NAMESPACE_STABLE');
    };
    $walk($root, ''); ksort($result, SORT_STRING); return $result;
}

/** Complete private bytes from original output files; never move shared writer offsets. */
function nhep_child_stream_capture(array &$children, array $runtimeTree): array
{
    $result = [];
    foreach (['http', 'channel'] as $kind) {
        nhep_expect(isset($children[$kind]) && $children[$kind]['kind'] === $kind
            && $children[$kind]['closed'] === null, 'NHE_STREAM_CAPTURE_ORIGINAL_LIVE_REGISTERED_CHILD');
        foreach (['stdout', 'stderr'] as $name) {
            $stream = $children[$kind]['streams'][$name] ?? null;
            $leaf = 'legacy-' . $kind . '.' . $name; $path = '/legacy-runtime/' . $leaf;
            nhep_expect(is_array($stream) && $stream['path'] === $path && is_resource($stream['handle'])
                && get_resource_type($stream['handle']) === 'stream' && is_array($stream['created']),
                'NHE_STREAM_CAPTURE_SAME_ORIGINAL_OWNED_OUTPUT_HANDLE');
            clearstatcache(true, $path); $named = lstat($path); $owned = fstat($stream['handle']);
            nhep_expect(is_array($named) && is_array($owned) && is_file($path) && !is_link($path)
                && realpath($path) === $path, 'NHE_STREAM_CAPTURE_ORIGINAL_REGULAR_NAMED_FILE');
            $stat = nhep_file_stat($named);
            foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
                nhep_expect($stat[$key] === $stream['created'][$key], 'NHE_STREAM_CAPTURE_ORIGINAL_CREATED_IDENTITY');
            nhep_expect(($stat['mode'] & 0777) === 0600 && $stat['nlink'] === 1 && $stat['uid'] === posix_geteuid()
                && $stat['size'] >= 0 && $stat['size'] <= 16777216 && nhep_file_stat($owned) === $stat,
                'NHE_STREAM_CAPTURE_COMPLETE_ORIGINAL_PRIVATE_OUTPUT');
            $raw = file_get_contents($path); clearstatcache(true, $path);
            $after = lstat($path); $ownedAfter = fstat($stream['handle']);
            nhep_expect(is_string($raw) && strlen($raw) === $stat['size'] && is_array($after) && is_array($ownedAfter)
                && !is_link($path) && realpath($path) === $path && nhep_file_stat($after) === $stat
                && nhep_file_stat($ownedAfter) === $stat, 'NHE_STREAM_CAPTURE_FULL_BYTES_AND_STAT_NINE_STABLE');
            $pin = ['bytes' => strlen($raw), 'sha256' => hash('sha256', $raw)];
            nhep_expect(($runtimeTree[$leaf] ?? null) === ['kind' => 'file', 'stat' => $stat] + $pin,
                'NHE_STREAM_CAPTURE_FULL_BYTES_BOUND_TO_SAME_RUNTIME_TREE');
            $result[$kind][$name] = ['path' => $path, 'stat' => $stat] + $pin + ['raw' => $raw]; unset($raw);
        }
    }
    return $result;
}

/** Join the already fully qualified parent to its original receipts before read-only observation. */
function nhep_observation_parent(array $qualified): void
{
    nhep_expect(PHP_SAPI === 'cli' && __FILE__ === '/run/nonempty/legacy-history-producer.php'
        && realpath($_SERVER['SCRIPT_FILENAME'] ?? '') === __FILE__ && getcwd() === '/legacy-workspace/crmeb'
        && is_array($qualified['freeze_pin'] ?? null) && is_array($qualified['context'] ?? null)
        && is_array($qualified['process'] ?? null), 'NHE_OBSERVATION_ORIGINAL_DIRECT_QUALIFIED_PARENT');
    $freeze = json_decode(nhe_file('/run/audit/preparation-source-binding.json', $qualified['freeze_pin']),
        true, 128, JSON_THROW_ON_ERROR);
    nhep_expect(is_array($freeze) && ($freeze['schema'] ?? null) === 1
        && ($freeze['status'] ?? null) === 'CLEAN_SOURCE_FROZEN_ONLY'
        && ($freeze['nonempty_history'] ?? null) === ($qualified['authority'] ?? null)
        && ($freeze['source_sha'] ?? null) === ($qualified['context']['source_sha'] ?? null)
        && $qualified['context']['source_sha'] === getenv('AUDIT_SOURCE_SHA')
        && $qualified['context']['run_id'] === getenv('AUDIT_RUN_ID'), 'NHE_OBSERVATION_ORIGINAL_SOURCE_RUN_AUTHORITY');
    foreach (['context_raw' => '/run/audit/actual-run-context.json', 'manifest_raw' => '/run/audit/manifest.json',
        'created_raw' => '/run/audit/evidence/audit-legacy-history-producer-container-created.json',
        'binding_raw' => '/run/audit/evidence/audit-legacy-history-producer-source-binding.json'] as $key => $path) {
        nhep_expect(is_string($qualified[$key] ?? null), 'NHE_OBSERVATION_ORIGINAL_COMPLETE_QUALIFIED_RECEIPT');
        nhe_file($path, ['path' => $path, 'bytes' => strlen($qualified[$key]), 'sha256' => hash('sha256', $qualified[$key])]);
    }
    $manifest = json_decode($qualified['manifest_raw'], true, 128, JSON_THROW_ON_ERROR);
    nhep_expect(is_array($manifest) && ($manifest['guard_mode'] ?? null) === 'read-only',
        'NHE_OBSERVATION_ONLY_EXISTING_ORDINARY_READ_ONLY_GUARD');
    audit_guard_assert();
    $parent = nhe_parent_process($qualified);
    nhep_expect($parent['receipt']['pid'] === getmypid(), 'NHE_OBSERVATION_SAME_ACTUAL_PRODUCER_PARENT');
    foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
        nhep_expect($parent['native'][$key] === $qualified['process'][$key], 'NHE_OBSERVATION_ORIGINAL_FIVE_PARENT_IDENTITIES');
    foreach ($qualified['authority']['control_files'] as $pin) nhe_file($pin['path'], $pin);
    nhe_includes($qualified);
}

/** Exact seven comparison parts; raw Redis and native proofs never leave caller-owned private RAM. */
function nhep_observation(array $qualified, PDO $db, Redis $redis, array &$children, array &$privateReadback): array
{
    $observationStart = time();
    nhep_observation_parent($qualified);
    nhep_expect(function_exists('nheh_snapshot'), 'NHE_OBSERVATION_FROZEN_SEVEN_PART_CONSUMER_LOADED');
    nhep_expect(is_array($children['http']['http_time_reference'] ?? null), 'NHE_OBSERVATION_ORIGINAL_HTTP_TIME_REFERENCE_REQUIRED');
    $httpTimeReference = nhep_http_time_reference($children['http']['http_time_reference']);
    $first = [];
    foreach (['http', 'channel'] as $kind) $first[$kind] = nhep_child_observation($children, $kind);
    $privateReadback = ['actual_interval' => [$observationStart, null], 'native_before' => $first,
        'redis_native' => null, 'native_streams' => null, 'native_after' => null, 'http_time_reference' => null];
    $database = nhep_database_capture($db, $qualified['context']['run_id']);
    $cache = nhep_redis_capture($redis, $qualified['context']['run_id']);
    $privateReadback['redis_native'] = $cache['native'];
    $snapshot = ['database' => $database['database'], 'rows' => $database['rows'], 'redis' => $cache['snapshot'],
        'private' => ['app' => nhep_file_tree('/run/audit-app'),
            'fixtures' => nhep_file_tree('/run/audit-fixtures')],
        'public' => ['legacy_public' => nhep_file_tree('/legacy-workspace/crmeb/public')],
        'logs' => ['runtime' => nhep_file_tree('/legacy-runtime'),
            'legacy_root_runtime' => nhep_file_tree('/legacy-workspace/crmeb/runtime')], 'native' => []];
    nhep_expect(is_array($snapshot['logs']['runtime']), 'NHE_OBSERVATION_ORIGINAL_RUNTIME_PRESENT');
    $privateReadback['native_streams'] = nhep_child_stream_capture($children, $snapshot['logs']['runtime']);
    $last = [];
    foreach (['http', 'channel'] as $kind) {
        $last[$kind] = nhep_child_observation($children, $kind);
        nhep_expect($last[$kind]['native'] === $first[$kind]['native'] && $last[$kind]['group'] === $first[$kind]['group'],
            'NHE_OBSERVATION_SAME_OWNED_CHILD_HANDLE_AND_GROUP_DURING_SNAPSHOT');
        $snapshot['native'][$kind] = $last[$kind]['native'];
    }
    $privateReadback['native_after'] = $last; nhe_includes($qualified); nheh_snapshot($snapshot);
    nhep_http_time_reference($httpTimeReference);
    $privateReadback['http_time_reference'] = $httpTimeReference;
    $privateReadback['actual_interval'][1] = time();
    nhep_expect($privateReadback['actual_interval'][1] >= $observationStart, 'NHE_OBSERVATION_REAL_WALL_CLOCK_INTERVAL');
    return $snapshot;
}

/** Source-reviewed first-six normal HTTP models; no execution or observer dispatch. */
/** SOURCE-ONLY candidate. Definitions only; no loader, entry, PDO or resource call.
 * Private complete rows, requests and responses must remain in private RAM.
 * Source/Run/actor/child qualification and the remaining observation parts stay
 * with the original producer. This finite DB model never proves token validity.
 */
function nhep_auth_db_snapshot(array $view): void
{
    nhe_keys($view, ['database', 'rows'], 'NHE_AUTH_DB_FULL_VIEW');
    nhe_keys($view['database'], ['names', 'modes', 'tables'], 'NHE_AUTH_DB_FULL_DATABASE');
    $names = $view['database']['names']; $sorted = $names; sort($sorted, SORT_STRING);
    nhep_expect(array_is_list($names) && count($names) === 164 && $names === $sorted
        && count(array_unique($names, SORT_STRING)) === 164 && is_array($view['database']['modes'])
        && array_keys($view['database']['tables']) === $names && array_keys($view['rows']) === $names,
        'NHE_AUTH_DB_ORIGINAL_ALL_164_TABLES');
    foreach ($names as $name) {
        $table = $view['database']['tables'][$name];
        nhe_keys($table, ['metadata', 'ddl', 'projected_columns', 'projection'], 'NHE_AUTH_DB_FULL_TABLE');
        nhep_expect(is_array($table['metadata']) && is_array($table['metadata']['columns'] ?? null)
            && is_string($table['ddl']) && $table['ddl'] !== ''
            && $table['projected_columns'] === array_keys($table['metadata']['columns'])
            && is_array($view['rows'][$name]) && array_is_list($view['rows'][$name]),
            'NHE_AUTH_DB_ORIGINAL_COLUMNS_DDL_AND_ROWS');
        foreach ($view['rows'][$name] as $row) nhep_expect(is_array($row)
            && array_keys($row) === $table['projected_columns'], 'NHE_AUTH_DB_EACH_FULL_ORIGINAL_ROW');
        $rows = $view['rows'][$name];
        usort($rows, static fn(array $a, array $b): int => strcmp(serialize($a), serialize($b)));
        nhep_expect($rows === $view['rows'][$name]
            && m4lh_actor_projection($rows) === $table['projection'], 'NHE_AUTH_DB_FULL_NATIVE_PROJECTION');
    }
    foreach (['eb_system_admin', 'eb_user', 'eb_system_log', 'eb_system_menus',
        'eb_marketplace_merchant', 'eb_marketplace_employee', 'eb_marketplace_audit_log',
        'eb_system_event', 'eb_system_notification'] as $name)
        nhep_expect(in_array($name, $names, true), 'NHE_AUTH_DB_REQUIRED_REAL_TABLE');
}

/** Locate one independently named identity; no row or projection is returned. */
function nhep_auth_db_index(array $rows, array $metadata, string $pk, int $id): int
{
    nhep_expect($id > 0 && isset($metadata['columns'][$pk]), 'NHE_AUTH_DB_REAL_ID_COLUMN');
    $wanted = m4lh_actor_native($metadata['columns'][$pk], $id); $matches = [];
    foreach ($rows as $index => $row) {
        nhep_expect(array_key_exists($pk, $row)
            && m4lh_actor_native($metadata['columns'][$pk], $row[$pk]) === $row[$pk],
            'NHE_AUTH_DB_ORIGINAL_NATIVE_ID_TYPE');
        if ($row[$pk] === $wanted) $matches[] = $index;
    }
    nhep_expect(count($matches) === 1, 'NHE_AUTH_DB_ONE_ACTUAL_NAMED_IDENTITY');
    return $matches[0];
}

/** The only accepted observed scalar is a native unsigned timestamp in this HTTP interval. */
function nhep_auth_db_time(array $metadata, string $column, mixed $value, array $interval, int $minimum = 0): int
{
    $definition = $metadata['columns'][$column] ?? null;
    nhep_expect(is_array($definition)
        && preg_match('/\Aint(?:\([0-9]+\))? unsigned\z/D', strtolower($definition['COLUMN_TYPE'])) === 1
        && $definition['IS_NULLABLE'] === 'NO' && is_int($value)
        && m4lh_actor_native($definition, $value) === $value
        && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 4294967295
        && $value >= $interval[0] && $value <= $interval[1]
        && $value >= $minimum, 'NHE_AUTH_DB_INDEPENDENT_NATIVE_HTTP_TIME_WINDOW');
    return $value;
}

/** Clone complete BEFORE rows; overrides are finite producer fields only. */
function nhep_auth_db_update(array $before, string $table, int $index, array $changes): array
{
    $rows = $before['rows'][$table]; $columns = $before['database']['tables'][$table]['metadata']['columns'];
    nhep_expect(isset($rows[$index]) && $changes !== []
        && array_diff(array_keys($changes), array_keys($columns)) === [], 'NHE_AUTH_DB_EXPLICIT_BEFORE_UPDATE');
    foreach ($changes as $name => $value) $rows[$index][$name] = m4lh_actor_native($columns[$name], $value);
    return $rows;
}

/** Original auto-increment must supply exactly the BEFORE next ID, not an arbitrary after ID. */
function nhep_auth_db_append(array $before, array $actual, string $table, array $values, array $interval): array
{
    $original = $before['database']['tables'][$table]; $id = m4lh_actor_next($original, 'id');
    foreach ($before['rows'][$table] as $row)
        nhep_expect($row['id'] !== $id, 'NHE_AUTH_DB_NEXT_ID_ABSENT_BEFORE');
    $index = nhep_auth_db_index($actual['rows'][$table], $original['metadata'], 'id', $id);
    nhep_expect(!array_key_exists('id', $values) && !array_key_exists('add_time', $values),
        'NHE_AUTH_DB_INSERT_ID_TIME_NOT_CALLER_OVERRIDES');
    $time = nhep_auth_db_time($original['metadata'], 'add_time',
        $actual['rows'][$table][$index]['add_time'], $interval);
    $row = m4lh_actor_expected_row($original['metadata'], ['id' => $id] + $values + ['add_time' => $time]);
    $rows = $before['rows'][$table]; $rows[] = $row;
    return $rows;
}

/** These are actual BEFORE selectors, not a waiver of event/Channel observation. */
function nhep_auth_db_login_events(array $before, string $mark, bool $customerNotice): void
{
    $event = $before['database']['tables']['eb_system_event']['metadata']['columns'];
    foreach (['mark', 'is_del', 'is_open'] as $field)
        nhep_expect(isset($event[$field]), 'NHE_AUTH_DB_ORIGINAL_CUSTOM_EVENT_SCHEMA');
    foreach ($before['rows']['eb_system_event'] as $row) {
        // The dedicated fixture contract has no enabled custom code at all.
        // Refuse enabled rows even for another mark instead of guessing collation.
        $deleted = m4lh_actor_native($event['is_del'], $row['is_del']);
        $open = m4lh_actor_native($event['is_open'], $row['is_open']);
        nhep_expect(is_int($deleted) && is_int($open) && !($deleted === 0 && $open === 1),
            'NHE_AUTH_DB_NO_ENABLED_CUSTOM_CODE');
    }
    nhep_expect(in_array($mark, ['admin_login', 'user_login'], true), 'NHE_AUTH_DB_FINITE_LOGIN_EVENT_MARK');
    if (!$customerNotice) return;
    $notification = $before['database']['tables']['eb_system_notification']['metadata']['columns'];
    $channels = ['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat'];
    foreach (array_merge(['custom_trigger'], $channels) as $field)
        nhep_expect(isset($notification[$field]), 'NHE_AUTH_DB_ORIGINAL_CUSTOM_NOTICE_SCHEMA');
    foreach ($before['rows']['eb_system_notification'] as $row) {
        // The prepared fixture disables every native notification channel.
        // This stronger existing input also closes SQL collation ambiguity.
        foreach ($channels as $field) nhep_expect(
            m4lh_actor_native($notification[$field], $row[$field]) === 0,
            'NHE_AUTH_DB_NO_ENABLED_LOGIN_NOTICE_CHANNEL');
    }
}

/** getVisitName is an unordered exact api_url lookup. Refuse ambiguity. */
function nhep_auth_db_visit_page(array $before): string
{
    $columns = $before['database']['tables']['eb_system_menus']['metadata']['columns'];
    nhep_expect(isset($columns['api_url'], $columns['menu_name']), 'NHE_AUTH_DB_VISIT_MENU_REAL_COLUMNS');
    $names = [];
    foreach ($before['rows']['eb_system_menus'] as $row) {
        nhep_expect(is_string($row['api_url']) && is_string($row['menu_name']), 'NHE_AUTH_DB_NATIVE_MENU_TEXT');
        nhep_expect(strtolower(rtrim($row['api_url'], ' ')) !== 'setting/info' || $row['api_url'] === 'setting/info',
            'NHE_AUTH_DB_CANONICAL_BEFORE_VISIT_URL');
        if ($row['api_url'] === 'setting/info') $names[] = $row['menu_name'];
    }
    nhep_expect(count($names) <= 1, 'NHE_AUTH_DB_UNAMBIGUOUS_BEFORE_MENU_VALUE');
    return ($names[0] ?? '') ?: '未知';
}

/**
 * Finite first-six-step independent DB oracle. No actual metadata/row/projection
 * enters expected. Only checked original IDs and time-window scalars may enter.
 * Strict comparison includes all 164 tables, old rows, metadata, modes and DDL.
 */
function nhep_auth_database_model(array $before, array $actual, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_database_expected', 'm4lh_actor_native',
        'm4lh_actor_projection', 'm4lh_actor_expected_row', 'm4lh_actor_next'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_AUTH_DB_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($before); nhep_auth_db_snapshot($actual);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'], 'NHE_AUTH_DB_HTTP_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHE_AUTH_DB_PRIVATE_REQUEST');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHE_AUTH_DB_PRIVATE_ACTOR');
    $steps = [
        'admin_login' => [1, 'POST', '/adminapi/login', 'admin'],
        'admin_identity' => [2, 'GET', '/adminapi/setting/info', 'admin'],
        'platform_self_merchant_review' => [3, 'PUT', 'review', 'admin'],
        'platform_self_merchant_accept_orders' => [4, 'PUT', 'flags', 'admin'],
        'customer_login' => [5, 'POST', '/api/login', 'customer'],
        'customer_identity' => [6, 'GET', '/api/userinfo', 'customer'],
    ];
    $step = $intent['step'];
    nhep_expect(is_string($step) && isset($steps[$step]), 'NHE_AUTH_DB_STEP_NOT_IMPLEMENTED');
    [$sequence, $method, $route, $actor] = $steps[$step];
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === $method && $intent['actor'] === $actor
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['origin']) && preg_match('~\Ahttp://127\.0\.0\.1:([1-9][0-9]{0,4})\z~D', $intent['origin'], $origin) === 1
        && (int)$origin[1] <= 65535 && is_string($intent['path']), 'NHE_AUTH_DB_EXACT_QUALIFIED_NORMAL_STEP');
    $target = null;
    if ($route === 'review' || $route === 'flags') {
        nhep_expect(preg_match('~\A/adminapi/marketplace/merchants/([1-9][0-9]{0,9})/' . $route . '\z~D', $intent['path'], $match) === 1
            && (int)$match[1] <= 4294967295, 'NHE_AUTH_DB_REAL_FIXTURE_MERCHANT_PATH');
        $target = (int)$match[1];
    } else nhep_expect($intent['path'] === $route, 'NHE_AUTH_DB_EXACT_ROUTE');
    $identity = $privateRequest['actor_identity']; $id = $identity['id']; $account = $identity['account'];
    nhep_expect(is_int($id) && $id > 0 && $intent['actor_id'] === $id
        && is_string($account) && preg_match('/\A[a-z0-9_]{10,32}\z/D', $account) === 1,
        'NHE_AUTH_DB_ACTUAL_PRIVATE_FIXTURE_ID_ACCOUNT');
    $actorTable = $actor === 'admin' ? 'eb_system_admin' : 'eb_user'; $pk = $actor === 'admin' ? 'id' : 'uid';
    $actorMeta = $before['database']['tables'][$actorTable]['metadata'];
    $index = nhep_auth_db_index($before['rows'][$actorTable], $actorMeta, $pk, $id);
    $actualIndex = nhep_auth_db_index($actual['rows'][$actorTable], $actorMeta, $pk, $id);
    $owner = $before['rows'][$actorTable][$index];
    nhep_expect($owner['account'] === $account && $actual['rows'][$actorTable][$actualIndex]['account'] === $account
        && $owner['status'] === 1 && $owner['is_del'] === 0
        && ($actor !== 'admin' || $owner['level'] === 0), 'NHE_AUTH_DB_SAME_NATIVE_ELIGIBLE_OWNER');
    $login = $step === 'admin_login' || $step === 'customer_login';
    $token = $privateRequest['token']; $body = $privateRequest['body'];
    nhep_expect($login ? $token === null : (is_string($token)
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $token) === 1), 'NHE_AUTH_DB_REAL_LOGIN_OR_AUTHENTICATED_REQUEST');
    nhep_expect(($method === 'GET') ? $body === null : is_array($body), 'NHE_AUTH_DB_ORIGINAL_BODY_METHOD');
    $interval = $privateResponse['actual_interval'] ?? null;
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0 && $interval[0] <= $interval[1]
        && $interval[1] <= 4294967295
        && ($privateResponse['http'] ?? null) === 200 && ($privateResponse['transport_errno'] ?? null) === 0
        && array_key_exists('transport_failure_class', $privateResponse) && $privateResponse['transport_failure_class'] === null
        && ($privateResponse['primary_ip'] ?? null) === '127.0.0.1' && ($privateResponse['primary_port'] ?? null) === (int)$origin[1]
        && is_string($privateResponse['raw'] ?? null) && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json'] ?? null), 'NHE_AUTH_DB_REAL_COMPLETE_NORMAL_HTTP_RESPONSE');
    $json = $privateResponse['json']; $decoded = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $json && ($json['status'] ?? null) === 200
        && is_string($json['msg'] ?? null) && is_array($json['data'] ?? null), 'NHE_AUTH_DB_ORIGINAL_SUCCESS_JSON');
    $data = $json['data']; $expectedRows = []; $inserts = [];
    if ($login) {
        $passwordKey = $actor === 'admin' ? 'pwd' : 'password';
        nhep_expect(($body['account'] ?? null) === $account && is_string($body[$passwordKey] ?? null)
            && strlen($body[$passwordKey]) >= 6 && strlen($body[$passwordKey]) <= 32,
            'NHE_AUTH_DB_REAL_BEFORE_CREDENTIAL_INPUT');
        if ($actor === 'admin') {
            nhe_keys($body, ['account', 'pwd', 'key', 'captchaVerification', 'captchaType'], 'NHE_AUTH_DB_PLATFORM_LOGIN_BODY');
            nhep_expect($body['key'] === '' && $body['captchaVerification'] === '' && $body['captchaType'] === ''
                && password_verify($body['pwd'], $owner['pwd']), 'NHE_AUTH_DB_PLATFORM_ORIGINAL_PASSWORD_MATCH');
            $info = $data['user_info'] ?? null;
            nhep_expect(is_array($info) && ($info['id'] ?? null) === $id && ($info['account'] ?? null) === $account
                && ($info['level'] ?? null) === 0, 'NHE_AUTH_DB_PLATFORM_LOGIN_NATIVE_RESPONSE_OWNER');
            nhep_auth_db_login_events($before, 'admin_login', false);
        } else {
            nhe_keys($body, ['account', 'password', 'spread', 'agent_id'], 'NHE_AUTH_DB_CUSTOMER_LOGIN_BODY');
            nhep_expect($body['spread'] === 0 && $body['agent_id'] === 0
                && $owner['pwd'] === md5($body['password']) && $owner['pwd'] !== md5('123456'),
                'NHE_AUTH_DB_CUSTOMER_ORIGINAL_PASSWORD_NO_SPREAD_OR_STAFF');
            nhep_auth_db_login_events($before, 'user_login', true);
        }
        nhep_expect(is_string($data['token'] ?? null)
            && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $data['token']) === 1
            && is_int($data['expires_time'] ?? null) && $data['expires_time'] > $interval[0],
            'NHE_AUTH_DB_REAL_LOGIN_RESPONSE_TOKEN_CACHE_PROOF_STILL_SEPARATE');
        $time = nhep_auth_db_time($actorMeta, 'last_time',
            $actual['rows'][$actorTable][$actualIndex]['last_time'], $interval, $owner['last_time']);
        $changes = ['last_time' => $time, 'last_ip' => '127.0.0.1'];
        if ($actor === 'admin') {
            nhep_expect(is_int($owner['login_count']) && $owner['login_count'] >= 0
                && $owner['login_count'] < 4294967295, 'NHE_AUTH_DB_BEFORE_LOGIN_COUNTER_NO_OVERFLOW');
            $changes['login_count'] = $owner['login_count'] + 1;
        }
        $expectedRows[$actorTable] = nhep_auth_db_update($before, $actorTable, $index, $changes);
    } elseif ($step === 'admin_identity') {
        nhep_expect(($data['id'] ?? null) === $id && ($data['account'] ?? null) === $account,
            'NHE_AUTH_DB_PLATFORM_IDENTITY_REAL_RESPONSE');
        $expectedRows['eb_system_log'] = nhep_auth_db_append($before, $actual, 'eb_system_log', [
            'admin_id' => $id, 'admin_name' => $account, 'path' => 'setting/info',
            'page' => nhep_auth_db_visit_page($before), 'method' => 'adminapi', 'ip' => '127.0.0.1', 'type' => 'system',
        ], $interval);
        $inserts['eb_system_log'] = 1;
    } elseif ($step === 'customer_identity') {
        // Old User DTO hides account; use the full native owner binding above.
        nhep_expect(($data['uid'] ?? null) === $id, 'NHE_AUTH_DB_CUSTOMER_IDENTITY_REAL_UID');
        $time = nhep_auth_db_time($actorMeta, 'last_time',
            $actual['rows'][$actorTable][$actualIndex]['last_time'], $interval, $owner['last_time']);
        $expectedRows[$actorTable] = nhep_auth_db_update($before, $actorTable, $index, ['last_time' => $time]);
    } else {
        nhep_expect(is_int($target) && $target > 0, 'NHE_AUTH_DB_ACTUAL_MERCHANT_TARGET_REQUIRED');
        $table = 'eb_marketplace_merchant'; $meta = $before['database']['tables'][$table]['metadata'];
        $merchantIndex = nhep_auth_db_index($before['rows'][$table], $meta, 'mer_id', $target);
        $observedIndex = nhep_auth_db_index($actual['rows'][$table], $meta, 'mer_id', $target);
        $merchant = $before['rows'][$table][$merchantIndex];
        $field = $route === 'review' ? 'review_status' : 'accept_orders';
        nhe_keys($body, [$field], 'NHE_AUTH_DB_EXACT_SINGLE_MERCHANT_CHANGE_BODY');
        nhep_expect($body[$field] === 1 && $merchant[$field] === 0 && $merchant['closed_at'] === null
            && $merchant['security_locked'] === 0 && $merchant['fulfillment_enabled'] === 1
            && ($route !== 'flags' || $merchant['review_status'] === 1), 'NHE_AUTH_DB_REAL_MERCHANT_TRANSITION');
        $time = nhep_auth_db_time($meta, 'update_time', $actual['rows'][$table][$observedIndex]['update_time'],
            $interval, $merchant['update_time']);
        $expectedRows[$table] = nhep_auth_db_update($before, $table, $merchantIndex, [$field => 1, 'update_time' => $time]);
        // These are the DAO's original PLATFORM_FIELDS, independently built.
        $responseMerchant = $expectedRows[$table][$merchantIndex];
        $publicFields = ['mer_id', 'name', 'logo', 'after_sale_contact', 'shipping_note', 'review_status',
            'accept_orders', 'fulfillment_enabled', 'security_locked', 'closed_at', 'add_time', 'update_time'];
        $publicExpected = [];
        foreach ($publicFields as $name) $publicExpected[$name] = $responseMerchant[$name];
        nhep_expect($data === $publicExpected, 'NHE_AUTH_DB_MERCHANT_RESPONSE_EQUALS_INDEPENDENT_PLATFORM_FIELDS');
        $protected = 0;
        if ($route === 'review') {
            $employeeMeta = $before['database']['tables']['eb_marketplace_employee']['metadata'];
            nhep_expect(isset($employeeMeta['columns']['id'], $employeeMeta['columns']['mer_id']),
                'NHE_AUTH_DB_ORIGINAL_EMPLOYEE_BINDING_SCHEMA');
            $employeeIds = [];
            foreach ($before['rows']['eb_marketplace_employee'] as $employee) {
                $employeeMer = m4lh_actor_native($employeeMeta['columns']['mer_id'], $employee['mer_id']);
                $employeeId = m4lh_actor_native($employeeMeta['columns']['id'], $employee['id']);
                nhep_expect(is_int($employeeMer) && $employeeMer > 0 && is_int($employeeId) && $employeeId > 0
                    && !isset($employeeIds[$employeeId]), 'NHE_AUTH_DB_REAL_UNIQUE_EMPLOYEE_BINDINGS');
                $employeeIds[$employeeId] = true;
                if ($employeeMer === $target) $protected++;
            }
        }
        $audit = 'eb_marketplace_audit_log';
        nhep_expect(strtolower($before['database']['tables'][$audit]['metadata']['columns']['detail']['COLUMN_TYPE']) === 'json',
            'NHE_AUTH_DB_ORIGINAL_AUDIT_JSON_COLUMN');
        // MySQL native JSON formatting for this exact two-field ASCII object.
        // It is built only from fixed changed field + independent before count.
        $detail = '{"changed_fields": ["' . $field . '"], "protected_employee_count": ' . $protected . '}';
        $expectedRows[$audit] = nhep_auth_db_append($before, $actual, $audit, [
            'mer_id' => $target, 'actor_type' => 'admin', 'actor_id' => $id,
            'action' => 'marketplace-merchants-' . $route, 'resource_type' => 'merchant',
            'resource_id' => (string)$target, 'result' => 'success', 'detail' => $detail,
        ], $interval);
        $inserts[$audit] = 1;
    }
    $expected = nhep_database_expected($before, $expectedRows, $inserts);
    nhep_expect($expected === $actual, 'NHE_AUTH_DB_ALL_164_TABLES_COMPLETE_INDEPENDENT_EXPECTED');
    return $expected;
}

/** Pure candidate definitions. No App, token issuer, Redis client or entry point is loaded. */
function nhepar_uint(mixed $value, bool $zero = false): int
{
    nhep_expect((is_int($value) || is_string($value))
        && preg_match('/\A(?:0|[1-9][0-9]{0,9})\z/D', (string)$value) === 1
        && bccomp((string)$value, '4294967295', 0) <= 0
        && ($zero || (string)$value !== '0'), 'NHEPAR_INDEPENDENT_NATIVE_UNSIGNED_VALUE');
    return (int)$value;
}

function nhepar_pairs(array $fields): array
{
    $pairs = [];
    foreach ($fields as $field => $value) {
        nhep_expect(is_string($field) && is_string($value), 'NHEPAR_INDEPENDENT_HASH_STRING_FIELDS');
        $pairs[] = [$field, $value];
    }
    usort($pairs, static fn(array $a, array $b): int => strcmp($a[0], $b[0]));
    return $pairs;
}

/** Check the complete private capture envelope before using any single original key. */
function nhepar_capture(array $capture): void
{
    nhe_keys($capture, ['snapshot', 'native'], 'NHEPAR_CAPTURE_EXACT_TWO_KEYS');
    nhep_expect(is_array($capture['snapshot']) && is_array($capture['native']), 'NHEPAR_CAPTURE_ARRAYS');
    nhep_redis_snapshot($capture['snapshot']);
    nhep_expect(array_keys($capture['native']) === array_keys($capture['snapshot']['keys']), 'NHEPAR_COMPLETE_NATIVE_NAMESPACE');
    foreach ($capture['native'] as $keyHash => $row) {
        nhep_expect(is_array($row), 'NHEPAR_COMPLETE_NATIVE_ROW');
        nhe_keys($row, ['key', 'type', 'dump', 'dump_sha256', 'expires', 'value'], 'NHEPAR_NATIVE_EXACT_SIX_KEYS');
        nhep_expect(is_string($row['key']) && hash('sha256', $row['key']) === $keyHash
            && is_string($row['dump']) && $row['dump'] !== ''
            && hash('sha256', $row['dump']) === $row['dump_sha256'], 'NHEPAR_NATIVE_FULL_KEY_AND_DUMP_BYTES');
        $value = $row['value'];
        if ($row['type'] === 'string') {
            nhep_expect(is_string($value), 'NHEPAR_NATIVE_STRING_BYTES');
        } elseif ($row['type'] === 'hash') {
            nhep_expect(is_array($value) && array_is_list($value), 'NHEPAR_NATIVE_HASH_PAIRS'); $previous = null;
            foreach ($value as $pair) {
                nhep_expect(is_array($pair) && array_is_list($pair) && count($pair) === 2
                    && is_string($pair[0]) && is_string($pair[1])
                    && ($previous === null || strcmp($previous, $pair[0]) < 0), 'NHEPAR_NATIVE_COMPLETE_SORTED_HASH');
                $previous = $pair[0];
            }
        } elseif ($row['type'] === 'set') {
            nhep_expect(is_array($value) && array_is_list($value), 'NHEPAR_NATIVE_SET_MEMBERS'); $previous = null;
            foreach ($value as $member) {
                nhep_expect(is_string($member) && ($previous === null || strcmp($previous, $member) < 0), 'NHEPAR_NATIVE_COMPLETE_SORTED_SET');
                $previous = $member;
            }
        } else {
            nhep_expect($value === false, 'NHEPAR_OTHER_NATIVE_TYPES_COMPLETE_DUMP_ONLY');
        }
        $digest = $row['type'] === 'set' ? hash('sha256', "set\0" . serialize($value)) : $row['dump_sha256'];
        nhep_expect($capture['snapshot']['keys'][$keyHash] === ['type' => $row['type'], 'sha256' => $digest,
            'expires' => $row['expires']], 'NHEPAR_NATIVE_AND_COMPARISON_DESCRIPTOR_JOIN');
    }
}

function nhepar_entry(array $capture, string $key): ?array
{
    $row = $capture['native'][hash('sha256', $key)] ?? null;
    nhep_expect($row === null || $row['key'] === $key, 'NHEPAR_EXACT_ORIGINAL_RAW_KEY');
    return $row;
}

/** The actual digest is adopted only after complete independent type/value/expiry proof. */
function nhepar_bind(array $actual, string $key, string $type, mixed $value, int|array $expiry,
    array $beforeSnapshot): array
{
    $row = nhepar_entry($actual, $key);
    nhep_expect(is_array($row) && $row['type'] === $type && $row['value'] === $value,
        'NHEPAR_COMPLETE_INDEPENDENT_NATIVE_VALUE');
    if (is_int($expiry)) {
        nhep_expect($row['expires'] === $expiry, 'NHEPAR_INDEPENDENT_FIXED_ABSOLUTE_EXPIRY');
    } else {
        nhe_keys($expiry, ['ttl'], 'NHEPAR_EXACT_INDEPENDENT_RELATIVE_TTL');
        nhep_expect(is_int($expiry['ttl']) && $expiry['ttl'] > 0, 'NHEPAR_POSITIVE_SOURCE_TTL');
        $milliseconds = bcmul((string)$expiry['ttl'], '1000', 0);
        $earliest = bcadd($beforeSnapshot['time_ms'], $milliseconds, 0);
        $latest = bcadd($actual['snapshot']['time_ms'], $milliseconds, 0);
        nhep_expect(is_int($row['expires']) && bccomp((string)$row['expires'], $earliest, 0) >= 0
            && bccomp((string)$row['expires'], $latest, 0) <= 0, 'NHEPAR_SOURCE_TTL_WITHIN_ACTUAL_REDIS_CLOCK_WINDOW');
    }
    return ['type' => $type, 'sha256' => $actual['snapshot']['keys'][hash('sha256', $key)]['sha256'], 'expires' => $row['expires']];
}

/** Validate only an already-issued token. This never creates a JWT or calls the legacy token issuer. */
function nhepar_jwt(#[SensitiveParameter] string $token, #[SensitiveParameter] string $signingKey): array
{
    nhep_expect(strlen($token) >= 16 && strlen($token) <= 4096, 'NHEPAR_ACTUAL_ISSUED_TOKEN_LENGTH');
    $parts = explode('.', $token); nhep_expect(count($parts) === 3, 'NHEPAR_ACTUAL_ISSUED_TOKEN_THREE_PARTS'); $decoded = [];
    foreach ($parts as $part) {
        nhep_expect($part !== '' && preg_match('/\A[A-Za-z0-9_-]+\z/D', $part) === 1, 'NHEPAR_CANONICAL_TOKEN_BASE64URL');
        $raw = base64_decode(strtr($part, '-_', '+/') . str_repeat('=', (4 - strlen($part) % 4) % 4), true);
        nhep_expect(is_string($raw) && rtrim(strtr(base64_encode($raw), '+/', '-_'), '=') === $part,
            'NHEPAR_COMPLETE_TOKEN_BASE64URL_BYTES'); $decoded[] = $raw;
    }
    $header = json_decode($decoded[0], true, 8, JSON_THROW_ON_ERROR);
    $claims = json_decode($decoded[1], true, 16, JSON_THROW_ON_ERROR);
    nhep_expect(is_array($header) && !array_is_list($header) && is_array($claims) && !array_is_list($claims), 'NHEPAR_REAL_TOKEN_JSON_OBJECTS');
    nhe_keys($header, ['typ', 'alg'], 'NHEPAR_ORIGINAL_JWT_HEADER_FIELDS');
    nhep_expect($header['typ'] === 'JWT' && $header['alg'] === 'HS256' && strlen($decoded[2]) === 32
        && hash_equals(hash_hmac('sha256', $parts[0] . '.' . $parts[1], $signingKey, true), $decoded[2]),
        'NHEPAR_ACTUAL_JWT_SIGNATURE_VERIFIED');
    return $claims;
}

function nhepar_actor(array $rows, array $intent, array $request): array
{
    $admin = $intent['actor'] === 'admin'; $table = $admin ? 'eb_system_admin' : 'eb_user'; $pk = $admin ? 'id' : 'uid';
    nhep_expect(is_array($rows[$table] ?? null) && array_is_list($rows[$table]), 'NHEPAR_COMPLETE_ORIGINAL_ACTOR_TABLE');
    $id = nhepar_uint($intent['actor_id']); $matches = [];
    foreach ($rows[$table] as $row) if (nhepar_uint($row[$pk] ?? null) === $id) $matches[] = $row;
    nhep_expect(count($matches) === 1, 'NHEPAR_ONE_INDEPENDENT_BEFORE_ACTOR'); $actor = $matches[0];
    nhe_keys($request['actor_identity'], ['id', 'account'], 'NHEPAR_PRIVATE_ACTOR_IDENTITY_KEYS');
    nhep_expect($request['actor_identity']['id'] === $id && is_string($actor['account'] ?? null)
        && $request['actor_identity']['account'] === $actor['account'] && is_string($actor['pwd'] ?? null) && $actor['pwd'] !== ''
        && nhepar_uint($actor['status'] ?? null, true) === 1 && nhepar_uint($actor['is_del'] ?? null, true) === 0,
        'NHEPAR_REAL_BEFORE_ENABLED_ACTOR_AND_PRIVATE_IDENTITY');
    if ($admin) nhep_expect(nhepar_uint($actor['level'] ?? null, true) === 0 && is_string($actor['roles'] ?? null),
        'NHEPAR_FIXED_NORMAL_HIGHEST_ADMINISTRATOR');
    else nhep_expect(nhepar_uint($actor['spread_uid'] ?? null, true) === 0, 'NHEPAR_FIXED_CUSTOMER_WITHOUT_SPREAD_PARENT');
    return $actor;
}

function nhepar_time_claims(array $claims, array $interval, bool $new, array $actualSnapshot, bool $admin): void
{
    foreach (['iat', 'nbf', 'exp'] as $key) nhep_expect(is_int($claims[$key] ?? null) && $claims[$key] > 0
        && $claims[$key] <= 999999999999, 'NHEPAR_ORIGINAL_NATIVE_TOKEN_TIME_CLAIMS');
    nhep_expect($claims['nbf'] === $claims['iat']
        && ($new ? ($claims['iat'] >= $interval[0] && $claims['iat'] <= $interval[1]) : $claims['iat'] <= $interval[1])
        && bccomp(bcmul((string)$claims['exp'], '1000', 0), $actualSnapshot['time_ms'], 0) > 0,
        'NHEPAR_FIXED_ORIGINAL_TTL_AND_ACTUAL_ISSUE_OR_USE_WINDOW');
    if ($admin) {
        nhep_expect($claims['exp'] === $claims['iat'] + 2592000, 'NHEPAR_ADMIN_SINGLE_ORIGINAL_CLOCK_EXACT_TTL');
    } else {
        // Old JwtAuth takes time() and strtotime('+ 30day') independently.
        $expiryClock = $claims['exp'] - 2592000;
        nhep_expect($expiryClock >= $claims['iat'] && $expiryClock <= $interval[1]
            && (!$new || $expiryClock >= $interval[0]), 'NHEPAR_CUSTOMER_SECOND_ORIGINAL_CLOCK_IN_HTTP_WINDOW');
    }
}

/** One Think cache remember, independently derived from the known old source and BEFORE rows. */
function nhepar_remember(array $before, array $actual, string $logical, string $wire, int $ttl,
    array &$changes, array &$tagMembers): void
{
    $key = 'c:' . $logical; $old = nhepar_entry($before, $key);
    if ($old !== null) {
        nhep_expect($old['type'] === 'string' && $old['value'] === $wire, 'NHEPAR_BEFORE_CACHE_MATCHES_INDEPENDENT_DB_VALUE');
        nhep_expect($ttl === 0 ? $old['expires'] === -1 : ($old['expires'] > 0
            && bccomp((string)$old['expires'], $actual['snapshot']['time_ms'], 0) > 0), 'NHEPAR_CACHE_EXPIRY_BOUNDARY_BRANCH_NOT_IMPLEMENTED');
        $bound = nhepar_bind($actual, $key, 'string', $wire, $old['expires'], $before['snapshot']);
        nhep_expect($bound === $before['snapshot']['keys'][hash('sha256', $key)], 'NHEPAR_ORIGINAL_CACHE_VALUE_AND_DEADLINE_NOT_RENEWED');
    } else {
        $changes[$key] = nhepar_bind($actual, $key, 'string', $wire, $ttl === 0 ? -1 : ['ttl' => $ttl], $before['snapshot']);
    }
    $tagMembers[] = $key;
}

function nhepar_tag(array $before, array $actual, string $tag, array $append, array &$changes): void
{
    $key = 'c:CRMEB:' . md5($tag); $old = nhepar_entry($before, $key); $members = [];
    if ($old !== null) {
        nhep_expect($old['type'] === 'set' && $old['expires'] === -1 && is_array($old['value']), 'NHEPAR_ORIGINAL_PERMANENT_TAG_SET');
        $members = $old['value'];
    }
    foreach ($append as $member) nhep_expect(is_string($member), 'NHEPAR_INDEPENDENT_PHYSICAL_TAG_MEMBER');
    $members = array_values(array_unique(array_merge($members, $append), SORT_STRING)); sort($members, SORT_STRING);
    if ($members === []) {
        nhep_expect(nhepar_entry($actual, $key) === null, 'NHEPAR_NO_SPURIOUS_EMPTY_TAG'); return;
    }
    $changes[$key] = nhepar_bind($actual, $key, 'set', $members, -1, $before['snapshot']);
}

function nhepar_admin(array $before, array $actual, array $actor, array $intent, array $request, array $response,
    #[SensitiveParameter] array $configuration, array &$changes): void
{
    $new = $intent['step'] === 'admin_login'; $data = $new ? $response['json']['data'] : null;
    $token = $new ? ($data['token'] ?? null) : $request['token'];
    nhep_expect(is_string($token), 'NHEPAR_ORIGINAL_ADMIN_TOKEN_REQUIRED'); $claims = nhepar_jwt($token, $configuration['signing_key']);
    nhe_keys($claims, ['auth_schema', 'session_epoch', 'sid', 'session_version', 'iss', 'aud', 'jti', 'iat', 'nbf', 'exp'], 'NHEPAR_ADMIN_COMPLETE_ORIGINAL_CLAIMS');
    nhep_expect(is_array($claims['jti']), 'NHEPAR_ADMIN_ORIGINAL_SUBJECT_OBJECT'); nhe_keys($claims['jti'], ['id', 'type'], 'NHEPAR_ADMIN_SUBJECT_FIELDS');
    $id = (string)nhepar_uint($actor['id']);
    nhep_expect($claims['auth_schema'] === 2 && $claims['session_epoch'] === $configuration['auth']['session_epoch']
        && $claims['iss'] === $configuration['auth']['issuer'] && $claims['aud'] === 'adminapi'
        && $claims['jti'] === ['id' => $id, 'type' => 'admin'] && is_string($claims['sid']) && is_string($claims['session_version'])
        && preg_match('/\A[a-f0-9]{32}\z/D', $claims['sid']) === 1
        && preg_match('/\A[a-f0-9]{32}\z/D', $claims['session_version']) === 1, 'NHEPAR_ADMIN_INDEPENDENT_APP_SUBJECT_AND_NONCES');
    nhepar_time_claims($claims, $response['actual_interval'], $new, $actual['snapshot'], true);
    $prefix = 'auth:v2:' . $configuration['auth']['session_epoch'] . ':adminapi:';
    $accountKey = $prefix . 'account:' . $id; $sessionKey = $prefix . 'session:' . $claims['sid'];
    $account = nhepar_pairs(['initialized' => '1', 'blocked' => '0', 'session_version' => $claims['session_version']]);
    $session = nhepar_pairs(['subject_id' => $id, 'session_version' => $claims['session_version'], 'type' => 'admin', 'audience' => 'adminapi',
        'token_digest' => hash('sha256', $token), 'credential_stamp' => hash_hmac('sha256', 'adminapi|' . $id . '|' . $actor['pwd'], $configuration['auth']['stamp_key']),
        'expires_at' => (string)$claims['exp'], 'status' => 'active']);
    $deadline = ($claims['exp'] + 60) * 1000; $oldAccount = nhepar_entry($before, $accountKey); $oldSession = nhepar_entry($before, $sessionKey);
    $accountDescriptor = nhepar_bind($actual, $accountKey, 'hash', $account, -1, $before['snapshot']);
    $sessionDescriptor = nhepar_bind($actual, $sessionKey, 'hash', $session, $deadline, $before['snapshot']);
    if ($new) {
        nhe_keys($request['body'], ['account', 'pwd', 'key', 'captchaVerification', 'captchaType'], 'NHEPAR_FIXED_ADMIN_LOGIN_BODY');
        nhep_expect($request['token'] === null && $request['body']['account'] === $actor['account']
            && is_string($request['body']['pwd']) && password_verify($request['body']['pwd'], $actor['pwd'])
            && $request['body']['key'] === '' && $request['body']['captchaVerification'] === '' && $request['body']['captchaType'] === ''
            && ($data['expires_time'] ?? null) === $claims['exp'] && nhepar_uint($data['user_info']['id'] ?? null) === (int)$id
            && ($data['user_info']['account'] ?? null) === $actor['account'] && ($data['user_info']['level'] ?? null) === 0
            && $oldSession === null, 'NHEPAR_REAL_SUCCESSFUL_ADMIN_CREDENTIAL_LOGIN_AND_NEW_SESSION');
        if ($oldAccount !== null) nhep_expect($oldAccount['type'] === 'hash' && $oldAccount['expires'] === -1
            && ($oldAccount['value'] === $account || $oldAccount['value'] === nhepar_pairs(['initialized' => '0', 'blocked' => '0'])),
            'NHEPAR_ORIGINAL_ACCOUNT_INIT_BRANCH');
        $changes[$accountKey] = $accountDescriptor; $changes[$sessionKey] = $sessionDescriptor;
        $identity = json_encode(['kind' => 'known', 'id' => $id, 'account' => $actor['account']], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
        $failure = 'auth:login:adminapi:' . hash_hmac('sha256', "admin-login-failure:v1\0" . $identity . "\0" . inet_pton('127.0.0.1'), $configuration['auth']['stamp_key']);
        nhep_expect(nhepar_entry($before, $failure) === null && nhepar_entry($actual, $failure) === null,
            'NHEPAR_NEW_NORMAL_LOGIN_HAS_NO_FAILURE_COUNTER');
    } else {
        nhep_expect(is_array($oldAccount) && $oldAccount['type'] === 'hash' && $oldAccount['value'] === $account && $oldAccount['expires'] === -1
            && is_array($oldSession) && $oldSession['type'] === 'hash' && $oldSession['value'] === $session && $oldSession['expires'] === $deadline
            && $accountDescriptor === $before['snapshot']['keys'][hash('sha256', $accountKey)]
            && $sessionDescriptor === $before['snapshot']['keys'][hash('sha256', $sessionKey)], 'NHEPAR_ADMIN_VERIFY_READS_SAME_BINDING_WITHOUT_RENEWAL');
    }
    unset($token, $claims, $session, $identity, $failure);
}

function nhepar_customer(array $before, array $actual, array $actor, array $intent, array $request, array $response,
    #[SensitiveParameter] array $configuration, array &$changes): void
{
    $new = $intent['step'] === 'customer_login'; $data = $new ? $response['json']['data'] : null;
    $token = $new ? ($data['token'] ?? null) : $request['token'];
    nhep_expect(is_string($token), 'NHEPAR_ORIGINAL_CUSTOMER_TOKEN_REQUIRED'); $claims = nhepar_jwt($token, $configuration['signing_key']);
    nhe_keys($claims, ['pwd', 'iss', 'aud', 'iat', 'nbf', 'exp', 'jti'], 'NHEPAR_CUSTOMER_COMPLETE_LEGACY_CLAIMS');
    nhep_expect(is_array($claims['jti']), 'NHEPAR_CUSTOMER_ORIGINAL_SUBJECT_OBJECT'); nhe_keys($claims['jti'], ['id', 'type'], 'NHEPAR_CUSTOMER_SUBJECT_FIELDS');
    $id = nhepar_uint($actor['uid']); $host = substr($intent['origin'], strlen('http://'));
    nhep_expect($claims['jti'] === ['id' => $id, 'type' => 'api'] && $claims['pwd'] === md5('')
        && $claims['iss'] === $host && $claims['aud'] === $host, 'NHEPAR_CUSTOMER_ACTUAL_LEGACY_SUBJECT_AND_ORIGIN');
    nhepar_time_claims($claims, $response['actual_interval'], $new, $actual['snapshot'], false);
    $ttl = $claims['exp'] - $claims['iat'] + 60; $key = 'c:' . md5($token);
    $wire = serialize(['uid' => $id, 'type' => 'api', 'token' => $token, 'exp' => $ttl]); $old = nhepar_entry($before, $key);
    if ($new) {
        nhe_keys($request['body'], ['account', 'password', 'spread', 'agent_id'], 'NHEPAR_FIXED_CUSTOMER_LOGIN_BODY');
        nhep_expect($request['token'] === null && $request['body']['account'] === $actor['account']
            && is_string($request['body']['password']) && hash_equals($actor['pwd'], md5($request['body']['password']))
            && $actor['pwd'] !== md5('123456') && $request['body']['spread'] === 0 && $request['body']['agent_id'] === 0
            && ($data['expires_time'] ?? null) === $claims['exp'] && $old === null, 'NHEPAR_REAL_CUSTOMER_CREDENTIAL_LOGIN_AND_NEW_LEGACY_WHITELIST');
        $changes[$key] = nhepar_bind($actual, $key, 'string', $wire, ['ttl' => $ttl], $before['snapshot']);
        nhepar_tag($before, $actual, 'api', [$key], $changes);
    } else {
        nhep_expect(is_array($old) && $old['type'] === 'string' && $old['value'] === $wire && $old['expires'] > 0,
            'NHEPAR_EXISTING_REAL_CUSTOMER_WHITELIST');
        $bound = nhepar_bind($actual, $key, 'string', $wire, $old['expires'], $before['snapshot']);
        nhep_expect($bound === $before['snapshot']['keys'][hash('sha256', $key)], 'NHEPAR_CUSTOMER_AUTH_NO_WHITELIST_RENEWAL');
        nhepar_tag($before, $actual, 'api', [], $changes);
    }
    unset($token, $claims, $wire);
}

/** Only the first six exact normal old-477 HTTP intents are implemented. */
function nhep_auth_redis_model(array $beforeCapture, array $actualCapture, array $beforeDBrows, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration): array
{
    $steps = ['admin_login' => [1, 'POST', '/adminapi/login', 'admin'],
        'admin_identity' => [2, 'GET', '/adminapi/setting/info', 'admin'],
        'platform_self_merchant_review' => [3, 'PUT', null, 'admin'],
        'platform_self_merchant_accept_orders' => [4, 'PUT', null, 'admin'],
        'customer_login' => [5, 'POST', '/api/login', 'customer'],
        'customer_identity' => [6, 'GET', '/api/userinfo', 'customer']];
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'], 'NHEPAR_ORIGINAL_INTENT_KEYS');
    nhep_expect(is_string($intent['step']) && isset($steps[$intent['step']]), 'NHEPAR_HTTP_STEP_REDIS_MODEL_NOT_IMPLEMENTED'); $spec = $steps[$intent['step']];
    nhep_expect($intent['sequence'] === $spec[0] && $intent['method'] === $spec[1] && $intent['actor'] === $spec[3]
        && ($spec[2] === null || $intent['path'] === $spec[2]) && $intent['origin'] === 'http://127.0.0.1:8000'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1,
        'NHEPAR_EXACT_ORIGINAL_NORMAL_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPAR_ORIGINAL_PRIVATE_REQUEST_KEYS');
    nhep_expect(($intent['method'] === 'GET') === ($privateRequest['body'] === null)
        && ($privateRequest['token'] === null) === in_array($intent['step'], ['admin_login', 'customer_login'], true)
        && is_array($privateRequest['actor_identity']) && is_array($privateResponse['json'] ?? null)
        && ($privateResponse['json']['status'] ?? null) === 200 && is_array($privateResponse['json']['data'] ?? null)
        && ($privateResponse['http'] ?? null) === 200 && ($privateResponse['transport_errno'] ?? null) === 0
        && ($privateResponse['primary_ip'] ?? null) === '127.0.0.1' && ($privateResponse['primary_port'] ?? null) === 8000
        && ($privateResponse['local_ip'] ?? null) === '127.0.0.1' && is_array($privateResponse['actual_interval'] ?? null)
        && array_is_list($privateResponse['actual_interval']) && count($privateResponse['actual_interval']) === 2,
        'NHEPAR_ACTUAL_SUCCESSFUL_OWN_NORMAL_HTTP_RESPONSE');
    foreach ($privateResponse['actual_interval'] as $time) nhep_expect(is_int($time) && $time > 0 && $time <= 4294967295, 'NHEPAR_ACTUAL_HTTP_NATIVE_TIME_WINDOW');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPAR_BOTH_ATOMIC_CAPTURES_SAME_ORIGINAL_RUN_SENTINEL');
    }
    unset($capture, $sentinel);
    nhep_expect(bccomp($beforeCapture['snapshot']['time'][0], (string)$privateResponse['actual_interval'][0], 0) <= 0
        && $privateResponse['actual_interval'][0] <= $privateResponse['actual_interval'][1]
        && bccomp((string)$privateResponse['actual_interval'][1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPAR_ORIGINAL_HTTP_WINDOW_INSIDE_INDEPENDENT_REDIS_OBSERVATIONS');
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id'] && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']), 'NHEPAR_SAME_RUN_ORIGINAL_PRIVATE_AUTH_CONFIGURATION');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect(array_key_exists($table, $beforeDBrows) && $beforeDBrows[$table] === [], 'NHEPAR_FIXED_EMPTY_LANGUAGE_TABLES');
    foreach (['eb_system_event', 'eb_system_notification', 'eb_system_config'] as $table)
        nhep_expect(is_array($beforeDBrows[$table] ?? null) && array_is_list($beforeDBrows[$table]), 'NHEPAR_COMPLETE_CHANNEL_AND_CONFIG_BEFORE_TABLES');
    foreach ($beforeDBrows['eb_system_event'] as $row) nhep_expect(!(nhepar_uint($row['is_del'] ?? null, true) === 0
        && nhepar_uint($row['is_open'] ?? null, true) === 1), 'NHEPAR_NO_ENABLED_CUSTOM_EVENT');
    foreach ($beforeDBrows['eb_system_notification'] as $row) foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat', 'is_app'] as $field)
        nhep_expect(nhepar_uint($row[$field] ?? null, true) === 0, 'NHEPAR_NO_ENABLED_CUSTOM_NOTICE_CHANNEL');
    $actor = nhepar_actor($beforeDBrows, $intent, $privateRequest); $changes = []; $tagMembers = [];
    $cold = match ($intent['step']) {
        'admin_login' => ['param_filter_type', 'param_filter_data', 'site_logo', 'site_logo_square', 'new_order_audio_link', 'site_name', 'model_checkbox'],
        'platform_self_merchant_review', 'platform_self_merchant_accept_orders' => ['param_filter_type', 'param_filter_data'],
        'customer_login' => ['param_filter_type', 'param_filter_data', 'store_brokerage_binding_status', 'brokerage_bindind', 'store_brokerage_binding_time'],
        'customer_identity' => ['extract_time'], 'admin_identity' => [],
    };
    foreach ($cold as $name) {
        $matches = array_values(array_filter($beforeDBrows['eb_system_config'], static fn(array $row): bool => ($row['menu_name'] ?? null) === $name));
        nhep_expect($matches === [], 'NHEPAR_KNOWN_COLD_CONFIG_ACTUALLY_ABSENT_FROM_BEFORE_DB');
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, 'N;', 0, $changes, $tagMembers);
    }
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire)
        nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    if ($intent['actor'] === 'admin') nhepar_admin($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);
    else nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);
    if (in_array($intent['step'], ['platform_self_merchant_review', 'platform_self_merchant_accept_orders'], true)) {
        $review = $intent['step'] === 'platform_self_merchant_review';
        nhep_expect(preg_match('~\A/adminapi/marketplace/merchants/([1-9][0-9]*)/' . ($review ? 'review' : 'flags') . '\z~D', $intent['path'], $match) === 1
            && is_array($privateRequest['body']) && $privateRequest['body'] === ($review ? ['review_status' => 1] : ['accept_orders' => 1]),
            'NHEPAR_EXACT_NORMAL_MERCHANT_OPERATION');
        $merId = nhepar_uint($match[1]);
        nhep_expect(is_array($beforeDBrows['eb_marketplace_merchant'] ?? null) && is_array($beforeDBrows['eb_marketplace_employee'] ?? null), 'NHEPAR_COMPLETE_MERCHANT_BEFORE_TABLES');
        $merchants = array_values(array_filter($beforeDBrows['eb_marketplace_merchant'], static fn(array $row): bool => nhepar_uint($row['mer_id'] ?? null) === $merId));
        nhep_expect(count($merchants) === 1, 'NHEPAR_ACTUAL_UNIQUE_TARGET_MERCHANT');
        foreach ($beforeDBrows['eb_marketplace_employee'] as $employee) nhep_expect(nhepar_uint($employee['mer_id'] ?? null) !== $merId,
            'NHEPAR_MERCHANT_EMPLOYEE_ACCOUNT_CHANGE_MODEL_NOT_IMPLEMENTED');
        foreach (['c:all_auth', 'c:' . md5('Admin_rules_level_' . '_2_' . implode('_', explode(',', $actor['roles'])))] as $key) {
            nhep_expect(nhepar_entry($actualCapture, $key) === null, 'NHEPAR_ACTUAL_PERMISSION_CACHE_REMOVAL'); $changes[$key] = null;
        }
    }
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    unset($actor, $config, $changes, $tagMembers);
    return $expected;
}

/** Source-reviewed first-eight headers/files/native definitions; complete business execution remains refused. */
/**
 * Pure first-eight-step private header/cookie model. It creates no cookie or ID,
 * calls no service, and returns private observation only, never a public proof.
 */
function nhep_auth_headers_model(array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse, #[SensitiveParameter] array $beforeCookieIds): array
{
    foreach (['nhep_expect', 'nhe_keys'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_AUTH_HEADER_PURE_DEPENDENCY_REQUIRED');
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'], 'NHE_AUTH_HEADER_ORIGINAL_INTENT');
    $steps = ['admin_login' => [1, 'POST', '/adminapi/login', 'admin'],
        'admin_identity' => [2, 'GET', '/adminapi/setting/info', 'admin'],
        'platform_self_merchant_review' => [3, 'PUT', 'review', 'admin'],
        'platform_self_merchant_accept_orders' => [4, 'PUT', 'flags', 'admin'],
        'customer_login' => [5, 'POST', '/api/login', 'customer'],
        'customer_identity' => [6, 'GET', '/api/userinfo', 'customer'],
        'platform_system_balance_add' => [7, 'PUT', 'funding', 'admin'],
        'funded_balance_read' => [8, 'GET', '/api/userinfo', 'customer'],
        'refund_family_cart' => [9, 'POST', '/api/cart/add', 'customer'],
        'refund_family_confirm' => [10, 'POST', '/api/order/confirm', 'customer'],
        'refund_family_create' => [11, 'POST', 'create', 'customer'],
        'refund_family_unpaid_read' => [12, 'GET', 'detail', 'customer'],
        'refund_family_pay' => [13, 'POST', '/api/order/pay', 'customer'],
        'refund_family_paid_read' => [14, 'GET', 'detail', 'customer'],
        'review_family_cart' => [15, 'POST', '/api/cart/add', 'customer'],
        'review_family_confirm' => [16, 'POST', '/api/order/confirm', 'customer'],
        'review_family_create' => [17, 'POST', 'create', 'customer'],
        'review_family_unpaid_read' => [18, 'GET', 'detail', 'customer'],
        'review_family_pay' => [19, 'POST', '/api/order/pay', 'customer'],
        'review_family_paid_read' => [20, 'GET', 'detail', 'customer'],
        'two_paid_balance_read' => [21, 'GET', '/api/userinfo', 'customer'],
        'unshipped_refund_apply' => [22, 'POST', 'refund_apply', 'customer'],
        'owned_refund_identity' => [23, 'GET', '/api/order/refund/list?page=1&limit=20', 'customer'],
        'platform_refund_approve' => [24, 'PUT', 'refund_approve', 'admin'],
        'owned_refund_completed_read' => [25, 'GET', 'refund_detail', 'customer'],
        'owned_refunded_root_read' => [26, 'GET', 'detail', 'customer'],
        'refunded_balance_read' => [27, 'GET', '/api/userinfo', 'customer'],
        'platform_manual_courier' => [28, 'PUT', 'manual_courier', 'admin'],
        'owned_shipped_read' => [29, 'GET', 'detail', 'customer'],
        'customer_receipt' => [30, 'POST', '/api/order/take', 'customer'],
        'owned_received_read' => [31, 'GET', 'detail', 'customer'],
        'customer_purchased_item_comment' => [32, 'POST', '/api/order/comment', 'customer'],
        'platform_pending_review_identity' => [33, 'GET', 'review_list', 'admin'],
        'platform_review_approve' => [34, 'PUT', 'review_approve', 'admin'],
        'platform_review_reply' => [35, 'PUT', 'review_reply', 'admin'],
        'platform_approved_replied_read' => [36, 'GET', 'review_list', 'admin'],
        'owned_commented_completed_read' => [37, 'GET', 'detail', 'customer'],





];
    $step = $intent['step'];
    nhep_expect(is_string($step) && isset($steps[$step]), 'NHE_AUTH_HEADER_STEP_NOT_IMPLEMENTED');
    [$sequence, $method, $route, $actor] = $steps[$step];
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === $method && $intent['actor'] === $actor
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['path']) && is_int($intent['actor_id']) && $intent['actor_id'] > 0
        && $intent['actor_id'] <= 4294967295, 'NHE_AUTH_HEADER_EXACT_NORMAL_SEQUENCE_AND_ORIGIN');
    if ($route === 'review' || $route === 'flags') {
        nhep_expect(preg_match('~\A/adminapi/marketplace/merchants/([1-9][0-9]{0,9})/' . $route . '\z~D', $intent['path'], $merchant) === 1
            && (int)$merchant[1] <= 4294967295, 'NHE_AUTH_HEADER_FIXED_MERCHANT_ROUTE');
    } elseif ($route === 'funding') {
        nhep_expect(preg_match('~\A/adminapi/user/update_other/([1-9][0-9]{0,9})\z~D',
            $intent['path'], $fundingRecipient) === 1 && (int)$fundingRecipient[1] <= 2147483647,
            'NHE_AUTH_HEADER_FIXED_SIGNED_FUNDING_RECIPIENT_ROUTE');
    } elseif ($route === 'create') {
        nhep_expect(preg_match('~\A/api/order/create/([1-9][0-9]{0,18})\z~D',
            $intent['path'], $createKey) === 1 && (strlen($createKey[1]) < 19
                || strcmp($createKey[1], '9223372036854775807') <= 0),
            'NHE_AUTH_HEADER_FIXED_SIGNED_CREATE_KEY_ROUTE');
    } elseif ($route === 'detail') {
        nhep_expect(preg_match('~\A/api/order/detail/(cp([1-9][0-9]{0,18}))\z~D',
            $intent['path'], $detailKey) === 1 && (strlen($detailKey[2]) < 19
                || strcmp($detailKey[2], '9223372036854775807') <= 0),
            'NHE_AUTH_HEADER_FIXED_SIGNED_DETAIL_CP_ROUTE');
    } elseif ($route === 'refund_apply') {
        nhep_expect(preg_match('~\A/api/order/refund/apply/([1-9][0-9]{0,9})\z~D',
            $intent['path'], $refundRoot) === 1 && (strlen($refundRoot[1]) < 10
                || strcmp($refundRoot[1], '4294967295') <= 0),
            'NHE_AUTH_HEADER_FIXED_UINT_REFUND_APPLY_ROOT_ROUTE');
    } elseif ($route === 'refund_approve') {
        nhep_expect(preg_match('~\A/adminapi/refund/refund/([1-9][0-9]{0,9})\z~D',
            $intent['path'], $approvalRefund) === 1 && (strlen($approvalRefund[1]) < 10
                || strcmp($approvalRefund[1], '2147483647') <= 0),
            'NHE_AUTH_HEADER_FIXED_SIGNED_REFUND_APPROVAL_PK_ROUTE');
    } elseif ($route === 'refund_detail') {
        nhep_expect(preg_match('~\A/api/order/refund/detail/([1-9][0-9]{0,18})\z~D',
            $intent['path'], $detailRefund) === 1 && (strlen($detailRefund[1]) < 19
                || strcmp($detailRefund[1], '9223372036854775807') <= 0),
            'NHE_AUTH_HEADER_FIXED_SIGNED64_REFUND_DETAIL_NUMBER_ROUTE');
    } elseif ($route === 'manual_courier') {
        nhep_expect(preg_match('~\A/adminapi/order/delivery/([1-9][0-9]{0,9})\z~D',
            $intent['path'], $deliveryRoot) === 1 && (strlen($deliveryRoot[1]) < 10
                || strcmp($deliveryRoot[1], '2147483647') <= 0),
            'NHE_AUTH_HEADER_FIXED_SIGNED_MANUAL_COURIER_ROOT_ROUTE');
    } elseif ($route === 'review_list') {
        nhep_expect(preg_match('~\A/adminapi/product/reply\?product_id=([1-9][0-9]{0,9})&page=1&limit=20\z~D', $intent['path'], $reviewRouteId) === 1
        && (strlen($reviewRouteId[1]) < 10 || strcmp($reviewRouteId[1], '2147483647') <= 0),
        'NHE_FACTORY_FIXED_SIGNED_REVIEW_LIST_ROUTE');
    } elseif ($route === 'review_approve') {
        nhep_expect(preg_match('~\A/adminapi/product/reply/set_status/([1-9][0-9]{0,9})/1\z~D', $intent['path'], $reviewRouteId) === 1
        && (strlen($reviewRouteId[1]) < 10 || strcmp($reviewRouteId[1], '2147483647') <= 0),
        'NHE_FACTORY_FIXED_SIGNED_REVIEW_APPROVE_ROUTE');
    } elseif ($route === 'review_reply') {
        nhep_expect(preg_match('~\A/adminapi/product/reply/set_reply/([1-9][0-9]{0,9})\z~D', $intent['path'], $reviewRouteId) === 1
        && (strlen($reviewRouteId[1]) < 10 || strcmp($reviewRouteId[1], '2147483647') <= 0),
        'NHE_FACTORY_FIXED_SIGNED_REVIEW_REPLY_ROUTE');
    } else nhep_expect($intent['path'] === $route, 'NHE_AUTH_HEADER_FIXED_ORIGINAL_ROUTE');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHE_AUTH_HEADER_ORIGINAL_PRIVATE_REQUEST');
    nhep_expect(is_array($privateRequest['actor_identity']), 'NHE_AUTH_HEADER_PRIVATE_ACTOR_OBJECT');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHE_AUTH_HEADER_PRIVATE_ACTOR_KEYS');
    nhep_expect($privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account'])
        && preg_match('/\A[a-z0-9_]{10,32}\z/D', $privateRequest['actor_identity']['account']) === 1
        && (($method === 'GET') ? $privateRequest['body'] === null : is_array($privateRequest['body'])),
        'NHE_AUTH_HEADER_ORIGINAL_ACTOR_AND_BODY_BINDING');
    $login = $step === 'admin_login' || $step === 'customer_login';
    nhep_expect($login ? $privateRequest['token'] === null : (is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1),
        'NHE_AUTH_HEADER_ORIGINAL_LOGIN_OR_AUTHENTICATED_CALL');

    nhep_expect(array_is_list($beforeCookieIds) && count($beforeCookieIds) === $sequence - 1,
        'NHE_AUTH_HEADER_ALL_PREVIOUS_PRIVATE_COOKIE_OBSERVATIONS');
    $seen = [];
    foreach ($beforeCookieIds as $id) {
        nhep_expect(is_string($id) && preg_match('/\A[a-f0-9]{32}\z/D', $id) === 1
            && !isset($seen[$id]), 'NHE_AUTH_HEADER_PREVIOUS_UNIQUE_NATIVE_MD5_IDS');
        $seen[$id] = true;
    }
    $interval = $privateResponse['actual_interval'] ?? null;
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 4294967295
        && ($privateResponse['http'] ?? null) === 200 && ($privateResponse['transport_errno'] ?? null) === 0
        && array_key_exists('transport_failure_class', $privateResponse) && $privateResponse['transport_failure_class'] === null
        && ($privateResponse['primary_ip'] ?? null) === '127.0.0.1' && ($privateResponse['primary_port'] ?? null) === 8000
        && ($privateResponse['local_ip'] ?? null) === '127.0.0.1' && is_int($privateResponse['local_port'] ?? null)
        && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw'] ?? null) && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json'] ?? null), 'NHE_AUTH_HEADER_ONE_COMPLETE_NATIVE_SUCCESS_RESPONSE');
    $decoded = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $privateResponse['json']
        && !array_is_list($decoded) && ($decoded['status'] ?? null) === 200,
        'NHE_AUTH_HEADER_REAL_ORIGINAL_SUCCESS_JSON');

    $headers = $privateResponse['headers'] ?? null;
    nhep_expect(is_array($headers), 'NHE_AUTH_HEADER_ORIGINAL_CALLBACK_ENVELOPE');
    nhe_keys($headers, ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'], 'NHE_AUTH_HEADER_EXACT_FIVE_CALLBACK_FIELDS');
    nhep_expect($headers['complete'] === true && $headers['limit_exceeded'] === false
        && is_int($headers['bytes']) && $headers['bytes'] > 0 && $headers['bytes'] <= 65536
        && is_array($headers['lines']) && array_is_list($headers['lines']) && count($headers['lines']) >= 3
        && is_array($headers['blocks']) && array_is_list($headers['blocks']) && count($headers['blocks']) === 1
        && $headers['blocks'][0] === $headers['lines'], 'NHE_AUTH_HEADER_SINGLE_COMPLETE_BLOCK_WITHOUT_TRUNCATION');
    $lines = $headers['lines']; $last = count($lines) - 1;
    nhep_expect(in_array($lines[0], ["HTTP/1.0 200 OK\r\n", "HTTP/1.1 200 OK\r\n"], true)
        && $lines[$last] === "\r\n", 'NHE_AUTH_HEADER_ORIGINAL_CLI_SUCCESS_STATUS_AND_FINAL_CRLF');
    $bytes = 0; $cookieIds = [];
    foreach ($lines as $index => $line) {
        nhep_expect(is_string($line) && strlen($line) >= 2 && str_ends_with($line, "\r\n"),
            'NHE_AUTH_HEADER_EACH_COMPLETE_ORIGINAL_CRLF_LINE');
        $bytes += strlen($line);
        nhep_expect($bytes <= 65536, 'NHE_AUTH_HEADER_ORIGINAL_TOTAL_BYTE_LIMIT');
        if ($index === 0 || $index === $last) continue;
        $body = substr($line, 0, -2); $colon = strpos($body, ':');
        nhep_expect(is_int($colon) && $colon > 0, 'NHE_AUTH_HEADER_NO_EXTRA_STATUS_EMPTY_OR_FOLDED_LINE');
        $name = substr($body, 0, $colon); $value = substr($body, $colon + 1);
        nhep_expect(preg_match("/\A[!#$%&'*+.^_`|~0-9A-Za-z-]+\z/D", $name) === 1
            && preg_match('/\A[\x09\x20-\x7e\x80-\xff]*\z/D', $value) === 1,
            'NHE_AUTH_HEADER_COMPLETE_VALID_FIELD_WITHOUT_EMBEDDED_CONTROL_OR_CRLF');
        nhep_expect(strcasecmp($name, 'Set-Cookie2') !== 0, 'NHE_AUTH_HEADER_NO_OTHER_COOKIE_MECHANISM');
        if (strcasecmp($name, 'Set-Cookie') === 0) {
            // php-8.2.33 head.c/head.h, then CLI send_headers appends CRLF.
            nhep_expect(preg_match('~\ASet-Cookie: PHPSESSID=([a-f0-9]{32}); path=/\r\n\z~D', $line, $cookie) === 1,
                'NHE_AUTH_HEADER_EXACT_NATIVE_SESSION_COOKIE_AND_ONLY_SOURCE_ATTRIBUTES');
            $cookieIds[] = $cookie[1];
        }
    }
    nhep_expect($bytes === $headers['bytes'] && count($cookieIds) === 1,
        'NHE_AUTH_HEADER_COMPLETE_BYTE_SUM_AND_UNIQUE_SOURCE_COOKIE');
    $id = $cookieIds[0];
    nhep_expect(!isset($seen[$id]), 'NHE_AUTH_HEADER_NEW_OBSERVED_ID_WITHOUT_COOKIE_JAR_REUSE');
    $ids = $beforeCookieIds; $ids[] = $id;
    // The full raw envelope and ID are PRIVATE observations, not seven-part output.
    return ['cookie_id' => $id, 'seen_cookie_ids' => $ids, 'headers' => $headers];
}

/** Pure candidate definitions only. Complete private trees/streams must never be published. */
function nhep_auth_files_stat(array $stat): void
{
    nhe_keys($stat, ['dev', 'ino', 'mode', 'nlink', 'uid', 'gid', 'size', 'mtime', 'ctime'], 'NHE_AUTH_FILES_STAT_NINE');
    foreach ($stat as $value) nhep_expect(is_int($value) && $value >= 0, 'NHE_AUTH_FILES_NATIVE_NONNEGATIVE_STAT');
    nhep_expect($stat['ino'] > 0 && $stat['nlink'] > 0
        && in_array($stat['mode'] & 0170000, [0040000, 0100000], true), 'NHE_AUTH_FILES_ORIGINAL_REGULAR_OR_DIRECTORY');
}

function nhep_auth_files_tree(array $tree): void
{
    $paths = array_keys($tree); $sorted = $paths; sort($sorted, SORT_STRING);
    nhep_expect($paths === $sorted && isset($tree['']) && is_array($tree[''])
        && ($tree['']['kind'] ?? null) === 'directory', 'NHE_AUTH_FILES_COMPLETE_SORTED_RUNTIME_WITH_ROOT');
    $identities = [];
    foreach ($tree as $path => $row) {
        nhep_expect(is_string($path) && is_array($row) && is_string($row['kind'] ?? null)
            && is_array($row['stat'] ?? null), 'NHE_AUTH_FILES_COMPLETE_RUNTIME_ROW');
        if ($path !== '') {
            nhep_expect(!str_starts_with($path, '/') && !str_ends_with($path, '/')
                && !str_contains($path, '\\') && !str_contains($path, "\0") && !str_contains($path, '//'),
                'NHE_AUTH_FILES_CANONICAL_RELATIVE_RUNTIME_PATH');
            foreach (explode('/', $path) as $part) nhep_expect($part !== '' && $part !== '.' && $part !== '..',
                'NHE_AUTH_FILES_REAL_RUNTIME_PATH_COMPONENT');
            $slash = strrpos($path, '/'); $parent = $slash === false ? '' : substr($path, 0, $slash);
            nhep_expect(isset($tree[$parent]) && ($tree[$parent]['kind'] ?? null) === 'directory',
                'NHE_AUTH_FILES_NO_MISSING_OR_FILE_PARENT');
        }
        nhep_auth_files_stat($row['stat']); $stat = $row['stat'];
        $identity = $stat['dev'] . ':' . $stat['ino'];
        nhep_expect(!isset($identities[$identity]), 'NHE_AUTH_FILES_DISTINCT_ORIGINAL_NATIVE_ENTRIES');
        $identities[$identity] = true;
        if ($row['kind'] === 'directory') {
            nhe_keys($row, ['kind', 'stat'], 'NHE_AUTH_FILES_DIRECTORY_ROW_KEYS');
            nhep_expect(($stat['mode'] & 0170000) === 0040000 && $stat['nlink'] >= 2,
                'NHE_AUTH_FILES_COMPLETE_NATIVE_DIRECTORY');
        } else {
            nhe_keys($row, ['kind', 'stat', 'bytes', 'sha256'], 'NHE_AUTH_FILES_FILE_ROW_KEYS');
            nhep_expect($row['kind'] === 'file' && ($stat['mode'] & 0170000) === 0100000 && $stat['nlink'] === 1
                && is_int($row['bytes']) && $row['bytes'] === $stat['size'] && $row['bytes'] <= 67108864
                && is_string($row['sha256']) && preg_match('/\A[a-f0-9]{64}\z/D', $row['sha256']) === 1,
                'NHE_AUTH_FILES_COMPLETE_NATIVE_FILE_BYTES');
        }
    }
}

/** Validate the private full readback against the same observation's complete runtime tree. */
function nhep_auth_files_streams(#[SensitiveParameter] array $private, array $tree): void
{
    nhep_expect(is_array($private['native_streams'] ?? null), 'NHE_AUTH_FILES_REAL_PRIVATE_NATIVE_STREAMS');
    nhe_keys($private['native_streams'], ['http', 'channel'], 'NHE_AUTH_FILES_BOTH_ORIGINAL_STREAM_OWNERS');
    foreach (['http', 'channel'] as $kind) {
        $streams = $private['native_streams'][$kind];
        nhep_expect(is_array($streams), 'NHE_AUTH_FILES_COMPLETE_PRIVATE_CHILD_STREAMS');
        nhe_keys($streams, ['stdout', 'stderr'], 'NHE_AUTH_FILES_COMPLETE_PRIVATE_DUAL_STREAMS');
        foreach (['stdout', 'stderr'] as $name) {
            $stream = $streams[$name]; $leaf = 'legacy-' . $kind . '.' . $name;
            nhep_expect(is_array($stream), 'NHE_AUTH_FILES_PRIVATE_NATIVE_STREAM_ROW');
            nhe_keys($stream, ['path', 'stat', 'bytes', 'sha256', 'raw'], 'NHE_AUTH_FILES_COMPLETE_PRIVATE_STREAM_KEYS');
            nhep_expect($stream['path'] === '/legacy-runtime/' . $leaf && is_array($stream['stat'])
                && is_string($stream['raw']) && strlen($stream['raw']) <= 16777216
                && is_int($stream['bytes']) && $stream['bytes'] === strlen($stream['raw'])
                && $stream['sha256'] === hash('sha256', $stream['raw']), 'NHE_AUTH_FILES_FULL_PRIVATE_STREAM_RAW_BYTES');
            nhep_auth_files_stat($stream['stat']); $stat = $stream['stat'];
            nhep_expect($stat['mode'] === (0100000 | 0600) && $stat['nlink'] === 1
                && $stat['size'] === $stream['bytes'] && $stat['dev'] === $tree['']['stat']['dev']
                && $stat['uid'] === $tree['']['stat']['uid']
                && ($tree[$leaf] ?? null) === ['kind' => 'file', 'stat' => $stat,
                    'bytes' => $stream['bytes'], 'sha256' => $stream['sha256']],
                'NHE_AUTH_FILES_PRIVATE_FULL_STREAM_BOUND_TO_SAME_RUNTIME_TREE');
        }
    }
}

