    nhe_keys($reference, ['schema', 'timezone', 'TZ', 'TZDIR', 'localtime', 'zone'], 'NHE_HTTP_PRIVATE_SYSTEM_TIME_REFERENCE_KEYS');
    nhep_expect($reference['schema'] === 1 && $reference['timezone'] === 'UTC' && $reference['TZ'] === false && $reference['TZDIR'] === false
