            $stable = ['native' => $proof['native'], 'group' => $proof['group'], 'members' => $identities, 'listener_inode' => $proof['listener']['inode']];
            if (!isset($originalProofs[$kind])) $originalProofs[$kind] = $stable;
            else nhep_expect($stable === $originalProofs[$kind], 'NHE_HTTP_ORIGINAL_FIVE_PROCESS_IDENTITIES_GROUP_AND_LISTENER_PRESERVED');
        }
