        nhe_keys($view['native_streams'], ['http', 'channel'], 'NHE_HTTP_BOTH_ORIGINAL_STREAM_OWNERS');
        foreach (['http', 'channel'] as $kind) {
            nhe_keys($view['native_streams'][$kind], ['stdout', 'stderr'], 'NHE_HTTP_COMPLETE_NATIVE_DUAL_STREAMS');
            foreach (['stdout', 'stderr'] as $name) {
                $stream = $view['native_streams'][$kind][$name];
                nhe_keys($stream, ['path', 'stat', 'bytes', 'sha256', 'raw'], 'NHE_HTTP_COMPLETE_PRIVATE_NATIVE_STREAM');
                nhep_expect($stream['path'] === '/legacy-runtime/legacy-' . $kind . '.' . $name && is_array($stream['stat'])
                    && nhep_file_stat($stream['stat']) === $stream['stat'] && $stream['stat']['mode'] === (0100000 | 0600)
                    && $stream['stat']['nlink'] === 1 && is_string($stream['raw']) && strlen($stream['raw']) <= 16777216
                    && $stream['bytes'] === strlen($stream['raw']) && $stream['stat']['size'] === $stream['bytes']
                    && $stream['sha256'] === hash('sha256', $stream['raw']), 'NHE_HTTP_ORIGINAL_COMPLETE_STREAM_RAW_AND_NATIVE_STAT');
                if ($viewIndex === 1) {
                    $old = $beforePrivate['native_streams'][$kind][$name];
                    foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
                        nhep_expect($stream['stat'][$key] === $old['stat'][$key], 'NHE_HTTP_FOUR_ORIGINAL_STREAM_CREATED_IDENTITIES');
                    if ($kind !== 'http' || $name !== 'stderr') nhep_expect($stream === $old, 'NHE_HTTP_ALL_OTHER_COMPLETE_NATIVE_STREAMS_UNCHANGED');
                }
            }
