    }
    $oldRaw = $beforePrivate['native_streams']['http']['stderr']['raw']; $actualRaw = $afterPrivate['native_streams']['http']['stderr']['raw'];
    nhep_expect(str_starts_with($actualRaw, $oldRaw), 'NHE_HTTP_COMPLETE_ORIGINAL_STDERR_PREFIX_PRESERVED');
    $append = substr($actualRaw, strlen($oldRaw)); $endpoint = '127.0.0.1:' . $response['local_port'];
    nhep_expect(preg_match('~\A\[([^\r\n]{24})\] ' . preg_quote($endpoint, '~') . ' Accepted\n\[([^\r\n]{24})\] '
        . preg_quote($endpoint, '~') . ' Closing\n\z~D', $append, $match) === 1, 'NHE_HTTP_ONLY_INDEPENDENT_NATIVE_ACCEPTED_AND_CLOSING');
    $accepted = nhep_http_asctime($match[1], $hw);
