    $raw = $oldRaw . '[' . $stamp($accepted) . '] ' . $endpoint . " Accepted\n[" . $stamp($closed) . '] ' . $endpoint . " Closing\n";
    nhep_expect($raw === $actualRaw, 'NHE_HTTP_COMPLETE_INDEPENDENT_NATIVE_STDERR_EXPECTED');
    return ['raw' => $raw, 'bytes' => strlen($raw), 'sha256' => hash('sha256', $raw)];
