/** Passive original stderr observation only; success here is not full stream/business acceptance. */
function nhep_http_wait_closing(array &$children, array $intent, #[SensitiveParameter] array $response,
    #[SensitiveParameter] array $beforePrivate): array
{
    nhep_expect(isset($children['http']) && is_array($children['http']['http_time_reference'] ?? null)
        && ($beforePrivate['http_time_reference'] ?? null) === $children['http']['http_time_reference']
        && ($response['local_ip'] ?? null) === '127.0.0.1' && is_int($response['local_port'] ?? null)
        && $response['local_port'] > 0 && $response['local_port'] <= 65535 && is_array($response['actual_interval'] ?? null)
        && is_int($response['actual_interval'][0] ?? null) && $response['actual_interval'][0] > 0
        && ($intent['origin'] ?? null) === 'http://127.0.0.1:8000', 'NHE_HTTP_PASSIVE_ORIGINAL_REQUEST_AND_TIME_REFERENCE_REQUIRED');
    $original = nhep_http_time_reference($children['http']['http_time_reference']);
    $baseline = $beforePrivate['native_streams']['http']['stderr'] ?? null;
    nhep_expect(is_array($baseline) && is_string($baseline['raw'] ?? null) && $baseline['bytes'] === strlen($baseline['raw'])
        && $baseline['sha256'] === hash('sha256', $baseline['raw']), 'NHE_HTTP_PASSIVE_COMPLETE_ORIGINAL_BEFORE_STREAM');
    $started = time(); $deadline = hrtime(true) + 5000000000;
    do {
        $proof = nhep_child_observation($children, 'http'); $stream = $children['http']['streams']['stderr'];
        $path = '/legacy-runtime/legacy-http.stderr';
        nhep_expect($stream['path'] === $path && is_resource($stream['handle']) && get_resource_type($stream['handle']) === 'stream'
            && is_resource($children['http']['streams']['stdout']['handle'])
            && !stream_isatty($children['http']['streams']['stdout']['handle']), 'NHE_HTTP_PASSIVE_SAME_ORIGINAL_NON_TTY_OUTPUT_HANDLES');
        clearstatcache(true, $path); $named = lstat($path); $owned = fstat($stream['handle']);
        nhep_expect(is_array($named) && is_array($owned) && is_file($path) && !is_link($path) && realpath($path) === $path,
            'NHE_HTTP_PASSIVE_ORIGINAL_STDERR_NAMED_HANDLE');
        $a = nhep_file_stat($named); $ownedStat = nhep_file_stat($owned);
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
            nhep_expect($a[$key] === $stream['created'][$key] && $a[$key] === $baseline['stat'][$key]
                && $ownedStat[$key] === $a[$key], 'NHE_HTTP_PASSIVE_ORIGINAL_SIX_STREAM_FIELDS');
        nhep_expect($a['mode'] === (0100000 | 0600) && $a['nlink'] === 1 && $a['size'] >= 0 && $a['size'] <= 16777216
            && $ownedStat['size'] >= 0 && $ownedStat['size'] <= 16777216, 'NHE_HTTP_PASSIVE_PRIVATE_FULL_NATIVE_STREAM');
        $raw = file_get_contents($path); clearstatcache(true, $path); $last = lstat($path); $lastOwned = fstat($stream['handle']);
        nhep_expect(is_string($raw) && is_array($last) && is_array($lastOwned) && !is_link($path) && realpath($path) === $path,
            'NHE_HTTP_PASSIVE_FULL_STDERR_READ'); $z = nhep_file_stat($last); $ownedLast = nhep_file_stat($lastOwned);
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
            nhep_expect($z[$key] === $a[$key] && $ownedLast[$key] === $a[$key], 'NHE_HTTP_PASSIVE_STREAM_IDENTITY_DURING_READ');
        if ($ownedStat === $a && $a === $z && $ownedLast === $z && strlen($raw) === $a['size']) {
            nhep_expect(str_starts_with($raw, $baseline['raw']), 'NHE_HTTP_PASSIVE_COMPLETE_BEFORE_PREFIX_PRESERVED');
            $tail = substr($raw, strlen($baseline['raw'])); $endpoint = '127.0.0.1:' . $response['local_port'];
            if (preg_match('~(?:\A|\n)\[([^\r\n]{24})\] ' . preg_quote($endpoint, '~') . ' Closing\n\z~D', $tail, $m) === 1) {
                nhep_expect(hrtime(true) <= $deadline, 'NHE_HTTP_CLOSING_OBSERVED_WITHIN_ORIGINAL_FIVE_SECOND_WINDOW');
                $ended = time(); nhep_expect($ended >= $started, 'NHE_HTTP_PASSIVE_REAL_WALL_CLOCK_INTERVAL');
                nhep_http_asctime($m[1], [$response['actual_interval'][0], $ended]);
                nhep_child_observation($children, 'http'); nhep_http_time_reference($original);
                return ['closing_observed' => true, 'actual_interval' => [$started, $ended],
                    'stream' => ['path' => $path, 'stat' => $a, 'bytes' => strlen($raw), 'sha256' => hash('sha256', $raw), 'raw' => $raw]];
            }
        }
        unset($raw); if (hrtime(true) >= $deadline) break; usleep(10000);
    } while (hrtime(true) < $deadline);
    throw new RuntimeException('NHE_HTTP_ORIGINAL_CLOSING_NOT_OBSERVED_WITHIN_EXISTING_FIVE_SECONDS');
}

