            && $pending['before_sha256'] === hash('sha256', serialize($before7)),
            'NHE_AUTH_OBSERVERS_EXACT_ORIGINAL_BEFORE_INTENT_AND_PRIVATE_REQUEST');
        $beforeHash = $pending['before_sha256']; $beforePrivate = $pending['private'];
        $pending = null; $failed = true; $firstFailure = null; $afterPrivate = [];
        try {
            nhep_http_wait_closing($children, $intent, $privateResponse, $beforePrivate);
        } catch (Throwable $failure) {
            $firstFailure = $failure;
        }
        // A successful Closing precedes one real frame on the original ready subscriber.
        // A Closing failure skips this wait; either failure still gets exactly one actual-after below.
        if ($firstFailure === null && (isset($paySteps[$intent['step']])
            || $intent['step'] === 'unshipped_refund_apply'
            || $intent['step'] === 'customer_purchased_item_comment')) {
            try {
                if ($intent['step'] === 'customer_purchased_item_comment') {
                    $eventContext = nhepcm_context(
                        ['database' => $before7['database'], 'rows' => $before7['rows']], $intent, $privateRequest);
                } elseif ($intent['step'] === 'unshipped_refund_apply') {
                    $eventContext = nheprdb_context(
                        ['database' => $before7['database'], 'rows' => $before7['rows']], $intent, $privateRequest);
                } else {
                    $eventContext = nhepop_context(
                        ['database' => $before7['database'], 'rows' => $before7['rows']], $intent, $privateRequest);
                }
                $subscriber = $children['channel']['subscriber'] ?? null;
                nhep_expect(is_array($subscriber) && is_array($subscriber['state'] ?? null)
                    && ($subscriber['state']['run_id'] ?? null) === $intent['run_id']
                    && ($subscriber['state']['observe'] ?? null) === $children['channel']['observe']
                    && ($subscriber['state']['socket'] ?? null) === $subscriber['socket']
                    && ($subscriber['state']['socket_id'] ?? null) === $subscriber['socket_id']
                    && ($subscriber['state']['local_endpoint'] ?? null) === $subscriber['local_endpoint'],
                    'NHE_AUTH_OBSERVERS_PAY_SAME_ORIGINAL_SUBSCRIBER_AFTER_CLOSING');
                // Pass the registered state element itself by reference; no copied state, reconnect or publish.
                $packet = nhep_channel_read($children['channel']['subscriber']['state']);
                if ($intent['step'] === 'customer_purchased_item_comment') {
                    nhep_expect($packet === $eventContext['channel_packet'],
                        'NHE_AUTH_OBSERVERS_COMMENT_COMPLETE_ORIGINAL_ADMIN_NEW_PUSH_FIVE_INTEGER_FRAME');
                } elseif ($intent['step'] === 'unshipped_refund_apply') {
                    nhep_expect($packet === ['channel' => 'crmeb', 'data' => ['type' => 'NEW_REFUND_ORDER',
                        'data' => ['order_id' => $eventContext['order']['row']['order_id']]]],
                        'NHE_AUTH_OBSERVERS_REFUND_COMPLETE_ORIGINAL_NEW_REFUND_ORDER_FRAME');
                } else {
                    nhep_expect($packet === ['channel' => 'crmeb', 'data' => ['type' => 'NEW_ORDER',
                        'data' => ['order_id' => $eventContext['order']['row']['order_id']]]],
                        'NHE_AUTH_OBSERVERS_PAY_COMPLETE_ORIGINAL_NEW_ORDER_FRAME');
                }
                unset($packet, $eventContext, $subscriber);
            } catch (Throwable $channelFailure) {
                $firstFailure = $channelFailure;
            }
        }
        // Even failed transport/Closing gets one actual after observation, never a retry.
        try {
            $actual7 = nhep_observation($qualified, $db, $redis, $children, $afterPrivate);
        } catch (Throwable $observationFailure) {
            if ($firstFailure !== null) throw $firstFailure;
            throw $observationFailure;
        }
        if ($firstFailure !== null) throw $firstFailure;
        nhep_expect(audit_config() === $privateAuthConfiguration,
            'NHE_AUTH_OBSERVERS_ORIGINAL_REAL_PRIVATE_CONFIGURATION_PRESERVED');
        if ($intent['step'] === 'platform_system_balance_add' || $intent['step'] === 'funded_balance_read'
            || $intent['step'] === 'two_paid_balance_read' || $intent['step'] === 'refunded_balance_read') {
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_funding_database_model(
                ['database' => $before7['database'], 'rows' => $before7['rows']],
                ['database' => $actual7['database'], 'rows' => $actual7['rows']],
                $intent, $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $actualOrderNo = null;
            if ($intent['step'] === 'platform_system_balance_add') {
                // Only the BEFORE next PK after the complete independent DB proof, never an ACK/last row.
                $recharge = $before7['database']['tables']['eb_user_recharge'];
                $nextRechargeId = m4lh_actor_next($recharge, 'id');
                $rechargeIndex = nhep_auth_db_index($actual7['rows']['eb_user_recharge'],
                    $recharge['metadata'], 'id', $nextRechargeId);
                $actualOrderNo = $actual7['rows']['eb_user_recharge'][$rechargeIndex]['order_id'];
                nhep_expect(is_string($actualOrderNo), 'NHE_AUTH_OBSERVERS_ONLY_BEFORE_NEXT_PK_RECHARGE_ORDER');
            }
            $cache = nhep_funding_redis_model($beforeCapture, $actualCapture, $before7['rows'],
                $intent, $privateRequest, $privateResponse, $privateAuthConfiguration, $actualOrderNo);
        } elseif (isset($commerceSteps[$intent['step']])) {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $database = nhep_cart_confirm_database_model($beforeDB2, $actualDB2, $intent, $privateRequest, $privateResponse);
            $cache = nhep_cart_confirm_redis_model(
                ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']],
                ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']],
                $beforeDB2, $intent, $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif (isset($createSteps[$intent['step']])) {
            $createFamily = $createSteps[$intent['step']];
            $createContext = $commerce['confirmation_contexts'][$createFamily] ?? null;
            $createReceipt = $commerce['confirmation_receipts'][$createFamily] ?? null;
            nhep_expect(is_array($createContext) && is_array($createReceipt)
                && $createReceipt['context'] === $createContext && $createReceipt['family'] === $createFamily
                && is_string($createReceipt['physicalKey'])
                && $createReceipt['descriptor'] === ($before7['redis']['keys'][hash('sha256', $createReceipt['physicalKey'])] ?? null),
                'NHE_AUTH_OBSERVERS_CREATE_SAME_ORIGINAL_CONTEXT_RECEIPT_AND_BOUND_BEFORE');
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_create_database_model($beforeDB2, $actualDB2, $intent, $privateRequest,
                $privateResponse, $beforeCapture, $actualCapture, $createContext);
            // Only this BEFORE next-PK row after the independent complete DB proof supplies the CP candidate.
            $orderTable = $before7['database']['tables']['eb_store_order'];
            $nextOrderId = m4lh_actor_next($orderTable, 'id');
            $orderIndex = nhep_auth_db_index($actual7['rows']['eb_store_order'], $orderTable['metadata'], 'id', $nextOrderId);
            $actualOrderNo = $actual7['rows']['eb_store_order'][$orderIndex]['order_id'];
            nhep_expect(is_string($actualOrderNo), 'NHE_AUTH_OBSERVERS_CREATE_ONLY_PROVED_BEFORE_NEXT_PK_ORDER_NUMBER');
            $cache = nhep_create_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration, $createContext, $actualOrderNo);
        } elseif (isset($detailSteps[$intent['step']])) {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $database = nhep_order_detail_database_model($beforeDB2, $actualDB2, $intent, $privateRequest, $privateResponse);
            $cache = nhep_order_detail_redis_model(
                ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']],
                ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']],
                $beforeDB2, $intent, $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif (isset($paySteps[$intent['step']])) {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $database = nhep_order_pay_database_model($beforeDB2, $actualDB2, $intent, $privateRequest, $privateResponse);
            $cache = nhep_order_pay_redis_model(
                ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']],
                ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']],
                $beforeDB2, $intent, $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif ($intent['step'] === 'unshipped_refund_apply') {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_unshipped_refund_database_model($beforeDB2, $actualDB2, $intent, $privateRequest,
                $privateResponse, $beforeCapture, $actualCapture);
            // Only this BEFORE next-PK row after the complete DB7 proof supplies the bare refund number.
            $refundTable = $before7['database']['tables']['eb_store_order_refund'];
            $nextRefundId = m4lh_actor_next($refundTable, 'id');
            $refundIndex = nhep_auth_db_index($actual7['rows']['eb_store_order_refund'],
                $refundTable['metadata'], 'id', $nextRefundId);
            $actualRefundNo = $actual7['rows']['eb_store_order_refund'][$refundIndex]['order_id'];
            nhep_expect(is_string($actualRefundNo), 'NHE_AUTH_OBSERVERS_REFUND_ONLY_PROVED_BEFORE_NEXT_PK_BARE_NUMBER');
            $cache = nhep_unshipped_refund_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration, $actualRefundNo);
        } elseif ($intent['step'] === 'owned_refund_identity') {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_owned_refund_list_database_model($beforeDB2, $actualDB2, $intent,
                $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $cache = nhep_owned_refund_list_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif ($intent['step'] === 'platform_refund_approve') {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_platform_refund_approve_database_model($beforeDB2, $actualDB2, $intent,
                $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $cache = nhep_platform_refund_approve_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif ($intent['step'] === 'owned_refund_completed_read') {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_owned_refund_detail_database_model($beforeDB2, $actualDB2, $intent,
                $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $cache = nhep_owned_refund_detail_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif ($intent['step'] === 'platform_manual_courier') {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_manual_courier_database_model($beforeDB2, $actualDB2, $intent,
                $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $cache = nhep_manual_courier_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif ($intent['step'] === 'customer_receipt') {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_customer_receipt_database_model($beforeDB2, $actualDB2, $intent,
                $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $cache = nhep_customer_receipt_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif ($intent['step'] === 'customer_purchased_item_comment') {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_customer_comment_database_model($beforeDB2, $actualDB2, $intent,
                $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $cache = nhep_customer_comment_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif (in_array($intent['step'], ['platform_pending_review_identity', 'platform_approved_replied_read'], true)) {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_platform_review_list_database_model($beforeDB2, $actualDB2, $intent,
                $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $cache = nhep_platform_review_list_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration);
        } elseif (in_array($intent['step'], ['platform_review_approve', 'platform_review_reply'], true)) {
            $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
            $actualDB2 = ['database' => $actual7['database'], 'rows' => $actual7['rows']];
            $beforeCapture = ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']];
            $actualCapture = ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']];
            $database = nhep_platform_review_write_database_model($beforeDB2, $actualDB2, $intent,
                $privateRequest, $privateResponse, $beforeCapture, $actualCapture);
            $cache = nhep_platform_review_write_redis_model($beforeCapture, $actualCapture, $beforeDB2, $intent,
                $privateRequest, $privateResponse, $privateAuthConfiguration);
        } else {
            $database = nhep_auth_database_model(
                ['database' => $before7['database'], 'rows' => $before7['rows']],
                ['database' => $actual7['database'], 'rows' => $actual7['rows']],
                $intent, $privateRequest, $privateResponse);
            $cache = nhep_auth_redis_model(
                ['snapshot' => $before7['redis'], 'native' => $beforePrivate['redis_native']],
                ['snapshot' => $actual7['redis'], 'native' => $afterPrivate['redis_native']],
                $before7['rows'], $intent, $privateRequest, $privateResponse, $privateAuthConfiguration);
        }
        $headers = nhep_auth_headers_model($intent, $privateRequest, $privateResponse, $cookieIds);
        $files = nhep_auth_files_model($before7, $actual7, $intent, $privateResponse, $beforePrivate, $afterPrivate);
        $expected7 = ['database' => $database['database'], 'rows' => $database['rows'], 'redis' => $cache,
            'private' => $files['private'], 'public' => $files['public'], 'logs' => $files['logs'],
            'native' => $before7['native']];
        nheh_snapshot($expected7);
        nhep_expect($expected7 === $actual7, 'NHE_AUTH_OBSERVERS_COMPLETE_INDEPENDENT_EXPECTED_SEVEN_PARTS');
        $nextCommerce = $commerce;
        if (isset($commerceSteps[$intent['step']])) {
            [$family, $confirm] = $commerceSteps[$intent['step']];
            nhep_expect(!isset($commerce['confirmation_contexts'][$family])
                && !isset($commerce['confirmation_receipts'][$family]), 'NHE_AUTH_OBSERVERS_CONFIRMATION_COMMIT_IS_CREATE_ONLY');
            if (!$confirm) {
                nhep_expect(!isset($commerce['carts'][$family]), 'NHE_AUTH_OBSERVERS_CART_COMMIT_IS_CREATE_ONLY');
                // The complete DB model has proved this BEFORE next-PK row, not an arbitrary response/AFTER row.
                $cartId = m4lh_actor_next($before7['database']['tables']['eb_store_cart'], 'id');
                $nextCommerce['carts'][$family] = ['family' => $family, 'intent' => $intent,
                    'request' => $privateRequest, 'cartId' => $cartId];
            } else {
                $cart = $commerce['carts'][$family] ?? null;
                nhep_expect(is_array($cart) && $cart['family'] === $family
                    && $cart['intent']['run_id'] === $intent['run_id'] && $cart['intent']['actor_id'] === $intent['actor_id']
                    && $cart['intent']['sequence'] + 1 === $intent['sequence']
                    && $cart['request']['actor_identity'] === $privateRequest['actor_identity']
                    && $cart['request']['token'] === $privateRequest['token']
                    && $privateRequest['body']['cartId'] === (string)$cart['cartId'],
                    'NHE_AUTH_OBSERVERS_SAME_PRIVATE_CART_ASSOCIATION_AT_CONFIRM_COMMIT');
                $beforeDB2 = ['database' => $before7['database'], 'rows' => $before7['rows']];
                $orderKey = $privateResponse['json']['data']['orderKey'] ?? null;
                nhep_expect(is_string($orderKey), 'NHE_AUTH_OBSERVERS_ORIGINAL_ACCEPTED_CONFIRM_KEY');
                $built = nhep_confirmation_value_expected($beforeDB2, $intent, $privateRequest,
                    $orderKey, $privateResponse['actual_interval']);
                nhe_keys($built, ['orderKey', 'logicalKey', 'tuple', 'wire', 'responseCartInfo'],
                    'NHE_AUTH_OBSERVERS_COMPLETE_INDEPENDENT_CONFIRMATION_BUILDER');
                nhep_expect($built['orderKey'] === $orderKey
                    && $built['logicalKey'] === 'user_order_' . $intent['actor_id'] . $orderKey
                    && is_array($built['tuple']) && is_string($built['wire'])
                    && $built['wire'] === serialize($built['tuple']), 'NHE_AUTH_OBSERVERS_ACCEPTED_KEY_AND_INDEPENDENT_COMPLETE_VALUE');
                $physicalKey = 'c:' . $built['logicalKey']; $keyHash = hash('sha256', $physicalKey);
                // This exact descriptor comes from the independently proved expected7, after full seven-part equality.
                $descriptor = $expected7['redis']['keys'][$keyHash] ?? null;
                nhep_expect(is_array($descriptor), 'NHE_AUTH_OBSERVERS_ACCEPTED_CONFIRMATION_DESCRIPTOR_PRESENT');
                nhe_keys($descriptor, ['type', 'sha256', 'expires'], 'NHE_AUTH_OBSERVERS_COMPLETE_ORIGINAL_SNAPSHOT_DESCRIPTOR');
                nhep_expect($descriptor['type'] === 'string' && is_string($descriptor['sha256'])
                    && preg_match('/\A[a-f0-9]{64}\z/D', $descriptor['sha256']) === 1
                    && is_int($descriptor['expires']) && $descriptor['expires'] > 0
                    && $descriptor === ($actual7['redis']['keys'][$keyHash] ?? null),
                    'NHE_AUTH_OBSERVERS_ORIGINAL_ACCEPTED_TYPE_DUMP_HASH_AND_EXACT_ABSOLUTE_EXPIRY');
                $context = ['beforeDB2' => $beforeDB2, 'intent' => $intent, 'request' => $privateRequest,
                    'orderKey' => $built['orderKey'], 'httpInterval' => $privateResponse['actual_interval']];
                nhe_keys($context, ['beforeDB2', 'intent', 'request', 'orderKey', 'httpInterval'],
                    'NHE_AUTH_OBSERVERS_EXACT_FIVE_FIELD_ACCEPTED_CONFIRMATION_CONTEXT');
                $nextCommerce['confirmation_contexts'][$family] = $context;
                $nextCommerce['confirmation_receipts'][$family] = ['family' => $family, 'intent' => $intent,
                    'actor_identity' => $privateRequest['actor_identity'], 'token' => $privateRequest['token'],
                    'cartId' => $cart['cartId'], 'orderKey' => $built['orderKey'], 'physicalKey' => $physicalKey,
                    'descriptor' => $descriptor, 'context' => $context];
                unset($nextCommerce['carts'][$family]);
            }
        }
        if (isset($createSteps[$intent['step']])) {
            nhep_expect($createFamily === $createSteps[$intent['step']]
                && ($nextCommerce['confirmation_contexts'][$createFamily] ?? null) === $createContext
                && ($nextCommerce['confirmation_receipts'][$createFamily] ?? null) === $createReceipt
                && $createReceipt['context'] === $createContext && !isset($nextCommerce['carts'][$createFamily]),
                'NHE_AUTH_OBSERVERS_CREATE_CONSUMES_ONLY_SAME_ORIGINAL_CONFIRMATION_AFTER_ALL_SEVEN');
            unset($nextCommerce['confirmation_contexts'][$createFamily], $nextCommerce['confirmation_receipts'][$createFamily]);
        }
        // All receipt work above is private and may fail without advancing accepted state/cookies/counts.
        $commerce = $nextCommerce;
        if ($intent['sequence'] === 37) $accepted7 = $expected7;
        $cookieIds = $headers['seen_cookie_ids']; $completed++; $failed = false;
        return ['before_sha256' => $beforeHash, 'expected' => $expected7, 'actual' => $actual7];
    };
    $finish = static function () use (&$completed, &$failed, &$pending, &$commerce, &$accepted7): array {
        nhep_expect($completed === 37 && $pending === null && $failed === false
            && $commerce['carts'] === [] && $commerce['confirmation_contexts'] === []
            && $commerce['confirmation_receipts'] === [] && is_array($accepted7),
            'NHE_AUTH_OBSERVERS_FINISH_ONLY_AFTER_COMPLETE_ACCEPTED_HISTORY');
        nheh_snapshot($accepted7);
        return $accepted7;
    };
    nheh_observers($qualified, $qualified['context']['run_id'], $before, $after);
    return ['before' => $before, 'after' => $after, 'finish' => $finish];
}

/** Source-reviewed funding definitions; complete business execution remains refused. */
/** Pure step-7/8 candidate. Complete native rows/tokens/captures stay private RAM.
 * No loader, entry execution, resource access or first-six-definition changes.
 */
function nhep_funding_db_signed_time(#[SensitiveParameter] array $metadata, string $column,
    #[SensitiveParameter] mixed $value, array $interval): int
{
    $definition = $metadata['columns'][$column] ?? null;
    nhep_expect(in_array($column, ['pay_time', 'add_time'], true) && is_array($definition)
        && preg_match('/\Aint(?:\([0-9]+\))?\z/D', strtolower($definition['COLUMN_TYPE'])) === 1
        && $definition['IS_NULLABLE'] === 'NO' && is_int($value)
        && m4lh_actor_native($definition, $value) === $value
        && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $value >= $interval[0] && $value <= $interval[1],
        'NHE_FUND_DB_ORIGINAL_SIGNED_RECHARGE_HTTP_TIME');
    return $value;
}

/** This is the real BEFORE OutPush selector, not an assumed zero side effect. */
function nhep_funding_db_no_outpush(#[SensitiveParameter] array $before): void
{
    nhep_expect(isset($before['database']['tables']['eb_out_account'], $before['rows']['eb_out_account']),
        'NHE_FUND_DB_COMPLETE_ORIGINAL_OUT_ACCOUNT_TABLE');
    $columns = $before['database']['tables']['eb_out_account']['metadata']['columns'];
    foreach (['is_del', 'status', 'push_open'] as $field)
        nhep_expect(isset($columns[$field]), 'NHE_FUND_DB_REAL_OUT_PUSH_SELECTOR_COLUMNS');
    foreach ($before['rows']['eb_out_account'] as $row) {
        $flags = [];
        foreach (['is_del', 'status', 'push_open'] as $field) {
            $value = m4lh_actor_native($columns[$field], $row[$field]);
            nhep_expect(is_int($value) && $value === $row[$field], 'NHE_FUND_DB_NATIVE_OUT_PUSH_FLAGS');
            $flags[$field] = $value;
        }
        nhep_expect(!($flags['is_del'] === 0 && $flags['status'] === 1 && $flags['push_open'] === 1),
            'NHE_FUND_DB_ENABLED_OUT_PUSH_NOT_IMPLEMENTED');
    }
}

/** The actual unordered api_url equality query must have one unambiguous result. */
function nhep_funding_db_visit_page(#[SensitiveParameter] array $before): string
{
    $columns = $before['database']['tables']['eb_system_menus']['metadata']['columns'];
    nhep_expect(isset($columns['api_url'], $columns['menu_name']), 'NHE_FUND_DB_ORIGINAL_VISIT_MENU_COLUMNS');
    $path = 'user/update_other/<id>'; $names = [];
    foreach ($before['rows']['eb_system_menus'] as $row) {
        nhep_expect(is_string($row['api_url']) && is_string($row['menu_name']), 'NHE_FUND_DB_NATIVE_MENU_TEXT');
        nhep_expect(strtolower(rtrim($row['api_url'], ' ')) !== $path || $row['api_url'] === $path,
            'NHE_FUND_DB_CANONICAL_UNAMBIGUOUS_VISIT_ROUTE');
        if ($row['api_url'] === $path) $names[] = $row['menu_name'];
    }
    nhep_expect(count($names) <= 1, 'NHE_FUND_DB_UNAMBIGUOUS_BEFORE_VISIT_NAME');
    return ($names[0] ?? '') ?: '未知';
}

/** Independent complete DB model for precisely the existing normal steps 7/8.
 * AFTER contributes only checked original-next-ID candidates and native times.
 * The order helper must independently reconstruct the full observed cz number.
 */
function nhep_funding_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $beforeRedisCapture, #[SensitiveParameter] array $actualRedisCapture): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhep_auth_db_index',
        'nhep_auth_db_time', 'nhep_auth_db_update', 'nhep_auth_db_append', 'nhep_database_expected',
        'm4lh_actor_expect', 'm4lh_actor_native', 'm4lh_actor_expected_row', 'm4lh_actor_next',
        'm4lh_actor_projection', 'm4lh_actor_counter_ddl', 'bcadd'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_FUND_DB_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'], 'NHE_FUND_DB_HTTP_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHE_FUND_DB_PRIVATE_REQUEST');
    nhep_expect(is_array($privateRequest['actor_identity']), 'NHE_FUND_DB_PRIVATE_ACTOR_OBJECT');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHE_FUND_DB_PRIVATE_ACTOR_KEYS');
    $steps = [
        'platform_system_balance_add' => [7, 'PUT', 'admin'],
        'funded_balance_read' => [8, 'GET', 'customer'],
        'two_paid_balance_read' => [21, 'GET', 'customer'],
        'refunded_balance_read' => [27, 'GET', 'customer'],
    ];
    $step = $intent['step'];
    nhep_expect(is_string($step) && isset($steps[$step]), 'NHE_FUND_DB_STEP_NOT_IMPLEMENTED');
    [$sequence, $method, $actor] = $steps[$step];
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === $method && $intent['actor'] === $actor
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['origin']) && preg_match('~\Ahttp://127\.0\.0\.1:([1-9][0-9]{0,4})\z~D', $intent['origin'], $origin) === 1
        && (int)$origin[1] <= 65535 && is_string($intent['path']), 'NHE_FUND_DB_EXACT_NORMAL_HTTP_STEP');
    $identity = $privateRequest['actor_identity']; $actorId = $identity['id']; $account = $identity['account'];
    nhep_expect(is_int($actorId) && $actorId > 0 && $actorId <= 4294967295 && $intent['actor_id'] === $actorId
        && is_string($account) && preg_match('/\A[a-z0-9_]{10,32}\z/D', $account) === 1
        && is_string($privateRequest['token']) && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1,
        'NHE_FUND_DB_REAL_PRIVATE_ACTOR_AND_ISSUED_TOKEN_SHAPE');
    $actorTable = $actor === 'admin' ? 'eb_system_admin' : 'eb_user'; $actorPk = $actor === 'admin' ? 'id' : 'uid';
    $actorMeta = $beforeDB2['database']['tables'][$actorTable]['metadata'];
    $actorIndex = nhep_auth_db_index($beforeDB2['rows'][$actorTable], $actorMeta, $actorPk, $actorId);
    $actualActorIndex = nhep_auth_db_index($actualDB2['rows'][$actorTable], $actorMeta, $actorPk, $actorId);
    $owner = $beforeDB2['rows'][$actorTable][$actorIndex];
    nhep_expect($owner['account'] === $account && $actualDB2['rows'][$actorTable][$actualActorIndex]['account'] === $account
        && $owner['status'] === 1 && $owner['is_del'] === 0 && ($actor !== 'admin' || $owner['level'] === 0),
        'NHE_FUND_DB_ORIGINAL_ELIGIBLE_SAME_OWNER');
    nhep_funding_db_no_outpush($beforeDB2);
    $interval = $privateResponse['actual_interval'] ?? null;
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 4294967295
        && ($privateResponse['http'] ?? null) === 200 && ($privateResponse['transport_errno'] ?? null) === 0
        && array_key_exists('transport_failure_class', $privateResponse) && $privateResponse['transport_failure_class'] === null
        && ($privateResponse['primary_ip'] ?? null) === '127.0.0.1' && ($privateResponse['primary_port'] ?? null) === (int)$origin[1]
        && is_string($privateResponse['raw'] ?? null) && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json'] ?? null), 'NHE_FUND_DB_COMPLETE_ACTUAL_NORMAL_RESPONSE');
    $json = $privateResponse['json']; $decoded = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $json
        && ($json['status'] ?? null) === 200 && is_string($json['msg'] ?? null), 'NHE_FUND_DB_BOUND_ORIGINAL_SUCCESS_JSON');
    $expectedRows = []; $insertCounts = [];
    if ($step === 'platform_system_balance_add') {
        if (!function_exists('nhep_funding_order_expected'))
            throw new RuntimeException('NHE_FUND_DB_INDEPENDENT_ORDER_MODEL_REQUIRED');
        nhep_expect(preg_match('~\A/adminapi/user/update_other/([1-9][0-9]{0,9})\z~D', $intent['path'], $match) === 1
            && (int)$match[1] <= 2147483647, 'NHE_FUND_DB_ORIGINAL_SIGNED_RECHARGE_RECIPIENT_ROUTE');
        $uid = (int)$match[1]; $body = $privateRequest['body'];
        nhep_expect(is_array($body), 'NHE_FUND_DB_REAL_FUNDING_BODY_OBJECT');
        nhe_keys($body, ['money_status', 'money', 'integration_status', 'integration', 'mark'], 'NHE_FUND_DB_FIXED_FIVE_FIELD_BODY');
        nhep_expect($body['money_status'] === 1 && $body['money'] === '100.00'
            && $body['integration_status'] === 0 && $body['integration'] === '0' && $body['mark'] === $intent['run_id'],
            'NHE_FUND_DB_ONLY_ORIGINAL_SYSTEM_HUNDRED_NO_INTEGRAL_CHANGE');
        nhe_keys($json, ['status', 'msg'], 'NHE_FUND_DB_NATIVE_FUNDING_SUCCESS_HAS_NO_DATA');
        nhep_expect($json['msg'] === '修改成功', 'NHE_FUND_DB_REAL_FUNDING_SUCCESS_MESSAGE');
        foreach (['eb_user_money', 'eb_user_recharge'] as $table)
            nhep_expect(isset($beforeDB2['database']['tables'][$table], $beforeDB2['rows'][$table]), 'NHE_FUND_DB_ORIGINAL_MONEY_TABLE_REQUIRED');
        $userMeta = $beforeDB2['database']['tables']['eb_user']['metadata'];
        $userIndex = nhep_auth_db_index($beforeDB2['rows']['eb_user'], $userMeta, 'uid', $uid);
        $recipient = $beforeDB2['rows']['eb_user'][$userIndex];
        nhep_expect($recipient['status'] === 1 && $recipient['is_del'] === 0 && $recipient['now_money'] === '0.00',
            'NHE_FUND_DB_ORIGINAL_ZERO_BALANCE_NORMAL_CUSTOMER');
        $balance = bcadd($recipient['now_money'], $body['money'], 2);
        nhep_expect($balance === '100.00', 'NHE_FUND_DB_INDEPENDENT_FIXED_SCALE_BALANCE');
        $expectedRows['eb_user'] = nhep_auth_db_update($beforeDB2, 'eb_user', $userIndex, ['now_money' => $balance]);
        $expectedRows['eb_user_money'] = nhep_auth_db_append($beforeDB2, $actualDB2, 'eb_user_money', [
            'uid' => $uid, 'link_id' => (string)$actorId, 'type' => 'system_add', 'title' => '系统增加余额',
            'number' => '100.00', 'balance' => $balance, 'pm' => 1, 'mark' => $intent['run_id'], 'status' => 1,
        ], $interval);
        $recharge = $beforeDB2['database']['tables']['eb_user_recharge'];
        $next = m4lh_actor_next($recharge, 'id');
        foreach ($beforeDB2['rows']['eb_user_recharge'] as $row)
            nhep_expect($row['id'] !== $next, 'NHE_FUND_DB_BEFORE_NEXT_RECHARGE_ID_ABSENT');
        $rechargeIndex = nhep_auth_db_index($actualDB2['rows']['eb_user_recharge'], $recharge['metadata'], 'id', $next);
        $observed = $actualDB2['rows']['eb_user_recharge'][$rechargeIndex];
        nhep_expect(is_string($observed['order_id']), 'NHE_FUND_DB_NATIVE_ORDER_CANDIDATE_ONLY');
        $order = nhep_funding_order_expected($beforeRedisCapture, $actualRedisCapture, $intent,
            $privateRequest, $privateResponse, $observed['order_id']);
        nhep_expect(is_string($order) && $order === $observed['order_id'], 'NHE_FUND_DB_COMPLETE_INDEPENDENT_ORDER_NUMBER');
        $payTime = nhep_funding_db_signed_time($recharge['metadata'], 'pay_time', $observed['pay_time'], $interval);
        $addTime = nhep_funding_db_signed_time($recharge['metadata'], 'add_time', $observed['add_time'], $interval);
        $newRecharge = m4lh_actor_expected_row($recharge['metadata'], [
            'id' => $next, 'uid' => $uid, 'order_id' => $order, 'price' => '100.00', 'give_price' => '0.00',
            'recharge_type' => 'system', 'paid' => 1, 'pay_time' => $payTime, 'add_time' => $addTime, 'channel_type' => 'system',
        ]);
        $expectedRows['eb_user_recharge'] = $beforeDB2['rows']['eb_user_recharge'];
        $expectedRows['eb_user_recharge'][] = $newRecharge;
        $expectedRows['eb_system_log'] = nhep_auth_db_append($beforeDB2, $actualDB2, 'eb_system_log', [
            'admin_id' => $actorId, 'admin_name' => $account, 'path' => 'user/update_other/<id>',
            'page' => nhep_funding_db_visit_page($beforeDB2), 'method' => 'adminapi', 'ip' => '127.0.0.1', 'type' => 'system',
        ], $interval);
        $insertCounts = ['eb_user_money' => 1, 'eb_user_recharge' => 1, 'eb_system_log' => 1];
    } else {
        nhep_expect($intent['path'] === '/api/userinfo' && $privateRequest['body'] === null,
            'NHE_FUND_DB_EXACT_FUNDED_CUSTOMER_GET');
        nhe_keys($json, ['status', 'msg', 'data'], 'NHE_FUND_DB_REAL_FUNDED_IDENTITY_JSON_KEYS');
        $data = $json['data'];
        if (in_array($step, ['two_paid_balance_read', 'refunded_balance_read'], true)) {
            nhep_expect(function_exists('nhep_two_paid_userinfo_value'),
                'NHE_FUND_DB_COMPLETE_ORIGINAL_TWO_PAID_USERINFO_MODEL_REQUIRED');
            $value = nhep_two_paid_userinfo_value($beforeDB2, $intent, $privateRequest);
            nhep_expect($json === ['status' => 200, 'msg' => 'success', 'data' => $value],
                'NHE_FUND_DB_COMPLETE_ORIGINAL_TWO_PAID_USERINFO_JSON');
        } else {
            nhep_expect(is_array($data) && $owner['now_money'] === '100.00'
                && ($data['uid'] ?? null) === $actorId && ($data['now_money'] ?? null) === '100.00'
                && ($data['last_time'] ?? null) === $owner['last_time'], 'NHE_FUND_DB_FUNDED_BEFORE_USER_DTO_NOT_AFTER_TIME');
        }
        $time = nhep_auth_db_time($actorMeta, 'last_time',
            $actualDB2['rows'][$actorTable][$actualActorIndex]['last_time'], $interval, $owner['last_time']);
        $expectedRows['eb_user'] = nhep_auth_db_update($beforeDB2, 'eb_user', $actorIndex, ['last_time' => $time]);
    }
    $expected = nhep_database_expected($beforeDB2, $expectedRows, $insertCounts);
    nhep_expect($expected === $actualDB2, 'NHE_FUND_DB_ALL_164_TABLES_COMPLETE_INDEPENDENT_EXPECTED');
    return $expected;
}

/** Definitions only. Original old-477 steps 7/8; no client, App, token issuer or entry point. */
function nhepfr_exchange(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $request, #[SensitiveParameter] array $response): bool
{
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'], 'NHEPFR_EXACT_ORIGINAL_INTENT_KEYS');
    $funding = ($intent['step'] ?? null) === 'platform_system_balance_add';
    $readSequence = ($intent['step'] ?? null) === 'funded_balance_read' ? 8
        : (($intent['step'] ?? null) === 'two_paid_balance_read' ? 21
            : (($intent['step'] ?? null) === 'refunded_balance_read' ? 27 : null));
    nhep_expect(PHP_INT_SIZE === 8 && ($funding || is_int($readSequence))
        && $intent['sequence'] === ($funding ? 7 : $readSequence) && $intent['actor'] === ($funding ? 'admin' : 'customer')
        && $intent['method'] === ($funding ? 'PUT' : 'GET') && $intent['origin'] === 'http://127.0.0.1:8000'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['path']), 'NHEPFR_ONLY_TWO_EXACT_NORMAL_FUNDING_INTENTS');
    $actorId = nhepar_uint($intent['actor_id']);
    if ($funding) {
        nhep_expect(preg_match('~\A/adminapi/user/update_other/([1-9][0-9]{0,9})\z~D', $intent['path'], $match) === 1,
            'NHEPFR_ORIGINAL_SYSTEM_BALANCE_ROUTE');
        nhepar_uint($match[1]);
    } else {
        nhep_expect($intent['path'] === '/api/userinfo', 'NHEPFR_ORIGINAL_FUNDED_CUSTOMER_IDENTITY_ROUTE');
    }
    nhe_keys($request, ['token', 'body', 'actor_identity'], 'NHEPFR_EXACT_PRIVATE_REQUEST_KEYS');
    nhep_expect(is_string($request['token']) && strlen($request['token']) >= 16 && strlen($request['token']) <= 4096
        && is_array($request['actor_identity']), 'NHEPFR_EXISTING_REAL_PRIVATE_ACTOR_TOKEN');
    nhe_keys($request['actor_identity'], ['id', 'account'], 'NHEPFR_EXACT_PRIVATE_ACTOR_IDENTITY');
    nhep_expect($request['actor_identity']['id'] === $actorId && is_string($request['actor_identity']['account'])
        && $request['actor_identity']['account'] !== '', 'NHEPFR_REAL_PRIVATE_ACTOR_IDENTITY_BINDING');
    nhep_expect($request['body'] === ($funding ? ['money_status' => 1, 'money' => '100.00',
        'integration_status' => 0, 'integration' => '0', 'mark' => $intent['run_id']] : null),
        'NHEPFR_ONLY_ORIGINAL_ONE_HUNDRED_SYSTEM_ADD_WITHOUT_POINTS');
    nhep_expect(($response['http'] ?? null) === 200 && ($response['transport_errno'] ?? null) === 0
        && ($response['primary_ip'] ?? null) === '127.0.0.1' && ($response['primary_port'] ?? null) === 8000
        && ($response['local_ip'] ?? null) === '127.0.0.1' && is_array($response['json'] ?? null)
        && is_array($response['actual_interval'] ?? null) && array_is_list($response['actual_interval'])
        && count($response['actual_interval']) === 2, 'NHEPFR_ORIGINAL_OWN_SUCCESSFUL_NATIVE_HTTP_EXCHANGE');
    foreach ($response['actual_interval'] as $time) nhep_expect(is_int($time) && $time > 0 && $time <= 4294967295,
        'NHEPFR_ORIGINAL_NATIVE_HTTP_SECOND_WINDOW');
    nhe_keys($response['json'], $funding ? ['status', 'msg'] : ['status', 'msg', 'data'], 'NHEPFR_ORIGINAL_JSON_RESPONSE_FIELDS');
    nhep_expect($response['json']['status'] === 200 && $response['json']['msg'] === ($funding ? '修改成功' : 'success')
        && ($funding || is_array($response['json']['data'])), 'NHEPFR_ORIGINAL_SUCCESS_WITHOUT_INVENTED_FUNDING_DATA');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPFR_COMPLETE_ATOMIC_CAPTURES_SAME_NATIVE_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $actualUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($actualUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$response['actual_interval'][0], 0) <= 0
        && $response['actual_interval'][0] <= $response['actual_interval'][1]
        && bccomp((string)$response['actual_interval'][1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPFR_HTTP_INSIDE_MONOTONIC_INDEPENDENT_REDIS_OBSERVATIONS');
    return $funding;
}

/**
 * A restricted native order number is decoded, independently proved and fully reconstructed.
 * Frozen old app: Redis DB0, raw unprefixed resolver, PHP64, Asia/Shanghai epoch; no App is loaded here.
 */
function nhep_funding_order_expected(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $request, #[SensitiveParameter] array $response, string $actualOrderNo): string
{
    nhep_expect(nhepfr_exchange($beforeCapture, $actualCapture, $intent, $request, $response), 'NHEPFR_ORDER_PROOF_ONLY_ORIGINAL_STEP_SEVEN');
    nhep_expect(preg_match('/\Acz([1-9][0-9]{0,18})\z/D', $actualOrderNo, $match) === 1
        && bccomp($match[1], '9223372036854775807', 0) <= 0, 'NHEPFR_CANONICAL_NATIVE_CZ_POSITIVE_SIGNED_64_BIT_NUMBER');
    $number = $match[1]; $elapsed = bcdiv($number, '4194304', 0); $low = bcmod($number, '4194304', 0);
    $datacenter = bcdiv($low, '131072', 0);
    $worker = bcmod(bcdiv($low, '4096', 0), '32', 0); $sequence = bcmod($low, '4096', 0);
    nhep_expect(bccomp($elapsed, '0', 0) > 0 && bccomp($elapsed, '2199023255551', 0) <= 0
        && $datacenter === '0' && $worker === '0' && $sequence === '0', 'NHEPFR_ORIGINAL_DEFAULT_NODE_IDS_AND_FRESH_ZERO_SEQUENCE_ONLY');
    // Old config/app.php and Think App initialization select Asia/Shanghai, not C-log UTC.
    $millis = bcadd('1640966400000', $elapsed, 0);
    $httpStart = bcmul((string)$response['actual_interval'][0], '1000', 0);
    $httpLast = bcsub(bcmul(bcadd((string)$response['actual_interval'][1], '1', 0), '1000', 0), '1', 0);
    nhep_expect(bccomp($millis, $httpStart, 0) >= 0 && bccomp($millis, $httpLast, 0) <= 0
        && bccomp($millis, $beforeCapture['snapshot']['time_ms'], 0) >= 0
        && bccomp($millis, $actualCapture['snapshot']['time_ms'], 0) <= 0,
        'NHEPFR_DECODED_NATIVE_MILLISECOND_IN_REAL_HTTP_AND_CAPTURE_WINDOWS');
    nhep_expect(nhepar_entry($beforeCapture, $millis) === null, 'NHEPFR_FRESH_BEFORE_RAW_MILLISECOND_KEY_REQUIRED');
    $expectedNumber = bcadd(bcmul(bcsub($millis, '1640966400000', 0), '4194304', 0), '0', 0);
    $expected = 'cz' . $expectedNumber;
    nhep_expect($expected === $actualOrderNo, 'NHEPFR_FULL_INDEPENDENT_CZ_RECONSTRUCTION');
    $row = nhepar_entry($actualCapture, $millis); $latestDeadline = bcadd($httpLast, '1000', 0);
    if ($row === null) {
        // This proves only the final naturally expired namespace. No expired DUMP or exact TTL was observed.
        nhep_expect(bccomp($actualCapture['snapshot']['time_ms'], $latestDeadline, 0) > 0,
            'NHEPFR_MISSING_COUNTER_ONLY_AFTER_PROVEN_LAST_POSSIBLE_DEADLINE');
    } else {
        nhep_expect($row['type'] === 'string' && $row['value'] === '1' && is_int($row['expires']) && $row['expires'] > 0
            && bccomp((string)$row['expires'], bcadd($millis, '1000', 0), 0) >= 0
            && bccomp((string)$row['expires'], $latestDeadline, 0) <= 0
            && bccomp((string)$row['expires'], $actualCapture['snapshot']['time_ms'], 0) >= 0,
            'NHEPFR_ORIGINAL_FIRST_PSETEX_STRING_ONE_AND_COMPLETE_ABSOLUTE_DEADLINE');
        // Bind only after the complete independent raw type/value/deadline proof above.
        nhepar_bind($actualCapture, $millis, 'string', '1', ['ttl' => 1], $beforeCapture['snapshot']);
    }
    return $expected;
}

/** Old AuthV2 verify branch only. It reads the real request token and never expects JSON data. */
function nhepfr_admin_verify(#[SensitiveParameter] array $before, #[SensitiveParameter] array $actual,
    #[SensitiveParameter] array $actor, array $intent, #[SensitiveParameter] array $request,
    #[SensitiveParameter] array $response, #[SensitiveParameter] array $configuration): void
{
    nhep_expect($intent['step'] === 'platform_system_balance_add' && is_string($request['token']), 'NHEPFR_ONLY_REAL_NONLOGIN_ADMIN_VERIFY');
    $token = $request['token']; $claims = nhepar_jwt($token, $configuration['signing_key']);
    nhe_keys($claims, ['auth_schema', 'session_epoch', 'sid', 'session_version', 'iss', 'aud', 'jti', 'iat', 'nbf', 'exp'], 'NHEPFR_ADMIN_COMPLETE_ORIGINAL_CLAIMS');
    nhep_expect(is_array($claims['jti']), 'NHEPFR_ADMIN_ORIGINAL_SUBJECT_OBJECT');
    nhe_keys($claims['jti'], ['id', 'type'], 'NHEPFR_ADMIN_ORIGINAL_SUBJECT_FIELDS'); $id = (string)nhepar_uint($actor['id']);
    nhep_expect($claims['auth_schema'] === 2 && $claims['session_epoch'] === $configuration['auth']['session_epoch']
        && $claims['iss'] === $configuration['auth']['issuer'] && $claims['aud'] === 'adminapi'
        && $claims['jti'] === ['id' => $id, 'type' => 'admin'] && is_string($claims['sid']) && is_string($claims['session_version'])
        && preg_match('/\A[a-f0-9]{32}\z/D', $claims['sid']) === 1
        && preg_match('/\A[a-f0-9]{32}\z/D', $claims['session_version']) === 1, 'NHEPFR_ADMIN_REAL_SUBJECT_AND_ORIGINAL_NONCES');
    nhepar_time_claims($claims, $response['actual_interval'], false, $actual['snapshot'], true);
    $prefix = 'auth:v2:' . $configuration['auth']['session_epoch'] . ':adminapi:';
    $accountKey = $prefix . 'account:' . $id; $sessionKey = $prefix . 'session:' . $claims['sid'];
    $account = nhepar_pairs(['initialized' => '1', 'blocked' => '0', 'session_version' => $claims['session_version']]);
    $session = nhepar_pairs(['subject_id' => $id, 'session_version' => $claims['session_version'], 'type' => 'admin', 'audience' => 'adminapi',
        'token_digest' => hash('sha256', $token), 'credential_stamp' => hash_hmac('sha256', 'adminapi|' . $id . '|' . $actor['pwd'], $configuration['auth']['stamp_key']),
        'expires_at' => (string)$claims['exp'], 'status' => 'active']);
    $deadline = ($claims['exp'] + 60) * 1000; $oldAccount = nhepar_entry($before, $accountKey); $oldSession = nhepar_entry($before, $sessionKey);
    $accountDescriptor = nhepar_bind($actual, $accountKey, 'hash', $account, -1, $before['snapshot']);
    $sessionDescriptor = nhepar_bind($actual, $sessionKey, 'hash', $session, $deadline, $before['snapshot']);
    nhep_expect(is_array($oldAccount) && $oldAccount['type'] === 'hash' && $oldAccount['value'] === $account && $oldAccount['expires'] === -1
        && is_array($oldSession) && $oldSession['type'] === 'hash' && $oldSession['value'] === $session && $oldSession['expires'] === $deadline
        && $accountDescriptor === $before['snapshot']['keys'][hash('sha256', $accountKey)]
        && $sessionDescriptor === $before['snapshot']['keys'][hash('sha256', $sessionKey)], 'NHEPFR_REAL_ADMIN_VERIFY_COMPLETE_BINDING_WITHOUT_RENEWAL');
}

/**
 * Only exact steps 7/8. Caller supplies complete original BEFORE rows and the same actual captures as DB.
 * Step 7's last argument is only the next-PK-bound native recharge number; step 8 must pass null.
 */
function nhep_funding_redis_model(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    #[SensitiveParameter] array $beforeDBrows, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse, #[SensitiveParameter] array $privateAuthConfiguration, ?string $actualOrderNo = null): array
{
    $funding = nhepfr_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhep_expect($funding ? is_string($actualOrderNo) : $actualOrderNo === null, 'NHEPFR_NATIVE_ORDER_NUMBER_ONLY_FOR_STEP_SEVEN');
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id'] && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']), 'NHEPFR_SAME_RUN_REAL_PRIVATE_AUTH_CONFIGURATION');
    foreach (['eb_system_config', 'eb_system_event', 'eb_system_notification', 'eb_out_account', 'eb_user'] as $table)
        nhep_expect(is_array($beforeDBrows[$table] ?? null) && array_is_list($beforeDBrows[$table]), 'NHEPFR_COMPLETE_ORIGINAL_BEFORE_TABLES_REQUIRED');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect(array_key_exists($table, $beforeDBrows) && $beforeDBrows[$table] === [], 'NHEPFR_ORIGINAL_EMPTY_LANGUAGE_FIXTURE');
    foreach ($beforeDBrows['eb_system_event'] as $row) nhep_expect(!(nhepar_uint($row['is_del'] ?? null, true) === 0
        && nhepar_uint($row['is_open'] ?? null, true) === 1), 'NHEPFR_ENABLED_CUSTOM_EVENT_NOT_IMPLEMENTED');
    foreach ($beforeDBrows['eb_system_notification'] as $row) foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat', 'is_app'] as $field)
        nhep_expect(nhepar_uint($row[$field] ?? null, true) === 0, 'NHEPFR_ENABLED_CUSTOM_NOTICE_NOT_IMPLEMENTED');
    foreach ($beforeDBrows['eb_out_account'] as $row) {
        $deleted = nhepar_uint($row['is_del'] ?? null, true); $status = nhepar_uint($row['status'] ?? null, true);
        $push = nhepar_uint($row['push_open'] ?? null, true);
        nhep_expect(!($deleted === 0 && $status === 1 && $push === 1), 'NHEPFR_ACTIVE_OUTPUSH_ACCOUNT_BRANCH_NOT_IMPLEMENTED');
    }
    $actor = nhepar_actor($beforeDBrows, $intent, $privateRequest); $changes = []; $tagMembers = [];
    if ($funding) {
        preg_match('~\A/adminapi/user/update_other/([1-9][0-9]{0,9})\z~D', $intent['path'], $match); $uid = nhepar_uint($match[1]);
        $users = array_values(array_filter($beforeDBrows['eb_user'], static fn(array $row): bool => nhepar_uint($row['uid'] ?? null) === $uid));
        nhep_expect(count($users) === 1 && ($users[0]['now_money'] ?? null) === '0.00'
            && nhepar_uint($users[0]['status'] ?? null, true) === 1 && nhepar_uint($users[0]['is_del'] ?? null, true) === 0,
            'NHEPFR_REAL_BEFORE_ZERO_BALANCE_TARGET_CUSTOMER');
        nhepfr_admin_verify($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config);
    } else {
        $readBalance = $intent['step'] === 'two_paid_balance_read' ? '59.70'
            : ($intent['step'] === 'refunded_balance_read' ? '79.85' : '100.00');
        nhep_expect(($actor['now_money'] ?? null) === $readBalance
            && nhepar_uint($privateResponse['json']['data']['uid'] ?? null) === nhepar_uint($actor['uid'])
            && ($privateResponse['json']['data']['now_money'] ?? null) === $readBalance, 'NHEPFR_REAL_ALREADY_FUNDED_CUSTOMER_AND_RESPONSE');
        $apiTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('api'));
        nhep_expect(is_array($apiTag) && $apiTag['type'] === 'set' && $apiTag['expires'] === -1
            && in_array('c:' . md5($privateRequest['token']), $apiTag['value'], true), 'NHEPFR_ORIGINAL_CUSTOMER_WHITELIST_TAG_MEMBERSHIP');
        nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);
    }
    // Cache N; is getter null; sys_config converts it to ''. PHP8 '' != 0 enters both filter reads.
    foreach ($funding ? ['param_filter_type', 'param_filter_data'] : ['station_open', 'extract_time'] as $name) {
        $matches = array_values(array_filter($beforeDBrows['eb_system_config'], static fn(array $row): bool => ($row['menu_name'] ?? null) === $name));
        if ($name === 'station_open') {
            nhep_expect(count($matches) === 1 && is_string($matches[0]['value'] ?? null)
                && json_decode($matches[0]['value'], true, 8, JSON_THROW_ON_ERROR) === 1, 'NHEPFR_REAL_INSTALLED_OPEN_STATION_CONFIG');
            $wire = '1';
        } else {
            nhep_expect($matches === [], 'NHEPFR_ORIGINAL_ABSENT_DB_CONFIG_INDEPENDENT_NULL_WIRE'); $wire = 'N;';
        }
        nhep_expect(nhepar_entry($beforeCapture, 'c:system_config_' . $name) !== null, 'NHEPFR_FIRST_SIX_WARM_CONFIG_HIT_REQUIRED');
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire) {
        if (!in_array($intent['step'], ['two_paid_balance_read', 'refunded_balance_read'], true))
            nhep_expect(nhepar_entry($beforeCapture, 'c:' . $name) !== null, 'NHEPFR_FIRST_SIX_ACTIVE_LANGUAGE_CACHE_REQUIRED');
        nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
    }
    $tagKey = 'c:CRMEB:' . md5('crmeb'); $tag = nhepar_entry($beforeCapture, $tagKey);
    nhep_expect(is_array($tag) && $tag['type'] === 'set' && $tag['expires'] === -1, 'NHEPFR_ORIGINAL_COMPLETE_CRMEB_TAG_REQUIRED');
    foreach ($tagMembers as $member) nhep_expect(in_array($member, $tag['value'], true), 'NHEPFR_ORIGINAL_WARM_CACHE_TAG_MEMBERSHIP');
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', [], $changes);
    nhep_expect($changes[$tagKey] === $beforeCapture['snapshot']['keys'][hash('sha256', $tagKey)], 'NHEPFR_COMPLETE_ORIGINAL_CRMEB_TAG_NOT_CHANGED');
    if ($funding) {
        $expectedOrder = nhep_funding_order_expected($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse, $actualOrderNo);
        $key = bcadd('1640966400000', bcdiv(substr($expectedOrder, 2), '4194304', 0), 0);
        $changes[$key] = nhepar_entry($actualCapture, $key) === null ? null
            : nhepar_bind($actualCapture, $key, 'string', '1', ['ttl' => 1], $beforeCapture['snapshot']);
    }
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'], 'NHEPFR_COMPLETE_NAMESPACE_UNKNOWN_REDIS_SIDE_EFFECT_REJECTED');
    return $expected;
}

/** Source-reviewed cart/confirm DB definitions only; Redis and observer dispatch remain pending. */
/** Pure finite cart/confirm DB candidate. Native rows and private HTTP data stay in RAM. */
function nhepcd_id(#[SensitiveParameter] mixed $value, int $maximum = 4294967295): int
{
    nhep_expect((is_int($value) || is_string($value))
        && preg_match('/\A[1-9][0-9]{0,9}\z/D', (string)$value) === 1
        && bccomp((string)$value, (string)$maximum, 0) <= 0,
        'NHE_CART_DB_CANONICAL_POSITIVE_ORIGINAL_ID');
    return (int)$value;
}

/** Exact independent BEFORE selection; the native row is never taken from AFTER. */
function nhepcd_one(#[SensitiveParameter] array $before, string $table,
    #[SensitiveParameter] array $where): array
{
    nhep_expect(isset($before['database']['tables'][$table], $before['rows'][$table])
        && $where !== [], 'NHE_CART_DB_COMPLETE_BEFORE_SELECTOR');
    $metadata = $before['database']['tables'][$table]['metadata']; $wanted = []; $matches = [];
    foreach ($where as $column => $value) {
        nhep_expect(isset($metadata['columns'][$column]), 'NHE_CART_DB_REAL_SELECTOR_COLUMN');
        $wanted[$column] = m4lh_actor_native($metadata['columns'][$column], $value);
    }
    foreach ($before['rows'][$table] as $index => $row) {
        $match = true;
        foreach ($wanted as $column => $value) {
            nhep_expect(array_key_exists($column, $row)
                && m4lh_actor_native($metadata['columns'][$column], $row[$column]) === $row[$column],
                'NHE_CART_DB_SELECTOR_ORIGINAL_NATIVE_TYPE');
            if ($row[$column] !== $value) $match = false;
        }
        if ($match) $matches[] = ['index' => $index, 'row' => $row, 'metadata' => $metadata];
    }
    nhep_expect(count($matches) === 1, 'NHE_CART_DB_UNIQUE_BEFORE_FIXTURE_ROW');
    return $matches[0];
}

/** Reconstruct the fixed Run fixture identities from BEFORE, without a receipt/ACK argument. */
function nhepcd_fixture(#[SensitiveParameter] array $before, array $intent,
    #[SensitiveParameter] array $request): array
{
    $uid = $request['actor_identity']['id']; $account = $request['actor_identity']['account'];
    nhep_expect(is_int($uid) && $uid > 0 && $uid <= 2147483647 && $intent['actor_id'] === $uid
        && is_string($account) && preg_match('/\A[a-z0-9_]{10,32}\z/D', $account) === 1,
        'NHE_CART_DB_REAL_CUSTOMER_ID_ACCOUNT_AND_SIGNED_LOG_RANGE');
    $sentinels = $before['rows']['audit_sentinel'] ?? null;
    nhep_expect(is_array($sentinels) && count($sentinels) === 1
        && ($sentinels[0]['run_id'] ?? null) === $intent['run_id'], 'NHE_CART_DB_BEFORE_SAME_ORIGINAL_RUN');
    $owner = nhepcd_one($before, 'eb_user', ['uid' => $uid]); $user = $owner['row'];
    nhep_expect($user['account'] === $account && $user['status'] === 1 && $user['is_del'] === 0
        && $user['user_type'] === 'h5' && $user['is_money_level'] === 0 && $user['spread_uid'] === 0
        && $user['nickname'] === '旧历史普通顾客' && is_int($user['add_time']) && $user['add_time'] > 0,
        'NHE_CART_DB_ORIGINAL_ELIGIBLE_NORMAL_CUSTOMER');
    $product = nhepcd_one($before, 'eb_store_product', ['store_name' => '旧历史商品-' . $intent['run_id']]);
    $root = $product['row']; $productId = nhepcd_id($root['id'], 2147483647);
    foreach (['is_del' => 0, 'is_show' => 1, 'review_status' => 2, 'spec_type' => 1,
        'is_virtual' => 0, 'virtual_type' => 0, 'vip_product' => 0, 'is_vip' => 0,
        'is_limit' => 0, 'freight' => 1, 'temp_id' => 1, 'is_postage' => 1,
        'logistics' => '1', 'min_qty' => 1, 'unit_name' => '件', 'price' => '20.15', 'cost' => '7.45',
        'postage' => '0.00', 'custom_form' => '[]', 'add_time' => $user['add_time']] as $column => $value)
        nhep_expect(array_key_exists($column, $root) && $root[$column] === $value,
            'NHE_CART_DB_ORIGINAL_NORMAL_PRODUCT_BRANCH');
    nhep_expect(is_int($root['stock']) && $root['stock'] >= 1 && is_int($root['sales']) && $root['sales'] >= 0,
        'NHE_CART_DB_CURRENT_ROOT_INVENTORY_NOT_RESET');
    $merchantId = nhepcd_id($root['mer_id']);
    $merchant = nhepcd_one($before, 'eb_marketplace_merchant', ['mer_id' => $merchantId]);
    foreach (['review_status' => 1, 'accept_orders' => 1, 'security_locked' => 0,
        'fulfillment_enabled' => 1, 'closed_at' => null] as $column => $value)
        nhep_expect(array_key_exists($column, $merchant['row']) && $merchant['row'][$column] === $value,
            'NHE_CART_DB_REAL_ENABLED_PRODUCT_OWNER');
    $unique = substr(hash('sha256', 'legacy-sku-' . $intent['run_id']), 0, 8);
    // Production first selects unique/type globally, then checks its product_id.
    $sku = nhepcd_one($before, 'eb_store_product_attr_value', ['unique' => $unique, 'type' => 0]);
    $skuRow = $sku['row']; $skuId = nhepcd_id($skuRow['id']);
    nhep_expect($skuRow['product_id'] === $productId && $skuRow['suk'] === '普通'
        && $skuRow['price'] === '20.15' && $skuRow['cost'] === '7.45'
        && $skuRow['is_show'] === 1 && $skuRow['is_virtual'] === 0
        && is_int($skuRow['stock']) && $skuRow['stock'] >= 1
        && is_int($skuRow['sales']) && $skuRow['sales'] >= 0,
        'NHE_CART_DB_RUN_SKU_REAL_PRODUCT_AND_CURRENT_INVENTORY');
    $attribute = nhepcd_one($before, 'eb_store_product_attr', ['product_id' => $productId, 'type' => 0]);
    nhep_expect($attribute['row']['attr_name'] === '规格' && $attribute['row']['attr_values'] === '普通',
        'NHE_CART_DB_ORIGINAL_RUN_SPECIFICATION');
    // The original fixture creates one address for this newly created identity.
    $address = nhepcd_one($before, 'eb_user_address', ['uid' => $uid]);
    $addressId = nhepcd_id($address['row']['id']);
    $expectedAddress = m4lh_actor_expected_row($address['metadata'], [
        'id' => $addressId, 'uid' => $uid, 'real_name' => '隔离普通顾客', 'phone' => '00000000000',
        'province' => '验证省', 'city' => '验证市', 'district' => '验证区', 'detail' => '专用旧历史地址',
        'is_default' => 1, 'add_time' => $user['add_time'],
    ]);
    nhep_expect($address['row'] === $expectedAddress, 'NHE_CART_DB_ORIGINAL_OWNED_VALID_FIXTURE_ADDRESS');
    $template = nhepcd_one($before, 'eb_shipping_templates', ['id' => 1]);
    nhep_expect($template['row'] === m4lh_actor_expected_row($template['metadata'], [
        'id' => 1, 'name' => '默认模版', 'type' => 1, 'appoint' => 0, 'no_delivery' => 0,
        'sort' => 0, 'add_time' => 1658394592,
    ]), 'NHE_CART_DB_ORIGINAL_INITIALIZER_SHIPPING_TEMPLATE');
    return ['uid' => $uid, 'user' => $owner, 'product_id' => $productId, 'sku_id' => $skuId,
        'sku_unique' => $unique, 'address_id' => $addressId];
}

/** Prove the finite normal selectors; cache warmth is a separate Redis responsibility. */
function nhepcd_before_guards(#[SensitiveParameter] array $before, bool $cart): void
{
    $settings = $cart ? ['queue_open'] : ['image_thumb_status', 'member_func_status',
        'member_card_status', 'member_price_status'];
    foreach ($settings as $name) {
        foreach ($before['rows']['eb_system_config'] as $row) {
            nhep_expect(is_string($row['menu_name']), 'NHE_CART_DB_NATIVE_CONFIG_NAME');
            nhep_expect(strtolower(rtrim($row['menu_name'], ' ')) !== $name || $row['menu_name'] === $name,
                'NHE_CART_DB_CANONICAL_UNAMBIGUOUS_CONFIGURATION_NAME');
        }
        $setting = nhepcd_one($before, 'eb_system_config', ['menu_name' => $name]);
        nhep_expect(is_string($setting['row']['value']) && $setting['row']['value'] === '0'
            && json_decode($setting['row']['value'], true) === 0 && json_last_error() === JSON_ERROR_NONE,
            'NHE_CART_DB_ORIGINAL_NORMAL_JSON_ZERO_CONFIGURATION');
    }
    $columns = $before['database']['tables']['eb_system_event']['metadata']['columns'];
    foreach ($before['rows']['eb_system_event'] as $row) {
        $deleted = m4lh_actor_native($columns['is_del'], $row['is_del']);
        $open = m4lh_actor_native($columns['is_open'], $row['is_open']);
        nhep_expect($deleted === $row['is_del'] && $open === $row['is_open']
            && is_int($deleted) && is_int($open) && !($deleted === 0 && $open === 1),
            'NHE_CART_DB_ENABLED_CUSTOM_EVENT_NOT_IMPLEMENTED');
    }
    nhep_funding_db_no_outpush($before);
    if (!$cart) nhep_expect($before['rows']['eb_store_coupon_issue'] === [],
        'NHE_CART_DB_AUTO_COUPON_CANDIDATE_BRANCH_NOT_IMPLEMENTED');
}

/** Only four fixed steps. AFTER supplies checked next-PK candidates and interval-native times. */
function nhep_cart_confirm_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhep_auth_db_index',
        'nhep_auth_db_time', 'nhep_auth_db_update', 'nhep_auth_db_append', 'nhep_database_expected',
        'nhep_funding_db_signed_time', 'nhep_funding_db_no_outpush', 'm4lh_actor_native',
        'm4lh_actor_expected_row', 'm4lh_actor_next', 'm4lh_actor_projection', 'bccomp'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_CART_DB_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHE_CART_DB_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHE_CART_DB_ORIGINAL_PRIVATE_REQUEST');
    nhep_expect(is_array($privateRequest['actor_identity']), 'NHE_CART_DB_PRIVATE_ACTOR_OBJECT');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHE_CART_DB_PRIVATE_ACTOR_IDENTITY');
    $steps = [
        'refund_family_cart' => [9, true], 'refund_family_confirm' => [10, false],
        'review_family_cart' => [15, true], 'review_family_confirm' => [16, false],
    ];
    nhep_expect(is_string($intent['step']) && isset($steps[$intent['step']]), 'NHE_CART_DB_STEP_NOT_IMPLEMENTED');
    [$sequence, $cart] = $steps[$intent['step']];
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === 'POST'
        && $intent['path'] === ($cart ? '/api/cart/add' : '/api/order/confirm')
        && $intent['actor'] === 'customer' && $intent['origin'] === 'http://127.0.0.1:8000'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['body']), 'NHE_CART_DB_EXACT_ORIGINAL_NORMAL_HTTP_STEP');
    $interval = $privateResponse['actual_interval'] ?? null;
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && ($privateResponse['http'] ?? null) === 200 && ($privateResponse['transport_errno'] ?? null) === 0
        && array_key_exists('transport_failure_class', $privateResponse) && $privateResponse['transport_failure_class'] === null
        && ($privateResponse['primary_ip'] ?? null) === '127.0.0.1' && ($privateResponse['primary_port'] ?? null) === 8000
        && is_string($privateResponse['raw'] ?? null) && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json'] ?? null), 'NHE_CART_DB_REAL_COMPLETE_NORMAL_HTTP_RESPONSE');
    $json = $privateResponse['json']; $decoded = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $json
        && ($json['status'] ?? null) === 200 && is_string($json['msg'] ?? null)
        && is_array($json['data'] ?? null), 'NHE_CART_DB_ORIGINAL_SUCCESS_RESPONSE');
    $fixture = nhepcd_fixture($beforeDB2, $intent, $privateRequest);
    nhepcd_before_guards($beforeDB2, $cart);
    $uid = $fixture['uid']; $productId = $fixture['product_id']; $unique = $fixture['sku_unique'];
    $user = $fixture['user']; $actualUser = nhep_auth_db_index($actualDB2['rows']['eb_user'],
        $user['metadata'], 'uid', $uid);
    $time = nhep_auth_db_time($user['metadata'], 'last_time',
        $actualDB2['rows']['eb_user'][$actualUser]['last_time'], $interval, $user['row']['last_time']);
    $expectedRows = ['eb_user' => nhep_auth_db_update($beforeDB2, 'eb_user', $user['index'], ['last_time' => $time])];
    $insertCounts = []; $body = $privateRequest['body']; $data = $json['data'];
    if ($cart) {
        nhe_keys($body, ['productId', 'cartNum', 'uniqueId', 'new', 'is_new', 'combinationId',
            'secKillId', 'bargainId', 'advanceId', 'pinkId'], 'NHE_CART_DB_EXACT_TEN_FIELD_CART_BODY');
        nhep_expect($body === ['productId' => $productId, 'cartNum' => 1, 'uniqueId' => $unique,
            'new' => 0, 'is_new' => 0, 'combinationId' => 0, 'secKillId' => 0, 'bargainId' => 0,
            'advanceId' => 0, 'pinkId' => 0], 'NHE_CART_DB_FIXED_ORIGINAL_NORMAL_CART_INPUT');
        $cartColumns = $beforeDB2['database']['tables']['eb_store_cart']['metadata']['columns'];
        foreach ($beforeDB2['rows']['eb_store_cart'] as $row) {
            foreach (['uid', 'product_id', 'product_attr_unique', 'status'] as $column)
                nhep_expect(m4lh_actor_native($cartColumns[$column], $row[$column]) === $row[$column],
                    'NHE_CART_DB_ORIGINAL_STOCK_SELECTOR_NATIVE_VALUES');
            // Stock correction is broader than merge: do not filter old pay/del/new/type flags.
            nhep_expect(!($row['uid'] === $uid && $row['product_id'] === $productId
                && $row['product_attr_unique'] === $unique && ($row['status'] === 1 || $row['status'] === null)),
                'NHE_CART_DB_EXISTING_STOCK_ADJUSTMENT_OR_MERGE_BRANCH_NOT_IMPLEMENTED');
        }
        $cartTable = $beforeDB2['database']['tables']['eb_store_cart'];
        $cartId = m4lh_actor_next($cartTable, 'id');
        nhe_keys($data, ['cartId'], 'NHE_CART_DB_ORIGINAL_CART_RESPONSE_ONLY_ID');
        nhep_expect(nhepcd_id($data['cartId']) === $cartId, 'NHE_CART_DB_RESPONSE_MATCHES_INDEPENDENT_BEFORE_NEXT_PK');
        $expectedRows['eb_store_cart'] = nhep_auth_db_append($beforeDB2, $actualDB2, 'eb_store_cart', [
            'uid' => $uid, 'product_id' => $productId, 'cart_num' => 1, 'product_attr_unique' => $unique, 'type' => '0',
        ], $interval);
        $insertCounts['eb_store_cart'] = 1;
        $table = 'eb_store_product_log'; $original = $beforeDB2['database']['tables'][$table];
        $logId = m4lh_actor_next($original, 'id');
        foreach ($beforeDB2['rows'][$table] as $row)
            nhep_expect($row['id'] !== $logId, 'NHE_CART_DB_LOG_BEFORE_NEXT_ID_ABSENT');
        $logIndex = nhep_auth_db_index($actualDB2['rows'][$table], $original['metadata'], 'id', $logId);
        $logTime = nhep_funding_db_signed_time($original['metadata'], 'add_time',
            $actualDB2['rows'][$table][$logIndex]['add_time'], $interval);
        $log = m4lh_actor_expected_row($original['metadata'], ['id' => $logId, 'type' => 'cart',
            'product_id' => $productId, 'uid' => $uid, 'cart_num' => 1, 'add_time' => $logTime]);
        $expectedRows[$table] = $beforeDB2['rows'][$table]; $expectedRows[$table][] = $log;
        $insertCounts[$table] = 1;
    } else {
        nhe_keys($body, ['cartId', 'new', 'addressId', 'shipping_type', 'is_gift'],
            'NHE_CART_DB_EXACT_FIVE_FIELD_CONFIRM_BODY');
        $cartId = nhepcd_id($body['cartId']);
        nhep_expect(is_string($body['cartId']) && $body === ['cartId' => (string)$cartId, 'new' => 0,
            'addressId' => $fixture['address_id'], 'shipping_type' => 1, 'is_gift' => 0],
            'NHE_CART_DB_ORIGINAL_SINGLE_CART_OWNED_ADDRESS_CONFIRM_INPUT');
        $saved = nhepcd_one($beforeDB2, 'eb_store_cart', ['id' => $cartId]);
        $row = $saved['row'];
        nhep_expect(is_int($row['add_time']) && $row['add_time'] > 0 && $row['add_time'] <= $interval[1]
            && $row === m4lh_actor_expected_row($saved['metadata'], ['id' => $cartId, 'uid' => $uid,
                'product_id' => $productId, 'cart_num' => 1, 'product_attr_unique' => $unique,
                'type' => '0', 'add_time' => $row['add_time']]),
            'NHE_CART_DB_BEFORE_REAL_OWNED_UNPAID_PERSISTENT_RUN_CART');
        nhep_expect(is_array($data['userInfo'] ?? null) && is_array($data['addressInfo'] ?? null)
            && nhepcd_id($data['userInfo']['uid'] ?? null) === $uid
            && nhepcd_id($data['addressInfo']['id'] ?? null) === $fixture['address_id']
            && nhepcd_id($data['addressInfo']['uid'] ?? null) === $uid && ($data['valid_count'] ?? null) === 1,
            'NHE_CART_DB_CONFIRM_RESPONSE_REAL_OWNER_ADDRESS_AND_ONE_VALID_CART');
        // Neither response DTO nor orderKey is used as an expected DB row.
    }
    $expected = nhep_database_expected($beforeDB2, $expectedRows, $insertCounts);
    nhep_expect($expected === $actualDB2, 'NHE_CART_DB_ALL_164_TABLES_COMPLETE_INDEPENDENT_EXPECTED');
    return $expected;
}

/** Complete confirmation value and cart/confirm Redis definitions; source-only, not dispatched. */
/** Rebuild one complete native BEFORE row in the actual ordered metadata columns. */
function nhepcv_native_row(#[SensitiveParameter] array $before, string $table, int $index): array
{
    nhep_expect(isset($before['database']['tables'][$table], $before['rows'][$table][$index]),
        'NHE_CONFIRM_VALUE_ORIGINAL_FULL_ROW_REQUIRED');
    $definition = $before['database']['tables'][$table]; $columns = $definition['metadata']['columns'];
    $row = $before['rows'][$table][$index];
    nhep_expect($columns !== [] && array_keys($columns) === $definition['projected_columns']
        && array_keys($row) === array_keys($columns), 'NHE_CONFIRM_VALUE_ORIGINAL_COLUMN_ORDER');
    $rebuilt = [];
    foreach ($columns as $name => $column) {
        nhep_expect(($column['COLUMN_NAME'] ?? null) === $name
            && ($column['GENERATION_EXPRESSION'] ?? null) === '',
            'NHE_CONFIRM_VALUE_REAL_ORDERED_NATIVE_COLUMN_DEFINITION');
        $rebuilt[$name] = m4lh_actor_native($column, $row[$name]);
    }
    nhep_expect($rebuilt === $row, 'NHE_CONFIRM_VALUE_EVERY_ORIGINAL_NATIVE_FIELD_TYPE');
    return $rebuilt;
}

/** Read only the fixed BEFORE configuration, or prove the one explicit missing-key default. */
function nhepcv_config(#[SensitiveParameter] array $before, array $intent, string $name,
    #[SensitiveParameter] mixed $wanted, bool $absent = false): mixed
{
    $matches = [];
    foreach ($before['rows']['eb_system_config'] as $index => $row) {
        nhep_expect(is_string($row['menu_name']), 'NHE_CONFIRM_VALUE_NATIVE_CONFIGURATION_NAME');
        nhep_expect(strtolower(rtrim($row['menu_name'], ' ')) !== $name || $row['menu_name'] === $name,
            'NHE_CONFIRM_VALUE_CANONICAL_UNAMBIGUOUS_CONFIGURATION');
        if ($row['menu_name'] === $name) $matches[] = $index;
    }
    if ($absent) {
        nhep_expect($name === 'offline_postage' && $wanted === null && $matches === [],
            'NHE_CONFIRM_VALUE_ORIGINAL_OFFLINE_POSTAGE_MISSING_DEFAULT');
        return null;
    }
    nhep_expect(count($matches) === 1, 'NHE_CONFIRM_VALUE_UNIQUE_ORIGINAL_CONFIGURATION_ROW');
    $row = nhepcv_native_row($before, 'eb_system_config', $matches[0]);
    nhep_expect(is_string($row['value']) && ($row['info'] ?? null) === 'normal-' . $intent['run_id']
        && ($row['desc'] ?? null) === 'synthetic-legacy-normal-config',
        'NHE_CONFIRM_VALUE_CURRENT_RUN_ORIGINAL_CONFIGURATION_FIXTURE');
    $decoded = json_decode($row['value'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $wanted
        && json_encode($wanted, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) === $row['value'],
        'NHE_CONFIRM_VALUE_EXACT_ORIGINAL_JSON_CONFIGURATION_TYPE');
    return $decoded;
}

/** The observed decimal is only a candidate: independently reconstruct the old fresh Snowflake. */
function nhepcv_order_key(#[SensitiveParameter] string $actualOrderKey, array $interval): string
{
    nhep_expect(PHP_INT_SIZE === 8 && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && preg_match('/\A[1-9][0-9]{0,18}\z/D', $actualOrderKey) === 1
        && bccomp($actualOrderKey, '9223372036854775807', 0) <= 0,
        'NHE_CONFIRM_VALUE_ORIGINAL_SIGNED_64_BIT_KEY_AND_HTTP_INTERVAL');
    // Old App Asia/Shanghai midnight 2020-06-05, not the funding 2022 epoch.
    $epoch = '1591286400000'; $shift = '4194304';
    nhep_expect(bcmod($actualOrderKey, $shift, 0) === '0',
        'NHE_CONFIRM_VALUE_DEFAULT_NODE_AND_FIRST_SEQUENCE_ZERO');
    $delta = bcdiv($actualOrderKey, $shift, 0);
    nhep_expect(bccomp($delta, '0', 0) >= 0 && bccomp($delta, '2199023255551', 0) <= 0,
        'NHE_CONFIRM_VALUE_ORIGINAL_41_BIT_MILLISECOND_DIFFERENCE');
    $millisecond = bcadd($epoch, $delta, 0);
    $earliest = bcmul((string)$interval[0], '1000', 0);
    $latest = bcadd(bcmul((string)$interval[1], '1000', 0), '999', 0);
    nhep_expect(bccomp($millisecond, $earliest, 0) >= 0 && bccomp($millisecond, $latest, 0) <= 0,
        'NHE_CONFIRM_VALUE_NATIVE_KEY_MILLISECOND_INSIDE_REAL_HTTP_WINDOW');
    $expected = bcmul(bcsub($millisecond, $epoch, 0), $shift, 0);
    nhep_expect($expected === $actualOrderKey, 'NHE_CONFIRM_VALUE_FULL_ORIGINAL_KEY_RECONSTRUCTED');
    return $expected;
}

/** Definitions-only full private order-confirmation value for precisely old normal steps 10/16. */
function nhep_confirmation_value_expected(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] string $actualOrderKey,
    array $actualHTTPInterval): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_id', 'nhepcd_one',
        'nhepcd_fixture', 'nhepcd_before_guards', 'nhep_funding_db_no_outpush', 'm4lh_actor_expect',
        'm4lh_actor_native', 'm4lh_actor_expected_row', 'm4lh_actor_projection',
        'bccomp', 'bcmod', 'bcdiv', 'bcmul', 'bcadd', 'bcsub', 'serialize'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_CONFIRM_VALUE_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHE_CONFIRM_VALUE_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHE_CONFIRM_VALUE_ORIGINAL_PRIVATE_REQUEST');
    nhep_expect(is_array($privateRequest['actor_identity']), 'NHE_CONFIRM_VALUE_PRIVATE_ACTOR_OBJECT');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHE_CONFIRM_VALUE_PRIVATE_ACTOR_IDENTITY');
    $steps = ['refund_family_confirm' => 10, 'review_family_confirm' => 16];
    nhep_expect(is_string($intent['step']) && isset($steps[$intent['step']])
        && $intent['sequence'] === $steps[$intent['step']] && $intent['method'] === 'POST'
        && $intent['path'] === '/api/order/confirm' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['body']), 'NHE_CONFIRM_VALUE_STEP_OR_BRANCH_NOT_IMPLEMENTED');
    $orderKey = nhepcv_order_key($actualOrderKey, $actualHTTPInterval);
    $fixture = nhepcd_fixture($beforeDB2, $intent, $privateRequest);
    nhepcd_before_guards($beforeDB2, false);
    foreach (['image_thumb_status', 'member_func_status', 'member_card_status', 'member_price_status'] as $name)
        nhepcv_config($beforeDB2, $intent, $name, 0);
    nhepcv_config($beforeDB2, $intent, 'station_open', 1);
    $free = nhepcv_config($beforeDB2, $intent, 'store_free_postage', '10000.00');
    $ratio = nhepcv_config($beforeDB2, $intent, 'integral_ratio', '0.00');
    // Only absence in this full BEFORE proves the original getConfigValue null/default path.
    $offline = nhepcv_config($beforeDB2, $intent, 'offline_postage', null, true);
    nhep_expect($offline === null, 'NHE_CONFIRM_VALUE_ORIGINAL_NULL_GETTER_DEFAULT');
    $offlinePostage = '';
    $body = $privateRequest['body'];
    nhe_keys($body, ['cartId', 'new', 'addressId', 'shipping_type', 'is_gift'],
        'NHE_CONFIRM_VALUE_EXACT_ORIGINAL_FIVE_FIELD_BODY');
    $cartId = nhepcd_id($body['cartId']);
    nhep_expect(is_string($body['cartId']) && $body === ['cartId' => (string)$cartId, 'new' => 0,
        'addressId' => $fixture['address_id'], 'shipping_type' => 1, 'is_gift' => 0],
        'NHE_CONFIRM_VALUE_ORIGINAL_OWNED_SINGLE_CART_INPUT');
    $saved = nhepcd_one($beforeDB2, 'eb_store_cart', ['id' => $cartId]);
    $cart = nhepcv_native_row($beforeDB2, 'eb_store_cart', $saved['index']);
    nhep_expect(count($cart) === 15 && is_int($cart['add_time']) && $cart['add_time'] > 0
        && $cart['add_time'] <= $actualHTTPInterval[1]
        && $cart === m4lh_actor_expected_row($saved['metadata'], ['id' => $cartId, 'uid' => $fixture['uid'],
            'type' => '0', 'product_id' => $fixture['product_id'], 'product_attr_unique' => $fixture['sku_unique'],
            'cart_num' => 1, 'add_time' => $cart['add_time']]),
        'NHE_CONFIRM_VALUE_ORIGINAL_FULL_OWNED_PERSISTENT_CART');
    $productSelection = nhepcd_one($beforeDB2, 'eb_store_product', ['id' => $fixture['product_id']]);
    $product = nhepcv_native_row($beforeDB2, 'eb_store_product', $productSelection['index']);
    // HasOne attrInfo uses only unique, without the normal service's type filter.
    $skuSelection = nhepcd_one($beforeDB2, 'eb_store_product_attr_value', ['unique' => $fixture['sku_unique']]);
    $sku = nhepcv_native_row($beforeDB2, 'eb_store_product_attr_value', $skuSelection['index']);
    $image = '/statics/system_images/spread_level_1.png';
    nhep_expect($sku['id'] === $fixture['sku_id'] && $sku['product_id'] === $fixture['product_id']
        && $sku['type'] === 0 && $sku['unique'] === $fixture['sku_unique'] && $sku['suk'] === '普通'
        && $sku['image'] === $image && $product['image'] === $image
        && $sku['price'] === '20.15' && $sku['cost'] === '7.45'
        && $product['price'] === '20.15' && $product['cost'] === '7.45'
        && is_int($sku['stock']) && $sku['stock'] >= $cart['cart_num']
        && $product['custom_form'] === '[]' && is_string($product['slider_image']),
        'NHE_CONFIRM_VALUE_REAL_GLOBAL_UNIQUE_SKU_IMAGE_AND_PRICING_BRANCH');
    $slides = json_decode($product['slider_image'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $slides === [$image],
        'NHE_CONFIRM_VALUE_ORIGINAL_SLIDER_IMAGE_GETTER');
    // Updating this existing key preserves its original native column position.
    $product['slider_image'] = $slides;
    $product['express_delivery'] = true;
    $product['store_mention'] = false;
    $product['attrInfo'] = $sku;
    // Original relation order is productInfo then top-level attrInfo.
    $cart['productInfo'] = $product;
    $cart['attrInfo'] = $sku;
    $cart['min_qty'] = $product['min_qty'];
    $cart['attrStatus'] = true;
    $cart['vip_truePrice'] = 0.0;
    $cart['costPrice'] = $sku['cost'];
    $cart['trueStock'] = $sku['stock'];
    $discount = bcdiv('100', '100', 2);
    $noPayVipPrice = bcmul($discount, $sku['price'], 2);
    $vipSaving = bcsub($sku['price'], $noPayVipPrice, 2);
    nhep_expect($discount === '1.00' && $noPayVipPrice === '20.15' && $vipSaving === '0.00',
        'NHE_CONFIRM_VALUE_FIXED_NORMAL_LEVEL_PRICE_FROM_BEFORE_SKU');
    $cart['truePrice'] = (float)$noPayVipPrice;
    $cart['sum_price'] = $sku['price'];
    $cart['price_type'] = 'level';
    $cart['is_valid'] = 1;
    $responseItem = $cart;
    unset($responseItem['attrInfo']);
    $responseCartInfo = [$responseItem];
    // valid[] is captured before handleCartList unsets attrInfo; computed adds postage later.
    $computedItem = $cart;
    $computedItem['postage_price'] = 0;
    $computedCartInfo = [$computedItem];
    $quantity = (string)$cart['cart_num'];
    $sumPrice = bcadd('0', bcmul($quantity, $cart['sum_price'], 2), 2);
    $totalPrice = bcadd('0', bcmul($quantity, (string)$cart['truePrice'], 2), 2);
    $costPrice = bcadd('0', bcmul($quantity, $cart['costPrice'], 2), 2);
    $vipPrice = bcadd('0', bcmul($quantity, (string)$cart['vip_truePrice'], 2), 2);
    $levelPrice = bcadd('0', bcmul($quantity, (string)$cart['vip_truePrice'], 2), 2);
    $storeFreePostage = (float)$free;
    nhep_expect($sumPrice === '20.15' && $totalPrice === '20.15' && $costPrice === '7.45'
        && $vipPrice === '0.00' && $levelPrice === '0.00' && $storeFreePostage === 10000.0
        && bccomp($sumPrice, $free, 2) < 0 && $product['freight'] === 1,
        'NHE_CONFIRM_VALUE_ORIGINAL_FREE_SHIPPING_AND_ALL_PRICE_TYPES');
    // Plain array values reproduce the RC1 reference lifecycle; no artificial shared references.
    $priceGroup = [
        'storePostage' => 0, 'storeFreePostage' => $storeFreePostage, 'isStoreFreePostage' => false,
        'sumPrice' => $sumPrice, 'totalPrice' => $totalPrice, 'costPrice' => $costPrice,
        'vipPrice' => $vipPrice, 'storePostageDiscount' => 0, 'cartInfo' => $computedCartInfo,
        'levelPrice' => $levelPrice, 'memberPrice' => 0, 'giftPrice' => 0,
    ];
    $other = ['offlinePostage' => $offlinePostage, 'integralRatio' => $ratio];
    $tuple = ['cartInfo' => $computedCartInfo, 'priceGroup' => $priceGroup, 'other' => $other];
    $wire = serialize($tuple);
    return ['orderKey' => $orderKey, 'logicalKey' => 'user_order_' . $fixture['uid'] . $orderKey,
        'tuple' => $tuple, 'wire' => $wire, 'responseCartInfo' => $responseCartInfo];
}

/** Definitions only. Four old-477 normal customer actions; all captures/rows/tokens stay private. */
function nhepcr_exchange(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $request, #[SensitiveParameter] array $response): bool
{
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPCR_ORIGINAL_COMPLETE_INTENT');
    $steps = ['refund_family_cart' => [9, true], 'refund_family_confirm' => [10, false],
        'review_family_cart' => [15, true], 'review_family_confirm' => [16, false]];
    nhep_expect(PHP_INT_SIZE === 8 && is_string($intent['step']) && isset($steps[$intent['step']]),
        'NHEPCR_ONLY_FOUR_ORIGINAL_CUSTOMER_STEPS');
    [$sequence, $cart] = $steps[$intent['step']];
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === 'POST'
        && $intent['path'] === ($cart ? '/api/cart/add' : '/api/order/confirm')
        && $intent['actor'] === 'customer' && $intent['origin'] === 'http://127.0.0.1:8000'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1,
        'NHEPCR_EXACT_ORIGINAL_NORMAL_INTENT');
    nhe_keys($request, ['token', 'body', 'actor_identity'], 'NHEPCR_EXACT_PRIVATE_REQUEST');
    nhep_expect(is_string($request['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $request['token']) === 1
        && is_array($request['body']) && is_array($request['actor_identity']),
        'NHEPCR_REAL_EXISTING_CUSTOMER_TOKEN_AND_REQUEST');
    nhe_keys($request['actor_identity'], ['id', 'account'], 'NHEPCR_EXACT_PRIVATE_ACTOR');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0
        && $request['actor_identity']['id'] === $intent['actor_id']
        && is_string($request['actor_identity']['account']) && $request['actor_identity']['account'] !== '',
        'NHEPCR_PRIVATE_REQUEST_REAL_ACTOR_BINDING');
    $interval = $response['actual_interval'] ?? null;
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && ($response['http'] ?? null) === 200 && ($response['transport_errno'] ?? null) === 0
        && array_key_exists('transport_failure_class', $response) && $response['transport_failure_class'] === null
        && ($response['primary_ip'] ?? null) === '127.0.0.1' && ($response['primary_port'] ?? null) === 8000
        && ($response['local_ip'] ?? null) === '127.0.0.1'
        && is_string($response['raw'] ?? null) && strlen($response['raw']) <= 6291456
        && is_array($response['json'] ?? null), 'NHEPCR_REAL_COMPLETE_SUCCESSFUL_LOCAL_HTTP');
    $decoded = json_decode($response['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $response['json'],
        'NHEPCR_REAL_RAW_RESPONSE_AND_PARSED_JSON_JOIN');
    nhe_keys($decoded, ['status', 'msg', 'data'], 'NHEPCR_ORIGINAL_JSON_RESPONSE_ENVELOPE');
    nhep_expect($decoded['status'] === 200 && $decoded['msg'] === 'success' && is_array($decoded['data']),
        'NHEPCR_ORIGINAL_NORMAL_SUCCESS_RESPONSE');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPCR_BOTH_COMPLETE_CAPTURES_SAME_ORIGINAL_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $actualUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($actualUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPCR_REAL_HTTP_WINDOW_INSIDE_MONOTONIC_NATIVE_REDIS_TIME');
    return $cart;
}

/** The known old getter reads one original JSON value, or a proved absent row; never Redis. */
function nhepcr_config_wire(#[SensitiveParameter] array $beforeDB2, string $name, mixed $expectedValue): string
{
    $matches = [];
    foreach ($beforeDB2['rows']['eb_system_config'] as $row) {
        nhep_expect(is_string($row['menu_name']), 'NHEPCR_ORIGINAL_NATIVE_CONFIG_NAME');
        nhep_expect(strtolower(rtrim($row['menu_name'], ' ')) !== $name || $row['menu_name'] === $name,
            'NHEPCR_CANONICAL_UNAMBIGUOUS_ORIGINAL_CONFIG_NAME');
        if ($row['menu_name'] === $name) $matches[] = $row;
    }
    if ($expectedValue === null) {
        nhep_expect($matches === [], 'NHEPCR_ORIGINAL_ABSENT_CONFIG_ROW_REQUIRED');
        $value = null;
    } else {
        nhep_expect(count($matches) === 1 && is_string($matches[0]['value']),
            'NHEPCR_UNIQUE_ORIGINAL_BEFORE_JSON_CONFIG_ROW');
        $value = json_decode($matches[0]['value'], true);
        nhep_expect(json_last_error() === JSON_ERROR_NONE && $value === $expectedValue,
            'NHEPCR_BEFORE_JSON_VALUE_AND_NATIVE_TYPE_MATCH_NORMAL_BRANCH');
    }
    // Think Driver::serialize stores only numeric values directly; arrays/null use PHP serialization.
    return is_numeric($value) ? (string)$value : serialize($value);
}

/** BEFORE plus independent cache/auth changes; this is not a DB or complete confirmation-DTO oracle. */
function nhep_cart_confirm_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_fixture', 'nhepcd_before_guards',
        'nhepcd_one', 'nhepcd_id', 'nhepar_capture', 'nhepar_entry', 'nhepar_actor', 'nhepar_customer',
        'nhepar_remember', 'nhepar_bind', 'nhepar_tag', 'nhepar_uint', 'nhep_redis_expected',
        'nhep_confirmation_value_expected', 'm4lh_actor_next', 'm4lh_actor_expected_row', 'bcadd', 'bcsub',
        'bcmul', 'bccomp'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPCR_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    $cart = nhepcr_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    $fixture = nhepcd_fixture($beforeDB2, $intent, $privateRequest);
    nhepcd_before_guards($beforeDB2, $cart);
    $rows = $beforeDB2['rows']; $uid = $fixture['uid']; $body = $privateRequest['body'];
    $data = $privateResponse['json']['data']; $interval = $privateResponse['actual_interval'];
    if ($cart) {
        nhe_keys($body, ['productId', 'cartNum', 'uniqueId', 'new', 'is_new', 'combinationId',
            'secKillId', 'bargainId', 'advanceId', 'pinkId'], 'NHEPCR_ORIGINAL_TEN_FIELD_CART_BODY');
        nhep_expect($body === ['productId' => $fixture['product_id'], 'cartNum' => 1,
            'uniqueId' => $fixture['sku_unique'], 'new' => 0, 'is_new' => 0, 'combinationId' => 0,
            'secKillId' => 0, 'bargainId' => 0, 'advanceId' => 0, 'pinkId' => 0], 'NHEPCR_FIXED_NORMAL_CART_INPUT');
        nhe_keys($data, ['cartId'], 'NHEPCR_ORIGINAL_CART_RESPONSE_ONLY_NATIVE_ID');
        $id = m4lh_actor_next($beforeDB2['database']['tables']['eb_store_cart'], 'id');
        nhep_expect(nhepcd_id($data['cartId']) === $id, 'NHEPCR_RESPONSE_CART_ID_FROM_BEFORE_NEXT_PK');
    } else {
        nhe_keys($body, ['cartId', 'new', 'addressId', 'shipping_type', 'is_gift'], 'NHEPCR_ORIGINAL_FIVE_FIELD_CONFIRM_BODY');
        $id = nhepcd_id($body['cartId']);
        nhep_expect(is_string($body['cartId']) && $body === ['cartId' => (string)$id, 'new' => 0,
            'addressId' => $fixture['address_id'], 'shipping_type' => 1, 'is_gift' => 0], 'NHEPCR_FIXED_OWNED_CONFIRM_INPUT');
        $saved = nhepcd_one($beforeDB2, 'eb_store_cart', ['id' => $id]);
        nhep_expect(is_int($saved['row']['add_time']) && $saved['row']['add_time'] > 0
            && $saved['row']['add_time'] <= $interval[1]
            && $saved['row'] === m4lh_actor_expected_row($saved['metadata'], ['id' => $id, 'uid' => $uid,
                'product_id' => $fixture['product_id'], 'cart_num' => 1, 'product_attr_unique' => $fixture['sku_unique'],
                'type' => '0', 'add_time' => $saved['row']['add_time']]), 'NHEPCR_ORIGINAL_REAL_OWNED_PERSISTENT_CART');
    }
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($rows[$table] === [], 'NHEPCR_ORIGINAL_EMPTY_LANGUAGE_TABLES');
    foreach ($rows['eb_system_notification'] as $row)
        foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat', 'is_app'] as $field)
            nhep_expect(nhepar_uint($row[$field], true) === 0, 'NHEPCR_ORIGINAL_DISABLED_NOTIFICATION_BRANCH');
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']), 'NHEPCR_SAME_RUN_REAL_PRIVATE_AUTH_CONFIGURATION');
    $actor = nhepar_actor($rows, $intent, $privateRequest); $changes = []; $tagMembers = [];
    $apiTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('api'));
    nhep_expect(is_array($apiTag) && $apiTag['type'] === 'set' && $apiTag['expires'] === -1
        && in_array('c:' . md5($privateRequest['token']), $apiTag['value'], true),
        'NHEPCR_BEFORE_ORIGINAL_CUSTOMER_WHITELIST_TAG_MEMBERSHIP');
    // This is the real non-login branch: use the existing request token, not fabricated login data.
    nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);
    $settings = ['station_open' => 1, 'param_filter_type' => null, 'param_filter_data' => null];
    if ($cart) {
        $settings['queue_open'] = 0;
    } else {
        $settings += ['member_func_status' => 0, 'member_card_status' => 0, 'image_thumb_status' => 0,
            'store_self_mention' => 0, 'pay_weixin_open' => 0, 'ali_pay_status' => 0, 'invoice_func_status' => 0,
            'special_invoice_status' => 0, 'balance_func_status' => 1, 'yue_pay_status' => 1, 'offline_pay_status' => 2,
            'store_free_postage' => '10000.00', 'integral_ratio' => '0.00', 'offline_postage' => null, 'friend_pay_status' => null];
    }
    foreach ($settings as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire)
        nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
    if (!$cart) {
        nhep_expect(is_string($data['orderKey'] ?? null), 'NHEPCR_ACTUAL_ORIGINAL_CONFIRMATION_KEY_STRING');
        $built = nhep_confirmation_value_expected($beforeDB2, $intent, $privateRequest, $data['orderKey'], $interval);
        nhe_keys($built, ['orderKey', 'logicalKey', 'tuple', 'wire', 'responseCartInfo'], 'NHEPCR_COMPLETE_INDEPENDENT_PRIVATE_VALUE_BUILDER');
        nhep_expect($built['orderKey'] === $data['orderKey'] && is_string($built['logicalKey'])
            && $built['logicalKey'] === 'user_order_' . $uid . $data['orderKey']
            && is_array($built['tuple']) && is_string($built['wire']) && $built['wire'] !== ''
            && is_array($built['responseCartInfo']), 'NHEPCR_SAME_REAL_KEY_AND_FULL_PRIVATE_PHP_VALUE');
        nhe_keys($built['tuple'], ['cartInfo', 'priceGroup', 'other'], 'NHEPCR_ORIGINAL_THREE_FIELD_CONFIRMATION_TUPLE');
        nhep_expect($built['wire'] === serialize($built['tuple']), 'NHEPCR_FULL_PHP_TUPLE_WIRE_NOT_JSON');
        $key = 'c:' . $built['logicalKey'];
        nhep_expect(nhepar_entry($beforeCapture, $key) === null, 'NHEPCR_CREATE_ONLY_CONFIRMATION_CACHE_KEY_ABSENT_BEFORE');
        // Require the complete present value. Missing data is never accepted merely because 600 seconds passed.
        $actualKey = nhepar_entry($actualCapture, $key);
        $earliest = bcadd(bcmul((string)$interval[0], '1000', 0), '600000', 0);
        $latest = bcadd(bcsub(bcmul(bcadd((string)$interval[1], '1', 0), '1000', 0), '1', 0), '600000', 0);
        nhep_expect(is_array($actualKey) && is_int($actualKey['expires']) && $actualKey['expires'] > 0
            && bccomp((string)$actualKey['expires'], $earliest, 0) >= 0
            && bccomp((string)$actualKey['expires'], $latest, 0) <= 0
            && bccomp((string)$actualKey['expires'], $actualCapture['snapshot']['time_ms'], 0) >= 0,
            'NHEPCR_REAL_SETEX_600_WITHIN_HTTP_AND_REDIS_CLOCK_WINDOWS');
        $bound = nhepar_bind($actualCapture, $key, 'string', $built['wire'], ['ttl' => 600], $beforeCapture['snapshot']);
        $changes[$key] = $bound; $tagMembers[] = $key;
        // Original JSON encoding normalizes floats/ints for these response views only; never for cache wire.
        $views = json_decode(json_encode(['cartInfo' => $built['responseCartInfo'],
            'priceGroup' => $built['tuple']['priceGroup']], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR),
            true, 512, JSON_THROW_ON_ERROR);
        nhep_expect(array_key_exists('cartInfo', $data) && array_key_exists('priceGroup', $data)
            && $data['cartInfo'] === $views['cartInfo'] && $data['priceGroup'] === $views['priceGroup'],
            'NHEPCR_INDEPENDENT_ORIGINAL_JSON_CART_AND_PRICE_RESPONSE_VIEWS');
    }
    // TagSet::remember appends on both warm and cold success. Preserve the full original set and union all actual reads.
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'], 'NHEPCR_COMPLETE_REDIS_NAMESPACE_INDEPENDENT_EXPECTED');
    return $expected;
}

/** Old create DB and Redis pure definitions; complete execution remains refused. */
/** Definitions only. Rebuild an original confirmation from its private, completed factory context. */
function nhepcx_confirmation(#[SensitiveParameter] array $beforeCreateDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $confirmedContext): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhep_auth_db_time',
        'nhep_auth_db_update', 'nhep_database_expected', 'nhep_confirmation_value_expected',
        'nhepcd_fixture', 'nhepcd_one', 'nhepcd_id'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_CREATE_CONFIRMATION_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeCreateDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHE_CREATE_CONFIRMATION_COMPLETE_CREATE_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHE_CREATE_CONFIRMATION_PRIVATE_CREATE_REQUEST');
    nhe_keys($confirmedContext, ['beforeDB2', 'intent', 'request', 'orderKey', 'httpInterval'],
        'NHE_CREATE_CONFIRMATION_ORIGINAL_FIVE_FIELD_PRIVATE_CONTEXT');
    nhep_expect(is_array($confirmedContext['beforeDB2']) && is_array($confirmedContext['intent'])
        && is_array($confirmedContext['request']) && is_string($confirmedContext['orderKey'])
        && is_array($confirmedContext['httpInterval']), 'NHE_CREATE_CONFIRMATION_ORIGINAL_CONTEXT_FIELD_TYPES');
    $steps = ['refund_family_create' => [11, 'refund_family_confirm', 10, 'refund_family'],
        'review_family_create' => [17, 'review_family_confirm', 16, 'review_family']];
    nhep_expect(is_string($intent['step']) && isset($steps[$intent['step']]),
        'NHE_CREATE_CONFIRMATION_CREATE_STEP_NOT_IMPLEMENTED');
    [$sequence, $confirmStep, $confirmSequence, $family] = $steps[$intent['step']];
    $original = $confirmedContext['intent']; $request = $confirmedContext['request'];
    // This calls the original five-argument builder, not a fabricated response or a caller's tuple.
    $built = nhep_confirmation_value_expected($confirmedContext['beforeDB2'], $original, $request,
        $confirmedContext['orderKey'], $confirmedContext['httpInterval']);
    nhe_keys($built, ['orderKey', 'logicalKey', 'tuple', 'wire', 'responseCartInfo'],
        'NHE_CREATE_CONFIRMATION_EXACT_INDEPENDENT_BUILDER_RESULT');
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === 'POST'
        && $intent['origin'] === 'http://127.0.0.1:8000' && $intent['actor'] === 'customer'
        && $intent['run_id'] === $original['run_id'] && $intent['actor_id'] === $original['actor_id']
        && $original['step'] === $confirmStep && $original['sequence'] === $confirmSequence
        && $intent['path'] === '/api/order/create/' . $built['orderKey']
        && is_array($privateRequest['actor_identity'])
        && $privateRequest['actor_identity'] === $request['actor_identity']
        && is_string($privateRequest['token']) && $privateRequest['token'] === $request['token']
        && is_array($privateRequest['body']), 'NHE_CREATE_CONFIRMATION_SAME_ORIGINAL_FAMILY_OWNER_TOKEN_AND_KEY');
    $body = $privateRequest['body'];
    nhe_keys($body, ['addressId', 'couponId', 'payType', 'useIntegral', 'mark', 'combinationId',
        'pinkId', 'seckill_id', 'bargainId', 'shipping_type', 'store_id', 'new', 'invoice_id',
        'advanceId', 'custom_form', 'is_gift', 'gift_mark'], 'NHE_CREATE_CONFIRMATION_EXACT_ORIGINAL_CREATE_BODY');
    nhep_expect($body === ['addressId' => $request['body']['addressId'], 'couponId' => 0,
        'payType' => 'yue', 'useIntegral' => 0, 'mark' => $intent['run_id'] . '-' . $family,
        'combinationId' => 0, 'pinkId' => 0, 'seckill_id' => 0, 'bargainId' => 0,
        'shipping_type' => 1, 'store_id' => 0, 'new' => 0, 'invoice_id' => 0, 'advanceId' => 0,
        'custom_form' => [], 'is_gift' => 0, 'gift_mark' => ''],
        'NHE_CREATE_CONFIRMATION_SAME_OWNED_ADDRESS_AND_FIXED_NORMAL_OPTIONS');
    $beforeConfirm = $confirmedContext['beforeDB2'];
    $fixture = nhepcd_fixture($beforeConfirm, $original, $request);
    $user = $fixture['user'];
    $current = nhepcd_one($beforeCreateDB2, 'eb_user', ['uid' => $fixture['uid']]);
    // Only this native scalar is read from the current BEFORE. All other rows/metadata are reconstructed.
    $time = nhep_auth_db_time($user['metadata'], 'last_time', $current['row']['last_time'],
        $confirmedContext['httpInterval'], $user['row']['last_time']);
    $expected = nhep_database_expected($beforeConfirm, ['eb_user' => nhep_auth_db_update(
        $beforeConfirm, 'eb_user', $user['index'], ['last_time' => $time])]);
    nhep_expect($expected === $beforeCreateDB2,
        'NHE_CREATE_CONFIRMATION_ALL_164_TABLES_ONLY_ORIGINAL_CONFIRM_AUTH_TIME_CHANGED');
    // Actual factory provenance, ordering and one-time consumption are the caller's private closure duty.
    return $built;
}

/** Finite original BEFORE selectors. This does not waive full Redis or actual Channel observation. */
function nhepcx_before_guards(#[SensitiveParameter] array $before, array $intent,
    #[SensitiveParameter] array $fixture): void
{
    nhepcd_before_guards($before, false);
    foreach (['queue_open', 'brokerage_func_status', 'division_status', 'store_self_mention'] as $name)
        nhepcv_config($before, $intent, $name, 0);
    nhepcv_config($before, $intent, 'offline_pay_status', 2);
    // These three are absent in the original finite normal config. Cache wire is independently checked elsewhere.
    foreach (['store_stock', 'is_self_brokerage', 'user_brokerage_type'] as $name) {
        foreach ($before['rows']['eb_system_config'] as $row)
            nhep_expect(is_string($row['menu_name'])
                && strtolower(rtrim($row['menu_name'], ' ')) !== $name,
                'NHE_CREATE_DB_ORIGINAL_MISSING_NORMAL_CONFIGURATION');
    }
    $product = nhepcd_one($before, 'eb_store_product', ['id' => $fixture['product_id']]);
    $root = nhepcv_native_row($before, 'eb_store_product', $product['index']);
    $sku = nhepcd_one($before, 'eb_store_product_attr_value', ['id' => $fixture['sku_id']]);
    $attr = nhepcv_native_row($before, 'eb_store_product_attr_value', $sku['index']);
    nhep_expect($root['is_sub'] === 0 && $root['presale'] === 0 && $root['give_integral'] === '0.00'
        && $root['stock'] >= 1 && $attr['stock'] >= 2,
        'NHE_CREATE_DB_NO_COMMISSION_PRESALE_GIFT_POINTS_OR_LOW_STOCK_CHANNEL_BRANCH');
    // PrintJob dispatch is synchronous at queue_open=0. The real selector includes all three conditions.
    foreach ($before['rows']['eb_system_ticket'] as $index => $row) {
        $ticket = nhepcv_native_row($before, 'eb_system_ticket', $index);
        nhep_expect(!($ticket['is_del'] === 0 && $ticket['status'] === 1 && $ticket['print_type'] === 2),
            'NHE_CREATE_DB_ACTIVE_NORMAL_ORDER_PRINTER_BRANCH_NOT_IMPLEMENTED');
    }
}

/** Old steps 11/17 only; complete expected rows come from BEFORE, fixed inputs and bounded native scalars. */
function nhep_create_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse, #[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $confirmedContext): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhep_auth_db_index',
        'nhep_auth_db_time', 'nhep_auth_db_update', 'nhep_auth_db_append', 'nhep_database_expected',
        'nhep_funding_db_signed_time', 'nhepcx_order_expected', 'nhepcd_fixture', 'nhepcd_one',
        'nhepcd_id', 'nhepcv_native_row', 'nhepcv_config', 'nhepcd_before_guards',
        'm4lh_actor_native', 'm4lh_actor_expected_row', 'm4lh_actor_next', 'json_encode', 'json_decode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_CREATE_DB_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    $built = nhepcx_confirmation($beforeDB2, $intent, $privateRequest, $confirmedContext);
    $interval = $privateResponse['actual_interval'] ?? null;
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $confirmedContext['httpInterval'][1] <= $interval[0]
        && ($privateResponse['http'] ?? null) === 200 && ($privateResponse['transport_errno'] ?? null) === 0
        && array_key_exists('transport_failure_class', $privateResponse) && $privateResponse['transport_failure_class'] === null
        && ($privateResponse['primary_ip'] ?? null) === '127.0.0.1' && ($privateResponse['primary_port'] ?? null) === 8000
        && is_string($privateResponse['raw'] ?? null) && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json'] ?? null), 'NHE_CREATE_DB_ONE_COMPLETE_REAL_SUCCESS_HTTP_WINDOW');
    $json = $privateResponse['json']; $decoded = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $json
        && ($json['status'] ?? null) === 200 && is_string($json['msg'] ?? null)
        && is_array($json['data'] ?? null), 'NHE_CREATE_DB_ORIGINAL_RAW_AND_PARSED_RESPONSE');
    $data = $json['data'];
    nhe_keys($data, ['status', 'result'], 'NHE_CREATE_DB_ORIGINAL_CREATE_RESPONSE_DATA');
    nhep_expect($data['status'] === 'SUCCESS' && is_array($data['result']),
        'NHE_CREATE_DB_NORMAL_CREATE_NOT_REPLAY_OR_DUPLICATE_ORDER');
    nhe_keys($data['result'], ['orderId', 'key'], 'NHE_CREATE_DB_ORIGINAL_CREATE_RESPONSE_RESULT');
    $fixture = nhepcd_fixture($beforeDB2, $intent, $privateRequest);
    nhepcx_before_guards($beforeDB2, $intent, $fixture);
    $uid = $fixture['uid']; $productId = $fixture['product_id']; $skuId = $fixture['sku_id'];
    $cartId = nhepcd_id($confirmedContext['request']['body']['cartId']);
    $cart = nhepcd_one($beforeDB2, 'eb_store_cart', ['id' => $cartId]);
    $address = nhepcd_one($beforeDB2, 'eb_user_address', ['id' => $fixture['address_id']]);
    $user = $fixture['user']; $userRow = nhepcv_native_row($beforeDB2, 'eb_user', $user['index']);
    nhep_expect(is_string($userRow['real_name']), 'NHE_CREATE_DB_ORIGINAL_NATIVE_CUSTOMER_NAME');
    $actualUser = nhep_auth_db_index($actualDB2['rows']['eb_user'], $user['metadata'], 'uid', $uid);
    $time = nhep_auth_db_time($user['metadata'], 'last_time',
        $actualDB2['rows']['eb_user'][$actualUser]['last_time'], $interval, $userRow['last_time']);
    $userChanges = ['last_time' => $time];
    if ($userRow['real_name'] === '') {
        $userChanges['real_name'] = $address['row']['real_name'];
        $userChanges['record_phone'] = $address['row']['phone'];
    }
    $expectedRows = ['eb_user' => nhep_auth_db_update($beforeDB2, 'eb_user', $user['index'], $userChanges)];
    $product = nhepcd_one($beforeDB2, 'eb_store_product', ['id' => $productId]);
    $sku = nhepcd_one($beforeDB2, 'eb_store_product_attr_value', ['id' => $skuId]);
    $expectedRows['eb_store_product'] = nhep_auth_db_update($beforeDB2, 'eb_store_product', $product['index'],
        ['stock' => $product['row']['stock'] - 1, 'sales' => $product['row']['sales'] + 1]);
    $expectedRows['eb_store_product_attr_value'] = nhep_auth_db_update($beforeDB2, 'eb_store_product_attr_value', $sku['index'],
        ['stock' => $sku['row']['stock'] - 1, 'sales' => $sku['row']['sales'] + 1]);
    $remainingCart = $beforeDB2['rows']['eb_store_cart']; unset($remainingCart[$cart['index']]);
    $expectedRows['eb_store_cart'] = array_values($remainingCart);

    $orderTable = $beforeDB2['database']['tables']['eb_store_order'];
    $oid = m4lh_actor_next($orderTable, 'id');
    nhepcd_id($oid, 2147483647); // The original item.oid and product log identities have signed int limits.
    foreach ($beforeDB2['rows']['eb_store_order'] as $row)
        nhep_expect(is_string($row['unique']) && is_string($row['order_id']) && $row['unique'] !== $built['orderKey']
            && !($row['uid'] === $uid && $row['is_del'] === 0 && $row['order_id'] === $built['orderKey']),
            'NHE_CREATE_DB_ORIGINAL_CONFIRMATION_NOT_ALREADY_CONSUMED_BY_AN_ORDER');
    $orderIndex = nhep_auth_db_index($actualDB2['rows']['eb_store_order'], $orderTable['metadata'], 'id', $oid);
    $actualOrderNo = $actualDB2['rows']['eb_store_order'][$orderIndex]['order_id'];
    nhep_expect(is_string($actualOrderNo), 'NHE_CREATE_DB_ONLY_BEFORE_NEXT_PK_NATIVE_CP_CANDIDATE');
    $orderNo = nhepcx_order_expected($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse, $actualOrderNo);
    nhep_expect($orderNo === $actualOrderNo && $data['result']['orderId'] === $orderNo
        && $data['result']['key'] === $built['orderKey'], 'NHE_CREATE_DB_FULL_CP_PROOF_AND_ORIGINAL_RESPONSE_BINDING');
    nhep_expect(m4lh_actor_native($orderTable['metadata']['columns']['mer_id'],
        $orderTable['metadata']['columns']['mer_id']['COLUMN_DEFAULT']) === 0,
        'NHE_CREATE_DB_UNASSIGNED_LEGACY_ORDER_MERCHANT_DEFAULT_ZERO');
    $cartIdsJSON = json_encode([$cartId]);
    nhep_expect(is_string($cartIdsJSON), 'NHE_CREATE_DB_ORIGINAL_CART_ID_ARRAY_MUTATOR_JSON');
    $expectedRows['eb_store_order'] = nhep_auth_db_append($beforeDB2, $actualDB2, 'eb_store_order', [
        'uid' => $uid, 'order_id' => $orderNo, 'real_name' => $address['row']['real_name'],
        'user_phone' => $address['row']['phone'], 'user_address' => $address['row']['province'] . ' '
            . $address['row']['city'] . ' ' . $address['row']['district'] . ' ' . $address['row']['detail'],
        'cart_id' => $cartIdsJSON, 'total_num' => 1, 'total_price' => '20.15', 'total_postage' => '0.00',
        'coupon_id' => 0, 'coupon_price' => '0.00', 'pay_price' => '20.15', 'pay_postage' => '0.00',
        'deduction_price' => '0.00', 'gift_price' => '0.00', 'paid' => 0, 'pay_type' => 'yue',
        'use_integral' => '0.00', 'gain_integral' => '0.00', 'mark' => $privateRequest['body']['mark'],
        'combination_id' => 0, 'pink_id' => 0, 'seckill_id' => 0, 'bargain_id' => 0, 'advance_id' => 0,
        'cost' => '7.45', 'unique' => $built['orderKey'], 'shipping_type' => 1, 'channel_type' => $userRow['user_type'],
        'province' => '', 'spread_uid' => 0, 'spread_two_uid' => 0, 'virtual_type' => 0, 'is_gift' => 0,
        'gift_mark' => '', 'pay_uid' => $uid, 'custom_form' => '[]',
        'division_id' => $userRow['division_id'], 'agent_id' => $userRow['agent_id'], 'staff_id' => $userRow['staff_id'],
        'staff_brokerage' => '0.00', 'agent_brokerage' => '0.00', 'division_brokerage' => '0.00',
    ], $interval);

    // The saved cart_info keeps all confirmation-time product/SKU inventory values before this order's decrement.
    $items = $built['tuple']['cartInfo'];
    nhep_expect(is_array($items) && array_is_list($items) && count($items) === 1
        && ($items[0]['id'] ?? null) === $cartId, 'NHE_CREATE_DB_COMPLETE_INDEPENDENT_CONFIRMATION_CART');
    $item = $items[0];
    $item['use_integral'] = 0; $item['integral_price'] = 0.0; $item['coupon_price'] = 0.0;
    $item['sum_true_price'] = '20.15'; $item['one_brokerage'] = '0'; $item['two_brokerage'] = '0';
    $item['staff_brokerage'] = '0.00'; $item['agent_brokerage'] = '0.00'; $item['division_brokerage'] = '0.00';
    $cartJSON = json_encode($item);
    nhep_expect(is_string($cartJSON), 'NHE_CREATE_DB_ORIGINAL_DEFAULT_JSON_ENCODE_OF_COMPLETE_CART');
    $itemTable = $beforeDB2['database']['tables']['eb_store_order_cart_info'];
    $itemId = m4lh_actor_next($itemTable, 'id');
    foreach ($beforeDB2['rows']['eb_store_order_cart_info'] as $row)
        nhep_expect($row['id'] !== $itemId, 'NHE_CREATE_DB_ITEM_ORIGINAL_NEXT_ID_ABSENT');
    $savedItem = m4lh_actor_expected_row($itemTable['metadata'], ['id' => $itemId, 'oid' => $oid,
        'uid' => $uid, 'cart_id' => (string)$cartId, 'product_id' => $productId, 'cart_info' => $cartJSON,
        'cart_num' => 1, 'surplus_num' => 1, 'unique' => md5($cartId . '' . $oid)]);
    $expectedRows['eb_store_order_cart_info'] = $beforeDB2['rows']['eb_store_order_cart_info'];
    $expectedRows['eb_store_order_cart_info'][] = $savedItem;

    $statusTable = $beforeDB2['database']['tables']['eb_store_order_status'];
    nhep_expect(array_keys($statusTable['metadata']['columns']) === ['oid', 'change_type', 'change_message', 'change_time']
        && $statusTable['metadata']['table']['AUTO_INCREMENT'] === null,
        'NHE_CREATE_DB_ORIGINAL_FOUR_COLUMN_STATUS_WITHOUT_ID_OR_COUNTER');
    foreach ($statusTable['metadata']['columns'] as $column)
        nhep_expect($column['EXTRA'] !== 'auto_increment', 'NHE_CREATE_DB_STATUS_HAS_NO_AUTO_INCREMENT_COLUMN');
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $row)
        nhep_expect($row['oid'] !== $oid, 'NHE_CREATE_DB_ORPHAN_STATUS_AT_NEW_ORDER_ID_NOT_IMPLEMENTED');
    $statusCandidates = [];
    foreach ($actualDB2['rows']['eb_store_order_status'] as $row)
        if ($row['oid'] === $oid) $statusCandidates[] = $row;
    nhep_expect(count($statusCandidates) === 1, 'NHE_CREATE_DB_ONLY_ONE_STATUS_FOR_INDEPENDENT_NEW_ORDER_ID');
    $statusTime = nhep_auth_db_time($statusTable['metadata'], 'change_time', $statusCandidates[0]['change_time'], $interval);
    $status = m4lh_actor_expected_row($statusTable['metadata'], ['oid' => $oid,
        'change_type' => 'cache_key_create_order', 'change_message' => '订单生成', 'change_time' => $statusTime]);
    $expectedRows['eb_store_order_status'] = $beforeDB2['rows']['eb_store_order_status'];
    $expectedRows['eb_store_order_status'][] = $status;

    $logTable = $beforeDB2['database']['tables']['eb_store_product_log'];
    $logId = m4lh_actor_next($logTable, 'id');
    foreach ($beforeDB2['rows']['eb_store_product_log'] as $row)
        nhep_expect($row['id'] !== $logId, 'NHE_CREATE_DB_LOG_ORIGINAL_NEXT_ID_ABSENT');
    $logIndex = nhep_auth_db_index($actualDB2['rows']['eb_store_product_log'], $logTable['metadata'], 'id', $logId);
    $logTime = nhep_funding_db_signed_time($logTable['metadata'], 'add_time',
        $actualDB2['rows']['eb_store_product_log'][$logIndex]['add_time'], $interval);
    $log = m4lh_actor_expected_row($logTable['metadata'], ['id' => $logId, 'type' => 'order',
        'product_id' => $productId, 'uid' => $uid, 'order_num' => 1, 'add_time' => $logTime]);
    $expectedRows['eb_store_product_log'] = $beforeDB2['rows']['eb_store_product_log'];
    $expectedRows['eb_store_product_log'][] = $log;
    $expected = nhep_database_expected($beforeDB2, $expectedRows,
        ['eb_store_order' => 1, 'eb_store_order_cart_info' => 1, 'eb_store_product_log' => 1]);
    nhep_expect($expected === $actualDB2, 'NHE_CREATE_DB_ALL_164_TABLES_COMPLETE_INDEPENDENT_EXPECTED');
    return $expected;
}

/** Definitions only. Original old-477 create11/17; private rows, tokens and values never leave RAM. */
function nhepcxr_exchange(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $request, #[SensitiveParameter] array $response): string
{
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPCXR_ORIGINAL_COMPLETE_CREATE_INTENT');
    $steps = ['refund_family_create' => [11, 'refund_family'], 'review_family_create' => [17, 'review_family']];
    nhep_expect(PHP_INT_SIZE === 8 && is_string($intent['step']) && isset($steps[$intent['step']]),
        'NHEPCXR_ONLY_ORIGINAL_TWO_CREATE_STEPS');
    [$sequence, $family] = $steps[$intent['step']];
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === 'POST' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1 && is_string($intent['path'])
        && preg_match('~\A/api/order/create/([1-9][0-9]{0,18})\z~D', $intent['path'], $path) === 1
        && bccomp($path[1], '9223372036854775807', 0) <= 0,
        'NHEPCXR_EXACT_ORIGINAL_CREATE_SEQUENCE_ORIGIN_AND_KEY_PATH');
    $key = $path[1];
    nhe_keys($request, ['token', 'body', 'actor_identity'], 'NHEPCXR_ORIGINAL_PRIVATE_REQUEST');
    nhep_expect(is_string($request['token']) && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $request['token']) === 1
        && is_array($request['body']) && is_array($request['actor_identity']), 'NHEPCXR_REAL_EXISTING_CUSTOMER_REQUEST');
    nhe_keys($request['actor_identity'], ['id', 'account'], 'NHEPCXR_ORIGINAL_PRIVATE_ACTOR');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 2147483647
        && $request['actor_identity']['id'] === $intent['actor_id'] && is_string($request['actor_identity']['account'])
        && preg_match('/\A[a-z0-9_]{10,32}\z/D', $request['actor_identity']['account']) === 1,
        'NHEPCXR_REAL_NATIVE_OWNER_ID_AND_ACCOUNT');
    $body = $request['body'];
    nhe_keys($body, ['addressId', 'couponId', 'payType', 'useIntegral', 'mark', 'combinationId', 'pinkId',
        'seckill_id', 'bargainId', 'shipping_type', 'store_id', 'new', 'invoice_id', 'advanceId',
        'custom_form', 'is_gift', 'gift_mark'], 'NHEPCXR_ORIGINAL_SEVENTEEN_FIELD_CREATE_BODY');
    nhep_expect(is_int($body['addressId']) && $body['addressId'] > 0 && $body['addressId'] <= 4294967295
        && $body === ['addressId' => $body['addressId'], 'couponId' => 0, 'payType' => 'yue', 'useIntegral' => 0,
            'mark' => $intent['run_id'] . '-' . $family, 'combinationId' => 0, 'pinkId' => 0, 'seckill_id' => 0,
            'bargainId' => 0, 'shipping_type' => 1, 'store_id' => 0, 'new' => 0, 'invoice_id' => 0,
            'advanceId' => 0, 'custom_form' => [], 'is_gift' => 0, 'gift_mark' => ''],
        'NHEPCXR_FIXED_ORIGINAL_NORMAL_CREATE_REQUEST');
    $interval = $response['actual_interval'] ?? null;
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0 && $interval[0] <= $interval[1]
        && $interval[1] <= 2147483647 && ($response['http'] ?? null) === 200
        && ($response['transport_errno'] ?? null) === 0 && array_key_exists('transport_failure_class', $response)
        && $response['transport_failure_class'] === null && ($response['primary_ip'] ?? null) === '127.0.0.1'
        && ($response['primary_port'] ?? null) === 8000 && ($response['local_ip'] ?? null) === '127.0.0.1'
        && is_int($response['local_port'] ?? null) && $response['local_port'] > 0 && $response['local_port'] <= 65535
        && is_string($response['raw'] ?? null) && strlen($response['raw']) <= 6291456
        && is_array($response['json'] ?? null), 'NHEPCXR_REAL_COMPLETE_OWN_NORMAL_HTTP');
    $json = json_decode($response['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $json === $response['json'], 'NHEPCXR_COMPLETE_RAW_JSON_JOIN');
    nhe_keys($json, ['status', 'msg', 'data'], 'NHEPCXR_ORIGINAL_RESPONSE_ENVELOPE');
    nhep_expect($json['status'] === 200 && $json['msg'] === '订单创建成功' && is_array($json['data']),
        'NHEPCXR_ORIGINAL_CHINESE_CREATE_SUCCESS_MESSAGE');
    nhe_keys($json['data'], ['status', 'result'], 'NHEPCXR_ORIGINAL_STATUS_RESPONSE_DATA');
    nhep_expect($json['data']['status'] === 'SUCCESS' && is_array($json['data']['result']),
        'NHEPCXR_ORIGINAL_CREATE_SUCCESS_NOT_EXISTING_ORDER');
    nhe_keys($json['data']['result'], ['orderId', 'key'], 'NHEPCXR_ORIGINAL_RESULT_KEYS');
    nhep_expect(is_string($json['data']['result']['orderId']) && $json['data']['result']['key'] === $key,
        'NHEPCXR_ORIGINAL_RESULT_NATIVE_ORDER_NUMBER_AND_CONFIRMATION_KEY');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPCXR_BOTH_COMPLETE_CAPTURES_SAME_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $afterUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($afterUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPCXR_REAL_HTTP_WINDOW_INSIDE_MONOTONIC_REDIS_OBSERVATIONS');
    return $key;
}

/** Shared with the DB model. The observed cp string is only a bounded native candidate. */
function nhepcx_order_expected(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] string $actualOrderNo): string
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepar_capture', 'nhepar_entry', 'nhepar_bind',
        'bcadd', 'bcsub', 'bcmul', 'bcdiv', 'bcmod', 'bccomp'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPCXR_ORDER_PURE_DEPENDENCY_REQUIRED');
    nhepcxr_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhep_expect(preg_match('/\Acp([1-9][0-9]{0,18})\z/D', $actualOrderNo, $match) === 1
        && bccomp($match[1], '9223372036854775807', 0) <= 0,
        'NHEPCXR_CANONICAL_NATIVE_CP_SIGNED_64_BIT_NUMBER');
    $number = $match[1]; $elapsed = bcdiv($number, '4194304', 0); $low = bcmod($number, '4194304', 0);
    $datacenter = bcdiv($low, '131072', 0);
    $worker = bcmod(bcdiv($low, '4096', 0), '32', 0); $sequence = bcmod($low, '4096', 0);
    nhep_expect(bccomp($elapsed, '0', 0) > 0 && bccomp($elapsed, '2199023255551', 0) <= 0
        && $datacenter === '0' && $worker === '0' && $sequence === '0',
        'NHEPCXR_ORIGINAL_DEFAULT_NODES_AND_FRESH_ZERO_SEQUENCE');
    $milliseconds = bcadd('1640966400000', $elapsed, 0);
    $httpStart = bcmul((string)$privateResponse['actual_interval'][0], '1000', 0);
    $httpLast = bcsub(bcmul(bcadd((string)$privateResponse['actual_interval'][1], '1', 0), '1000', 0), '1', 0);
    nhep_expect(bccomp($milliseconds, $httpStart, 0) >= 0 && bccomp($milliseconds, $httpLast, 0) <= 0
        && bccomp($milliseconds, $beforeCapture['snapshot']['time_ms'], 0) >= 0
        && bccomp($milliseconds, $actualCapture['snapshot']['time_ms'], 0) <= 0,
        'NHEPCXR_DECODED_MILLISECOND_WITHIN_REAL_HTTP_AND_CAPTURE_WINDOWS');
    nhep_expect(nhepar_entry($beforeCapture, $milliseconds) === null, 'NHEPCXR_FRESH_BEFORE_RAW_MILLISECOND_KEY');
    $expected = 'cp' . bcadd(bcmul(bcsub($milliseconds, '1640966400000', 0), '4194304', 0), '0', 0);
    nhep_expect($expected === $actualOrderNo
        && $privateResponse['json']['data']['result']['orderId'] === $expected,
        'NHEPCXR_FULL_CP_RECONSTRUCTION_AND_REAL_RESULT_NUMBER');
    $row = nhepar_entry($actualCapture, $milliseconds); $latestDeadline = bcadd($httpLast, '1000', 0);
    if ($row === null) {
        // Only natural absence is proven. No expired payload/DUMP or exact expired TTL is claimed.
        nhep_expect(bccomp($actualCapture['snapshot']['time_ms'], $latestDeadline, 0) > 0,
            'NHEPCXR_MISSING_COUNTER_ONLY_AFTER_LAST_POSSIBLE_DEADLINE');
    } else {
        nhep_expect($row['type'] === 'string' && $row['value'] === '1' && is_int($row['expires']) && $row['expires'] > 0
            && bccomp((string)$row['expires'], bcadd($milliseconds, '1000', 0), 0) >= 0
            && bccomp((string)$row['expires'], $latestDeadline, 0) <= 0
            && bccomp((string)$row['expires'], $actualCapture['snapshot']['time_ms'], 0) >= 0,
            'NHEPCXR_ORIGINAL_FIRST_PSETEX_ONE_COMPLETE_VALUE_AND_DEADLINE');
        nhepar_bind($actualCapture, $milliseconds, 'string', '1', ['ttl' => 1], $beforeCapture['snapshot']);
    }
    return $expected;
}

/** Full namespace from BEFORE plus independent old create effects, never a DB or seven-part ACK. */
function nhep_create_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration, #[SensitiveParameter] array $confirmedContext,
    #[SensitiveParameter] string $actualOrderNo): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_fixture', 'nhepcd_before_guards',
        'nhepcd_one', 'nhepcd_id', 'nhepcx_confirmation', 'nhepcr_config_wire', 'nhepar_capture', 'nhepar_entry',
        'nhepar_actor', 'nhepar_customer', 'nhepar_remember', 'nhepar_bind', 'nhepar_tag', 'nhepar_uint',
        'nhep_redis_expected', 'm4lh_actor_next', 'm4lh_actor_native', 'bcadd', 'bcsub', 'bcmul', 'bcdiv', 'bccomp'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPCXR_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    $key = nhepcxr_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    $built = nhepcx_confirmation($beforeDB2, $intent, $privateRequest, $confirmedContext);
    nhe_keys($built, ['orderKey', 'logicalKey', 'tuple', 'wire', 'responseCartInfo'], 'NHEPCXR_COMPLETE_INDEPENDENT_CONFIRMATION_VALUE');
    nhep_expect($built['orderKey'] === $key && is_string($built['logicalKey']) && is_array($built['tuple'])
        && is_string($built['wire']) && $built['wire'] !== '' && is_array($built['responseCartInfo']),
        'NHEPCXR_ORIGINAL_CONFIRMATION_KEY_AND_FULL_PRIVATE_VALUE');
    nhe_keys($built['tuple'], ['cartInfo', 'priceGroup', 'other'], 'NHEPCXR_ORIGINAL_THREE_FIELD_CONFIRMATION_TUPLE');
    nhep_expect($built['wire'] === serialize($built['tuple']) && is_array($built['tuple']['cartInfo'])
        && array_is_list($built['tuple']['cartInfo']) && count($built['tuple']['cartInfo']) === 1,
        'NHEPCXR_INDEPENDENT_COMPLETE_PHP_CONFIRMATION_NOT_ACTUAL_CACHE_BODY');
    $fixture = nhepcd_fixture($beforeDB2, $intent, $privateRequest); nhepcd_before_guards($beforeDB2, false);
    $uid = $fixture['uid']; $rows = $beforeDB2['rows'];
    nhep_expect($built['logicalKey'] === 'user_order_' . $uid . $key
        && $privateRequest['body']['addressId'] === $fixture['address_id'], 'NHEPCXR_CURRENT_REAL_OWNER_AND_ADDRESS');
    $product = nhepcd_one($beforeDB2, 'eb_store_product', ['id' => $fixture['product_id']]);
    $sku = nhepcd_one($beforeDB2, 'eb_store_product_attr_value', ['id' => $fixture['sku_id']]);
    nhep_expect(($product['row']['is_sub'] ?? null) === 0 && is_int($sku['row']['stock']) && $sku['row']['stock'] > 1,
        'NHEPCXR_NO_PRODUCT_COMMISSION_AND_POSITIVE_STOCK_AFTER_ONE_DECREMENT');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($rows[$table] === [], 'NHEPCXR_ORIGINAL_EMPTY_LANGUAGE_TABLES');
    foreach ($rows['eb_system_notification'] as $row)
        foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat', 'is_app'] as $field)
            nhep_expect(nhepar_uint($row[$field], true) === 0, 'NHEPCXR_DISABLED_NOTIFICATION_BRANCH');
    $ticketColumns = $beforeDB2['database']['tables']['eb_system_ticket']['metadata']['columns'];
    foreach ($rows['eb_system_ticket'] as $row) {
        foreach (['is_del', 'status', 'print_type'] as $column)
            nhep_expect(m4lh_actor_native($ticketColumns[$column], $row[$column]) === $row[$column],
                'NHEPCXR_ORIGINAL_NATIVE_PRINTER_SELECTOR');
        nhep_expect(!($row['is_del'] === 0 && $row['status'] === 1 && $row['print_type'] === 2),
            'NHEPCXR_ENABLED_CREATE_PRINTER_BRANCH_NOT_IMPLEMENTED');
    }
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']), 'NHEPCXR_SAME_RUN_ORIGINAL_PRIVATE_AUTH_CONFIGURATION');
    $actor = nhepar_actor($rows, $intent, $privateRequest); $changes = []; $tagMembers = [];
    $apiTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('api'));
    nhep_expect(is_array($apiTag) && $apiTag['type'] === 'set' && $apiTag['expires'] === -1
        && in_array('c:' . md5($privateRequest['token']), $apiTag['value'], true),
        'NHEPCXR_ORIGINAL_EXISTING_CUSTOMER_WHITELIST_TAG_MEMBERSHIP');
    nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);
    $settings = ['station_open' => 1, 'param_filter_type' => null, 'param_filter_data' => null,
        'offline_pay_status' => 2, 'store_free_postage' => '10000.00', 'store_self_mention' => 0,
        'store_stock' => null, 'brokerage_func_status' => 0, 'is_self_brokerage' => null,
        'division_status' => 0, 'user_brokerage_type' => null, 'queue_open' => 0, 'image_thumb_status' => 0];
    foreach ($settings as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    // Missing store_stock -> sys_config default empty string, strictly below this positive remaining stock.
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire)
        nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
    $physicalConfirmation = 'c:' . $built['logicalKey']; $oldConfirmation = nhepar_entry($beforeCapture, $physicalConfirmation);
    $confirmInterval = $confirmedContext['httpInterval'];
    $earliest = bcadd(bcmul((string)$confirmInterval[0], '1000', 0), '600000', 0);
    $latest = bcadd(bcsub(bcmul(bcadd((string)$confirmInterval[1], '1', 0), '1000', 0), '1', 0), '600000', 0);
    nhep_expect(is_array($oldConfirmation) && is_int($oldConfirmation['expires']) && $oldConfirmation['expires'] > 0
        && bccomp((string)$oldConfirmation['expires'], $earliest, 0) >= 0
        && bccomp((string)$oldConfirmation['expires'], $latest, 0) <= 0
        && bccomp((string)$oldConfirmation['expires'], $beforeCapture['snapshot']['time_ms'], 0) > 0,
        'NHEPCXR_REAL_ORIGINAL_CONFIRM_HTTP_WINDOW_SETEX_600_STILL_PRESENT_BEFORE_CREATE');
    nhepar_bind($beforeCapture, $physicalConfirmation, 'string', $built['wire'], $oldConfirmation['expires'], $beforeCapture['snapshot']);
    $crmebTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('crmeb'));
    nhep_expect(is_array($crmebTag) && $crmebTag['type'] === 'set' && $crmebTag['expires'] === -1
        && in_array($physicalConfirmation, $crmebTag['value'], true), 'NHEPCXR_ORIGINAL_CONFIRMATION_TAG_MEMBER_PRESENT');
    nhep_expect(nhepar_entry($actualCapture, $physicalConfirmation) === null, 'NHEPCXR_ORIGINAL_CONFIRMATION_DELETED_AFTER_CREATE');
    $changes[$physicalConfirmation] = null;
    // The route rule contains a literal normalized <key> placeholder; it is not the actual key value.
    $mutex = 'redis:mutex:' . md5('order/create/<key>' . $uid);
    $lock = 'lock_orderCreate' . $key;
    foreach ([$mutex, $lock] as $temporary)
        nhep_expect(nhepar_entry($beforeCapture, $temporary) === null && nhepar_entry($actualCapture, $temporary) === null,
            'NHEPCXR_TWO_ORIGINAL_TEMPORARY_LOCKS_ABSENT_AT_BOTH_NORMAL_BOUNDARIES');
    $expectedNumber = nhepcx_order_expected($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse, $actualOrderNo);
    $milliseconds = bcadd('1640966400000', bcdiv(substr($expectedNumber, 2), '4194304', 0), 0);
    if (nhepar_entry($actualCapture, $milliseconds) !== null)
        $changes[$milliseconds] = nhepar_bind($actualCapture, $milliseconds, 'string', '1', ['ttl' => 1], $beforeCapture['snapshot']);
    $oid = m4lh_actor_next($beforeDB2['database']['tables']['eb_store_order'], 'id');
    $cartId = nhepcd_id($confirmedContext['request']['body']['cartId']);
    // getOrderCartInfo sums refund_num by cart_id across all orders, not just the new OID.
    // The fixed producer creates fresh canonical cart IDs; do not silently ignore any old matching item.
    $itemColumns = $beforeDB2['database']['tables']['eb_store_order_cart_info']['metadata']['columns'];
    foreach ($rows['eb_store_order_cart_info'] as $previousItem) {
        nhep_expect(m4lh_actor_native($itemColumns['cart_id'], $previousItem['cart_id']) === $previousItem['cart_id'],
            'NHEPCXR_ORIGINAL_NATIVE_PREVIOUS_ITEM_CART_ID');
        nhep_expect(nhepcd_id($previousItem['cart_id']) !== $cartId, 'NHEPCXR_OLD_ITEM_REUSING_CURRENT_CART_BRANCH_NOT_IMPLEMENTED');
    }
    $cart = $built['tuple']['cartInfo'][0];
    nhep_expect(is_array($cart) && ($cart['id'] ?? null) === $cartId && ($cart['uid'] ?? null) === $uid
        && ($cart['product_id'] ?? null) === $fixture['product_id'] && ($cart['cart_num'] ?? null) === 1,
        'NHEPCXR_ORIGINAL_ONE_CART_VALUE_FROM_ACCEPTED_CONFIRMATION');
    $cart['use_integral'] = 0; $cart['integral_price'] = 0.0; $cart['coupon_price'] = 0.0;
    $cart['sum_true_price'] = bcmul((string)$cart['truePrice'], (string)$cart['cart_num'], 2);
    $cart['one_brokerage'] = '0'; $cart['two_brokerage'] = '0';
    $cart['staff_brokerage'] = '0.00'; $cart['agent_brokerage'] = '0.00'; $cart['division_brokerage'] = '0.00';
    // updateCartInfo persists default json_encode; getOrderCartInfo decodes that complete saved JSON.
    $saved = json_decode(json_encode($cart, JSON_THROW_ON_ERROR), true, 512, JSON_THROW_ON_ERROR);
    nhep_expect(is_array($saved) && is_array($saved['productInfo'] ?? null)
        && is_array($saved['productInfo']['attrInfo'] ?? null), 'NHEPCXR_COMPLETE_INDEPENDENT_SAVED_CART_JSON');
    $saved['refund_num'] = 0.0; // The original AggregateQuery::sum return type is float.
    $logicalDetails = md5('store_order_cart_info_' . $oid);
    $logicalTitle = md5('store_order_cart_product_title_' . $oid);
    foreach ([$logicalDetails, $logicalTitle] as $logical)
        nhep_expect(nhepar_entry($beforeCapture, 'c:' . $logical) === null, 'NHEPCXR_NEW_ORDER_CACHE_KEY_ABSENT_BEFORE');
    $detailsWire = serialize([$cartId => ['cart_info' => $saved]]);
    $changes['c:' . $logicalDetails] = nhepar_bind($actualCapture, 'c:' . $logicalDetails, 'string', $detailsWire, -1, $beforeCapture['snapshot']);
    $tagMembers[] = 'c:' . $logicalDetails;
    nhep_expect(is_string($product['row']['store_name']) && $product['row']['store_name'] !== '', 'NHEPCXR_ORIGINAL_FULL_PRODUCT_TITLE');
    $changes['c:' . $logicalTitle] = nhepar_bind($actualCapture, 'c:' . $logicalTitle, 'string', serialize($product['row']['store_name']), -1, $beforeCapture['snapshot']);
    $tagMembers[] = 'c:' . $logicalTitle;
    $cancel = ['order_cancel_time' => '0', 'order_activity_time' => '0', 'order_bargain_time' => '0',
        'order_seckill_time' => '0', 'order_pink_time' => '0'];
    foreach ($cancel as $name => $value)
        nhep_expect(nhepcr_config_wire($beforeDB2, $name, $value) === '0', 'NHEPCXR_ORIGINAL_FIVE_CANCEL_CONFIG_JSON_STRINGS');
    // more() caches this ordered string-valued map before Arr::setValeTime makes local floats.
    nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . md5(implode(',', array_keys($cancel))),
        serialize($cancel), 0, $changes, $tagMembers);
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'], 'NHEPCXR_COMPLETE_NAMESPACE_INDEPENDENT_CREATE_EXPECTED');
    return $expected;
}


/** Original 477 detail GET observers: pure definitions only; factory still rejects these steps. */
/** Definitions only. Original 477 detail GETs; every selected row/value stays private RAM. */
function nhepod_context(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_fixture', 'nhepcd_one',
        'nhepcd_id', 'nhepcv_native_row', 'nhepcv_config', 'm4lh_actor_native',
        'm4lh_actor_expected_row', 'bccomp', 'json_decode', 'json_encode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_ORDER_DETAIL_CONTEXT_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHE_ORDER_DETAIL_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHE_ORDER_DETAIL_ORIGINAL_PRIVATE_GET_REQUEST');
    nhep_expect(is_array($privateRequest['actor_identity']), 'NHE_ORDER_DETAIL_PRIVATE_NATIVE_ACTOR_REQUIRED');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHE_ORDER_DETAIL_ORIGINAL_ACTOR_IDENTITY');
    $steps = ['refund_family_unpaid_read' => [12, 'refund_family', 0],
        'refund_family_paid_read' => [14, 'refund_family', 1],
        'review_family_unpaid_read' => [18, 'review_family', 0],
        'review_family_paid_read' => [20, 'review_family', 1],
        'owned_refunded_root_read' => [26, 'refund_family', 1],
        'owned_shipped_read' => [29, 'review_family', 1],
        'owned_received_read' => [31, 'review_family', 1],
        'owned_commented_completed_read' => [37, 'review_family', 1]];
    nhep_expect(is_string($intent['step']) && isset($steps[$intent['step']]), 'NHE_ORDER_DETAIL_STEP_NOT_IMPLEMENTED');
    [$sequence, $family, $paid] = $steps[$intent['step']];
    $refunded = $intent['step'] === 'owned_refunded_root_read';
    $shipped = $intent['step'] === 'owned_shipped_read';
    $received = $intent['step'] === 'owned_received_read';
    $completed = $intent['step'] === 'owned_commented_completed_read';
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === 'GET' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['path'])
        && preg_match('~\A/api/order/detail/(cp([1-9][0-9]{0,18}))\z~D', $intent['path'], $path) === 1
        && bccomp($path[2], '9223372036854775807', 0) <= 0
        && $privateRequest['body'] === null && is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1,
        'NHE_ORDER_DETAIL_FIXED_REAL_GET_SEQUENCE_ORIGIN_CP_AND_NULL_BODY');
    // This original fixture selector accepts the real GET and never reads or fabricates a POST body.
    $fixture = nhepcd_fixture($beforeDB2, $intent, $privateRequest);
    $uid = $fixture['uid']; $number = $path[1];
    if ($refunded || $shipped || $received || $completed) nhep_expect($fixture['user']['row']['now_money'] === '79.85'
        && $fixture['user']['row']['pay_count'] === 2,
        'NHE_ORDER_DETAIL_REFUNDED_BEFORE_ORIGINAL_OWNER_BALANCE_AND_TWO_PAYMENTS');
    $order = nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-' . $family]);
    $row = nhepcv_native_row($beforeDB2, 'eb_store_order', $order['index']);
    $oid = nhepcd_id($row['id'], 2147483647);
    if ($shipped || $received || $completed) {
        // Original legacy-actors fixture, independently selected before the root's courier fields.
        $expressTable = $beforeDB2['database']['tables']['eb_express'];
        $expressMetadata = $expressTable['metadata'];
        nhep_expect(array_keys($expressMetadata['columns']) === ['id', 'code', 'name', 'partner_id', 'partner_key',
            'net', 'check_man', 'partner_name', 'is_code', 'courier_name', 'customer_name', 'code_name',
            'account', 'key', 'net_name', 'sort', 'is_show', 'status'],
            'NHE_ORDER_DETAIL_SHIPPED_ORIGINAL_COMPLETE_EXPRESS_COLUMNS');
        $codeColumn = $expressMetadata['columns']['code'];
        nhep_expect(strtolower($codeColumn['COLUMN_TYPE']) === 'varchar(50)' && $codeColumn['IS_NULLABLE'] === 'NO'
            && $codeColumn['CHARACTER_SET_NAME'] === 'utf8mb4'
            && in_array($codeColumn['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
                'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
            'NHE_ORDER_DETAIL_SHIPPED_ORIGINAL_EXPRESS_SQL_SELECTOR_METADATA');
        foreach ($beforeDB2['rows']['eb_express'] as $index => $unused) {
            $candidate = nhepcv_native_row($beforeDB2, 'eb_express', $index);
            nhep_expect(is_string($candidate['code']) && preg_match('/\A[\x20-\x7e]*\z/D', $candidate['code']) === 1
                && (strtolower(rtrim($candidate['code'], ' ')) !== 'shunfeng' || $candidate['code'] === 'shunfeng'),
                'NHE_ORDER_DETAIL_SHIPPED_NO_SQL_EQUIVALENT_EXPRESS_CODE_ALIAS');
        }
        $express = nhepcd_one($beforeDB2, 'eb_express', ['code' => 'shunfeng']);
        $expressRow = nhepcv_native_row($beforeDB2, 'eb_express', $express['index']);
        $expressId = nhepcd_id($expressRow['id']);
        nhep_expect($expressRow === m4lh_actor_expected_row($expressMetadata, ['id' => $expressId,
            'code' => 'shunfeng', 'name' => '顺丰速运', 'partner_id' => 1, 'is_show' => 1, 'status' => 0]),
            'NHE_ORDER_DETAIL_SHIPPED_COMPLETE_ORIGINAL_EXPRESS_FIXTURE_AND_DEFAULTS');
    }
    nhep_expect($row['order_id'] === $number && $row['uid'] === $uid && $row['pay_uid'] === $uid
        && $row['paid'] === $paid && $row['pay_type'] === 'yue' && $row['channel_type'] === 'h5'
        && is_string($row['unique']) && preg_match('/\A[1-9][0-9]{0,18}\z/D', $row['unique']) === 1
        && bccomp($row['unique'], '9223372036854775807', 0) <= 0,
        'NHE_ORDER_DETAIL_BEFORE_SAME_FAMILY_NATIVE_ROOT_OWNER_PAY_OWNER_AND_KEYS');
    foreach (['pid' => 0, 'status' => ($completed ? 3 : ($refunded ? -2 : ($received ? 2 : ($shipped ? 1 : 0)))), 'refund_status' => ($refunded ? 2 : 0),
        'refund_type' => ($refunded ? 6 : 0),
        'is_del' => 0, 'is_system_del' => 0, 'is_cancel' => 0, 'is_stock_up' => 0,
        'shipping_type' => 1, 'total_num' => 1, 'store_id' => 0, 'delivery_uid' => 0, 'clerk_id' => 0,
        'is_channel' => ($paid === 1 ? 2 : 0), 'virtual_type' => 0, 'is_gift' => 0, 'gift_uid' => 0,
        'combination_id' => 0, 'pink_id' => 0, 'seckill_id' => 0, 'bargain_id' => 0, 'advance_id' => 0,
        'coupon_id' => 0, 'verify_code' => '', 'delivery_type' => (($shipped || $received || $completed) ? 'express' : ''),
        'delivery_id' => (($shipped || $received || $completed) ? 'NHE' . $intent['run_id'] : ''),
        'delivery_name' => (($shipped || $received || $completed) ? '顺丰速运' : ''), 'delivery_code' => (($shipped || $received || $completed) ? 'shunfeng' : ''),
        'gift_mark' => '', 'custom_form' => '[]',
        'total_price' => '20.15', 'pay_price' => '20.15', 'cost' => '7.45',
        'freight_price' => '0.00', 'total_postage' => '0.00', 'pay_postage' => '0.00',
        'deduction_price' => '0.00', 'coupon_price' => '0.00', 'gift_price' => '0.00',
        'refund_price' => ($refunded ? '20.15' : '0.00'), 'use_integral' => '0.00', 'gain_integral' => '0.00',
        'back_integral' => '0.00'] as $column => $value)
        nhep_expect(array_key_exists($column, $row) && $row[$column] === $value,
            'NHE_ORDER_DETAIL_ONLY_ORIGINAL_NORMAL_UNSHIPPED_UNREFUNDED_ROOT');
    if ($refunded || $shipped || $received || $completed) nhep_expect(count($order['metadata']['columns']) === 87
        && $row['refund_reason_time'] === 0 && $row['refund_reason_wap_img'] === '',
        'NHE_ORDER_DETAIL_REFUNDED_FULL_ORIGINAL_ROOT_COLUMNS_AND_PRESERVED_REASON_FIELDS');
    nhep_expect(is_int($row['add_time']) && $row['add_time'] > 0
        && ($paid === 0 ? $row['pay_time'] === 0
            : (is_int($row['pay_time']) && $row['pay_time'] >= $row['add_time'])),
        'NHE_ORDER_DETAIL_ORIGINAL_BEFORE_CREATE_AND_PAY_TIMES');

    // MySQL's actual DAO uses BOTH ORs. Prove canonical ASCII lookup values rather than assume PHP === is SQL collation.
    $visible = []; $uniqueMatches = [];
    $orderColumns = $order['metadata']['columns'];
    foreach ($beforeDB2['rows']['eb_store_order'] as $index => $candidate) {
        foreach (['order_id', 'unique', 'uid', 'gift_uid', 'is_del', 'pid'] as $column)
            nhep_expect(m4lh_actor_native($orderColumns[$column], $candidate[$column]) === $candidate[$column],
                'NHE_ORDER_DETAIL_ORIGINAL_NATIVE_DAO_SELECTOR_FIELDS');
        foreach (['order_id', 'unique'] as $column)
            nhep_expect(is_string($candidate[$column]) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate[$column]) === 1,
                'NHE_ORDER_DETAIL_NONCANONICAL_LOOKUP_COLLATION_BRANCH_NOT_IMPLEMENTED');
        if (strtolower($candidate['unique']) === $row['unique']) $uniqueMatches[] = $index;
        if ($candidate['is_del'] === 0 && ($candidate['uid'] === $uid || $candidate['gift_uid'] === $uid)
            && (strtolower($candidate['order_id']) === $number || strtolower($candidate['unique']) === $number))
            $visible[] = $index;
        nhep_expect($candidate['pid'] !== $oid, 'NHE_ORDER_DETAIL_SPLIT_RELATION_BRANCH_NOT_IMPLEMENTED');
    }
    nhep_expect($visible === [$order['index']] && $uniqueMatches === [$order['index']]
        && nhepcd_one($beforeDB2, 'eb_store_order', ['id' => $oid]) === $order,
        'NHE_ORDER_DETAIL_ACTUAL_DAO_OR_LOOKUP_UNIQUE_AND_SAME_INDEPENDENT_ROOT');
    foreach (['store_self_mention', 'image_thumb_status', 'order_shipping_open',
        'invoice_func_status', 'special_invoice_status'] as $name)
        nhepcv_config($beforeDB2, $intent, $name, 0);
    // No invoice relation, gift/verify QR, delivery-person or MiniOrder side effect is admitted.
    foreach ($beforeDB2['rows']['eb_store_order_invoice'] as $invoice)
        nhep_expect(m4lh_actor_native($beforeDB2['database']['tables']['eb_store_order_invoice']['metadata']['columns']['order_id'],
            $invoice['order_id']) !== $oid, 'NHE_ORDER_DETAIL_INVOICE_RELATION_BRANCH_NOT_IMPLEMENTED');

    $item = nhepcd_one($beforeDB2, 'eb_store_order_cart_info', ['oid' => $oid]);
    $saved = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $item['index']);
    $itemId = nhepcd_id($saved['id'], 2147483647); $cartId = nhepcd_id($saved['cart_id']);
    if ($refunded || $shipped || $received || $completed) nhep_expect(array_keys($item['metadata']['columns']) === ['id', 'oid', 'uid', 'cart_id',
        'product_id', 'old_cart_id', 'cart_num', 'refund_num', 'surplus_num', 'split_status', 'cart_info', 'unique'],
        'NHE_ORDER_DETAIL_REFUNDED_ORIGINAL_COMPLETE_TWELVE_ITEM_COLUMNS');
    nhep_expect($saved === m4lh_actor_expected_row($item['metadata'], ['id' => $itemId, 'oid' => $oid,
        'uid' => $uid, 'cart_id' => (string)$cartId, 'product_id' => $fixture['product_id'],
        'cart_num' => 1, 'surplus_num' => 1, 'cart_info' => $saved['cart_info'], 'unique' => md5($cartId . '' . $oid)]
        + ($refunded ? ['refund_num' => 1] : []))
        && is_string($saved['cart_info']) && $saved['cart_info'] !== ''
        && $row['cart_id'] === json_encode([$cartId]), 'NHE_ORDER_DETAIL_ONE_ORIGINAL_FULL_UNSPLIT_SAVED_ITEM_AND_CART_ID');
    $itemUniqueMatches = [];
    foreach ($beforeDB2['rows']['eb_store_order_cart_info'] as $index => $candidate) {
        nhep_expect(is_string($candidate['unique']) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate['unique']) === 1,
            'NHE_ORDER_DETAIL_NONCANONICAL_ITEM_UNIQUE_COLLATION_NOT_IMPLEMENTED');
        if (strtolower($candidate['unique']) === $saved['unique']) $itemUniqueMatches[] = $index;
    }
    nhep_expect($itemUniqueMatches === [$item['index']], 'NHE_ORDER_DETAIL_GLOBAL_SAVED_ITEM_UNIQUE_IS_UNAMBIGUOUS');
    foreach ($beforeDB2['rows']['eb_store_cart'] as $candidate)
        nhep_expect(m4lh_actor_native($beforeDB2['database']['tables']['eb_store_cart']['metadata']['columns']['id'],
            $candidate['id']) !== $cartId, 'NHE_ORDER_DETAIL_ORIGINAL_PERSISTENT_CART_ALREADY_CONSUMED');

    $cart = json_decode($saved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && is_array($cart) && !array_is_list($cart)
        && json_encode($cart) === $saved['cart_info'], 'NHE_ORDER_DETAIL_ORIGINAL_COMPLETE_DEFAULT_JSON_SAVED_CART');
    $cartMetadata = $beforeDB2['database']['tables']['eb_store_cart']['metadata'];
    $cartColumns = array_keys($cartMetadata['columns']); $baseCart = [];
    nhep_expect(count($cartColumns) === 15, 'NHE_ORDER_DETAIL_ORIGINAL_FIFTEEN_NATIVE_CART_COLUMNS');
    foreach ($cartColumns as $column) {
        nhep_expect(array_key_exists($column, $cart), 'NHE_ORDER_DETAIL_COMPLETE_ORIGINAL_SAVED_CART_BASE');
        $baseCart[$column] = m4lh_actor_native($cartMetadata['columns'][$column], $cart[$column]);
        nhep_expect($baseCart[$column] === $cart[$column], 'NHE_ORDER_DETAIL_NATIVE_SAVED_CART_BASE_TYPE');
    }
    nhep_expect(is_int($baseCart['add_time']) && $baseCart['add_time'] > 0 && $baseCart['add_time'] <= $row['add_time']
        && $baseCart === m4lh_actor_expected_row($cartMetadata, ['id' => $cartId, 'uid' => $uid,
            'type' => '0', 'product_id' => $fixture['product_id'], 'product_attr_unique' => $fixture['sku_unique'],
            'cart_num' => 1, 'add_time' => $baseCart['add_time']]), 'NHE_ORDER_DETAIL_ORIGINAL_OWNED_CART_AND_SKU_BASE');
    nhep_expect(is_array($cart['productInfo'] ?? null) && is_array($cart['attrInfo'] ?? null)
        && is_array($cart['productInfo']['attrInfo'] ?? null)
        && $cart['attrInfo'] === $cart['productInfo']['attrInfo'], 'NHE_ORDER_DETAIL_BOTH_ORIGINAL_SAVED_SKU_RELATIONS');
    $productSelection = nhepcd_one($beforeDB2, 'eb_store_product', ['id' => $fixture['product_id']]);
    $skuSelection = nhepcd_one($beforeDB2, 'eb_store_product_attr_value', ['unique' => $fixture['sku_unique']]);
    $product = nhepcv_native_row($beforeDB2, 'eb_store_product', $productSelection['index']);
    $sku = nhepcv_native_row($beforeDB2, 'eb_store_product_attr_value', $skuSelection['index']);
    $historicalProduct = $cart['productInfo']; $historicalSku = $cart['productInfo']['attrInfo'];
    // Inventory is persisted history. Validate it natively and retain it; never replace it with today's stock/sales.
    foreach ([['eb_store_product', $historicalProduct], ['eb_store_product_attr_value', $historicalSku]] as [$table, $history]) {
        foreach (['stock', 'sales'] as $column) {
            nhep_expect(array_key_exists($column, $history)
                && m4lh_actor_native($beforeDB2['database']['tables'][$table]['metadata']['columns'][$column], $history[$column]) === $history[$column]
                && is_int($history[$column]) && $history[$column] >= ($column === 'stock' ? 1 : 0),
                'NHE_ORDER_DETAIL_ORIGINAL_NATIVE_HISTORICAL_INVENTORY');
        }
    }
    $sku['stock'] = $historicalSku['stock']; $sku['sales'] = $historicalSku['sales'];
    nhep_expect($sku === $historicalSku && $sku['id'] === $fixture['sku_id']
        && $sku['product_id'] === $fixture['product_id'] && $sku['unique'] === $fixture['sku_unique']
        && $sku['suk'] === '普通' && $sku['type'] === 0 && $sku['price'] === '20.15' && $sku['cost'] === '7.45',
        'NHE_ORDER_DETAIL_ORIGINAL_COMPLETE_SAVED_SKU_WITH_HISTORICAL_INVENTORY');
    $slides = json_decode($product['slider_image'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $slides === ['/statics/system_images/spread_level_1.png'],
        'NHE_ORDER_DETAIL_ORIGINAL_PRODUCT_SLIDER_GETTER');
    $product['stock'] = $historicalProduct['stock']; $product['sales'] = $historicalProduct['sales'];
    $product['slider_image'] = $slides; $product['express_delivery'] = true;
    $product['store_mention'] = false; $product['attrInfo'] = $sku;
    nhep_expect($product === $historicalProduct, 'NHE_ORDER_DETAIL_COMPLETE_ORIGINAL_SAVED_PRODUCT_WITH_HISTORICAL_INVENTORY');
    $expectedCart = $baseCart;
    $expectedCart['productInfo'] = $product; $expectedCart['attrInfo'] = $sku;
    $expectedCart['min_qty'] = 1; $expectedCart['attrStatus'] = true; $expectedCart['vip_truePrice'] = 0;
    $expectedCart['costPrice'] = '7.45'; $expectedCart['trueStock'] = $historicalSku['stock'];
    $expectedCart['truePrice'] = 20.15; $expectedCart['sum_price'] = '20.15';
    $expectedCart['price_type'] = 'level'; $expectedCart['is_valid'] = 1; $expectedCart['postage_price'] = 0;
    $expectedCart['use_integral'] = 0; $expectedCart['integral_price'] = 0; $expectedCart['coupon_price'] = 0;
    $expectedCart['sum_true_price'] = '20.15'; $expectedCart['one_brokerage'] = '0'; $expectedCart['two_brokerage'] = '0';
    $expectedCart['staff_brokerage'] = '0.00'; $expectedCart['agent_brokerage'] = '0.00'; $expectedCart['division_brokerage'] = '0.00';
    nhep_expect($expectedCart === $cart, 'NHE_ORDER_DETAIL_COMPLETE_ORIGINAL_SAVED_CART_AND_FIXED_NORMAL_PRICE_FIELDS');
    if ($completed) {
        // tidyOrder counts the entire reply table by item.unique alone, with no other SQL predicate.
        $replyMetadata = $beforeDB2['database']['tables']['eb_store_product_reply']['metadata'];
        nhep_expect(array_keys($replyMetadata['columns']) === ['id', 'uid', 'oid', 'unique', 'product_id',
            'reply_type', 'product_score', 'service_score', 'comment', 'pics', 'add_time',
            'merchant_reply_content', 'merchant_reply_time', 'is_del', 'is_reply', 'nickname', 'avatar', 'suk', 'status'],
            'NHE_ORDER_DETAIL_COMPLETED_ORIGINAL_NINETEEN_REPLY_COLUMNS_WITHOUT_CART_ID');
        $uniqueColumn = $replyMetadata['columns']['unique'];
        nhep_expect(strtolower($uniqueColumn['COLUMN_TYPE']) === 'char(32)' && $uniqueColumn['IS_NULLABLE'] === 'NO'
            && $uniqueColumn['CHARACTER_SET_NAME'] === 'utf8mb4'
            && in_array($uniqueColumn['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
                'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
            'NHE_ORDER_DETAIL_COMPLETED_REAL_GLOBAL_UNIQUE_SQL_METADATA');
        $matches = [];
        foreach ($beforeDB2['rows']['eb_store_product_reply'] as $index => $unused) {
            $candidate = nhepcv_native_row($beforeDB2, 'eb_store_product_reply', $index);
            nhep_expect(is_string($candidate['unique']) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate['unique']) === 1,
                'NHE_ORDER_DETAIL_COMPLETED_NO_NONCANONICAL_GLOBAL_UNIQUE_COLLATION_ALIAS');
            if (strtolower($candidate['unique']) === $saved['unique']) $matches[] = $candidate;
        }
        nhep_expect(count($matches) === 1, 'NHE_ORDER_DETAIL_COMPLETED_GLOBAL_UNIQUE_COUNT_EXACTLY_ONE');
        $reply = $matches[0]; $replyId = nhepcd_id($reply['id'], 2147483647);
        $replyTime = $reply['add_time']; $merchantTime = $reply['merchant_reply_time'];
        $merchantTimeColumn = $replyMetadata['columns']['merchant_reply_time'];
        nhep_expect(preg_match('/\Aint(?:\([0-9]+\))?\z/D', strtolower($merchantTimeColumn['COLUMN_TYPE'])) === 1
            && $merchantTimeColumn['IS_NULLABLE'] === 'NO'
            && is_int($replyTime) && $replyTime > 0 && $replyTime <= 2147483647
            && is_int($merchantTime) && $merchantTime > 0 && $merchantTime <= 2147483647
            && $reply === m4lh_actor_expected_row($replyMetadata, [
                'id' => $replyId, 'uid' => $uid, 'oid' => $oid, 'unique' => $saved['unique'],
                'product_id' => $fixture['product_id'], 'reply_type' => 'product',
                'product_score' => 5, 'service_score' => 5, 'comment' => 'normal-history-' . $intent['run_id'],
                'pics' => '', 'add_time' => $replyTime, 'merchant_reply_content' => 'normal-reply-' . $intent['run_id'],
                'merchant_reply_time' => $merchantTime, 'is_del' => 0, 'is_reply' => 1,
                'nickname' => $fixture['user']['row']['nickname'], 'avatar' => $fixture['user']['row']['avatar'],
                'suk' => $cart['productInfo']['attrInfo']['suk'], 'status' => 1]),
            'NHE_ORDER_DETAIL_COMPLETED_FULL_APPROVED_REPLIED_BEFORE_ROW_SAME_ROOT_BUYER_PRODUCT_AND_ITEM');
    }
    return ['family' => $family, 'paid' => $paid, 'fixture' => $fixture, 'order' => $order, 'item' => $item, 'cart' => $cart];
}

/** Only Auth.parseToken's last_time may change; this does not accept the complete detail DTO or Redis. */
function nhep_order_detail_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepod_context', 'nhep_auth_db_snapshot', 'nhep_auth_db_index',
        'nhep_auth_db_time', 'nhep_auth_db_update', 'nhep_database_expected', 'nheh_root', 'json_decode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_ORDER_DETAIL_DB_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    $context = nhepod_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'paid', 'fixture', 'order', 'item', 'cart'], 'NHE_ORDER_DETAIL_CONTEXT_EXACT_SIX_KEYS');
    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHE_ORDER_DETAIL_ORIGINAL_COMPLETE_PRIVATE_HTTP_RESPONSE');
    $interval = $privateResponse['actual_interval'];
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 4294967295
        && $privateResponse['http'] === 200 && $privateResponse['transport_errno'] === 0
        && $privateResponse['transport_failure_class'] === null && $privateResponse['primary_ip'] === '127.0.0.1'
        && $privateResponse['primary_port'] === 8000 && $privateResponse['local_ip'] === '127.0.0.1'
        && is_int($privateResponse['local_port']) && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw']) && $privateResponse['raw'] !== '' && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json']) && !array_is_list($privateResponse['json'])
        && is_array($privateResponse['headers']), 'NHE_ORDER_DETAIL_ONE_REAL_NATIVE_HTTP_SUCCESS_AND_CLOCK_PAIR');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHE_ORDER_DETAIL_ORIGINAL_COMPLETE_HEADER_CALLBACK_SHAPE');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] >= 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false, 'NHE_ORDER_DETAIL_REAL_COMPLETE_NONTRUNCATED_HEADER_CAPTURE');
    $json = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $json === $privateResponse['json'],
        'NHE_ORDER_DETAIL_ORIGINAL_RAW_AND_PARSED_JSON_STRICT_JOIN');
    nhe_keys($json, ['status', 'msg', 'data'], 'NHE_ORDER_DETAIL_ORIGINAL_SUCCESS_ENVELOPE');
    nhep_expect($json['status'] === 200 && is_string($json['msg']) && is_array($json['data'])
        && !array_is_list($json['data']), 'NHE_ORDER_DETAIL_ORIGINAL_SUCCESS_DATA_OBJECT');
    $fixture = $context['fixture']; $order = $context['order']['row']; $item = $context['item']['row'];
    // Reuse the unchanged driver's public type contract, then bind ALL eight returned identities/states to BEFORE.
    $root = nheh_root($json, ['uid' => $fixture['uid'], 'product_id' => $fixture['product_id'],
        'sku_id' => $fixture['sku_id'], 'sku_unique' => $fixture['sku_unique'],
        'sku_suk' => $context['cart']['productInfo']['attrInfo']['suk']], $order['order_id'], $context['paid'], $order['status']);
    nhep_expect($root === ['id' => $order['id'], 'order_no' => $order['order_id'],
        'order_unique' => $order['unique'], 'item_unique' => $item['unique'],
        'cart_id' => (int)$item['cart_id'], 'paid' => $context['paid'],
        'status' => $order['status'], 'refund_status' => $order['refund_status']],
        'NHE_ORDER_DETAIL_EXISTING_ROOT_CONTRACT_MATCHES_INDEPENDENT_BEFORE_NOT_RESPONSE_SELECTED_IDENTITY');
    nhep_expect($order['add_time'] <= $interval[0] && $order['pay_time'] <= $interval[0],
        'NHE_ORDER_DETAIL_BEFORE_ORDER_TIMES_PRECEDE_REAL_READ_HTTP');
    $user = $fixture['user'];
    $actualUser = nhep_auth_db_index($actualDB2['rows']['eb_user'], $user['metadata'], 'uid', $fixture['uid']);
    // This one bounded native scalar is the only AFTER value allowed into the independently built expected DB.
    $lastTime = nhep_auth_db_time($user['metadata'], 'last_time',
        $actualDB2['rows']['eb_user'][$actualUser]['last_time'], $interval, $user['row']['last_time']);
    $expected = nhep_database_expected($beforeDB2, ['eb_user' => nhep_auth_db_update(
        $beforeDB2, 'eb_user', $user['index'], ['last_time' => $lastTime])]);
    nhep_expect($expected === $actualDB2, 'NHE_ORDER_DETAIL_ALL_164_TABLES_ONLY_ORIGINAL_SELF_AUTH_TIME_CHANGED');
    return $expected;
}

/** Definitions only. Normal 477 detail DTOs are rebuilt from complete private BEFORE state. */
function nhepodv_missing_config(#[SensitiveParameter] array $before, string $name): void
{
    nhep_expect(in_array($name, ['tengxun_map_key', 'friend_pay_status', 'routine_contact_type',
        'refund_time_available'], true), 'NHE_DETAIL_VALUE_ONLY_FOUR_ORIGINAL_MISSING_CONFIGS');
    foreach ($before['rows']['eb_system_config'] as $row) {
        nhep_expect(is_string($row['menu_name']), 'NHE_DETAIL_VALUE_NATIVE_CONFIGURATION_NAME');
        nhep_expect(strtolower(rtrim($row['menu_name'], ' ')) !== $name,
            'NHE_DETAIL_VALUE_ORIGINAL_CONFIGURATION_MUST_REALLY_BE_ABSENT');
    }
}

/** Match the old App timezone explicitly without changing the producer's global timezone. */
function nhepodv_date(string $format, int $seconds): string
{
    nhep_expect(in_array($format, ['Y-m-d', 'H:i:s', 'm-d H:i:s', 'Y-m-d H:i:s', 'm月d日H时i分'], true)
        && $seconds >= 0 && $seconds <= 2147483647, 'NHE_DETAIL_VALUE_ORIGINAL_DATE_FORMAT_AND_NATIVE_SECONDS');
    return (new DateTimeImmutable('@' . $seconds))->setTimezone(new DateTimeZone('Asia/Shanghai'))->format($format);
}

/** Full response data only. No actual response, cache, time candidate, App or observer acknowledgement. */
function nhep_order_detail_value_expected(#[SensitiveParameter] array $beforeDB2, array $intent,
