{
    foreach (['nhep_expect', 'nhe_keys', 'nhepod_context', 'nhepcv_native_row', 'nhepcv_config',
        'm4lh_actor_expected_row', 'bcadd', 'bcmul', 'json_encode', 'json_decode'] as $dependency)
