        && in_array($context['paid'], [0, 1], true) && is_array($context['fixture'])
        && is_array($context['order']) && is_array($context['item']) && is_array($context['cart'])
        && is_int($context['order']['index'] ?? null) && is_int($context['item']['index'] ?? null),
        'NHE_DETAIL_VALUE_COMPLETE_ORIGINAL_CONTEXT_TYPES');
    $fixture = $context['fixture']; $paid = $context['paid'];
    $refunded = $intent['step'] === 'owned_refunded_root_read';
    $shipped = $intent['step'] === 'owned_shipped_read';
    $received = $intent['step'] === 'owned_received_read';
    $completed = $intent['step'] === 'owned_commented_completed_read';
    $order = nhepcv_native_row($beforeDB2, 'eb_store_order', $context['order']['index']);
    $item = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $context['item']['index']);
    nhep_expect($order === $context['order']['row'] && $item === $context['item']['row']
        && is_int($fixture['user']['index'] ?? null), 'NHE_DETAIL_VALUE_ORIGINAL_FULL_ORDER_AND_ITEM');
    $user = nhepcv_native_row($beforeDB2, 'eb_user', $fixture['user']['index']);
    nhep_expect($user === $fixture['user']['row'] && $user['uid'] === $fixture['uid']
        && $order['uid'] === $user['uid'] && $order['pay_uid'] === $user['uid'],
        'NHE_DETAIL_VALUE_BEFORE_ORIGINAL_USER_BIND_AND_SELF_PAYMENT');

    foreach (['station_open' => 1, 'store_self_mention' => 0, 'image_thumb_status' => 0,
        'balance_func_status' => 1, 'yue_pay_status' => 1, 'pay_weixin_open' => 0,
        'ali_pay_status' => 0, 'offline_pay_status' => 2, 'invoice_func_status' => 0,
        'special_invoice_status' => 0, 'order_shipping_open' => 0] as $name => $wanted)
        nhepcv_config($beforeDB2, $intent, $name, $wanted);
    $siteUrl = nhepcv_config($beforeDB2, $intent, 'site_url', $intent['origin']);
    nhep_expect(is_string($siteUrl) && $siteUrl === $intent['origin'],
        'NHE_DETAIL_VALUE_BEFORE_SITE_URL_EQUALS_REAL_REQUEST_ORIGIN');
    foreach (['tengxun_map_key', 'friend_pay_status', 'routine_contact_type', 'refund_time_available'] as $name)
        nhepodv_missing_config($beforeDB2, $name);
    $cancel = [];
    foreach (['order_cancel_time', 'order_activity_time', 'order_bargain_time',
        'order_seckill_time', 'order_pink_time'] as $name)
        $cancel[$name] = nhepcv_config($beforeDB2, $intent, $name, '0');
    // CREATE-only initialization and all admitted preparation/business writes exclude these tables.
    // Their actual complete BEFORE emptiness is still mandatory; a cache value is never evidence.
    nhep_expect($beforeDB2['rows']['eb_system_group'] === [] && $beforeDB2['rows']['eb_system_group_data'] === [],
        'NHE_DETAIL_VALUE_ORIGINAL_GROUP_AND_GROUP_DATA_BOTH_REALLY_EMPTY');

    // Original status column query has no order. Reject ambiguous duplicate keys instead of choosing a row.
    $logs = [];
    $refundMessages = $refunded ? ['cache_key_create_order' => '订单生成', 'pay_success' => '用户付款成功',
        'integral_back' => '商品退积分', 'refund_price' => '退款给用户：20.15元'] : [];
    if ($shipped) $refundMessages = ['cache_key_create_order' => '订单生成', 'pay_success' => '用户付款成功',
        'delivery_goods' => '已发货 快递公司：顺丰速运 快递单号：NHE' . $intent['run_id']];
    if ($received) $refundMessages = ['cache_key_create_order' => '订单生成', 'pay_success' => '用户付款成功',
        'delivery_goods' => '已发货 快递公司：顺丰速运 快递单号：NHE' . $intent['run_id'],
        'take_delivery' => '已收货'];
    if ($completed) $refundMessages = ['cache_key_create_order' => '订单生成', 'pay_success' => '用户付款成功',
        'delivery_goods' => '已发货 快递公司：顺丰速运 快递单号：NHE' . $intent['run_id'],
        'take_delivery' => '已收货', 'check_order_over' => '用户评价'];
    if ($refunded || $shipped || $received || $completed) {
        $statusTable = $beforeDB2['database']['tables']['eb_store_order_status'];
        $statusMetadata = $statusTable['metadata'];
        nhep_expect(array_keys($statusMetadata['columns']) === ['oid', 'change_type', 'change_message', 'change_time']
            && $statusMetadata['table']['AUTO_INCREMENT'] === null
            && !array_key_exists('PRIMARY', $statusMetadata['indexes']) && $statusMetadata['constraints'] === []
            && stripos($statusTable['ddl'], 'PRIMARY KEY') === false,
            'NHE_DETAIL_VALUE_REFUNDED_ORIGINAL_FOUR_STATUS_COLUMNS_WITHOUT_ID_PRIMARY_OR_COUNTER');
        foreach ($statusMetadata['columns'] as $column)
            nhep_expect($column['EXTRA'] !== 'auto_increment',
                'NHE_DETAIL_VALUE_REFUNDED_STATUS_HAS_NO_AUTO_INCREMENT_COLUMN');
    }
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
        $status = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
        if ($status['oid'] !== $order['id']) continue;
        nhep_expect(is_string($status['change_type'])
            && in_array($status['change_type'], ($refunded || $shipped || $received || $completed) ? array_keys($refundMessages)
                : ($paid === 1 ? ['cache_key_create_order', 'pay_success'] : ['cache_key_create_order']), true)
            && !array_key_exists($status['change_type'], $logs)
            && is_int($status['change_time']) && $status['change_time'] > 0
            && $status['change_time'] <= 2147483647,
            'NHE_DETAIL_VALUE_ONLY_UNAMBIGUOUS_ORIGINAL_BEFORE_CREATE_PAY_LOGS');
        if ($refunded || $shipped || $received || $completed) nhep_expect($status === m4lh_actor_expected_row($statusMetadata, [
            'oid' => $order['id'], 'change_type' => $status['change_type'],
            'change_message' => $refundMessages[$status['change_type']], 'change_time' => $status['change_time']]),
            'NHE_DETAIL_VALUE_REFUNDED_COMPLETE_BEFORE_STATUS_ROW_AND_INDEPENDENT_SAVED_TIME');
        $logs[$status['change_type']] = $status['change_time'];
    }
    nhe_keys($logs, ($refunded || $shipped || $received || $completed) ? array_keys($refundMessages)
        : ($paid === 1 ? ['cache_key_create_order', 'pay_success'] : ['cache_key_create_order']),
        'NHE_DETAIL_VALUE_COMPLETE_ORIGINAL_NORMAL_STATUS_LOG_SET');
    if ($shipped) nhep_expect($logs['delivery_goods'] >= $logs['pay_success']
        && $logs['delivery_goods'] >= $order['pay_time'],
        'NHE_DETAIL_VALUE_SHIPPED_INDEPENDENT_HISTORICAL_DELIVERY_FOLLOWS_PAYMENT');
    if ($received) nhep_expect($logs['cache_key_create_order'] <= $logs['pay_success']
        && $logs['pay_success'] <= $logs['delivery_goods'] && $logs['delivery_goods'] <= $logs['take_delivery']
        && $logs['delivery_goods'] >= $order['pay_time'],
        'NHE_DETAIL_VALUE_RECEIVED_INDEPENDENT_COMPLETE_HISTORICAL_LOG_ORDER');

    if ($completed) {
        $replyCount = 0; $completedReply = null;
        foreach ($beforeDB2['rows']['eb_store_product_reply'] as $index => $unused) {
            $reply = nhepcv_native_row($beforeDB2, 'eb_store_product_reply', $index);
            nhep_expect(is_string($reply['unique']) && preg_match('/\A[A-Za-z0-9]*\z/D', $reply['unique']) === 1,
                'NHE_DETAIL_VALUE_COMPLETED_CANONICAL_FULL_GLOBAL_REPLY_COUNT');
            if (strtolower($reply['unique']) === $item['unique']) { $replyCount++; $completedReply = $reply; }
        }
        nhep_expect($replyCount === 1 && is_array($completedReply)
            && $completedReply['unique'] === $item['unique'] && $completedReply['oid'] === $order['id']
            && $completedReply['uid'] === $user['uid'] && $completedReply['product_id'] === $fixture['product_id']
            && $logs['cache_key_create_order'] <= $logs['pay_success']
            && $logs['pay_success'] <= $logs['delivery_goods'] && $logs['delivery_goods'] <= $logs['take_delivery']
            && $logs['delivery_goods'] >= $order['pay_time']
            && $logs['take_delivery'] <= $completedReply['add_time']
            && $completedReply['add_time'] <= $logs['check_order_over'],
            'NHE_DETAIL_VALUE_COMPLETED_GLOBAL_COUNT_ONE_AND_FIVE_INDEPENDENT_BEFORE_LOG_TIMES');
    } else {
    // count(unique) is global, not restricted to this OID; canonical keys avoid SQL collation guesses.
    foreach ($beforeDB2['rows']['eb_store_product_reply'] as $index => $unused) {
        $reply = nhepcv_native_row($beforeDB2, 'eb_store_product_reply', $index);
        nhep_expect(is_string($reply['unique']) && preg_match('/\A[A-Za-z0-9]*\z/D', $reply['unique']) === 1
            && strtolower($reply['unique']) !== $item['unique'],
            'NHE_DETAIL_VALUE_ORIGINAL_GLOBAL_ITEM_REPLY_COUNT_ZERO');
    }
    }

    // get(order_id, postage_price/member_price) admits the original no-row or single-row branch only.
    $economize = [];
    foreach ($beforeDB2['rows']['eb_store_order_economize'] as $index => $unused) {
        $saved = nhepcv_native_row($beforeDB2, 'eb_store_order_economize', $index);
        nhep_expect(is_string($saved['order_id']) && preg_match('/\A[A-Za-z0-9]*\z/D', $saved['order_id']) === 1,
            'NHE_DETAIL_VALUE_ORIGINAL_ECONOMIZE_CANONICAL_ORDER_NUMBER');
        if (strtolower($saved['order_id']) === $order['order_id']) {
            nhep_expect($saved['order_id'] === $order['order_id'], 'NHE_DETAIL_VALUE_ECONOMIZE_CASE_COLLISION_NOT_IMPLEMENTED');
            $economize[] = $saved;
        }
    }
    nhep_expect(count($economize) <= 1, 'NHE_DETAIL_VALUE_ORIGINAL_ECONOMIZE_QUERY_UNAMBIGUOUS');
    if ($economize !== []) nhep_expect(array_key_exists('postage_price', $economize[0])
        && array_key_exists('member_price', $economize[0]), 'NHE_DETAIL_VALUE_BOTH_ORIGINAL_NATIVE_ECONOMIZE_FIELDS');

    // ORM SELECT * order, native values and both getters; binding happens before relation toArray merge.
    $baseKeys = array_keys($order);
    $custom = json_decode($order['custom_form'], true);
    $cartIds = json_decode($order['cart_id'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $custom === []
        && $cartIds === [(int)$item['cart_id']], 'NHE_DETAIL_VALUE_ORIGINAL_CUSTOM_FORM_AND_CART_ID_GETTERS');
    $order['custom_form'] = $custom; $order['cart_id'] = $cartIds;
    foreach (['nickname', 'phone', 'avatar'] as $name) {
        nhep_expect(!array_key_exists($name, $order) && is_string($user[$name]),
            'NHE_DETAIL_VALUE_ORIGINAL_USER_BIND_FIELDS_NO_COLLISION');
        $order[$name] = $user[$name];
    }
    nhep_expect(!array_key_exists('split', $order) && !array_key_exists('invoice', $order),
        'NHE_DETAIL_VALUE_ORIGINAL_RELATION_NAMES_NO_COLLISION');
    $order['split'] = []; $order['invoice'] = null; // nhepod_context proved both complete empty relations.
    $order['add_time_y'] = nhepodv_date('Y-m-d', $order['add_time']);
    $order['add_time_h'] = nhepodv_date('H:i:s', $order['add_time']);
    $order['system_store'] = false; $order['code'] = '';
    $order['mapKey'] = ''; $order['yue_pay_status'] = 1; $order['pay_weixin_open'] = false;
    $order['ali_pay_status'] = false; $order['friend_pay_status'] = 0;

    $cart = $context['cart'];
    nhep_expect($cart['price_type'] === 'level' && $cart['vip_truePrice'] === 0
        && $item['cart_num'] === 1 && $item['surplus_num'] === 1
        && $item['refund_num'] === ($refunded ? 1 : 0),
        'NHE_DETAIL_VALUE_ORIGINAL_LEVEL_PRICE_AND_NATIVE_ITEM_QUANTITIES');
    $cart['cart_num'] = $item['cart_num']; $cart['surplus_num'] = $item['surplus_num'];
    $cart['refund_num'] = $item['refund_num']; $cart['surplus_refund_num'] = $item['surplus_num'] - $item['refund_num'];
    $cart['unique'] = $item['unique']; $cart['is_reply'] = 0;
    if ($completed) $cart['is_reply'] = $replyCount;
    // image_thumb_status=0 leaves both historical product/SKU images and their complete field order unchanged.
    $cart['vip_sum_truePrice'] = bcmul((string)$cart['vip_truePrice'], (string)($cart['cart_num'] ?: 1), 2);
    $cart['is_valid'] = 1;
    $order['cartInfo'] = [$cart];
    $order['_status'] = $refunded
        ? ['_type' => -2, '_title' => '已退款', '_msg' => '已为您退款,感谢您的支持',
            '_class' => 'state-sqtk', '_payType' => '余额支付', '_deliveryType' => '其他方式']
        : ($received
        ? ['_type' => 3, '_title' => '待评价', '_msg' => '已收货,快去评价一下吧',
            '_class' => 'state-ypj', '_payType' => '余额支付', '_deliveryType' => '快递配送']
        : ($shipped
        ? ['_type' => 2, '_title' => '待收货',
            '_msg' => nhepodv_date('m月d日H时i分', $logs['delivery_goods']) . '服务商已发货',
            '_class' => 'state-ysh', '_payType' => '余额支付', '_deliveryType' => '快递配送']
        : ($paid === 0
        ? ['_type' => 0, '_title' => '未支付',
            '_msg' => '请在' . nhepodv_date('m-d H:i:s', $order['add_time']) . '前完成支付!',
            '_class' => 'nobuy', '_payType' => '', '_deliveryType' => '其他方式']
        : ['_type' => 1, '_title' => '未发货', '_msg' => '商家未发货,请耐心等待',
            '_class' => 'state-nfh', '_payType' => '余额支付', '_deliveryType' => '其他方式'])));
    if ($completed) $order['_status'] = ['_type' => 4, '_title' => '交易完成',
        '_msg' => '交易完成,感谢您的支持', '_class' => 'state-ytk',
        '_payType' => '余额支付', '_deliveryType' => '快递配送'];
    $order['_pay_time'] = $paid === 1 ? nhepodv_date('Y-m-d H:i:s', $order['pay_time']) : '';
    $order['_add_time'] = nhepodv_date('Y-m-d H:i:s', $order['add_time']);
    // Original Arr converts the five string values to float before local arithmetic.
    $order['stop_time'] = (float)$cancel['order_cancel_time'] * 3600 + $order['add_time'];
    $order['status_pic'] = ''; // original data_order_details_images derives [] from both BEFORE tables.
    $order['offlinePayStatus'] = 2;
    $order['order_log'] = ['create' => nhepodv_date('Y-m-d', $logs['cache_key_create_order']),
        'pay' => $paid === 1 ? nhepodv_date('Y-m-d', $logs['pay_success']) : '',
        'delivery' => ($shipped || $received) ? nhepodv_date('Y-m-d', $logs['delivery_goods']) : '',
        'take' => $received ? nhepodv_date('Y-m-d', $logs['take_delivery']) : '', 'complete' => ''];
    if ($completed) {
        $order['order_log']['delivery'] = nhepodv_date('Y-m-d', $logs['delivery_goods']);
        $order['order_log']['take'] = nhepodv_date('Y-m-d', $logs['take_delivery']);
        $order['order_log']['complete'] = nhepodv_date('Y-m-d', $logs['check_order_over']);
    }
    $order['gift_user_info'] = ['gift_uid' => $order['gift_uid'], 'gift_nickname' => '', 'gift_avatar' => ''];
    $order['vip_true_price'] = bcadd('0', $cart['vip_sum_truePrice'], 2);
    $order['levelPrice'] = bcadd('0', $cart['vip_sum_truePrice'], 2);
    $order['memberPrice'] = 0;
    $order['postage_price'] = $economize === [] ? 0 : $economize[0]['postage_price'];
    $order['member_price'] = $economize === [] ? 0 : $economize[0]['member_price'];
    $order['routine_contact_type'] = 0; $order['invoice_func'] = false; $order['special_invoice'] = false;
    $order['refund_cartInfo'] = $order['cartInfo']; $order['refund_total_num'] = $order['total_num'];
    $order['refund_pay_price'] = $order['pay_price']; $order['is_apply_refund'] = true;
    $order['help_info'] = ['pay_uid' => $order['pay_uid'], 'pay_nickname' => '', 'pay_avatar' => '', 'help_status' => 0];
    $order['gift_user_info'] = ['gift_uid' => $order['gift_uid'], 'gift_nickname' => '', 'gift_avatar' => ''];
    $order['order_shipping_open'] = false;
    $order['is_refund_available'] = true; // missing refund_time_available becomes int0; no clock branch.
    $order['gift_key'] = $order['gift_code'] = ''; // right-associative: gift_code is inserted first.
    if ($order['avatar'] && substr($order['avatar'], 0, 4) !== 'http' && substr($order['avatar'], 0, 2) !== '//')
        $order['avatar'] = $siteUrl . str_replace('\\', '/', $order['avatar']);

    $added = ['add_time_y', 'add_time_h', 'system_store', 'code', 'mapKey', 'yue_pay_status',
        'pay_weixin_open', 'ali_pay_status', 'friend_pay_status', 'cartInfo', '_status', '_pay_time',
        '_add_time', 'stop_time', 'status_pic', 'offlinePayStatus', 'order_log', 'gift_user_info',
        'vip_true_price', 'levelPrice', 'memberPrice', 'postage_price', 'member_price', 'routine_contact_type',
        'invoice_func', 'special_invoice', 'refund_cartInfo', 'refund_total_num', 'refund_pay_price',
        'is_apply_refund', 'help_info', 'order_shipping_open', 'is_refund_available', 'gift_code', 'gift_key'];
    nhep_expect(count(array_unique(array_merge($baseKeys,
        ['nickname', 'phone', 'avatar', 'split', 'invoice'], $added), SORT_STRING)) === count($baseKeys) + 40
        && array_keys($order) === array_merge($baseKeys, ['nickname', 'phone', 'avatar', 'split', 'invoice'], $added),
        'NHE_DETAIL_VALUE_ALL_ORIGINAL_COLUMNS_BIND_RELATIONS_AND_ADDED_KEY_ORDER');
    // The real response uses JSON_UNESCAPED_UNICODE without PRESERVE_ZERO_FRACTION.
    // Normalize only this independently built DTO, never a cache wire or the stored cart JSON.
    $json = json_encode($order, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    $view = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
    nhep_expect(is_array($view) && array_keys($view) === array_keys($order),
        'NHE_DETAIL_VALUE_COMPLETE_INDEPENDENT_JSON_DATA_VIEW');
    return $view;
}

/** Definitions only. Four original detail GETs; private source values never leave the caller's RAM. */
function nhep_order_detail_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepod_context',
        'nhep_order_detail_value_expected', 'nhepcv_native_row', 'm4lh_actor_expected_row',
        'nhepcr_config_wire', 'nhepar_capture', 'nhepar_entry', 'nhepar_bind',
        'nhepar_actor', 'nhepar_customer', 'nhepar_remember', 'nhepar_tag', 'nhep_redis_expected',
        'bcadd', 'bcsub', 'bcmul', 'bccomp', 'json_decode', 'serialize', 'hash_equals'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPODR_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPODR_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPODR_ORIGINAL_PRIVATE_GET_REQUEST');
    $steps = ['refund_family_unpaid_read' => [12, 'refund_family', 0],
        'refund_family_paid_read' => [14, 'refund_family', 1],
        'review_family_unpaid_read' => [18, 'review_family', 0],
        'review_family_paid_read' => [20, 'review_family', 1],
        'owned_refunded_root_read' => [26, 'refund_family', 1],
        'owned_shipped_read' => [29, 'review_family', 1],
        'owned_received_read' => [31, 'review_family', 1],
        'owned_commented_completed_read' => [37, 'review_family', 1]];
    nhep_expect(PHP_INT_SIZE === 8 && is_string($intent['step']) && isset($steps[$intent['step']]),
        'NHEPODR_ONLY_ORIGINAL_FOUR_NORMAL_DETAIL_STEPS');
    [$sequence, $family, $paid] = $steps[$intent['step']];
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === 'GET'
        && $intent['actor'] === 'customer' && $intent['origin'] === 'http://127.0.0.1:8000'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['path'])
        && preg_match('~\A/api/order/detail/(cp([1-9][0-9]{0,18}))\z~D', $intent['path'], $path) === 1
        && bccomp($path[2], '9223372036854775807', 0) <= 0
        && $privateRequest['body'] === null && is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['actor_identity']), 'NHEPODR_REAL_CP_GET_NULL_BODY_ORIGINAL_RUN');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPODR_ORIGINAL_PRIVATE_ACTOR_IDENTITY');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 2147483647
        && $privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account'])
        && preg_match('/\A[a-z0-9_]{10,32}\z/D', $privateRequest['actor_identity']['account']) === 1,
        'NHEPODR_REAL_NATIVE_CUSTOMER_AND_CANONICAL_ACCOUNT');

    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHEPODR_ORIGINAL_COMPLETE_PRIVATE_HTTP_RESPONSE');
    $interval = $privateResponse['actual_interval'];
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $privateResponse['http'] === 200 && $privateResponse['transport_errno'] === 0
        && $privateResponse['transport_failure_class'] === null && $privateResponse['primary_ip'] === '127.0.0.1'
        && $privateResponse['primary_port'] === 8000 && $privateResponse['local_ip'] === '127.0.0.1'
        && is_int($privateResponse['local_port']) && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw']) && $privateResponse['raw'] !== '' && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json']) && !array_is_list($privateResponse['json'])
        && is_array($privateResponse['headers']), 'NHEPODR_REAL_COMPLETE_NORMAL_LOCAL_HTTP_AND_NATIVE_SECONDS');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHEPODR_ORIGINAL_COMPLETE_PRIVATE_HEADER_CAPTURE');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] >= 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false, 'NHEPODR_NATIVE_HEADERS_NOT_TRUNCATED');
    $json = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $json === $privateResponse['json'],
        'NHEPODR_FULL_RAW_AND_PARSED_JSON_STRICT_JOIN');
    nhe_keys($json, ['status', 'msg', 'data'], 'NHEPODR_ORIGINAL_SUCCESS_ENVELOPE');
    nhep_expect($json['status'] === 200 && $json['msg'] === 'success'
        && is_array($json['data']) && !array_is_list($json['data']), 'NHEPODR_ORIGINAL_SUCCESS_DATA_OBJECT');

    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPODR_BOTH_FULL_NATIVE_CAPTURES_SAME_ORIGINAL_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $actualUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($actualUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPODR_REAL_HTTP_WINDOW_INSIDE_MONOTONIC_NATIVE_REDIS_TIME');

    // Select the root and saved item from complete BEFORE, including the actual DAO's two ORs.
    $context = nhepod_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'paid', 'fixture', 'order', 'item', 'cart'], 'NHEPODR_SHARED_BEFORE_CONTEXT_EXACT_SIX_KEYS');
    nhep_expect($context['family'] === $family && $context['paid'] === $paid
        && is_array($context['fixture']) && is_array($context['order'])
        && is_array($context['item']) && is_array($context['cart']), 'NHEPODR_SAME_BEFORE_FAMILY_AND_PAID_STATE');
    nhe_keys($context['order'], ['index', 'row', 'metadata'], 'NHEPODR_COMPLETE_BEFORE_ORDER_SELECTION');
    nhe_keys($context['item'], ['index', 'row', 'metadata'], 'NHEPODR_COMPLETE_BEFORE_ITEM_SELECTION');
    $order = $context['order']['row']; $item = $context['item']['row']; $fixture = $context['fixture'];
    nhep_expect(is_array($order) && is_array($item)
        && ($fixture['uid'] ?? null) === $intent['actor_id'] && ($order['uid'] ?? null) === $intent['actor_id']
        && ($order['order_id'] ?? null) === $path[1] && ($order['mark'] ?? null) === $intent['run_id'] . '-' . $family
        && ($order['paid'] ?? null) === $paid && ($item['oid'] ?? null) === ($order['id'] ?? null)
        && is_int($order['add_time']) && $order['add_time'] > 0 && $order['add_time'] <= $interval[0]
        && is_int($order['pay_time']) && $order['pay_time'] <= $interval[0],
        'NHEPODR_BEFORE_REAL_CP_ROOT_ITEM_OWNER_AND_TIMES_BOUND_TO_THIS_GET');
    if ($intent['step'] === 'owned_shipped_read') {
        // This is the prior delivery's saved time, never this GET's time or an AFTER-selected row.
        $delivery = null; $statusMetadata = $beforeDB2['database']['tables']['eb_store_order_status']['metadata'];
        foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
            $savedLog = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
            if ($savedLog['oid'] !== $order['id'] || $savedLog['change_type'] !== 'delivery_goods') continue;
            nhep_expect($delivery === null, 'NHEPODR_SHIPPED_ONE_INDEPENDENT_BEFORE_DELIVERY_LOG');
            $delivery = $savedLog;
        }
        nhep_expect(is_array($delivery) && is_int($delivery['change_time']) && $delivery['change_time'] > 0
            && $delivery['change_time'] <= 2147483647 && $delivery['change_time'] <= $interval[0]
            && $delivery === m4lh_actor_expected_row($statusMetadata, ['oid' => $order['id'],
                'change_type' => 'delivery_goods',
                'change_message' => '已发货 快递公司：顺丰速运 快递单号：NHE' . $intent['run_id'],
                'change_time' => $delivery['change_time']]),
            'NHEPODR_SHIPPED_COMPLETE_BEFORE_DELIVERY_TIME_PRECEDES_REAL_GET');
    }
    if ($intent['step'] === 'owned_received_read') {
        // Receipt belongs to completed history before this GET, not to its clock or an AFTER-selected row.
        $take = null; $statusMetadata = $beforeDB2['database']['tables']['eb_store_order_status']['metadata'];
        foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
            $savedLog = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
            if ($savedLog['oid'] !== $order['id'] || $savedLog['change_type'] !== 'take_delivery') continue;
            nhep_expect($take === null, 'NHEPODR_RECEIVED_ONE_INDEPENDENT_BEFORE_TAKE_LOG');
            $take = $savedLog;
        }
        nhep_expect(is_array($take) && is_int($take['change_time']) && $take['change_time'] > 0
            && $take['change_time'] <= 2147483647 && $take['change_time'] <= $interval[0]
            && $take === m4lh_actor_expected_row($statusMetadata, ['oid' => $order['id'],
                'change_type' => 'take_delivery', 'change_message' => '已收货', 'change_time' => $take['change_time']]),
            'NHEPODR_RECEIVED_COMPLETE_BEFORE_TAKE_TIME_PRECEDES_REAL_GET');
    }
    if ($intent['step'] === 'owned_commented_completed_read') {
        // All five saved times and the distinct signed merchant reply time precede this GET.
        foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
            $savedLog = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
            if ($savedLog['oid'] === $order['id'])
                nhep_expect(is_int($savedLog['change_time']) && $savedLog['change_time'] > 0
                    && $savedLog['change_time'] <= 2147483647 && $savedLog['change_time'] <= $interval[0],
                    'NHEPODR37_ALL_FIVE_INDEPENDENT_BEFORE_LOG_TIMES_PRECEDE_THIS_GET');
        }
        $completedReply = null;
        foreach ($beforeDB2['rows']['eb_store_product_reply'] as $index => $unused) {
            $savedReply = nhepcv_native_row($beforeDB2, 'eb_store_product_reply', $index);
            if ($savedReply['unique'] !== $item['unique']) continue;
            nhep_expect($completedReply === null, 'NHEPODR37_ONE_ALREADY_PROVED_COMPLETE_BEFORE_REPLY');
            $completedReply = $savedReply;
        }
        nhep_expect(is_array($completedReply) && $completedReply['oid'] === $order['id']
            && $completedReply['uid'] === $intent['actor_id'] && $completedReply['product_id'] === $fixture['product_id']
            && is_int($completedReply['merchant_reply_time']) && $completedReply['merchant_reply_time'] > 0
            && $completedReply['merchant_reply_time'] <= 2147483647
            && $completedReply['merchant_reply_time'] <= $interval[0] && $completedReply['add_time'] <= $interval[0],
            'NHEPODR37_DISTINCT_NATIVE_SIGNED_BEFORE_MERCHANT_REPLY_TIME_PRECEDES_THIS_GET');
    }
    // The value builder takes BEFORE only. Actual data is compared in full and never fills a missing field.
    $expectedData = nhep_order_detail_value_expected($beforeDB2, $intent, $privateRequest);
    nhep_expect(!array_is_list($expectedData) && $json['data'] === $expectedData,
        'NHEPODR_COMPLETE_RESPONSE_DATA_STRICTLY_EQUALS_INDEPENDENT_BEFORE_DTO');

    $rows = $beforeDB2['rows'];
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($rows[$table] === [], 'NHEPODR_COMPLETE_BEFORE_LANGUAGE_TABLES_EMPTY');
    // A missing group ID alone is insufficient: its cast-to-zero DAO query must also have no data rows.
    nhep_expect($rows['eb_system_group'] === [] && $rows['eb_system_group_data'] === [],
        'NHEPODR_COMPLETE_BEFORE_GROUP_AND_GROUP_DATA_EMPTY_INDEPENDENT_IMAGE_SOURCE');
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']), 'NHEPODR_SAME_RUN_ORIGINAL_PRIVATE_AUTH_CONFIGURATION');
    $actor = nhepar_actor($rows, $intent, $privateRequest);
    nhep_expect($actor === $fixture['user']['row'], 'NHEPODR_AUTHENTICATED_ACTOR_IS_THE_SAME_COMPLETE_BEFORE_USER');
    $changes = []; $tagMembers = [];
    $apiTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('api'));
    nhep_expect(is_array($apiTag) && $apiTag['type'] === 'set' && $apiTag['expires'] === -1
        && in_array('c:' . md5($privateRequest['token']), $apiTag['value'], true),
        'NHEPODR_ORIGINAL_EXISTING_CUSTOMER_WHITELIST_API_TAG_MEMBERSHIP');
    nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);

    // Actual detail-path consumers only. An absent BEFORE row has null cache wire, not the getter's default.
    $settings = ['station_open' => 1, 'store_self_mention' => 0, 'tengxun_map_key' => null,
        'balance_func_status' => 1, 'yue_pay_status' => 1, 'pay_weixin_open' => 0, 'ali_pay_status' => 0,
        'friend_pay_status' => null, 'image_thumb_status' => 0, 'offline_pay_status' => 2,
        'routine_contact_type' => null, 'invoice_func_status' => 0, 'special_invoice_status' => 0,
        'order_shipping_open' => 0, 'refund_time_available' => null, 'site_url' => $intent['origin']];
    foreach ($settings as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    $cancel = ['order_cancel_time' => '0', 'order_activity_time' => '0', 'order_bargain_time' => '0',
        'order_seckill_time' => '0', 'order_pink_time' => '0'];
    foreach ($cancel as $name => $value)
        nhep_expect(nhepcr_config_wire($beforeDB2, $name, $value) === '0', 'NHEPODR_BEFORE_FIVE_ORIGINAL_CANCEL_JSON_STRINGS');
    // more() serializes the ordered string map before the caller's local Arr::setValeTime casts.
    nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . md5(implode(',', array_keys($cancel))),
        serialize($cancel), 0, $changes, $tagMembers);
    nhepar_remember($beforeCapture, $actualCapture, 'data_order_details_images', serialize([]), 0, $changes, $tagMembers);
    if ($intent['step'] === 'owned_commented_completed_read') {
    // Empty language tables independently determine all three values. Only these keys may expire/rebuild here.
    $interval = $privateResponse['actual_interval']; $ttlMs = '3600000';
    $getterLower = bcmul((string)$interval[0], '1000', 0);
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire) {
        $key = 'c:' . $name; $old = nhepar_entry($beforeCapture, $key);
        if ($old === null || bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) > 0) {
            nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
            if ($old === null) {
                $new = nhepar_entry($actualCapture, $key);
                $writeMs = bcsub((string)$new['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPODR37_REDIS_LANGUAGE_COLD_WRITE_CLOCK_INSIDE_ACTUAL_HTTP_SECONDS_AND_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
        } elseif (bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) === 0
            && nhepar_entry($actualCapture, $key) !== null) {
            // Existing full-namespace algorithm expires only when A > E; E == A is not a rebuild.
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                'NHEPODR37_REDIS_LANGUAGE_EQUAL_ACTUAL_DEADLINE_COMPATIBLE_WITH_SERIAL_WARM_GETTER');
            $descriptor = nhepar_bind($actualCapture, $key, 'string', $wire, $old['expires'], $beforeCapture['snapshot']);
            nhep_expect($descriptor === $beforeCapture['snapshot']['keys'][hash('sha256', $key)],
                'NHEPODR37_REDIS_EQUAL_DEADLINE_COMPLETE_ORIGINAL_WARM_DESCRIPTOR_NOT_RENEWED');
            $tagMembers[] = $key;
        } else {
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $beforeCapture['snapshot']['time_ms'], 0) >= 0,
                'NHEPODR37_REDIS_COMPLETE_BEFORE_LANGUAGE_VALUE_AND_NATURAL_DEADLINE');
            $now = nhepar_entry($actualCapture, $key);
            if ($now === null) {
                nhep_expect(bccomp((string)$old['expires'], bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                    'NHEPODR37_REDIS_UNREBUILT_LANGUAGE_CAN_ONLY_EXPIRE_AFTER_A_SERIAL_POSSIBLE_REAL_GETTER');
            } else {
                $changes[$key] = nhepar_bind($actualCapture, $key, 'string', $wire, ['ttl' => 3600], $beforeCapture['snapshot']);
                $writeMs = bcsub((string)$now['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, (string)$old['expires'], 0) > 0
                    && bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPODR37_REDIS_NATURAL_REBUILD_STRICTLY_AFTER_OLD_EXPIRY_AND_INSIDE_HTTP_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
            $tagMembers[] = $key;
        }
    }
    } else {
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire)
        nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
    }
    // Warm and cold reads append tags. Null may be recomputed, but its final wire and permanent deadline stay exact.
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    // No getMore/postMore or Blocker in this GET: no parameter remembers, create locks, counter or create detail/title touch.
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'], 'NHEPODR_COMPLETE_NAMESPACE_FROM_BEFORE_AND_INDEPENDENT_CHANGES');
    return $expected;
}


// Original pay13/19 independent pure database and Redis definitions.
/** Definitions only. Original 477 balance-payment POSTs; every selected row/value stays private RAM. */
function nhepop_context(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_fixture', 'nhepcd_one',
        'nhepcd_id', 'nhepcv_native_row', 'nhepcv_config', 'm4lh_actor_native',
        'm4lh_actor_expected_row', 'bccomp', 'json_decode', 'json_encode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_ORDER_PAY_CONTEXT_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHE_ORDER_PAY_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHE_ORDER_PAY_ORIGINAL_PRIVATE_POST_REQUEST');
    nhep_expect(is_array($privateRequest['actor_identity']), 'NHE_ORDER_PAY_PRIVATE_NATIVE_ACTOR_REQUIRED');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHE_ORDER_PAY_ORIGINAL_ACTOR_IDENTITY');
    $steps = ['refund_family_pay' => [13, 'refund_family'], 'review_family_pay' => [19, 'review_family']];
    nhep_expect(is_string($intent['step']) && isset($steps[$intent['step']]), 'NHE_ORDER_PAY_STEP_NOT_IMPLEMENTED');
    [$sequence, $family] = $steps[$intent['step']];
    nhep_expect(is_array($privateRequest['body']), 'NHE_ORDER_PAY_ORIGINAL_POST_BODY_REQUIRED');
    $body = $privateRequest['body'];
    nhe_keys($body, ['uni', 'paytype', 'quitUrl', 'type'], 'NHE_ORDER_PAY_EXACT_ORIGINAL_FOUR_FIELD_BODY');
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === 'POST' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && $intent['path'] === '/api/order/pay' && is_string($body['uni'])
        && preg_match('~\A(cp([1-9][0-9]{0,18}))\z~D', $body['uni'], $path) === 1
        && bccomp($path[2], '9223372036854775807', 0) <= 0
        && $body === ['uni' => $path[1], 'paytype' => 'yue', 'quitUrl' => '', 'type' => 0]
        && is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1,
        'NHE_ORDER_PAY_FIXED_REAL_POST_SEQUENCE_ORIGIN_CP_AND_FOUR_FIELD_BODY');
    // The original fixture selector receives this real POST; no detail GET/step/body is fabricated.
    $fixture = nhepcd_fixture($beforeDB2, $intent, $privateRequest);
    $uid = $fixture['uid']; $number = $path[1];
    $order = nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-' . $family]);
    $row = nhepcv_native_row($beforeDB2, 'eb_store_order', $order['index']);
    $oid = nhepcd_id($row['id'], 2147483647);
    nhep_expect($row['order_id'] === $number && $row['uid'] === $uid && $row['pay_uid'] === $uid
        && $row['paid'] === 0 && $row['pay_type'] === 'yue' && $row['channel_type'] === 'h5'
        && is_string($row['unique']) && preg_match('/\A[1-9][0-9]{0,18}\z/D', $row['unique']) === 1
        && bccomp($row['unique'], '9223372036854775807', 0) <= 0,
        'NHE_ORDER_PAY_BEFORE_SAME_FAMILY_NATIVE_ROOT_OWNER_PAY_OWNER_AND_KEYS');
    foreach (['pid' => 0, 'mer_id' => 0, 'status' => 0, 'refund_status' => 0, 'refund_type' => 0,
        'is_del' => 0, 'is_system_del' => 0, 'is_cancel' => 0, 'is_stock_up' => 0,
        'shipping_type' => 1, 'total_num' => 1, 'store_id' => 0, 'delivery_uid' => 0, 'clerk_id' => 0,
        'is_channel' => 0, 'virtual_type' => 0, 'is_gift' => 0, 'gift_uid' => 0,
        'combination_id' => 0, 'pink_id' => 0, 'seckill_id' => 0, 'bargain_id' => 0, 'advance_id' => 0,
        'coupon_id' => 0, 'verify_code' => '', 'delivery_type' => '', 'delivery_id' => '',
        'delivery_name' => '', 'delivery_code' => '', 'gift_mark' => '', 'custom_form' => '[]',
        'total_price' => '20.15', 'pay_price' => '20.15', 'cost' => '7.45',
        'freight_price' => '0.00', 'total_postage' => '0.00', 'pay_postage' => '0.00',
        'deduction_price' => '0.00', 'coupon_price' => '0.00', 'gift_price' => '0.00',
        'refund_price' => '0.00', 'use_integral' => '0.00', 'gain_integral' => '0.00', 'back_integral' => '0.00'] as $column => $value)
        nhep_expect(array_key_exists($column, $row) && $row[$column] === $value,
            'NHE_ORDER_PAY_ONLY_ORIGINAL_NORMAL_UNSHIPPED_UNREFUNDED_ROOT');
    nhep_expect(is_int($row['add_time']) && $row['add_time'] > 0 && $row['pay_time'] === 0,
        'NHE_ORDER_PAY_ORIGINAL_BEFORE_CREATE_AND_PAY_TIMES');

    // Original pay uses bare order_id globally, without detail's uid/gift_uid or unique ORs.
    $matches = []; $uniqueMatches = []; $orderColumns = $order['metadata']['columns'];
    foreach ($beforeDB2['rows']['eb_store_order'] as $index => $candidate) {
        foreach (['order_id', 'unique', 'pid'] as $column)
            nhep_expect(m4lh_actor_native($orderColumns[$column], $candidate[$column]) === $candidate[$column],
                'NHE_ORDER_PAY_ORIGINAL_NATIVE_BARE_LOOKUP_FIELDS');
        foreach (['order_id', 'unique'] as $column)
            nhep_expect(is_string($candidate[$column]) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate[$column]) === 1,
                'NHE_ORDER_PAY_NONCANONICAL_LOOKUP_COLLATION_BRANCH_NOT_IMPLEMENTED');
        if (strtolower($candidate['order_id']) === $number) $matches[] = $index;
        if (strtolower($candidate['unique']) === $row['unique']) $uniqueMatches[] = $index;
        nhep_expect($candidate['pid'] !== $oid, 'NHE_ORDER_PAY_SPLIT_RELATION_BRANCH_NOT_IMPLEMENTED');
    }
    nhep_expect($matches === [$order['index']] && $uniqueMatches === [$order['index']]
        && nhepcd_one($beforeDB2, 'eb_store_order', ['id' => $oid]) === $order,
        'NHE_ORDER_PAY_GLOBAL_BARE_ORDER_ID_UNIQUE_AND_SAME_INDEPENDENT_ROOT');
    foreach (['store_self_mention', 'image_thumb_status', 'order_shipping_open',
        'invoice_func_status', 'special_invoice_status'] as $name)
        nhepcv_config($beforeDB2, $intent, $name, 0);
    // No invoice relation, gift/verify QR, delivery-person or MiniOrder side effect is admitted.
    foreach ($beforeDB2['rows']['eb_store_order_invoice'] as $invoice)
        nhep_expect(m4lh_actor_native($beforeDB2['database']['tables']['eb_store_order_invoice']['metadata']['columns']['order_id'],
            $invoice['order_id']) !== $oid, 'NHE_ORDER_PAY_INVOICE_RELATION_BRANCH_NOT_IMPLEMENTED');

    $item = nhepcd_one($beforeDB2, 'eb_store_order_cart_info', ['oid' => $oid]);
    $saved = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $item['index']);
    $itemId = nhepcd_id($saved['id'], 2147483647); $cartId = nhepcd_id($saved['cart_id']);
    nhep_expect($saved === m4lh_actor_expected_row($item['metadata'], ['id' => $itemId, 'oid' => $oid,
        'uid' => $uid, 'cart_id' => (string)$cartId, 'product_id' => $fixture['product_id'],
        'cart_num' => 1, 'surplus_num' => 1, 'cart_info' => $saved['cart_info'], 'unique' => md5($cartId . '' . $oid)])
        && is_string($saved['cart_info']) && $saved['cart_info'] !== ''
        && $row['cart_id'] === json_encode([$cartId]), 'NHE_ORDER_PAY_ONE_ORIGINAL_FULL_UNSPLIT_SAVED_ITEM_AND_CART_ID');
    $itemUniqueMatches = [];
    foreach ($beforeDB2['rows']['eb_store_order_cart_info'] as $index => $candidate) {
        nhep_expect(is_string($candidate['unique']) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate['unique']) === 1,
            'NHE_ORDER_PAY_NONCANONICAL_ITEM_UNIQUE_COLLATION_NOT_IMPLEMENTED');
        if (strtolower($candidate['unique']) === $saved['unique']) $itemUniqueMatches[] = $index;
    }
    nhep_expect($itemUniqueMatches === [$item['index']], 'NHE_ORDER_PAY_GLOBAL_SAVED_ITEM_UNIQUE_IS_UNAMBIGUOUS');
    foreach ($beforeDB2['rows']['eb_store_cart'] as $candidate)
        nhep_expect(m4lh_actor_native($beforeDB2['database']['tables']['eb_store_cart']['metadata']['columns']['id'],
            $candidate['id']) !== $cartId, 'NHE_ORDER_PAY_ORIGINAL_PERSISTENT_CART_ALREADY_CONSUMED');

    $cart = json_decode($saved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && is_array($cart) && !array_is_list($cart)
        && json_encode($cart) === $saved['cart_info'], 'NHE_ORDER_PAY_ORIGINAL_COMPLETE_DEFAULT_JSON_SAVED_CART');
    $cartMetadata = $beforeDB2['database']['tables']['eb_store_cart']['metadata'];
    $cartColumns = array_keys($cartMetadata['columns']); $baseCart = [];
    nhep_expect(count($cartColumns) === 15, 'NHE_ORDER_PAY_ORIGINAL_FIFTEEN_NATIVE_CART_COLUMNS');
    foreach ($cartColumns as $column) {
        nhep_expect(array_key_exists($column, $cart), 'NHE_ORDER_PAY_COMPLETE_ORIGINAL_SAVED_CART_BASE');
        $baseCart[$column] = m4lh_actor_native($cartMetadata['columns'][$column], $cart[$column]);
        nhep_expect($baseCart[$column] === $cart[$column], 'NHE_ORDER_PAY_NATIVE_SAVED_CART_BASE_TYPE');
    }
    nhep_expect(is_int($baseCart['add_time']) && $baseCart['add_time'] > 0 && $baseCart['add_time'] <= $row['add_time']
        && $baseCart === m4lh_actor_expected_row($cartMetadata, ['id' => $cartId, 'uid' => $uid,
            'type' => '0', 'product_id' => $fixture['product_id'], 'product_attr_unique' => $fixture['sku_unique'],
            'cart_num' => 1, 'add_time' => $baseCart['add_time']]), 'NHE_ORDER_PAY_ORIGINAL_OWNED_CART_AND_SKU_BASE');
    nhep_expect(is_array($cart['productInfo'] ?? null) && is_array($cart['attrInfo'] ?? null)
        && is_array($cart['productInfo']['attrInfo'] ?? null)
        && $cart['attrInfo'] === $cart['productInfo']['attrInfo'], 'NHE_ORDER_PAY_BOTH_ORIGINAL_SAVED_SKU_RELATIONS');
    $productSelection = nhepcd_one($beforeDB2, 'eb_store_product', ['id' => $fixture['product_id']]);
    $skuSelection = nhepcd_one($beforeDB2, 'eb_store_product_attr_value', ['unique' => $fixture['sku_unique']]);
    $product = nhepcv_native_row($beforeDB2, 'eb_store_product', $productSelection['index']);
    $sku = nhepcv_native_row($beforeDB2, 'eb_store_product_attr_value', $skuSelection['index']);
    $historicalProduct = $cart['productInfo']; $historicalSku = $cart['productInfo']['attrInfo'];
    // Inventory is persisted history. Validate it natively and retain it; never replace it with today's stock/sales.
    foreach ([['eb_store_product', $historicalProduct], ['eb_store_product_attr_value', $historicalSku]] as [$table, $history]) {
        foreach (['stock', 'sales'] as $column) {
            nhep_expect(array_key_exists($column, $history)
                && m4lh_actor_native($beforeDB2['database']['tables'][$table]['metadata']['columns'][$column], $history[$column]) === $history[$column]
                && is_int($history[$column]) && $history[$column] >= ($column === 'stock' ? 1 : 0),
                'NHE_ORDER_PAY_ORIGINAL_NATIVE_HISTORICAL_INVENTORY');
        }
    }
    $sku['stock'] = $historicalSku['stock']; $sku['sales'] = $historicalSku['sales'];
    nhep_expect($sku === $historicalSku && $sku['id'] === $fixture['sku_id']
        && $sku['product_id'] === $fixture['product_id'] && $sku['unique'] === $fixture['sku_unique']
        && $sku['suk'] === '普通' && $sku['type'] === 0 && $sku['price'] === '20.15' && $sku['cost'] === '7.45',
        'NHE_ORDER_PAY_ORIGINAL_COMPLETE_SAVED_SKU_WITH_HISTORICAL_INVENTORY');
    $slides = json_decode($product['slider_image'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $slides === ['/statics/system_images/spread_level_1.png'],
        'NHE_ORDER_PAY_ORIGINAL_PRODUCT_SLIDER_GETTER');
    $product['stock'] = $historicalProduct['stock']; $product['sales'] = $historicalProduct['sales'];
    $product['slider_image'] = $slides; $product['express_delivery'] = true;
    $product['store_mention'] = false; $product['attrInfo'] = $sku;
    nhep_expect($product === $historicalProduct, 'NHE_ORDER_PAY_COMPLETE_ORIGINAL_SAVED_PRODUCT_WITH_HISTORICAL_INVENTORY');
    $expectedCart = $baseCart;
    $expectedCart['productInfo'] = $product; $expectedCart['attrInfo'] = $sku;
    $expectedCart['min_qty'] = 1; $expectedCart['attrStatus'] = true; $expectedCart['vip_truePrice'] = 0;
    $expectedCart['costPrice'] = '7.45'; $expectedCart['trueStock'] = $historicalSku['stock'];
    $expectedCart['truePrice'] = 20.15; $expectedCart['sum_price'] = '20.15';
    $expectedCart['price_type'] = 'level'; $expectedCart['is_valid'] = 1; $expectedCart['postage_price'] = 0;
    $expectedCart['use_integral'] = 0; $expectedCart['integral_price'] = 0; $expectedCart['coupon_price'] = 0;
    $expectedCart['sum_true_price'] = '20.15'; $expectedCart['one_brokerage'] = '0'; $expectedCart['two_brokerage'] = '0';
    $expectedCart['staff_brokerage'] = '0.00'; $expectedCart['agent_brokerage'] = '0.00'; $expectedCart['division_brokerage'] = '0.00';
    nhep_expect($expectedCart === $cart, 'NHE_ORDER_PAY_COMPLETE_ORIGINAL_SAVED_CART_AND_FIXED_NORMAL_PRICE_FIELDS');
    $user = nhepcv_native_row($beforeDB2, 'eb_user', $fixture['user']['index']);
    nhep_expect($user === $fixture['user']['row'] && is_string($user['now_money'])
        && preg_match('/\A(?:0|[1-9][0-9]{0,9})\.[0-9]{2}\z/D', $user['now_money']) === 1
        && bccomp($user['now_money'], '20.15', 2) >= 0 && is_int($user['pay_count'])
        && $user['pay_count'] >= 0 && $user['pay_count'] <= 4294967294
        && m4lh_actor_native($fixture['user']['metadata']['columns']['pay_count'], $user['pay_count'] + 1) === $user['pay_count'] + 1,
        'NHE_ORDER_PAY_ORIGINAL_LOCKED_ACCOUNT_HAS_EXACT_SUFFICIENT_BALANCE_AND_SAFE_COUNT');
    return ['family' => $family, 'fixture' => $fixture, 'order' => $order, 'item' => $item, 'cart' => $cart];
}

/** Close only the admitted synchronous original branches; Redis and NEW_ORDER remain separate proofs. */
function nhepop_before_guards(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $context): void
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepcd_one', 'nhepcd_id', 'nhepcv_native_row',
        'nhepcv_config', 'nhep_funding_db_no_outpush', 'm4lh_actor_expected_row'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_ORDER_PAY_GUARD_PURE_DEPENDENCY_REQUIRED');
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'cart'], 'NHE_ORDER_PAY_GUARD_EXACT_FIVE_FIELD_CONTEXT');
    nhep_expect(in_array($context['family'], ['refund_family', 'review_family'], true)
        && $context['order'] === nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-' . $context['family']])
        && $context['item'] === nhepcd_one($beforeDB2, 'eb_store_order_cart_info', ['oid' => $context['order']['row']['id']])
        && $context['fixture']['user']['row']['is_money_level'] === 0,
        'NHE_ORDER_PAY_GUARD_SAME_COMPLETE_BEFORE_CONTEXT_AND_NONMEMBER');
    foreach (['queue_open', 'brokerage_func_status', 'member_func_status'] as $name)
        nhepcv_config($beforeDB2, $intent, $name, 0);
    foreach (['eb_store_product_coupon', 'eb_store_coupon_issue', 'eb_store_coupon_issue_user', 'eb_store_coupon_user',
        'eb_luck_lottery', 'eb_luck_lottery_record', 'eb_luck_prize', 'eb_store_service'] as $table)
        nhep_expect(isset($beforeDB2['rows'][$table]) && $beforeDB2['rows'][$table] === [],
            'NHE_ORDER_PAY_ORIGINAL_COUPON_LOTTERY_AND_CUSTOMER_SERVICE_TABLES_REALLY_EMPTY');
    foreach ($beforeDB2['rows']['eb_system_ticket'] as $index => $unused) {
        $ticket = nhepcv_native_row($beforeDB2, 'eb_system_ticket', $index);
        nhep_expect(!($ticket['is_del'] === 0 && $ticket['status'] === 1 && $ticket['print_type'] === 1),
            'NHE_ORDER_PAY_ACTIVE_PAYMENT_PRINTER_BRANCH_NOT_IMPLEMENTED');
    }
    foreach ($beforeDB2['rows']['eb_system_event'] as $index => $unused) {
        $event = nhepcv_native_row($beforeDB2, 'eb_system_event', $index);
        nhep_expect(!($event['is_del'] === 0 && $event['is_open'] === 1),
            'NHE_ORDER_PAY_ENABLED_CUSTOM_EVENT_BRANCH_NOT_IMPLEMENTED');
    }
    nhep_funding_db_no_outpush($beforeDB2);
    foreach ($beforeDB2['rows']['eb_system_notification'] as $index => $unused) {
        $notice = nhepcv_native_row($beforeDB2, 'eb_system_notification', $index);
        foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat', 'is_app'] as $column)
            nhep_expect($notice[$column] === 0, 'NHE_ORDER_PAY_ALL_ORIGINAL_NOTICE_AND_CUSTOM_NOTICE_CHANNELS_DISABLED');
        foreach (['order_pay_success', 'admin_pay_success_code'] as $mark)
            nhep_expect(is_string($notice['mark'])
                && (strtolower(rtrim($notice['mark'], ' ')) !== $mark || $notice['mark'] === $mark),
                'NHE_ORDER_PAY_NOTIFICATION_MARK_COLLATION_UNAMBIGUOUS');
    }
    foreach (['order_pay_success' => 1, 'admin_pay_success_code' => 2] as $mark => $type) {
        $notice = nhepcd_one($beforeDB2, 'eb_system_notification', ['mark' => $mark]);
        nhep_expect($notice['row']['type'] === $type, 'NHE_ORDER_PAY_UNIQUE_ORIGINAL_PAYMENT_NOTICE_TYPES');
    }
    // User labels come from today's product row, unlike ProductLog's saved cart/cache content.
    $product = nhepcd_one($beforeDB2, 'eb_store_product', ['id' => $context['fixture']['product_id']]);
    $current = nhepcv_native_row($beforeDB2, 'eb_store_product', $product['index']);
    nhep_expect(is_string($current['label_id']), 'NHE_ORDER_PAY_ORIGINAL_CURRENT_PRODUCT_LABEL_STRING');
    $labelId = nhepcd_id($current['label_id'], 2147483647);
    nhep_expect($current['label_id'] === (string)$labelId, 'NHE_ORDER_PAY_ONE_CANONICAL_CURRENT_SIGNED_LABEL_ID');
    $label = nhepcd_one($beforeDB2, 'eb_user_label', ['id' => $labelId]);
    $categoryId = nhepcd_id($label['row']['label_cate'], 2147483647);
    $category = nhepcd_one($beforeDB2, 'eb_category', ['id' => $categoryId]);
    nhep_expect($label['row'] === m4lh_actor_expected_row($label['metadata'], ['id' => $labelId,
        'label_cate' => $categoryId, 'label_name' => 'normal-purchase-label-' . $intent['run_id']])
        && $category['row'] === m4lh_actor_expected_row($category['metadata'], ['id' => $categoryId,
            'name' => 'normal-label-category-' . $intent['run_id'], 'type' => 0, 'owner_id' => 0, 'pid' => 0, 'sort' => 0])
        && nhepcd_one($beforeDB2, 'eb_user_label', ['label_name' => 'normal-purchase-label-' . $intent['run_id']]) === $label
        && nhepcd_one($beforeDB2, 'eb_category', ['name' => 'normal-label-category-' . $intent['run_id']]) === $category,
        'NHE_ORDER_PAY_CURRENT_LABEL_AND_CATEGORY_ARE_THE_ORIGINAL_SAME_RUN_FIXTURE');
}

/** First normal yue payment only. The only actual candidates admitted are five separately bounded native times. */
function nhep_order_pay_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepop_context', 'nhepop_before_guards', 'nhep_auth_db_snapshot',
        'nhep_auth_db_index', 'nhep_auth_db_time', 'nhep_funding_db_signed_time', 'nhep_auth_db_update',
        'nhep_auth_db_append', 'nhep_database_expected', 'nhepcd_one', 'nhepcd_id', 'nhepcv_native_row',
        'm4lh_actor_next', 'm4lh_actor_expected_row', 'bcsub', 'json_decode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_ORDER_PAY_DB_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    $context = nhepop_context($beforeDB2, $intent, $privateRequest);
    nhepop_before_guards($beforeDB2, $intent, $context);
    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'], 'NHE_ORDER_PAY_ORIGINAL_COMPLETE_HTTP_RESPONSE');
    $interval = $privateResponse['actual_interval'];
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $privateResponse['http'] === 200 && $privateResponse['transport_errno'] === 0
        && $privateResponse['transport_failure_class'] === null && $privateResponse['primary_ip'] === '127.0.0.1'
        && $privateResponse['primary_port'] === 8000 && $privateResponse['local_ip'] === '127.0.0.1'
        && is_int($privateResponse['local_port']) && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw']) && $privateResponse['raw'] !== '' && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json']) && !array_is_list($privateResponse['json'])
        && is_array($privateResponse['headers']), 'NHE_ORDER_PAY_ONE_COMPLETE_NATIVE_LOOPBACK_SUCCESS_AND_REAL_CLOCK_PAIR');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHE_ORDER_PAY_ORIGINAL_HEADER_CALLBACK_EXACT_FIVE_FIELDS');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] >= 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false, 'NHE_ORDER_PAY_ORIGINAL_COMPLETE_NONTRUNCATED_HEADERS');
    $decoded = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $privateResponse['json']
        && $decoded === ['status' => 200, 'msg' => '余额支付成功', 'data' => ['status' => 'SUCCESS', 'result' => []]],
        'NHE_ORDER_PAY_EXACT_ORIGINAL_CHINESE_SUCCESS_WITH_EMPTY_RESULT');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($beforeDB2['rows'][$table] === [], 'NHE_ORDER_PAY_ORIGINAL_CHINESE_LANGUAGE_LOOKUP_TABLES_EMPTY');
    $fixture = $context['fixture']; $user = $fixture['user']; $order = $context['order']; $cart = $context['cart'];
    $uid = $fixture['uid']; $oid = $order['row']['id'];
    nhep_expect($order['row']['add_time'] <= $interval[0], 'NHE_ORDER_PAY_BEFORE_ORDER_PRECEDES_REAL_PAYMENT_HTTP');
    $actualUser = nhep_auth_db_index($actualDB2['rows']['eb_user'], $user['metadata'], 'uid', $uid);
    $authTime = nhep_auth_db_time($user['metadata'], 'last_time',
        $actualDB2['rows']['eb_user'][$actualUser]['last_time'], $interval, $user['row']['last_time']);
    $actualOrder = nhep_auth_db_index($actualDB2['rows']['eb_store_order'], $order['metadata'], 'id', $oid);
    $payTime = nhep_auth_db_time($order['metadata'], 'pay_time', $actualDB2['rows']['eb_store_order'][$actualOrder]['pay_time'], $interval);
    $balance = bcsub($user['row']['now_money'], '20.15', 2);
    $expectedRows = ['eb_user' => nhep_auth_db_update($beforeDB2, 'eb_user', $user['index'],
        ['last_time' => $authTime, 'now_money' => $balance, 'pay_count' => $user['row']['pay_count'] + 1]),
        'eb_store_order' => nhep_auth_db_update($beforeDB2, 'eb_store_order', $order['index'],
            ['is_channel' => 2, 'paid' => 1, 'pay_type' => 'yue', 'pay_time' => $payTime])];
    $moneyTable = $beforeDB2['database']['tables']['eb_user_money'];
    nhep_expect(array_keys($moneyTable['metadata']['columns']) === ['id', 'uid', 'link_id', 'type', 'title',
        'number', 'balance', 'pm', 'mark', 'status', 'add_time'], 'NHE_ORDER_PAY_ORIGINAL_FULL_ELEVEN_COLUMN_BALANCE_LEDGER');
    $expectedRows['eb_user_money'] = nhep_auth_db_append($beforeDB2, $actualDB2, 'eb_user_money', [
        'uid' => $uid, 'link_id' => (string)$oid, 'type' => 'pay_product', 'title' => '余额支付购买商品',
        'number' => '20.15', 'balance' => $balance, 'pm' => 0, 'mark' => '余额支付20.15元购买商品', 'status' => 1], $interval);

    $statusTable = $beforeDB2['database']['tables']['eb_store_order_status'];
    $labelTable = $beforeDB2['database']['tables']['eb_user_label_relation'];
    foreach ([[$statusTable, ['oid', 'change_type', 'change_message', 'change_time']], [$labelTable, ['uid', 'label_id']]] as [$table, $columns]) {
        nhep_expect(array_keys($table['metadata']['columns']) === $columns
            && $table['metadata']['table']['AUTO_INCREMENT'] === null
            && !array_key_exists('PRIMARY', $table['metadata']['indexes']) && $table['metadata']['constraints'] === []
            && stripos($table['ddl'], 'PRIMARY KEY') === false, 'NHE_ORDER_PAY_ORIGINAL_STATUS_AND_LABEL_HAVE_NO_ID_PRIMARY_KEY_OR_AI');
        foreach ($table['metadata']['columns'] as $column)
            nhep_expect($column['EXTRA'] !== 'auto_increment',
                'NHE_ORDER_PAY_NO_COUNTER_OR_PRIMARY_COLUMN_ON_MULTISET_TABLES');
    }
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
        $status = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
        nhep_expect($status['oid'] !== $oid || $status['change_type'] !== 'pay_success',
            'NHE_ORDER_PAY_CURRENT_ROOT_NOT_ALREADY_PAID_IN_BEFORE_STATUS');
    }
    $statusCandidates = [];
    foreach ($actualDB2['rows']['eb_store_order_status'] as $candidate)
        if ($candidate['oid'] === $oid && $candidate['change_type'] === 'pay_success') $statusCandidates[] = $candidate;
    nhep_expect(count($statusCandidates) === 1, 'NHE_ORDER_PAY_ONLY_ONE_ACTUAL_NEW_NAMED_PAY_STATUS_TIME_CANDIDATE');
    $statusTime = nhep_auth_db_time($statusTable['metadata'], 'change_time', $statusCandidates[0]['change_time'], $interval);
    $expectedRows['eb_store_order_status'] = $beforeDB2['rows']['eb_store_order_status'];
    $expectedRows['eb_store_order_status'][] = m4lh_actor_expected_row($statusTable['metadata'],
        ['oid' => $oid, 'change_type' => 'pay_success', 'change_message' => '用户付款成功', 'change_time' => $statusTime]);

    $product = nhepcd_one($beforeDB2, 'eb_store_product', ['id' => $fixture['product_id']]);
    $labelId = nhepcd_id($product['row']['label_id'], 2147483647); $existing = [];
    foreach ($beforeDB2['rows']['eb_user_label_relation'] as $index => $unused) {
        $relation = nhepcv_native_row($beforeDB2, 'eb_user_label_relation', $index);
        if ($relation['uid'] === $uid && $relation['label_id'] === $labelId) $existing[] = $index;
    }
    nhep_expect($context['family'] === 'refund_family' ? $existing === [] : $existing !== [],
        'NHE_ORDER_PAY_FIRST_FAMILY_ADDS_LABEL_SECOND_FAMILY_REUSES_EXISTING_RELATION');
    if ($existing === []) {
        $expectedRows['eb_user_label_relation'] = $beforeDB2['rows']['eb_user_label_relation'];
        $expectedRows['eb_user_label_relation'][] = m4lh_actor_expected_row($labelTable['metadata'], ['uid' => $uid, 'label_id' => $labelId]);
    }
    $logTable = $beforeDB2['database']['tables']['eb_store_product_log'];
    nhep_expect(array_keys($logTable['metadata']['columns']) === ['id', 'type', 'product_id', 'uid', 'visit_num',
        'cart_num', 'order_num', 'pay_num', 'pay_price', 'cost_price', 'pay_uid', 'refund_num', 'refund_price', 'collect_num', 'add_time'],
        'NHE_ORDER_PAY_ORIGINAL_FULL_FIFTEEN_COLUMN_PRODUCT_LOG');
    $logId = m4lh_actor_next($logTable, 'id'); nhepcd_id($logId, 2147483647);
    foreach ($beforeDB2['rows']['eb_store_product_log'] as $row)
        nhep_expect($row['id'] !== $logId, 'NHE_ORDER_PAY_BEFORE_NEXT_SIGNED_PRODUCT_LOG_ID_ABSENT');
    $logIndex = nhep_auth_db_index($actualDB2['rows']['eb_store_product_log'], $logTable['metadata'], 'id', $logId);
    $logTime = nhep_funding_db_signed_time($logTable['metadata'], 'add_time',
        $actualDB2['rows']['eb_store_product_log'][$logIndex]['add_time'], $interval);
    // ProductLog reads the complete permanent cart cache. BEFORE saved JSON supplies this DB expectation only;
    // the future Redis model must independently prove that full original wire, not just these three fields.
    $logPrice = (string)$cart['truePrice']; $logCost = $cart['costPrice'];
    nhep_expect($cart['cart_num'] === 1 && $logPrice === '20.15' && $logCost === '7.45',
        'NHE_ORDER_PAY_PRODUCT_LOG_VALUES_FROM_ORIGINAL_SAVED_CART_NOT_CURRENT_SKU');
    $expectedRows['eb_store_product_log'] = $beforeDB2['rows']['eb_store_product_log'];
    $expectedRows['eb_store_product_log'][] = m4lh_actor_expected_row($logTable['metadata'], ['id' => $logId,
        'type' => 'pay', 'product_id' => $fixture['product_id'], 'uid' => $uid, 'pay_uid' => $uid,
        'pay_num' => $cart['cart_num'], 'pay_price' => $logPrice, 'cost_price' => $logCost, 'add_time' => $logTime]);
    $expected = nhep_database_expected($beforeDB2, $expectedRows, ['eb_user_money' => 1, 'eb_store_product_log' => 1]);
    nhep_expect($expected === $actualDB2, 'NHE_ORDER_PAY_ALL_164_TABLES_COMPLETE_INDEPENDENT_NORMAL_PAYMENT_DELTA');
    return $expected;
}

/** Definitions only. Two original normal balance payments; complete private values stay in caller RAM. */
function nhep_order_pay_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepop_context', 'nhepop_before_guards',
        'nhepcd_id', 'nhepcr_config_wire', 'm4lh_actor_native', 'nhepar_capture', 'nhepar_entry',
        'nhepar_actor', 'nhepar_customer', 'nhepar_bind', 'nhepar_remember', 'nhepar_tag',
        'nhep_redis_expected', 'bcadd', 'bcsub', 'bcmul', 'bccomp', 'json_decode', 'serialize', 'hash_equals'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPOPR_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPOPR_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPOPR_ORIGINAL_PRIVATE_POST_REQUEST');
    $steps = ['refund_family_pay' => [13, 'refund_family'], 'review_family_pay' => [19, 'review_family']];
    nhep_expect(PHP_INT_SIZE === 8 && is_string($intent['step']) && isset($steps[$intent['step']])
        && is_array($privateRequest['body']) && is_array($privateRequest['actor_identity']),
        'NHEPOPR_ONLY_TWO_ORIGINAL_NORMAL_POST_STEPS');
    [$sequence, $family] = $steps[$intent['step']]; $body = $privateRequest['body'];
    nhe_keys($body, ['uni', 'paytype', 'quitUrl', 'type'], 'NHEPOPR_ORIGINAL_FOUR_FIELD_PAYMENT_BODY');
    nhep_expect($intent['sequence'] === $sequence && $intent['method'] === 'POST'
        && $intent['path'] === '/api/order/pay' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($body['uni']) && preg_match('/\Acp([1-9][0-9]{0,18})\z/D', $body['uni'], $number) === 1
        && bccomp($number[1], '9223372036854775807', 0) <= 0
        && $body === ['uni' => 'cp' . $number[1], 'paytype' => 'yue', 'quitUrl' => '', 'type' => 0]
        && is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1,
        'NHEPOPR_REAL_ORIGINAL_CP_YUE_POST_RUN_AND_ORIGIN');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPOPR_ORIGINAL_PRIVATE_ACTOR_IDENTITY');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 2147483647
        && $privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account'])
        && preg_match('/\A[a-z0-9_]{10,32}\z/D', $privateRequest['actor_identity']['account']) === 1,
        'NHEPOPR_REAL_NATIVE_CUSTOMER_ID_AND_ACCOUNT');

    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHEPOPR_ORIGINAL_COMPLETE_PRIVATE_HTTP_RESPONSE');
    $interval = $privateResponse['actual_interval'];
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $privateResponse['http'] === 200 && $privateResponse['transport_errno'] === 0
        && $privateResponse['transport_failure_class'] === null && $privateResponse['primary_ip'] === '127.0.0.1'
        && $privateResponse['primary_port'] === 8000 && $privateResponse['local_ip'] === '127.0.0.1'
        && is_int($privateResponse['local_port']) && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw']) && $privateResponse['raw'] !== '' && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json']) && !array_is_list($privateResponse['json'])
        && is_array($privateResponse['headers']), 'NHEPOPR_REAL_COMPLETE_NORMAL_LOCAL_HTTP_AND_NATIVE_SECONDS');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHEPOPR_ORIGINAL_HEADER_CALLBACK_EXACT_FIVE_FIELDS');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] >= 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false, 'NHEPOPR_REAL_COMPLETE_NONTRUNCATED_HEADERS');
    $decoded = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $decoded === $privateResponse['json']
        && $decoded === ['status' => 200, 'msg' => '余额支付成功', 'data' => ['status' => 'SUCCESS', 'result' => []]],
        'NHEPOPR_COMPLETE_ORIGINAL_CHINESE_PAYMENT_SUCCESS_AND_EMPTY_RESULT');

    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPOPR_BOTH_FULL_NATIVE_CAPTURES_SAME_ORIGINAL_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $actualUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($actualUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPOPR_REAL_PAYMENT_HTTP_WINDOW_INSIDE_MONOTONIC_NATIVE_REDIS_TIME');
    $context = nhepop_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'cart'], 'NHEPOPR_SHARED_BEFORE_CONTEXT_EXACT_FIVE_KEYS');
    nhep_expect($context['family'] === $family && is_array($context['fixture'])
        && is_array($context['order']) && is_array($context['item']) && is_array($context['cart']),
        'NHEPOPR_ORIGINAL_PAYMENT_FAMILY_AND_COMPLETE_BEFORE_CONTEXT');
    nhe_keys($context['order'], ['index', 'row', 'metadata'], 'NHEPOPR_COMPLETE_BEFORE_ORDER_SELECTION');
    nhe_keys($context['item'], ['index', 'row', 'metadata'], 'NHEPOPR_COMPLETE_BEFORE_ITEM_SELECTION');
    nhepop_before_guards($beforeDB2, $intent, $context);
    $fixture = $context['fixture']; $order = $context['order']['row']; $item = $context['item']['row'];
    $cart = $context['cart']; $uid = $fixture['uid']; $oid = nhepcd_id($order['id'], 2147483647);
    $cartId = nhepcd_id($item['cart_id']);
    nhep_expect($uid === $intent['actor_id'] && $order['uid'] === $uid && $order['pay_uid'] === $uid
        && $order['order_id'] === $body['uni'] && $order['mark'] === $intent['run_id'] . '-' . $family
        && $order['paid'] === 0 && $order['pay_time'] === 0 && $order['is_channel'] === 0
        && $item['oid'] === $oid && $item['uid'] === $uid && $cart['id'] === $cartId && $cart['uid'] === $uid
        && is_int($order['add_time']) && $order['add_time'] > 0 && $order['add_time'] <= $interval[0],
        'NHEPOPR_BEFORE_SAME_UNPAID_ROOT_ITEM_SAVED_CART_OWNER_CP_AND_HTTP');
    $rows = $beforeDB2['rows'];
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($rows[$table] === [], 'NHEPOPR_COMPLETE_BEFORE_LANGUAGE_TABLES_EMPTY');

    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']), 'NHEPOPR_SAME_RUN_ORIGINAL_PRIVATE_AUTH_CONFIGURATION');
    $actor = nhepar_actor($rows, $intent, $privateRequest);
    nhep_expect($actor === $fixture['user']['row'], 'NHEPOPR_AUTH_ACTOR_IS_THE_SAME_COMPLETE_BEFORE_BUYER');
    $apiTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('api'));
    nhep_expect(is_array($apiTag) && $apiTag['type'] === 'set' && $apiTag['expires'] === -1
        && in_array('c:' . md5($privateRequest['token']), $apiTag['value'], true),
        'NHEPOPR_ORIGINAL_EXISTING_CUSTOMER_WHITELIST_API_TAG_MEMBERSHIP');
    $changes = []; $tagMembers = [];
    nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);

    // The two create caches are get() hits, not remember() touches. Rebuild their whole wire from saved history.
    $globalReferences = []; $itemColumns = $context['item']['metadata']['columns'];
    foreach ($rows['eb_store_order_cart_info'] as $index => $reference) {
        $referenceCart = m4lh_actor_native($itemColumns['cart_id'], $reference['cart_id']);
        $referenceRefund = m4lh_actor_native($itemColumns['refund_num'], $reference['refund_num']);
        nhep_expect($referenceCart === $reference['cart_id'] && is_string($referenceCart)
            && $referenceCart === (string)nhepcd_id($referenceCart)
            && $referenceRefund === $reference['refund_num'], 'NHEPOPR_GLOBAL_NATIVE_CANONICAL_CART_ID_AND_REFUND_REFERENCE');
        if (nhepcd_id($referenceCart) === $cartId) {
            nhep_expect($reference === $item && $referenceRefund === 0,
                'NHEPOPR_ONLY_ORIGINAL_CURRENT_SAVED_ITEM_HAS_THIS_GLOBAL_CART_ID_AND_ZERO_REFUND');
            $globalReferences[] = $index;
        }
    }
    nhep_expect($globalReferences === [$context['item']['index']] && !array_key_exists('refund_num', $cart)
        && is_array($cart['productInfo']), 'NHEPOPR_COMPLETE_UNAMBIGUOUS_BEFORE_GLOBAL_REFUND_SUM_SOURCE');
    // AggregateQuery::sum returns float. Preserve the original PHP cache type and append order, not JSON int zero.
    $title = $cart['productInfo']['store_name'];
    nhep_expect(is_string($title) && $title !== '' && $title !== '0', 'NHEPOPR_ORIGINAL_SAVED_NONEMPTY_TRUTHY_PRODUCT_TITLE');
    $cart['refund_num'] = 0.0;
    $warmValues = ['c:' . md5('store_order_cart_info_' . $oid) => serialize([$cartId => ['cart_info' => $cart]]),
        'c:' . md5('store_order_cart_product_title_' . $oid) => serialize($title)];
    $crmebTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('crmeb'));
    nhep_expect(is_array($crmebTag) && $crmebTag['type'] === 'set' && $crmebTag['expires'] === -1,
        'NHEPOPR_ORIGINAL_PERMANENT_COMPLETE_CRMEB_TAG_PRESENT');
    foreach ($warmValues as $key => $wire) {
        $old = nhepar_entry($beforeCapture, $key);
        nhep_expect(is_array($old) && $old['type'] === 'string' && $old['expires'] === -1
            && $old['value'] === $wire && $old['value'] !== '' && in_array($key, $crmebTag['value'], true),
            'NHEPOPR_BEFORE_COMPLETE_INDEPENDENT_CREATE_CACHE_WIRE_AND_EXISTING_TAG_MEMBER');
        $bound = nhepar_bind($actualCapture, $key, 'string', $wire, -1, $beforeCapture['snapshot']);
        nhep_expect($bound === $beforeCapture['snapshot']['keys'][hash('sha256', $key)],
            'NHEPOPR_ORIGINAL_GET_CACHE_FULL_VALUE_DESCRIPTOR_AND_PERMANENT_DEADLINE_PRESERVED');
    }
    // No warm get() append. Real configuration and language remember() calls append on either normal branch.
    $settings = ['station_open' => 1, 'param_filter_type' => null, 'param_filter_data' => null,
        'queue_open' => 0, 'brokerage_func_status' => 0, 'member_func_status' => 0];
    foreach ($settings as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire)
        nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);

    $beforeMs = $beforeCapture['snapshot']['time_ms']; $actualMs = $actualCapture['snapshot']['time_ms'];
    $httpFirstMs = bcmul((string)$interval[0], '1000', 0);
    $httpLastMs = bcsub(bcmul(bcadd((string)$interval[1], '1', 0), '1000', 0), '1', 0);
    $sets = ['c:PAY_LOCK_' . $order['order_id'] => ['wire' => serialize('PAY_LOCK'), 'ttl' => 2],
        'c:order_product_coupon_' . $uid . '_' . $oid => ['wire' => serialize([]), 'ttl' => 7200]];
    foreach ($sets as $key => $set) {
        nhep_expect(nhepar_entry($beforeCapture, $key) === null, 'NHEPOPR_BOTH_ORIGINAL_PAYMENT_SET_KEYS_NEW_AND_ABSENT_BEFORE');
        $ttlMs = bcmul((string)$set['ttl'], '1000', 0);
        $firstDeadline = bcadd($httpFirstMs, $ttlMs, 0); $lastDeadline = bcadd($httpLastMs, $ttlMs, 0);
        $present = nhepar_entry($actualCapture, $key);
        if ($present !== null) {
            nhep_expect($present['type'] === 'string' && $present['value'] === $set['wire']
                && is_int($present['expires']) && $present['expires'] > 0
                && bccomp((string)$present['expires'], bcadd($beforeMs, $ttlMs, 0), 0) >= 0
                && bccomp((string)$present['expires'], bcadd($actualMs, $ttlMs, 0), 0) <= 0
                && bccomp((string)$present['expires'], $firstDeadline, 0) >= 0
                && bccomp((string)$present['expires'], $lastDeadline, 0) <= 0
                && bccomp($actualMs, (string)$present['expires'], 0) <= 0,
                'NHEPOPR_COMPLETE_SET_WIRE_AND_NATIVE_DEADLINE_INSIDE_BOTH_REDIS_AND_HTTP_BOUNDS');
            $changes[$key] = nhepar_bind($actualCapture, $key, 'string', $set['wire'], ['ttl' => $set['ttl']], $beforeCapture['snapshot']);
        } else {
            // Only this final absence is proved. No expired payload/DUMP, exact SET time or historic deadline is invented.
            nhep_expect(bccomp($actualMs, $lastDeadline, 0) > 0,
                'NHEPOPR_MISSING_SET_ONLY_AFTER_STRICT_LATEST_POSSIBLE_NATIVE_EXPIRY_NO_EQUALITY_OR_WAIT');
            $changes[$key] = null;
        }
        // TagSet::set appends after SET, including keys that have naturally expired before the actual capture.
        $tagMembers[] = $key;
    }
    // The real BEFORE guard closes lottery. Its old key is neither read nor deleted by the no-activity branch.
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'], 'NHEPOPR_COMPLETE_NAMESPACE_FROM_BEFORE_AND_INDEPENDENT_PAYMENT_CHANGES');
    return $expected;
}


