                    'NHE_REFUNDED_USERINFO_COMPLETE_ORIGINAL_TWENTY_FOUR_REFUND_COLUMNS');
                foreach ($refundDefaults as $column => $default) {
                    $definition = $refundMetadata['columns'][$column]; $type = strtolower($definition['COLUMN_TYPE']);
                    if (in_array($column, ['refund_price', 'refunded_price'], true)) $rightType = $type === 'decimal(12,2)';
                    elseif (in_array($column, ['refund_type', 'is_cancel', 'is_pink_cancel', 'is_del', 'is_system_del'], true))
