                nhep_expect($refundRow === $refundSelection['row'] && is_string($refundNumber)
                    && preg_match('/\A[1-9][0-9]{0,18}\z/D', $refundNumber) === 1
                    && bccomp($refundNumber, '9223372036854775807', 0) <= 0
                    && is_int($applicationTime) && $applicationTime >= $order['pay_time']
                    && $applicationTime <= 2147483647 && is_int($completionTime)
                    && $completionTime >= $applicationTime && $completionTime <= 2147483647
                    && is_string($refundCartJSON)
                    && $refundRow === m4lh_actor_expected_row($refundMetadata, [
                        'id' => $refundId, 'store_order_id' => $oid, 'store_id' => $order['store_id'],
                        'order_id' => $refundNumber, 'uid' => $uid, 'refund_type' => 6, 'refund_num' => 1,
                        'refund_price' => $order['pay_price'], 'refunded_price' => $order['pay_price'],
                        'refund_explain' => '', 'refund_img' => '[]',
                        'refund_reason' => 'normal-refund-' . $intent['run_id'],
                        'add_time' => $applicationTime, 'refunded_time' => $completionTime,
                        'cart_info' => $refundCartJSON, 'is_pink_cancel' => 0]),
                    'NHE_REFUNDED_USERINFO_COMPLETE_BEFORE_COMPLETED_REFUND_TEMPLATE_AND_SEPARATE_HISTORICAL_TIMES');
                $completedRefundRow = $refundRow;
            }
        }
        $orderIds[] = $oid; $orderNumbers[] = $order['order_id']; $itemIds[] = $itemId; $cartIds[] = $cartId;
        $prices[] = $order['pay_price'];
        $balances[] = bcsub($balances[count($balances) - 1], $order['pay_price'], 2);
    }
    if ($refunded) {
        nhep_expect(is_array($completedRefundRow), 'NHE_REFUNDED_USERINFO_INDEPENDENT_COMPLETED_BEFORE_REFUND_REQUIRED');
        $balances[] = bcadd($balances[2], $completedRefundRow['refunded_price'], 2);
    }
    nhep_expect($balances === ($refunded ? ['100.00', '79.85', '59.70', '79.85'] : ['100.00', '79.85', '59.70'])
        && $user['now_money'] === $balances[$refunded ? 3 : 2],
        'NHE_TWO_PAID_USERINFO_HUNDRED_MINUS_TWO_BEFORE_ROOT_PRICES');

    // Independently select the original fixture administrator, never reverse-select an actor from a money row.
    $adminSelection = nhepcd_one($beforeDB2, 'eb_system_admin', ['real_name' => '隔离平台管理员']);
    $admin = nhepcv_native_row($beforeDB2, 'eb_system_admin', $adminSelection['index']);
    $adminId = nhepcd_id($admin['id']);
    nhep_expect($admin === $adminSelection['row'] && $admin['level'] === 0 && $admin['status'] === 1 && $admin['is_del'] === 0,
        'NHE_TWO_PAID_USERINFO_ORIGINAL_UNIQUE_ELIGIBLE_PLATFORM_FIXTURE');
    $moneyMetadata = $beforeDB2['database']['tables']['eb_user_money']['metadata'];
    nhep_expect(array_keys($moneyMetadata['columns']) === ['id', 'uid', 'link_id', 'type', 'title',
        'number', 'balance', 'pm', 'mark', 'status', 'add_time'], 'NHE_TWO_PAID_USERINFO_ORIGINAL_ELEVEN_LEDGER_COLUMNS');
    $money = [];
    foreach ($beforeDB2['rows']['eb_user_money'] as $index => $unused) {
        $row = nhepcv_native_row($beforeDB2, 'eb_user_money', $index);
        if ($row['uid'] !== $uid) continue;
        $id = nhepcd_id($row['id']);
        nhep_expect(!array_key_exists($id, $money) && is_int($row['add_time']) && $row['add_time'] > 0,
            'NHE_TWO_PAID_USERINFO_ORIGINAL_DISTINCT_LEDGER_ID_AND_POSITIVE_NATIVE_TIME');
        $money[$id] = $row;
    }
    nhep_expect(count($money) === ($refunded ? 4 : 3), 'NHE_TWO_PAID_USERINFO_ONLY_ORIGINAL_THREE_OR_REFUNDED_FOUR_OWN_MONEY_ROWS');
    ksort($money, SORT_NUMERIC); $money = array_values($money); $lastId = 0;
    foreach ($money as $position => $row) {
        $id = nhepcd_id($row['id']);
        nhep_expect($id > $lastId, 'NHE_TWO_PAID_USERINFO_ORIGINAL_FUND_REFUND_PAY_REVIEW_PAY_ID_ORDER');
        $lastId = $id;
        if ($refunded && $position === 3) {
            $amount = $completedRefundRow['refunded_price'];
            $values = ['id' => $id, 'uid' => $uid, 'link_id' => (string)$orderIds[0],
                'type' => 'pay_product_refund', 'title' => '商品退款', 'number' => $amount,
                'balance' => $balances[3], 'pm' => 1, 'mark' => '订单退款到余额' . $amount . '元',
                'status' => 1, 'add_time' => $row['add_time']];
        } else {
            $values = ['id' => $id, 'uid' => $uid, 'link_id' => $position === 0 ? (string)$adminId : (string)$orderIds[$position - 1],
                'type' => $position === 0 ? 'system_add' : 'pay_product',
                'title' => $position === 0 ? '系统增加余额' : '余额支付购买商品',
                'number' => $position === 0 ? '100.00' : $prices[$position - 1], 'balance' => $balances[$position],
                'pm' => $position === 0 ? 1 : 0, 'mark' => $position === 0 ? $intent['run_id'] : '余额支付20.15元购买商品',
                'status' => 1, 'add_time' => $row['add_time']];
        }
        nhep_expect($row === m4lh_actor_expected_row($moneyMetadata, $values),
            'NHE_TWO_PAID_USERINFO_COMPLETE_ORIGINAL_FUND_AND_PAYMENT_LEDGER_TEMPLATES');
    }

    // The complete empty table makes both original filtered/time-ranged SUMs zero, without choosing a clock.
    nhep_expect($beforeDB2['rows']['eb_user_bill'] === [], 'NHE_TWO_PAID_USERINFO_FIXED_NORMAL_BROKERAGE_LEDGER_REALLY_EMPTY');
    $brokerageCommission = '0'; $refundCommission = '0';
    $brokenCommission = bcsub($brokerageCommission, $refundCommission, 2);
    $commissionCount = bcsub($user['brokerage_price'], $brokenCommission, 2);
    nhep_expect($brokenCommission === '0.00' && $commissionCount === '0.00',
        'NHE_TWO_PAID_USERINFO_ORIGINAL_TWO_DERIVED_DECIMAL_STRINGS');

    // Model::toArray retains data order; only these five original hidden fields are removed.
    $hidden = ['add_ip', 'account', 'clean_time', 'last_ip', 'pwd']; $value = $user; $keys = [];
    foreach ($hidden as $column) unset($value[$column]);
    foreach ($columns as $column) if (!in_array($column, $hidden, true)) $keys[] = $column;
    $value['broken_commission'] = $brokenCommission; $value['commissionCount'] = $commissionCount;
    $keys[] = 'broken_commission'; $keys[] = 'commissionCount';
    nhep_expect(count($value) === 52 && array_keys($value) === $keys && $value['last_time'] === $user['last_time']
        && $value['add_time'] === $user['add_time'] && $value['birthday'] === $user['birthday'],
        'NHE_TWO_PAID_USERINFO_EXACT_52_KEYS_IN_ORIGINAL_MODEL_ORDER_AND_BEFORE_TIMES');
    return $value;
}


/** Original step22 pure models; normal factory dispatch is added separately. */
/** Definitions only. Original step22 HTTP and captures; private inputs remain in RAM. */
function nheprn_exchange(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse): string
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepar_capture', 'nhepar_entry', 'bcadd', 'bcmul', 'bccomp'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPRN_EXCHANGE_PURE_DEPENDENCY_REQUIRED');
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPRN_ORIGINAL_COMPLETE_REFUND_INTENT');
    nhep_expect(PHP_INT_SIZE === 8 && $intent['sequence'] === 22 && $intent['step'] === 'unshipped_refund_apply'
        && $intent['method'] === 'POST' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1 && is_string($intent['path'])
        && preg_match('~\A/api/order/refund/apply/([1-9][0-9]{0,9})\z~D', $intent['path'], $path) === 1
        && bccomp($path[1], '4294967295', 0) <= 0,
        'NHEPRN_EXACT_ORIGINAL_STEP22_CUSTOMER_ORIGIN_AND_UINT_ROOT_PATH');
    $rootId = $path[1];
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPRN_ORIGINAL_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect(is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['body']) && is_array($privateRequest['actor_identity']),
        'NHEPRN_REAL_EXISTING_CUSTOMER_REQUEST');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPRN_ORIGINAL_PRIVATE_ACTOR_EXACT_TWO');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 2147483647
        && $privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account'])
        && preg_match('/\A[a-z0-9_]{10,32}\z/D', $privateRequest['actor_identity']['account']) === 1,
        'NHEPRN_REAL_NATIVE_NORMAL_BUYER_ID_AND_ACCOUNT');
    $body = $privateRequest['body'];
    nhe_keys($body, ['text', 'refund_reason_wap_img', 'refund_reason_wap_explain', 'refund_type', 'refund_price', 'cart_ids'],
        'NHEPRN_ORIGINAL_REFUND_BODY_EXACT_SIX');
    nhep_expect($body === ['text' => 'normal-refund-' . $intent['run_id'], 'refund_reason_wap_img' => '',
        'refund_reason_wap_explain' => '', 'refund_type' => 1, 'refund_price' => '20.15', 'cart_ids' => []],
        'NHEPRN_FIXED_ORIGINAL_BODY_ORDER_NATIVE_TYPES_AND_VALUES');
    $interval = $privateResponse['actual_interval'] ?? null;
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0 && $interval[0] <= $interval[1]
        && $interval[1] <= 2147483647 && ($privateResponse['http'] ?? null) === 200
        && ($privateResponse['transport_errno'] ?? null) === 0
        && array_key_exists('transport_failure_class', $privateResponse) && $privateResponse['transport_failure_class'] === null
        && ($privateResponse['primary_ip'] ?? null) === '127.0.0.1' && ($privateResponse['primary_port'] ?? null) === 8000
        && ($privateResponse['local_ip'] ?? null) === '127.0.0.1'
        && is_int($privateResponse['local_port'] ?? null) && $privateResponse['local_port'] > 0
        && $privateResponse['local_port'] <= 65535 && is_string($privateResponse['raw'] ?? null)
        && strlen($privateResponse['raw']) <= 6291456 && is_array($privateResponse['json'] ?? null),
        'NHEPRN_REAL_COMPLETE_OWN_NORMAL_HTTP');
    $json = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $json === $privateResponse['json'],
        'NHEPRN_COMPLETE_RAW_JSON_JOIN');
    nhe_keys($json, ['status', 'msg'], 'NHEPRN_ORIGINAL_SUCCESS_RESPONSE_ONLY_STATUS_AND_MSG');
    nhep_expect($json === ['status' => 200, 'msg' => '申请成功'], 'NHEPRN_ORIGINAL_CHINESE_SUCCESS_WITHOUT_DATA_OR_NUMBER');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPRN_BOTH_COMPLETE_CAPTURES_SAME_ORIGINAL_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $afterUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($afterUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPRN_REAL_HTTP_WINDOW_INSIDE_MONOTONIC_REDIS_TIME_OBSERVATIONS');
    // The route supplies only an identity candidate; DB ownership and the new row remain the caller's proof.
    return $rootId;
}

/** Original bare refund number only. The future DB caller must select its row independently before this call. */
function nheprn_refund_expected(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] string $actualRefundNo): string
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepar_capture', 'nhepar_entry', 'nhepar_bind', 'nheprn_exchange',
        'bcadd', 'bcsub', 'bcmul', 'bcdiv', 'bcmod', 'bccomp'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPRN_NUMBER_PURE_DEPENDENCY_REQUIRED');
    nheprn_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhep_expect(preg_match('/\A[1-9][0-9]{0,18}\z/D', $actualRefundNo) === 1
        && bccomp($actualRefundNo, '9223372036854775807', 0) <= 0,
        'NHEPRN_CANONICAL_BARE_DECIMAL_SIGNED64_REFUND_NUMBER');
    $elapsed = bcdiv($actualRefundNo, '4194304', 0); $low = bcmod($actualRefundNo, '4194304', 0);
    $datacenter = bcdiv($low, '131072', 0);
    $worker = bcmod(bcdiv($low, '4096', 0), '32', 0); $sequence = bcmod($low, '4096', 0);
    nhep_expect(bccomp($elapsed, '0', 0) > 0 && bccomp($elapsed, '2199023255551', 0) <= 0
        && $datacenter === '0' && $worker === '0' && $sequence === '0',
        'NHEPRN_ORIGINAL_DEFAULT_NODES_AND_FIRST_ZERO_SEQUENCE_ONLY');
    $milliseconds = bcadd('1640966400000', $elapsed, 0);
    $httpStart = bcmul((string)$privateResponse['actual_interval'][0], '1000', 0);
    $httpLast = bcsub(bcmul(bcadd((string)$privateResponse['actual_interval'][1], '1', 0), '1000', 0), '1', 0);
    nhep_expect(bccomp($milliseconds, $httpStart, 0) >= 0 && bccomp($milliseconds, $httpLast, 0) <= 0
        && bccomp($milliseconds, $beforeCapture['snapshot']['time_ms'], 0) >= 0
        && bccomp($milliseconds, $actualCapture['snapshot']['time_ms'], 0) <= 0,
        'NHEPRN_DECODED_PHYSICAL_MILLISECOND_INSIDE_REAL_HTTP_AND_CAPTURE_WINDOWS');
    nhep_expect(nhepar_entry($beforeCapture, $milliseconds) === null, 'NHEPRN_FRESH_BEFORE_RAW_MILLISECOND_KEY');
    $expected = bcadd(bcadd(bcadd(bcmul(bcsub($milliseconds, '1640966400000', 0), '4194304', 0),
        bcmul($datacenter, '131072', 0), 0), bcmul($worker, '4096', 0), 0), $sequence, 0);
    nhep_expect($expected === $actualRefundNo, 'NHEPRN_FULL_BARE_SNOWFLAKE_RECONSTRUCTION');
    $row = nhepar_entry($actualCapture, $milliseconds); $latestDeadline = bcadd($httpLast, '1000', 0);
    if ($row === null) {
        // Uncertain expiry is refused. No expired payload or exact expired deadline is invented.
        nhep_expect(bccomp($actualCapture['snapshot']['time_ms'], $latestDeadline, 0) > 0,
            'NHEPRN_MISSING_COUNTER_ONLY_AFTER_LAST_POSSIBLE_NATURAL_DEADLINE');
    } else {
        nhep_expect($row['type'] === 'string' && $row['value'] === '1' && is_int($row['expires']) && $row['expires'] > 0
            && bccomp((string)$row['expires'], bcadd($milliseconds, '1000', 0), 0) >= 0
            && bccomp((string)$row['expires'], $latestDeadline, 0) <= 0
            && bccomp((string)$row['expires'], $actualCapture['snapshot']['time_ms'], 0) >= 0,
            'NHEPRN_FIRST_PSETEX_1000MS_RAW_WIRE_ONE_AND_COMPLETE_ABSOLUTE_DEADLINE');
        nhepar_bind($actualCapture, $milliseconds, 'string', '1', ['ttl' => 1], $beforeCapture['snapshot']);
    }
    return $expected;
}

