    $cart = json_decode($saved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && is_array($cart) && !array_is_list($cart)
        && json_encode($cart) === $saved['cart_info'], 'NHE_REFUND_CONTEXT_ORIGINAL_COMPLETE_DEFAULT_JSON_SAVED_CART');
    $cartMetadata = $beforeDB2['database']['tables']['eb_store_cart']['metadata'];
    $cartColumns = array_keys($cartMetadata['columns']); $baseCart = [];
    nhep_expect(count($cartColumns) === 15, 'NHE_REFUND_CONTEXT_ORIGINAL_FIFTEEN_NATIVE_CART_COLUMNS');
    foreach ($cartColumns as $column) {
        nhep_expect(array_key_exists($column, $cart), 'NHE_REFUND_CONTEXT_COMPLETE_ORIGINAL_SAVED_CART_BASE');
        $baseCart[$column] = m4lh_actor_native($cartMetadata['columns'][$column], $cart[$column]);
        nhep_expect($baseCart[$column] === $cart[$column], 'NHE_REFUND_CONTEXT_NATIVE_SAVED_CART_BASE_TYPE');
    }
    nhep_expect(is_int($baseCart['add_time']) && $baseCart['add_time'] > 0 && $baseCart['add_time'] <= $row['add_time']
        && $baseCart === m4lh_actor_expected_row($cartMetadata, ['id' => $cartId, 'uid' => $uid,
            'type' => '0', 'product_id' => $fixture['product_id'], 'product_attr_unique' => $fixture['sku_unique'],
            'cart_num' => 1, 'add_time' => $baseCart['add_time']]), 'NHE_REFUND_CONTEXT_ORIGINAL_OWNED_CART_AND_SKU_BASE');
    nhep_expect(is_array($cart['productInfo'] ?? null) && is_array($cart['attrInfo'] ?? null)
        && is_array($cart['productInfo']['attrInfo'] ?? null)
        && $cart['attrInfo'] === $cart['productInfo']['attrInfo'], 'NHE_REFUND_CONTEXT_BOTH_ORIGINAL_SAVED_SKU_RELATIONS');
    $productSelection = nhepcd_one($beforeDB2, 'eb_store_product', ['id' => $fixture['product_id']]);
    $skuSelection = nhepcd_one($beforeDB2, 'eb_store_product_attr_value', ['unique' => $fixture['sku_unique']]);
    $product = nhepcv_native_row($beforeDB2, 'eb_store_product', $productSelection['index']);
    $sku = nhepcv_native_row($beforeDB2, 'eb_store_product_attr_value', $skuSelection['index']);
    $historicalProduct = $cart['productInfo']; $historicalSku = $cart['productInfo']['attrInfo'];
    // Inventory is persisted history. Validate it natively and retain it; never replace it with today's stock/sales.
    foreach ([['eb_store_product', $historicalProduct], ['eb_store_product_attr_value', $historicalSku]] as [$table, $history]) {
        foreach (['stock', 'sales'] as $column) {
            nhep_expect(array_key_exists($column, $history)
                && m4lh_actor_native($beforeDB2['database']['tables'][$table]['metadata']['columns'][$column], $history[$column]) === $history[$column]
                && is_int($history[$column]) && $history[$column] >= ($column === 'stock' ? 1 : 0),
                'NHE_REFUND_CONTEXT_ORIGINAL_NATIVE_HISTORICAL_INVENTORY');
        }
    }
    $sku['stock'] = $historicalSku['stock']; $sku['sales'] = $historicalSku['sales'];
    nhep_expect($sku === $historicalSku && $sku['id'] === $fixture['sku_id']
        && $sku['product_id'] === $fixture['product_id'] && $sku['unique'] === $fixture['sku_unique']
        && $sku['suk'] === '普通' && $sku['type'] === 0 && $sku['price'] === '20.15' && $sku['cost'] === '7.45',
        'NHE_REFUND_CONTEXT_ORIGINAL_COMPLETE_SAVED_SKU_WITH_HISTORICAL_INVENTORY');
    $slides = json_decode($product['slider_image'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $slides === ['/statics/system_images/spread_level_1.png'],
        'NHE_REFUND_CONTEXT_ORIGINAL_PRODUCT_SLIDER_GETTER');
    $product['stock'] = $historicalProduct['stock']; $product['sales'] = $historicalProduct['sales'];
    $product['slider_image'] = $slides; $product['express_delivery'] = true;
    $product['store_mention'] = false; $product['attrInfo'] = $sku;
    nhep_expect($product === $historicalProduct, 'NHE_REFUND_CONTEXT_COMPLETE_ORIGINAL_SAVED_PRODUCT_WITH_HISTORICAL_INVENTORY');
    $expectedCart = $baseCart;
    $expectedCart['productInfo'] = $product; $expectedCart['attrInfo'] = $sku;
    $expectedCart['min_qty'] = 1; $expectedCart['attrStatus'] = true; $expectedCart['vip_truePrice'] = 0;
    $expectedCart['costPrice'] = '7.45'; $expectedCart['trueStock'] = $historicalSku['stock'];
    $expectedCart['truePrice'] = 20.15; $expectedCart['sum_price'] = '20.15';
    $expectedCart['price_type'] = 'level'; $expectedCart['is_valid'] = 1; $expectedCart['postage_price'] = 0;
    $expectedCart['use_integral'] = 0; $expectedCart['integral_price'] = 0; $expectedCart['coupon_price'] = 0;
    $expectedCart['sum_true_price'] = '20.15'; $expectedCart['one_brokerage'] = '0'; $expectedCart['two_brokerage'] = '0';
    $expectedCart['staff_brokerage'] = '0.00'; $expectedCart['agent_brokerage'] = '0.00'; $expectedCart['division_brokerage'] = '0.00';
    nhep_expect($expectedCart === $cart, 'NHE_REFUND_CONTEXT_COMPLETE_ORIGINAL_SAVED_CART_AND_FIXED_NORMAL_PRICE_FIELDS');
    $user = nhepcv_native_row($beforeDB2, 'eb_user', $fixture['user']['index']);
    nhep_expect($user === $fixture['user']['row'] && $user['now_money'] === '59.70' && $user['pay_count'] === 2
        && is_int($user['last_time']) && $user['last_time'] > 0,
        'NHE_REFUND_CONTEXT_ORIGINAL_TWO_PAID_BUYER_BALANCE_COUNT_AND_BEFORE_AUTH_TIME');
    return ['family' => $family, 'fixture' => $fixture, 'order' => $order, 'item' => $item, 'cart' => $cart];
}

/** BEFORE-only synchronous support gates. Queue0 does not imply an absence of writes. */
function nheprdb_before_guards(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $context): void
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_one', 'nhepcv_native_row',
        'nhepcv_config', 'nhep_funding_db_no_outpush', 'json_decode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_REFUND_GUARD_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHE_REFUND_GUARD_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'cart'], 'NHE_REFUND_GUARD_CONTEXT_EXACT_FIVE');
    nhep_expect($intent['sequence'] === 22 && $intent['step'] === 'unshipped_refund_apply'
        && $intent['method'] === 'POST' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && $context['family'] === 'refund_family' && is_array($context['fixture'])
        && is_array($context['order']) && is_array($context['item']) && is_array($context['cart']),
        'NHE_REFUND_GUARD_ONLY_REAL_22_AND_ORIGINAL_REFUND_FAMILY');
    nhe_keys($context['order'], ['index', 'row', 'metadata'], 'NHE_REFUND_GUARD_ORIGINAL_ORDER_SELECTION');
    nhe_keys($context['item'], ['index', 'row', 'metadata'], 'NHE_REFUND_GUARD_ORIGINAL_ITEM_SELECTION');
    nhe_keys($context['fixture'], ['uid', 'user', 'product_id', 'sku_id', 'sku_unique', 'address_id'],
        'NHE_REFUND_GUARD_ORIGINAL_GENERIC_FIXTURE_SHAPE');
    $oid = $context['order']['row']['id']; $uid = $context['fixture']['uid'];
    nhep_expect($context['order'] === nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-refund_family'])
        && $context['order'] === nhepcd_one($beforeDB2, 'eb_store_order', ['id' => $oid])
        && $context['item'] === nhepcd_one($beforeDB2, 'eb_store_order_cart_info', ['oid' => $oid])
        && $context['fixture']['user'] === nhepcd_one($beforeDB2, 'eb_user', ['uid' => $uid])
        && $intent['path'] === '/api/order/refund/apply/' . $oid && $intent['actor_id'] === $uid
        && $context['order']['row']['uid'] === $uid && $context['order']['row']['pay_uid'] === $uid
        && $context['fixture']['user']['row']['is_money_level'] === 0,
        'NHE_REFUND_GUARD_SAME_COMPLETE_BEFORE_CONTEXT_ROOT_ITEM_OWNER_AND_ROUTE');
    $cart = json_decode($context['item']['row']['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $cart === $context['cart'],
        'NHE_REFUND_GUARD_CONTEXT_CART_IS_COMPLETE_ORIGINAL_BEFORE_JSON');
    // Deliberately stronger first-application closed set, including inactive/cancelled refund rows.
    foreach ($beforeDB2['rows']['eb_store_order_refund'] as $index => $unused) {
        $refund = nhepcv_native_row($beforeDB2, 'eb_store_order_refund', $index);
        nhep_expect($refund['store_order_id'] !== $oid, 'NHE_REFUND_GUARD_ROOT_HAS_NO_PREVIOUS_REFUND_ROW');
    }
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
        $status = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
        nhep_expect($status['oid'] !== $oid || $status['change_type'] !== 'apply_refund',
            'NHE_REFUND_GUARD_ROOT_HAS_NO_PREVIOUS_APPLY_REFUND_STATUS');
    }
    nhepcv_config($beforeDB2, $intent, 'queue_open', 0);
    nhep_expect($beforeDB2['rows']['eb_store_service'] === [],
        'NHE_REFUND_GUARD_COMPLETE_SERVICE_TABLE_EMPTY_BEFORE_ADMIN_NOTICE_LOOP');
    foreach ($beforeDB2['rows']['eb_system_event'] as $index => $unused) {
        $event = nhepcv_native_row($beforeDB2, 'eb_system_event', $index);
        nhep_expect(!($event['is_del'] === 0 && $event['is_open'] === 1),
            'NHE_REFUND_GUARD_ENABLED_CUSTOM_EVENT_BRANCH_NOT_IMPLEMENTED');
    }
    nhep_funding_db_no_outpush($beforeDB2);
    $mark = 'send_order_apply_refund';
    foreach ($beforeDB2['rows']['eb_system_notification'] as $index => $unused) {
        $notice = nhepcv_native_row($beforeDB2, 'eb_system_notification', $index);
        nhep_expect(is_string($notice['mark'])
            && (strtolower(rtrim($notice['mark'], ' ')) !== $mark || $notice['mark'] === $mark),
            'NHE_REFUND_GUARD_NOTIFICATION_MARK_COLLATION_UNAMBIGUOUS');
    }
    $notice = nhepcd_one($beforeDB2, 'eb_system_notification', ['mark' => $mark]);
    nhep_expect($notice['row'] === nhepcv_native_row($beforeDB2, 'eb_system_notification', $notice['index'])
        && $notice['row']['type'] === 2, 'NHE_REFUND_GUARD_UNIQUE_CANONICAL_ORIGINAL_ADMIN_NOTICE_TYPE');
    foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat', 'is_app'] as $column)
        nhep_expect($notice['row'][$column] === 0, 'NHE_REFUND_GUARD_ALL_SIX_NATIVE_NOTICE_CHANNELS_DISABLED');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($beforeDB2['rows'][$table] === [], 'NHE_REFUND_GUARD_THREE_ORIGINAL_CHINESE_LANGUAGE_TABLES_EMPTY');
    // Old OrderRefundCreateAfterListener::handle only destructures its order; other listeners have separate gates.
}

/** Only four table deltas. AFTER supplies next-PK number and three separately bounded native times. */
function nhep_unshipped_refund_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse, #[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nheprdb_context', 'nheprdb_before_guards', 'nheprn_exchange',
        'nheprn_refund_expected', 'nhep_auth_db_snapshot', 'nhep_auth_db_index', 'nhep_auth_db_time',
        'nhep_funding_db_signed_time', 'nhep_auth_db_update', 'nhep_database_expected', 'nhepcd_id',
        'm4lh_actor_native', 'm4lh_actor_expected_row', 'm4lh_actor_next', 'json_encode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_REFUND_DB_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    $context = nheprdb_context($beforeDB2, $intent, $privateRequest);
    nheprdb_before_guards($beforeDB2, $intent, $context);
    $routeId = nheprn_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHE_REFUND_DB_ORIGINAL_COMPLETE_PRIVATE_HTTP_RESPONSE');
    nhep_expect(is_array($privateResponse['headers']), 'NHE_REFUND_DB_PRIVATE_HEADERS_ARRAY');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHE_REFUND_DB_ORIGINAL_HEADER_CALLBACK_EXACT_FIVE');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] >= 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false,
        'NHE_REFUND_DB_ORIGINAL_COMPLETE_NONTRUNCATED_HEADER_CALLBACK');
    $interval = $privateResponse['actual_interval']; $fixture = $context['fixture'];
    $user = $fixture['user']; $order = $context['order']; $item = $context['item'];
    $uid = $fixture['uid']; $oid = $order['row']['id'];
    nhep_expect($routeId === (string)$oid && $order['row']['add_time'] <= $interval[0]
        && $order['row']['pay_time'] <= $interval[0] && $user['row']['last_time'] <= $interval[0],
        'NHE_REFUND_DB_BEFORE_SAME_OWN_PAID_ROOT_PRECEDES_REAL_STEP22_HTTP');

    $refundTable = $beforeDB2['database']['tables']['eb_store_order_refund']; $metadata = $refundTable['metadata'];
    $defaults = ['id' => null, 'store_order_id' => 0, 'store_id' => 0, 'order_id' => '', 'uid' => 0,
        'refund_type' => 0, 'refund_num' => 0, 'refund_price' => '0.00', 'refunded_price' => '0.00',
        'refund_phone' => '', 'refund_express' => '', 'refund_express_name' => '', 'refund_explain' => '',
        'refund_img' => null, 'refund_reason' => '', 'refuse_reason' => '', 'remark' => '', 'refunded_time' => 0,
        'cart_info' => null, 'is_cancel' => 0, 'is_pink_cancel' => 0, 'is_del' => 0, 'add_time' => 0, 'is_system_del' => 0];
    nhep_expect(count($defaults) === 24 && array_keys($metadata['columns']) === array_keys($defaults),
        'NHE_REFUND_DB_ORIGINAL_COMPLETE_TWENTY_FOUR_COLUMNS');
    foreach ($defaults as $column => $default) {
        $definition = $metadata['columns'][$column]; $type = strtolower($definition['COLUMN_TYPE']);
        if (in_array($column, ['refund_price', 'refunded_price'], true)) $rightType = $type === 'decimal(12,2)';
        elseif (in_array($column, ['refund_type', 'is_cancel', 'is_pink_cancel', 'is_del', 'is_system_del'], true))
            $rightType = preg_match('/\Atinyint(?:\([0-9]+\))?\z/D', $type) === 1;
        elseif (in_array($column, ['id', 'store_order_id', 'store_id', 'uid', 'refund_num', 'refunded_time', 'add_time'], true))
            $rightType = preg_match('/\Aint(?:\([0-9]+\))?\z/D', $type) === 1;
        elseif ($column === 'refund_img') $rightType = $type === 'text';
        elseif ($column === 'cart_info') $rightType = $type === 'longtext';
        else {
            $length = ['order_id' => 50, 'refund_phone' => 32, 'refund_express' => 100,
                'refund_express_name' => 255, 'refund_explain' => 255, 'refund_reason' => 255,
                'refuse_reason' => 255, 'remark' => 255][$column];
            $rightType = $type === 'varchar(' . $length . ')';
        }
        nhep_expect($rightType && $definition['COLUMN_NAME'] === $column
            && $definition['GENERATION_EXPRESSION'] === ''
            && $definition['EXTRA'] === ($column === 'id' ? 'auto_increment' : '')
            && $definition['IS_NULLABLE'] === (in_array($column, ['refund_img', 'cart_info', 'is_del', 'is_system_del'], true) ? 'YES' : 'NO'),
            'NHE_REFUND_DB_ORIGINAL_COLUMN_TYPE_NULLABILITY_AND_NO_GENERATED_VALUES');
        if ($column === 'id') nhep_expect($definition['COLUMN_DEFAULT'] === null, 'NHE_REFUND_DB_ORIGINAL_AUTO_ID_NULL_DEFAULT');
        else nhep_expect(m4lh_actor_native($definition, $definition['COLUMN_DEFAULT']) === $default,
            'NHE_REFUND_DB_ORIGINAL_DDL_NATIVE_DEFAULTS_BEFORE_BUILDING_NEW_ROW');
    }
    nhep_expect(array_keys($metadata['indexes']) === ['PRIMARY'] && count($metadata['indexes']['PRIMARY']) === 1
        && $metadata['indexes']['PRIMARY'][0]['COLUMN_NAME'] === 'id'
        && (string)$metadata['indexes']['PRIMARY'][0]['NON_UNIQUE'] === '0'
        && (string)$metadata['indexes']['PRIMARY'][0]['SEQ_IN_INDEX'] === '1'
        && count($metadata['constraints']) === 1 && $metadata['constraints'][0]['CONSTRAINT_NAME'] === 'PRIMARY'
        && $metadata['constraints'][0]['CONSTRAINT_TYPE'] === 'PRIMARY KEY'
        && $metadata['checks'] === [] && $metadata['foreign'] === [] && $metadata['triggers'] === [],
        'NHE_REFUND_DB_ONLY_ORIGINAL_ID_PRIMARY_KEY_NO_INVENTED_UNIQUE_REFUND_NUMBER');
    $rid = m4lh_actor_next($refundTable, 'id'); nhepcd_id($rid, 2147483647);
    foreach ($beforeDB2['rows']['eb_store_order_refund'] as $beforeRefund)
        nhep_expect($beforeRefund['id'] !== $rid, 'NHE_REFUND_DB_BEFORE_NEXT_REFUND_PK_ABSENT');
    $actualRefundIndex = nhep_auth_db_index($actualDB2['rows']['eb_store_order_refund'], $metadata, 'id', $rid);
    $candidateNumber = $actualDB2['rows']['eb_store_order_refund'][$actualRefundIndex]['order_id'];
    nhep_expect(is_string($candidateNumber), 'NHE_REFUND_DB_ONLY_BEFORE_NEXT_PK_ROW_BARE_NUMBER_CANDIDATE');
    $number = nheprn_refund_expected($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse, $candidateNumber);
    $refundTime = nhep_funding_db_signed_time($metadata, 'add_time',
        $actualDB2['rows']['eb_store_order_refund'][$actualRefundIndex]['add_time'], $interval);
    $actualUserIndex = nhep_auth_db_index($actualDB2['rows']['eb_user'], $user['metadata'], 'uid', $uid);
    $authTime = nhep_auth_db_time($user['metadata'], 'last_time',
        $actualDB2['rows']['eb_user'][$actualUserIndex]['last_time'], $interval, $user['row']['last_time']);

    $statusTable = $beforeDB2['database']['tables']['eb_store_order_status']; $statusMetadata = $statusTable['metadata'];
    nhep_expect(array_keys($statusMetadata['columns']) === ['oid', 'change_type', 'change_message', 'change_time']
        && $statusMetadata['table']['AUTO_INCREMENT'] === null && !array_key_exists('PRIMARY', $statusMetadata['indexes'])
        && $statusMetadata['constraints'] === [] && $statusMetadata['checks'] === []
        && $statusMetadata['foreign'] === [] && $statusMetadata['triggers'] === []
        && stripos($statusTable['ddl'], 'PRIMARY KEY') === false,
        'NHE_REFUND_DB_ORIGINAL_FOUR_COLUMN_STATUS_WITHOUT_PRIMARY_ID_OR_AI');
    foreach ($statusMetadata['columns'] as $column)
        nhep_expect($column['EXTRA'] !== 'auto_increment', 'NHE_REFUND_DB_STATUS_NEVER_ADVANCES_AN_ID_COUNTER');
    $statusTimes = [];
    foreach ($actualDB2['rows']['eb_store_order_status'] as $candidate)
        if ($candidate['oid'] === $oid && $candidate['change_type'] === 'apply_refund') $statusTimes[] = $candidate['change_time'];
    nhep_expect(count($statusTimes) === 1, 'NHE_REFUND_DB_ONE_NEW_STATUS_TIME_FOR_BEFORE_ROOT_AND_FIXED_TYPE');
    $statusTime = nhep_auth_db_time($statusMetadata, 'change_time', $statusTimes[0], $interval);
    // Auth, refund and status are separately bounded; their original timestamp calls need not be equal.
    $expectedRows = ['eb_user' => nhep_auth_db_update($beforeDB2, 'eb_user', $user['index'], ['last_time' => $authTime]),
        'eb_store_order_cart_info' => nhep_auth_db_update($beforeDB2, 'eb_store_order_cart_info', $item['index'],
            ['refund_num' => $item['row']['cart_num']])];
    $expectedRows['eb_store_order_status'] = $beforeDB2['rows']['eb_store_order_status'];
    $expectedRows['eb_store_order_status'][] = m4lh_actor_expected_row($statusMetadata, ['oid' => $oid,
        'change_type' => 'apply_refund', 'change_message' => '用户申请退款，原因：' . $privateRequest['body']['text'],
        'change_time' => $statusTime]);
    $cartJSON = json_encode([$context['cart']]); $imageJSON = json_encode([]);
    nhep_expect(is_string($cartJSON) && $imageJSON === '[]', 'NHE_REFUND_DB_DEFAULT_JSON_OF_FULL_BEFORE_CART_ARRAY_AND_EMPTY_IMAGES');
    $newRefund = m4lh_actor_expected_row($metadata, ['id' => $rid, 'store_order_id' => $oid,
        'store_id' => $order['row']['store_id'], 'order_id' => $number, 'uid' => $uid, 'refund_type' => 1,
        'refund_num' => $order['row']['total_num'], 'refund_price' => $order['row']['pay_price'],
        'refund_explain' => $privateRequest['body']['refund_reason_wap_explain'], 'refund_img' => $imageJSON,
        'refund_reason' => $privateRequest['body']['text'], 'add_time' => $refundTime,
        'cart_info' => $cartJSON, 'is_pink_cancel' => 0]);
    $expectedRows['eb_store_order_refund'] = $beforeDB2['rows']['eb_store_order_refund'];
    $expectedRows['eb_store_order_refund'][] = $newRefund;
    // refund_no is an old in-memory assignment. The entire persistent order table remains BEFORE.
    $expected = nhep_database_expected($beforeDB2, $expectedRows, ['eb_store_order_refund' => 1]);
    nhep_expect($expected === $actualDB2, 'NHE_REFUND_DB_ALL_164_TABLES_FOUR_INDEPENDENT_DELTAS_AND_SOLE_REFUND_AI');
    return $expected;
}

/** Definitions only. Original step22 full Redis expected; all private values remain in caller RAM. */
function nhep_unshipped_refund_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration, #[SensitiveParameter] string $actualRefundNo): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nheprdb_context', 'nheprdb_before_guards',
        'nheprn_exchange', 'nheprn_refund_expected', 'nhepcd_id', 'm4lh_actor_native', 'nhepcr_config_wire',
        'nhepar_capture', 'nhepar_entry', 'nhepar_actor', 'nhepar_customer', 'nhepar_bind',
        'nhepar_remember', 'nhepar_tag', 'nhep_redis_expected', 'bcadd', 'bcdiv', 'serialize', 'hash_equals'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPRR_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    // Both shared BEFORE definitions receive the genuine POST intent and untouched private request.
    $context = nheprdb_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'cart'], 'NHEPRR_ORIGINAL_BEFORE_CONTEXT_EXACT_FIVE');
    nhep_expect($context['family'] === 'refund_family' && is_array($context['fixture'])
        && is_array($context['order']) && is_array($context['item']) && is_array($context['cart']),
        'NHEPRR_ONLY_ORIGINAL_UNSHIPPED_REFUND_FAMILY');
    nhe_keys($context['order'], ['index', 'row', 'metadata'], 'NHEPRR_COMPLETE_BEFORE_ORDER_SELECTION');
    nhe_keys($context['item'], ['index', 'row', 'metadata'], 'NHEPRR_COMPLETE_BEFORE_ITEM_SELECTION');
    nheprdb_before_guards($beforeDB2, $intent, $context);
    // This verifies complete native captures, same Run/sentinel, actual HTTP/raw JSON and real TIME envelope.
    $routeId = nheprn_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHEPRR_ORIGINAL_COMPLETE_PRIVATE_HTTP_RESPONSE');
    nhep_expect(is_array($privateResponse['headers']), 'NHEPRR_REAL_PRIVATE_HEADER_CALLBACK');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHEPRR_ORIGINAL_HEADER_CALLBACK_EXACT_FIVE');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] >= 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false,
        'NHEPRR_COMPLETE_NONTRUNCATED_ORIGINAL_HEADERS');
    $fixture = $context['fixture']; $order = $context['order']['row']; $item = $context['item']['row'];
    $cart = $context['cart']; $rows = $beforeDB2['rows']; $interval = $privateResponse['actual_interval'];
    $uid = $fixture['uid']; $oid = nhepcd_id($order['id'], 2147483647); $cartId = nhepcd_id($item['cart_id']);
    nhep_expect($routeId === (string)$oid && $uid === $intent['actor_id']
        && $order['uid'] === $uid && $order['pay_uid'] === $uid && $order['paid'] === 1
        && $order['mark'] === $intent['run_id'] . '-refund_family'
        && $item['oid'] === $oid && $item['uid'] === $uid && $item['refund_num'] === 0
        && $cart['id'] === $cartId && $cart['uid'] === $uid
        && $order['add_time'] <= $interval[0] && $order['pay_time'] <= $interval[0]
        && $fixture['user']['row']['last_time'] <= $interval[0],
        'NHEPRR_SAME_BEFORE_OWN_PAID_ROOT_ITEM_SAVED_CART_AND_REAL_HTTP');

    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']),
        'NHEPRR_SAME_RUN_ORIGINAL_PRIVATE_AUTH_CONFIGURATION');
    $actor = nhepar_actor($rows, $intent, $privateRequest);
    nhep_expect($actor === $fixture['user']['row'], 'NHEPRR_REAL_AUTH_ACTOR_IS_ORIGINAL_COMPLETE_BEFORE_BUYER');
    $apiTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('api'));
    nhep_expect(is_array($apiTag) && $apiTag['type'] === 'set' && $apiTag['expires'] === -1
        && in_array('c:' . md5($privateRequest['token']), $apiTag['value'], true),
        'NHEPRR_ORIGINAL_PERMANENT_API_TAG_ALREADY_CONTAINS_EXISTING_WHITELIST');
    $changes = []; $tagMembers = [];
    // Requires the designed generic lazy-data correction; never fabricate response.data for this no-data success.
    nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);

    // Reconstruct the original detail cache from saved history and the actual global cart-id SUM source.
    $globalReferences = []; $itemColumns = $context['item']['metadata']['columns'];
    foreach ($rows['eb_store_order_cart_info'] as $index => $reference) {
        $referenceCart = m4lh_actor_native($itemColumns['cart_id'], $reference['cart_id']);
        $referenceRefund = m4lh_actor_native($itemColumns['refund_num'], $reference['refund_num']);
        nhep_expect($referenceCart === $reference['cart_id'] && is_string($referenceCart)
            && $referenceCart === (string)nhepcd_id($referenceCart)
            && $referenceRefund === $reference['refund_num'],
            'NHEPRR_GLOBAL_NATIVE_CANONICAL_CART_ID_AND_REFUND_REFERENCE');
        if (nhepcd_id($referenceCart) === $cartId) {
            nhep_expect($reference === $item && $referenceRefund === 0,
                'NHEPRR_ONLY_ORIGINAL_SAVED_ITEM_HAS_THIS_GLOBAL_CART_ID_AND_ZERO_REFUND');
            $globalReferences[] = $index;
        }
    }
    nhep_expect($globalReferences === [$context['item']['index']] && !array_key_exists('refund_num', $cart)
        && is_array($cart['productInfo']), 'NHEPRR_COMPLETE_UNAMBIGUOUS_BEFORE_GLOBAL_REFUND_SUM_SOURCE');
    $title = $cart['productInfo']['store_name'];
    nhep_expect(is_string($title) && $title !== '' && $title !== '0',
        'NHEPRR_ONLY_ORIGINAL_NONEMPTY_TRUTHY_SAVED_PRODUCT_TITLE');
    // AggregateQuery::sum is float; append at the original cache position without changing the saved JSON.
    $cart['refund_num'] = 0.0;
    $detailKey = 'c:' . md5('store_order_cart_info_' . $oid);
    $titleKey = 'c:' . md5('store_order_cart_product_title_' . $oid);
    $warmValues = [$detailKey => serialize([$cartId => ['cart_info' => $cart]]), $titleKey => serialize($title)];
    $crmebTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('crmeb'));
    nhep_expect(is_array($crmebTag) && $crmebTag['type'] === 'set' && $crmebTag['expires'] === -1,
        'NHEPRR_ORIGINAL_PERMANENT_COMPLETE_CRMEB_TAG_PRESENT');
    foreach ($warmValues as $key => $wire) {
        $old = nhepar_entry($beforeCapture, $key);
        nhep_expect(is_array($old) && $old['type'] === 'string' && $old['expires'] === -1
            && $old['value'] === $wire && $old['value'] !== '' && in_array($key, $crmebTag['value'], true),
            'NHEPRR_BEFORE_BOTH_ORIGINAL_PERMANENT_WARM_FULL_WIRES_AND_EXISTING_TAG_MEMBERS');
        if ($key === $detailKey) {
            // clearOrderCartInfo performs DEL only. Neither tag membership nor the payload is reconstructed.
            nhep_expect(nhepar_entry($actualCapture, $key) === null, 'NHEPRR_ORIGINAL_DETAIL_PAYLOAD_DELETED_WITHOUT_REBUILD');
            $changes[$key] = null;
        } else {
            // Notice reads the original title by get(), including when all six notice channels are disabled.
            $bound = nhepar_bind($actualCapture, $key, 'string', $wire, -1, $beforeCapture['snapshot']);
            nhep_expect($bound === $beforeCapture['snapshot']['keys'][hash('sha256', $key)],
                'NHEPRR_WARM_TITLE_GET_PRESERVES_FULL_DESCRIPTOR_AND_PERMANENT_DEADLINE');
        }
    }
    // PHP8.2: sys_config missing type returns ''; '' != 0 is true, so missing data is read as well.
    foreach (['station_open' => 1, 'param_filter_type' => null, 'param_filter_data' => null] as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    // Warm N; may be recomputed and SET with a transient lock. Only the final permanent wire is proved here.
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire)
        nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);

    // Caller supplies only the number from the independently proved BEFORE next-refund-PK row after DB7.
    $number = nheprn_refund_expected($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse, $actualRefundNo);
    nhep_expect($number === $actualRefundNo, 'NHEPRR_COMPLETE_INDEPENDENT_BARE_REFUND_NUMBER');
    $milliseconds = bcadd('1640966400000', bcdiv($number, '4194304', 0), 0);
    $counter = nhepar_entry($actualCapture, $milliseconds);
    if ($counter === null) {
        // The number proof permits this only strictly after Hlast+1000; no expired wire or SET time is invented.
        $changes[$milliseconds] = null;
    } else {
        // Number proof already established fresh BEFORE, raw wire 1 and both actual capture/HTTP deadline bounds.
        $changes[$milliseconds] = nhepar_bind($actualCapture, $milliseconds, 'string', '1', ['ttl' => 1], $beforeCapture['snapshot']);
    }
    // Only the three real configuration and three language remembers append. DEL keeps every original tag member.
    // The warm title get and bare Snowflake key never append a new member here.
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'], 'NHEPRR_COMPLETE_NAMESPACE_FROM_BEFORE_AND_INDEPENDENT_STEP22_CHANGES');
    return $expected;
}

/** Definitions only. Genuine original step23; complete private BEFORE data stays in RAM. */
function nheprl_context(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_fixture', 'nhepcd_one',
        'nhepcd_id', 'nhepcv_native_row', 'nhepcv_config', 'm4lh_actor_native',
        'm4lh_actor_expected_row', 'bccomp', 'bcadd', 'json_decode', 'json_encode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPRL_CONTEXT_PURE_DEPENDENCY_REQUIRED');
    nhep_expect(PHP_INT_SIZE === 8 && class_exists(DateTimeImmutable::class, false)
        && class_exists(DateTimeZone::class, false), 'NHEPRL_NATIVE_64_BIT_AND_BUILTIN_EXPLICIT_DATE_CLASSES');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPRL_CONTEXT_ORIGINAL_COMPLETE_INTENT');
    nhep_expect($intent['sequence'] === 23 && $intent['step'] === 'owned_refund_identity'
        && $intent['method'] === 'GET' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000'
        && $intent['path'] === '/api/order/refund/list?page=1&limit=20'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1,
        'NHEPRL_CONTEXT_EXACT_TRUE_23_ORIGIN_CUSTOMER_AND_FIXED_QUERY');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPRL_CONTEXT_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect($privateRequest['body'] === null && is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['actor_identity']), 'NHEPRL_CONTEXT_REAL_EXISTING_GET_NULL_BODY_AND_TOKEN');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPRL_CONTEXT_ORIGINAL_IDENTITY_EXACT_TWO');
