        'product_id' => $fixture['product_id'], 'old_cart_id' => '', 'cart_num' => 1,
        'refund_num' => 1, 'surplus_num' => 1, 'split_status' => 0,
        'cart_info' => $saved['cart_info'], 'unique' => md5($cartId . '' . $oid)])
        && is_string($saved['cart_info']) && $saved['cart_info'] !== ''
