        && $productRow['price'] === '20.15' && $productRow['cost'] === '7.45'
        && $productRow['is_virtual'] === 0 && $productRow['virtual_type'] === 0,
        'NHEPMC_CONTEXT_ORIGINAL_RUN_PRODUCT_AND_GLOBALLY_UNIQUE_NORMAL_SKU');
    $item = nhepcd_one($beforeDB2, 'eb_store_order_cart_info', ['oid' => $oid]);
    $saved = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $item['index']);
    nhep_expect(array_keys($item['metadata']['columns']) === ['id', 'oid', 'uid', 'cart_id', 'product_id',
        'old_cart_id', 'cart_num', 'refund_num', 'surplus_num', 'split_status', 'cart_info', 'unique'],
        'NHEPMC_CONTEXT_ORIGINAL_COMPLETE_TWELVE_ITEM_COLUMNS');
    $itemId = nhepcd_id($saved['id'], 2147483647); $cartId = nhepcd_id($saved['cart_id']);
    nhep_expect($saved === $item['row'] && $saved === m4lh_actor_expected_row($item['metadata'], [
        'id' => $itemId, 'oid' => $oid, 'uid' => $uid, 'cart_id' => (string)$cartId,
        'product_id' => $productId, 'old_cart_id' => '', 'cart_num' => 1, 'refund_num' => 0,
        'surplus_num' => 1, 'split_status' => 0, 'cart_info' => $saved['cart_info'], 'unique' => md5($cartId . '' . $oid)])
        && is_string($saved['cart_info']) && $saved['cart_info'] !== '' && $root['cart_id'] === json_encode([$cartId]),
        'NHEPMC_CONTEXT_ONE_REAL_REVIEW_FAMILY_UNSPLIT_ITEM_AND_ROOT_CART');
    $cart = json_decode($saved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && is_array($cart) && !array_is_list($cart)
        && json_encode($cart) === $saved['cart_info'], 'NHEPMC_CONTEXT_COMPLETE_BEFORE_SAVED_DEFAULT_JSON_CART');
    $cartMetadata = $beforeDB2['database']['tables']['eb_store_cart']['metadata']; $baseCart = [];
    nhep_expect(count($cartMetadata['columns']) === 15
        && array_slice(array_keys($cart), 0, 15) === array_keys($cartMetadata['columns']),
        'NHEPMC_CONTEXT_ORIGINAL_FIFTEEN_NATIVE_SAVED_CART_BASE_COLUMNS');
    foreach ($cartMetadata['columns'] as $column => $definition) {
        $baseCart[$column] = m4lh_actor_native($definition, $cart[$column]);
        nhep_expect($baseCart[$column] === $cart[$column], 'NHEPMC_CONTEXT_EVERY_ORIGINAL_NATIVE_SAVED_CART_BASE_FIELD');
    }
    nhep_expect(is_int($baseCart['add_time']) && $baseCart['add_time'] > 0 && $baseCart['add_time'] <= $root['add_time']
        && $baseCart === m4lh_actor_expected_row($cartMetadata, ['id' => $cartId, 'uid' => $uid, 'type' => '0',
            'product_id' => $productId, 'product_attr_unique' => $skuUnique, 'cart_num' => 1, 'add_time' => $baseCart['add_time']])
        && is_array($cart['productInfo'] ?? null) && is_array($cart['attrInfo'] ?? null)
        && ($cart['productInfo']['attrInfo'] ?? null) === $cart['attrInfo']
        && ($cart['productInfo']['id'] ?? null) === $productId
        && ($cart['productInfo']['store_name'] ?? null) === $productRow['store_name']
        && ($cart['attrInfo']['id'] ?? null) === $skuId && ($cart['attrInfo']['product_id'] ?? null) === $productId
        && ($cart['attrInfo']['unique'] ?? null) === $skuUnique && ($cart['attrInfo']['type'] ?? null) === 0
        && ($cart['attrInfo']['suk'] ?? null) === '普通' && ($cart['truePrice'] ?? null) === 20.15
        && ($cart['sum_price'] ?? null) === '20.15' && ($cart['postage_price'] ?? null) === 0
        && !array_key_exists('refund_num', $cart), 'NHEPMC_CONTEXT_REAL_SAVED_CART_IDENTITIES_PRICE_QUANTITY_AND_ZERO_POSTAGE');
    foreach ([[$cart['productInfo'], $productRow, $product['metadata']],
        [$cart['attrInfo'], $skuRow, $sku['metadata']]] as [$history, $current, $metadata]) {
        nhep_expect(is_string($history['image'] ?? null) && $history['image'] !== '' && $history['image'] === $current['image'],
            'NHEPMC_CONTEXT_ORIGINAL_NONEMPTY_SAVED_PRODUCT_AND_SKU_IMAGES');
        foreach (['stock', 'sales'] as $column)
            nhep_expect(is_int($history[$column] ?? null) && $history[$column] >= ($column === 'stock' ? 1 : 0)
                && m4lh_actor_native($metadata['columns'][$column], $history[$column]) === $history[$column],
                'NHEPMC_CONTEXT_PRESERVE_ORIGINAL_NATIVE_HISTORICAL_INVENTORY_NOT_CURRENT_STOCK');
    }
    nhep_expect(array_keys($order['metadata']['columns']) === ['id', 'pid', 'order_id', 'trade_no', 'uid', 'real_name', 'user_phone', 'user_address', 'cart_id', 'freight_price', 'total_num', 'total_price', 'total_postage', 'pay_price', 'pay_postage', 'deduction_price', 'coupon_id', 'coupon_price', 'paid', 'pay_time', 'pay_type', 'add_time', 'status', 'is_stock_up', 'refund_status', 'refund_type', 'refund_express', 'refund_express_name', 'refund_reason_wap_img', 'refund_reason_wap_explain', 'refund_reason_time', 'refund_reason_wap', 'refund_reason', 'refund_price', 'delivery_name', 'delivery_code', 'delivery_type', 'delivery_id', 'kuaidi_label', 'kuaidi_task_id', 'kuaidi_order_id', 'fictitious_content', 'delivery_uid', 'gain_integral', 'use_integral', 'back_integral', 'spread_uid', 'spread_two_uid', 'one_brokerage', 'two_brokerage', 'mark', 'is_del', 'is_cancel', 'unique', 'remark', 'mer_id', 'is_mer_check', 'combination_id', 'pink_id', 'cost', 'seckill_id', 'bargain_id', 'advance_id', 'verify_code', 'store_id', 'shipping_type', 'clerk_id', 'is_channel', 'is_remind', 'is_system_del', 'channel_type', 'province', 'express_dump', 'virtual_type', 'virtual_info', 'pay_uid', 'custom_form', 'staff_id', 'agent_id', 'division_id', 'staff_brokerage', 'agent_brokerage', 'division_brokerage', 'is_gift', 'gift_price', 'gift_uid', 'gift_mark'],
        'NHEPMC_CONTEXT_ORIGINAL_ORDERED_87_ROOT_COLUMNS_FOR_NATIVE_ROWS_AND_QUERY_FIELDS');
    $menuColumns = $beforeDB2['database']['tables']['eb_system_menus']['metadata']['columns'];
    $url = $menuColumns['api_url'] ?? null;
    nhep_expect(is_array($url) && strtolower($url['COLUMN_TYPE']) === 'varchar(100)'
        && $url['IS_NULLABLE'] === 'NO' && $url['CHARACTER_SET_NAME'] === 'utf8mb4'
        && in_array($url['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
            'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
        'NHEPMC_CONTEXT_ORIGINAL_MENU_URL_NATIVE_TYPE_CHARSET_AND_FINITE_COLLATIONS');
    $rule = 'order/delivery/<id>'; $pages = [];
    foreach ($beforeDB2['rows']['eb_system_menus'] as $index => $unused) {
        $menu = nhepcv_native_row($beforeDB2, 'eb_system_menus', $index);
        nhep_expect(is_string($menu['api_url']) && preg_match('/\A[\x20-\x7e]*\z/D', $menu['api_url']) === 1
            && is_string($menu['menu_name'])
            && (strtolower(rtrim($menu['api_url'], ' ')) !== $rule || $menu['api_url'] === $rule),
            'NHEPMC_CONTEXT_PRINTABLE_ASCII_MENU_URLS_AND_NO_SQL_EQUIVALENT_ROUTE_ALIAS');
        if ($menu['api_url'] === $rule) {
            $page = $menu['menu_name'] ?: '未知';
            if (!in_array($page, $pages, true)) $pages[] = $page;
        }
    }
    if ($pages === []) $pages[] = '未知';
    $expressCode = $beforeDB2['database']['tables']['eb_express']['metadata']['columns']['code'];
    nhep_expect($expressCode['IS_NULLABLE'] === 'NO' && $expressCode['CHARACTER_SET_NAME'] === 'utf8mb4'
        && in_array($expressCode['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
            'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
        'NHEPMC_CONTEXT_EXPRESS_SQL_EQUALITY_SUPPORTED_CHARSET_AND_COLLATION');
    nhep_expect($path[1] === (string)$oid && count($root) === 87
        && count($buyerRow) === 55 && $root['fictitious_content'] === '',
        'NHEPMC_CONTEXT_URL_IS_THE_INDEPENDENT_ORIGINAL_REVIEW_ROOT_WITH_ALL_NATIVE_COLUMNS');
    $express = nhepcd_one($beforeDB2, 'eb_express', ['code' => 'shunfeng']);
    $expressRow = nhepcv_native_row($beforeDB2, 'eb_express', $express['index']);
    nhep_expect($expressRow === $express['row'] && $expressRow === m4lh_actor_expected_row($express['metadata'], [
        'id' => nhepcd_id($expressRow['id']), 'code' => 'shunfeng', 'name' => '顺丰速运',
        'partner_id' => 1, 'is_show' => 1, 'status' => 0]),
        'NHEPMC_CONTEXT_COMPLETE_ORIGINAL_EXPRESS_FIXTURE_AND_DEFAULTS');
    foreach ($beforeDB2['rows']['eb_express'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_express', $index);
        nhep_expect(is_string($candidate['code']) && preg_match('/\A[\x20-\x7e]*\z/D', $candidate['code']) === 1
            && (strtolower(rtrim($candidate['code'], ' ')) !== 'shunfeng' || $candidate['code'] === 'shunfeng'),
            'NHEPMC_CONTEXT_NO_SQL_EQUIVALENT_EXPRESS_CODE_ALIAS');
    }
    $body = ['type' => 1, 'express_record_type' => 1, 'delivery_name' => $expressRow['name'],
        'delivery_code' => $expressRow['code'], 'delivery_id' => 'NHE' . $intent['run_id']];
    nhep_expect($privateRequest['body'] === $body, 'NHEPMC_CONTEXT_ALL_FIVE_BODY_VALUES_FROM_BEFORE_FIXTURE_AND_RUN');

    // Request.more preserves JSON int1/int0; unknown fields remain in options.data until Builder filters SQL.
    $data = ['delivery_name' => $expressRow['name'], 'delivery_id' => 'NHE' . $intent['run_id'],
        'delivery_code' => $expressRow['code'], 'express_record_type' => 1, 'express_temp_id' => '',
        'to_name' => '', 'to_tel' => '', 'to_addr' => '', 'sh_delivery_name' => '', 'sh_delivery_id' => '',
        'sh_delivery_uid' => '', 'fictitious_content' => '', 'day_type' => 0, 'pickup_time' => [],
        'pickup_start_time' => '', 'pickup_end_time' => '', 'delivery_type' => 'express', 'status' => 1];
    // Static Model::update has empty origin and null key. This is not the loaded-model PK cache identity.
    $options = ['json' => [], 'json_assoc' => false, 'field_type' => [],
        'where' => ['AND' => [['id', '=', $oid]]], 'strict' => false, 'cache' => [true, null, null],
        'key' => null, 'field' => array_keys($order['metadata']['columns']), 'data' => $data,
        'table' => 'eb_store_order', 'order' => [], 'join' => [], 'union' => [], 'master' => true,
        'lock' => false, 'fetch_sql' => false, 'array' => false, 'distinct' => false, 'procedure' => false,
        'group' => '', 'having' => '', 'limit' => '', 'force' => '', 'comment' => '', 'partition' => '',
        'duplicate' => '', 'extra' => ''];
    // PDOConnection.update consumes/clears getBind() before pdoExecute.master(true) and parseCache; binds are [].
    $queryKey = 'c:' . md5('audit_auth' . serialize(var_export($options, true)) . serialize([]));
    return ['family' => $family, 'admin' => $admin, 'buyer' => $buyer, 'order' => $order,
        'item' => $item, 'cart' => $cart, 'express' => $express, 'visit_pages' => $pages, 'query_cache_key' => $queryKey];
}

/** Actual normal28 support gates. Redis cold-key proof is separate because this function has no capture argument. */
function nhepmc_before_guards(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $context): void
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_one', 'nhepcd_id',
        'nhepcv_native_row', 'nhepcv_config', 'nhepcr_config_wire', 'nhep_funding_db_no_outpush',
        'm4lh_actor_expected_row', 'bccomp', 'json_decode', 'json_encode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPMC_GUARDS_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPMC_GUARDS_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($context, ['family', 'admin', 'buyer', 'order', 'item', 'cart', 'express', 'visit_pages', 'query_cache_key'],
        'NHEPMC_GUARDS_COMPLETE_CONTEXT_EXACT_NINE');
    nhep_expect($context['family'] === 'review_family' && $intent['sequence'] === 28
        && $intent['step'] === 'platform_manual_courier' && $intent['actor'] === 'admin' && $intent['method'] === 'PUT'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && $intent['actor_id'] === $context['admin']['row']['id']
        && $intent['path'] === '/adminapi/order/delivery/' . $context['order']['row']['id']
        && is_string($context['query_cache_key']) && preg_match('/\Ac:[a-f0-9]{32}\z/D', $context['query_cache_key']) === 1,
        'NHEPMC_GUARDS_TRUE_28_AND_BEFORE_REVIEW_ROOT_BINDING');
    foreach (['admin' => ['eb_system_admin', 'id'], 'buyer' => ['eb_user', 'uid'],
        'order' => ['eb_store_order', 'id'], 'item' => ['eb_store_order_cart_info', 'id'],
        'express' => ['eb_express', 'id']] as $name => [$table, $pk]) {
        $selection = $context[$name];
        nhe_keys($selection, ['index', 'row', 'metadata'], 'NHEPMC_GUARDS_COMPLETE_NATIVE_ENTITY_SELECTION');
        nhep_expect($selection === nhepcd_one($beforeDB2, $table, [$pk => $selection['row'][$pk]])
            && $selection['row'] === nhepcv_native_row($beforeDB2, $table, $selection['index']),
            'NHEPMC_GUARDS_EVERY_CONTEXT_ENTITY_IS_THE_ORIGINAL_BEFORE_ROW');
    }
    $root = $context['order']['row']; $oid = $root['id']; $uid = $context['buyer']['row']['uid'];
    $saved = $context['item']['row']; $cart = json_decode($saved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $cart === $context['cart']
        && $root['mark'] === $intent['run_id'] . '-review_family' && $root['uid'] === $uid && $root['pay_uid'] === $uid
        && $root['paid'] === 1 && $root['status'] === 0 && $root['refund_status'] === 0 && $root['refund_type'] === 0
        && $root['is_del'] === 0 && $root['shipping_type'] === 1 && $root['pink_id'] === 0
        && $saved['oid'] === $oid && $saved['uid'] === $uid && $saved['refund_num'] === 0,
        'NHEPMC_GUARDS_COMPLETE_SAVED_CART_AND_ACTUAL_DELIVERY_BRANCH');
    foreach ($beforeDB2['rows']['eb_store_order_refund'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_order_refund', $index);
        nhep_expect(!($candidate['store_order_id'] === $oid && in_array($candidate['refund_type'], [1, 2, 4, 5], true)
            && $candidate['is_cancel'] === 0 && $candidate['is_del'] === 0),
            'NHEPMC_GUARDS_NO_ACTUAL_ACTIVE_AFTERSALE_FOR_THIS_REVIEW_ROOT');
    }
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
        $status = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
        if ($status['oid'] === $oid) nhep_expect(is_string($status['change_type'])
            && preg_match('/\A[\x20-\x7e]*\z/D', $status['change_type']) === 1
            && strtolower(rtrim($status['change_type'], ' ')) !== 'delivery_goods',
            'NHEPMC_GUARDS_NO_PREVIOUS_DELIVERY_GOODS_FOR_THE_NAMED_ROOT');
    }
    // The other original family is already refunded; retain it and its complete 24-column refund row.
    $other = nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-refund_family']);
    $otherRoot = nhepcv_native_row($beforeDB2, 'eb_store_order', $other['index']);
    nhep_expect($otherRoot === $other['row'] && $otherRoot['id'] !== $oid && $otherRoot['order_id'] !== $root['order_id']
        && $otherRoot['uid'] === $uid && $otherRoot['pay_uid'] === $uid && $otherRoot['paid'] === 1
        && $otherRoot['status'] === -2 && $otherRoot['refund_status'] === 2 && $otherRoot['refund_type'] === 6
        && $otherRoot['refund_price'] === '20.15' && $otherRoot['pay_price'] === '20.15'
        && $otherRoot['refund_reason_time'] === 0 && $otherRoot['refund_reason_wap_img'] === ''
        && $otherRoot['refund_reason_wap'] === 'normal-refund-' . $intent['run_id']
        && $otherRoot['pid'] === 0 && $otherRoot['is_del'] === 0 && $otherRoot['is_cancel'] === 0,
        'NHEPMC_GUARDS_ORIGINAL_OTHER_FAMILY_ALREADY_COMPLETED_REFUND');
    $otherItem = nhepcd_one($beforeDB2, 'eb_store_order_cart_info', ['oid' => $otherRoot['id']]);
    $otherSaved = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $otherItem['index']);
    $otherCart = json_decode($otherSaved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && is_array($otherCart) && !array_is_list($otherCart)
        && json_encode($otherCart) === $otherSaved['cart_info'] && $otherSaved['uid'] === $uid
        && $otherSaved['refund_num'] === 1 && $otherSaved['cart_num'] === 1
        && $otherRoot['cart_id'] === json_encode([nhepcd_id($otherSaved['cart_id'])]),
        'NHEPMC_GUARDS_KEEP_OTHER_FAMILY_COMPLETE_SAVED_CART_JSON');
    $refund = nhepcd_one($beforeDB2, 'eb_store_order_refund', ['store_order_id' => $otherRoot['id'], 'uid' => $uid]);
    $refundRow = nhepcv_native_row($beforeDB2, 'eb_store_order_refund', $refund['index']);
    nhep_expect(count($refundRow) === 24 && is_string($refundRow['order_id'])
        && preg_match('/\A[1-9][0-9]{0,18}\z/D', $refundRow['order_id']) === 1
        && bccomp($refundRow['order_id'], '9223372036854775807', 0) <= 0
        && is_int($refundRow['add_time']) && $refundRow['add_time'] >= $otherRoot['pay_time']
        && is_int($refundRow['refunded_time']) && $refundRow['refunded_time'] >= $refundRow['add_time']
        && $refundRow['refunded_time'] > 0
        && $refundRow === m4lh_actor_expected_row($refund['metadata'], [
            'id' => nhepcd_id($refundRow['id'], 2147483647), 'store_order_id' => $otherRoot['id'],
            'store_id' => 0, 'order_id' => $refundRow['order_id'], 'uid' => $uid,
            'refund_type' => 6, 'refund_num' => 1, 'refund_price' => '20.15', 'refunded_price' => '20.15',
            'refund_explain' => '', 'refund_img' => '[]', 'refund_reason' => 'normal-refund-' . $intent['run_id'],
            'add_time' => $refundRow['add_time'], 'refunded_time' => $refundRow['refunded_time'],
            'cart_info' => json_encode([$otherCart]), 'is_pink_cancel' => 0]),
        'NHEPMC_GUARDS_COMPLETE_OLD_REFUND_NOT_REPLAYED_OR_RECONSTRUCTED_FROM_AFTER');
    foreach (['station_open' => 1, 'queue_open' => 0, 'order_shipping_open' => 0, 'system_delivery_time' => '7'] as $name => $value)
        nhepcv_config($beforeDB2, $intent, $name, $value);
    foreach (['param_filter_type', 'param_filter_data'] as $name)
        nhep_expect(nhepcr_config_wire($beforeDB2, $name, null) === 'N;', 'NHEPMC_GUARDS_BOTH_REAL_ABSENT_FILTER_CONFIGS');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($beforeDB2['rows'][$table] === [], 'NHEPMC_GUARDS_THREE_LANGUAGE_TABLES_EMPTY');
    nhep_funding_db_no_outpush($beforeDB2);
    foreach ([['eb_system_notification', 'mark', 'order_postage_success'],
        ['eb_system_notification', 'custom_trigger', 'order_express_success'],
        ['eb_system_event', 'mark', 'admin_order_express']] as [$table, $field, $wanted]) {
        $definition = $beforeDB2['database']['tables'][$table]['metadata']['columns'][$field];
        nhep_expect($definition['CHARACTER_SET_NAME'] === 'utf8mb4'
            && in_array($definition['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
                'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
            'NHEPMC_GUARDS_ORIGINAL_TECHNICAL_SELECTOR_CHARSET_AND_SUPPORTED_COLLATION');
        foreach ($beforeDB2['rows'][$table] as $index => $unused) {
            $candidate = nhepcv_native_row($beforeDB2, $table, $index); $value = $candidate[$field];
            nhep_expect($value === null || (is_string($value) && preg_match('/\A[\x20-\x7e]*\z/D', $value) === 1
                && (strtolower(rtrim($value, ' ')) !== $wanted || $value === $wanted)),
                'NHEPMC_GUARDS_CANONICAL_COMPLETE_SQL_TECHNICAL_SELECTOR_VALUES');
            if ($value !== $wanted) continue;
            if ($field === 'custom_trigger') {
                // All matches count, including any type/is_del; the listener has exactly these five switches.
                foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat'] as $flag)
                    nhep_expect($candidate[$flag] === 0, 'NHEPMC_GUARDS_ALL_MATCHING_CUSTOM_NOTICE_FIVE_CHANNELS_DISABLED');
            } elseif ($table === 'eb_system_event') nhep_expect(!($candidate['is_del'] === 0 && $candidate['is_open'] === 1),
                'NHEPMC_GUARDS_NO_ENABLED_MATCHING_ADMIN_EXPRESS_SCRIPT');
        }
    }
    // Actual ordinary notice selects only mark, without a type/is_del predicate.
    $notice = nhepcd_one($beforeDB2, 'eb_system_notification', ['mark' => 'order_postage_success']);
    nhep_expect($notice['row'] === nhepcv_native_row($beforeDB2, 'eb_system_notification', $notice['index'])
        && $notice['row']['type'] === 1 && $notice['row']['name'] === 'normal-' . $intent['run_id']
        && $notice['row']['title'] === 'synthetic normal ' . $intent['run_id'],
        'NHEPMC_GUARDS_UNIQUE_ORIGINAL_RUN_POSTAGE_NOTICE');
    foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat', 'is_app'] as $flag)
        nhep_expect($notice['row'][$flag] === 0, 'NHEPMC_GUARDS_ALL_SIX_ORDINARY_NOTICE_CHANNELS_DISABLED');
}

/** Exact original28 exchange; supplied native observations only, no new clock or resource access. */
function nhepmc_exchange(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse): void
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepar_capture', 'nhepar_entry', 'bcadd', 'bcmul', 'bccomp', 'json_decode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPMC_EXCHANGE_PURE_DEPENDENCY_REQUIRED');
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPMC_EXCHANGE_ORIGINAL_COMPLETE_INTENT');
    nhep_expect(PHP_INT_SIZE === 8 && $intent['sequence'] === 28 && $intent['step'] === 'platform_manual_courier'
        && $intent['method'] === 'PUT' && $intent['actor'] === 'admin'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['path']) && preg_match('~\A/adminapi/order/delivery/([1-9][0-9]{0,9})\z~D', $intent['path'], $path) === 1
        && bccomp($path[1], '2147483647', 0) <= 0,
        'NHEPMC_EXCHANGE_TRUE_28_ADMIN_ORIGIN_AND_CANONICAL_SIGNED_ROOT_PATH');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPMC_EXCHANGE_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect(is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['body']) && is_array($privateRequest['actor_identity']),
        'NHEPMC_EXCHANGE_REAL_EXISTING_ADMIN_TOKEN_BODY_AND_IDENTITY');
    nhe_keys($privateRequest['body'], ['type', 'express_record_type', 'delivery_name', 'delivery_code', 'delivery_id'],
        'NHEPMC_EXCHANGE_ORIGINAL_BODY_EXACT_FIVE');
    nhep_expect($privateRequest['body'] === ['type' => 1, 'express_record_type' => 1,
        'delivery_name' => '顺丰速运', 'delivery_code' => 'shunfeng', 'delivery_id' => 'NHE' . $intent['run_id']],
        'NHEPMC_EXCHANGE_FIXED_ORIGINAL_COURIER_BODY_NATIVE_TYPES_VALUES_AND_ORDER');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPMC_EXCHANGE_PRIVATE_ADMIN_IDENTITY_EXACT_TWO');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 4294967295
        && $privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account']),
        'NHEPMC_EXCHANGE_ORIGINAL_NATIVE_ADMIN_IDENTITY');
    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHEPMC_EXCHANGE_COMPLETE_ORIGINAL_PRIVATE_RESPONSE_EXACT_ELEVEN');
    $interval = $privateResponse['actual_interval'];
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $privateResponse['http'] === 200 && $privateResponse['transport_errno'] === 0
        && $privateResponse['transport_failure_class'] === null && $privateResponse['primary_ip'] === '127.0.0.1'
        && $privateResponse['primary_port'] === 8000 && $privateResponse['local_ip'] === '127.0.0.1'
        && is_int($privateResponse['local_port']) && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw']) && $privateResponse['raw'] !== '' && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json']) && !array_is_list($privateResponse['json']) && is_array($privateResponse['headers']),
        'NHEPMC_EXCHANGE_ONE_REAL_LOCAL_SUCCESS_AND_HTTP_SECONDS_INSIDE_SIGNED_TIME_RANGE');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHEPMC_EXCHANGE_ORIGINAL_HEADER_CALLBACK_EXACT_FIVE');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] > 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false
        && count($privateResponse['headers']['blocks']) === 1
        && $privateResponse['headers']['blocks'][0] === $privateResponse['headers']['lines'],
        'NHEPMC_EXCHANGE_ORIGINAL_COMPLETE_NONTRUNCATED_HEADERS');
    $lines = $privateResponse['headers']['lines']; $headerBytes = 0;
    nhep_expect(count($lines) >= 3 && in_array($lines[0], ["HTTP/1.0 200 OK\r\n", "HTTP/1.1 200 OK\r\n"], true)
        && $lines[count($lines) - 1] === "\r\n", 'NHEPMC_EXCHANGE_REAL_STATUS_AND_FINAL_HEADER_CRLF');
    foreach ($lines as $line) {
        nhep_expect(is_string($line) && str_ends_with($line, "\r\n"), 'NHEPMC_EXCHANGE_EVERY_ORIGINAL_HEADER_LINE_COMPLETE');
        $headerBytes += strlen($line);
    }
    nhep_expect($headerBytes === $privateResponse['headers']['bytes'], 'NHEPMC_EXCHANGE_COMPLETE_HEADER_BYTE_SUM');
    $json = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $json === $privateResponse['json'],
        'NHEPMC_EXCHANGE_ORIGINAL_COMPLETE_RAW_JSON_STRICT_JOIN');
    nhe_keys($json, ['status', 'msg', 'data'], 'NHEPMC_EXCHANGE_COMPLETE_SUCCESS_EXACT_THREE');
    nhep_expect($json === ['status' => 200, 'msg' => '操作成功', 'data' => []],
        'NHEPMC_EXCHANGE_ORIGINAL_CHINESE_SUCCESS_WITH_EMPTY_ARRAY_DATA');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPMC_EXCHANGE_BOTH_NATIVE_CAPTURES_SAME_ORIGINAL_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $afterUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($afterUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPMC_EXCHANGE_REAL_HTTP_WINDOW_ENCLOSED_BY_MONOTONIC_NATIVE_REDIS_TIME');
}

/** Three-table complete expected. Only the independently named log/status timestamps may come from AFTER. */
function nhep_manual_courier_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse, #[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepmc_context', 'nhepmc_before_guards', 'nhepmc_exchange',
        'nhep_auth_db_snapshot', 'nhep_auth_db_index', 'nhep_auth_db_time', 'nhep_auth_db_update',
        'nhep_database_expected', 'nhepcd_id', 'nhepar_entry', 'm4lh_actor_native',
        'm4lh_actor_expected_row', 'm4lh_actor_next'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPMC_DATABASE_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    $context = nhepmc_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'admin', 'buyer', 'order', 'item', 'cart', 'express', 'visit_pages', 'query_cache_key'],
        'NHEPMC_DATABASE_COMPLETE_CONTEXT_EXACT_NINE');
    nhepmc_before_guards($beforeDB2, $intent, $context);
    nhepmc_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhep_expect(nhepar_entry($beforeCapture, $context['query_cache_key']) === null
        && nhepar_entry($actualCapture, $context['query_cache_key']) === null,
        'NHEPMC_DATABASE_EXACT_SOURCE_GUID_CACHE_COLD_BEFORE_AND_AFTER');
    $interval = $privateResponse['actual_interval']; $root = $context['order']['row']; $oid = $root['id'];
    nhep_expect($root['add_time'] <= $interval[0] && $root['pay_time'] <= $interval[0]
        && $context['buyer']['row']['last_time'] <= $interval[0],
        'NHEPMC_DATABASE_EXISTING_BEFORE_TIMES_PRECEDE_REAL_DELIVERY_HTTP');
    $contracts = [
        'eb_system_log' => [
            'id' => ['int unsigned', null], 'admin_id' => ['int unsigned', 0], 'admin_name' => ['varchar(64)', ''],
            'path' => ['varchar(128)', ''], 'page' => ['varchar(64)', ''], 'method' => ['varchar(12)', ''],
            'ip' => ['varchar(16)', ''], 'type' => ['varchar(32)', ''], 'add_time' => ['int unsigned', 0],
            'merchant_id' => ['int unsigned', 0]],
        'eb_store_order_status' => [
            'oid' => ['int unsigned', 0], 'change_type' => ['varchar(32)', ''],
            'change_message' => ['varchar(256)', ''], 'change_time' => ['int unsigned', 0]],
    ];
    foreach ($contracts as $table => $fields) {
        $metadata = $beforeDB2['database']['tables'][$table]['metadata']; $hasId = $table === 'eb_system_log';
        nhep_expect(array_keys($metadata['columns']) === array_keys($fields)
            && $metadata['checks'] === [] && $metadata['foreign'] === [] && $metadata['triggers'] === [],
            'NHEPMC_DATABASE_COMPLETE_NATIVE_LOG_STATUS_COLUMNS_AND_NO_HIDDEN_WRITES');
        foreach ($fields as $column => [$wantedType, $default]) {
            $definition = $metadata['columns'][$column];
            $type = preg_replace('/\A(tinyint|int)(?:\([0-9]+\))?( unsigned)?\z/D', '$1$2', strtolower($definition['COLUMN_TYPE']));
            nhep_expect($type === $wantedType && $definition['COLUMN_NAME'] === $column
                && $definition['IS_NULLABLE'] === 'NO' && $definition['GENERATION_EXPRESSION'] === ''
                && $definition['EXTRA'] === ($hasId && $column === 'id' ? 'auto_increment' : ''),
                'NHEPMC_DATABASE_EACH_ORIGINAL_COLUMN_TYPE_NULLABILITY_AND_EXTRA');
            if ($default === null) nhep_expect($definition['COLUMN_DEFAULT'] === null, 'NHEPMC_DATABASE_AUTO_ID_NULL_DEFAULT');
            else nhep_expect(m4lh_actor_native($definition, $definition['COLUMN_DEFAULT']) === $default,
                'NHEPMC_DATABASE_EACH_ORIGINAL_NATIVE_DEFAULT');
        }
        if ($hasId) nhep_expect(isset($metadata['indexes']['PRIMARY']) && count($metadata['indexes']['PRIMARY']) === 1
            && $metadata['indexes']['PRIMARY'][0]['COLUMN_NAME'] === 'id'
            && (string)$metadata['indexes']['PRIMARY'][0]['NON_UNIQUE'] === '0'
            && (string)$metadata['indexes']['PRIMARY'][0]['SEQ_IN_INDEX'] === '1'
            && count($metadata['constraints']) === 1 && $metadata['constraints'][0]['CONSTRAINT_NAME'] === 'PRIMARY'
            && $metadata['constraints'][0]['CONSTRAINT_TYPE'] === 'PRIMARY KEY',
            'NHEPMC_DATABASE_LOG_HAS_ITS_SINGLE_ORIGINAL_AUTO_PK');
        else nhep_expect($metadata['table']['AUTO_INCREMENT'] === null && !isset($metadata['indexes']['PRIMARY'])
            && $metadata['constraints'] === [], 'NHEPMC_DATABASE_STATUS_HAS_NO_ID_PK_OR_AI');
    }
    nhep_expect($context['order']['metadata']['triggers'] === [] && $context['order']['metadata']['checks'] === []
        && $context['order']['metadata']['foreign'] === [], 'NHEPMC_DATABASE_ROOT_NO_HIDDEN_DATABASE_WRITES');
    $system = $beforeDB2['database']['tables']['eb_system_log'];
    $next = m4lh_actor_next($system, 'id'); nhepcd_id($next, 4294967294);
    foreach ($beforeDB2['rows']['eb_system_log'] as $row)
        nhep_expect($row['id'] !== $next, 'NHEPMC_DATABASE_INDEPENDENT_BEFORE_NEXT_LOG_ID_NOT_ALREADY_USED');
    $index = nhep_auth_db_index($actualDB2['rows']['eb_system_log'], $system['metadata'], 'id', $next);
    $actualLog = $actualDB2['rows']['eb_system_log'][$index];
    $logTime = nhep_auth_db_time($system['metadata'], 'add_time', $actualLog['add_time'], $interval);
    $candidates = [];
    foreach ($context['visit_pages'] as $page) {
        $candidate = m4lh_actor_expected_row($system['metadata'], ['id' => $next,
            'admin_id' => $context['admin']['row']['id'], 'admin_name' => $context['admin']['row']['account'],
            'path' => 'order/delivery/<id>', 'page' => $page, 'method' => 'adminapi',
            'ip' => '127.0.0.1', 'type' => 'system', 'add_time' => $logTime, 'merchant_id' => 0]);
        if ($candidate === $actualLog) $candidates[] = $candidate;
    }
    nhep_expect(count($candidates) === 1, 'NHEPMC_DATABASE_ONE_COMPLETE_INDEPENDENT_LOG_CANDIDATE');
    $statusTimes = [];
    foreach ($actualDB2['rows']['eb_store_order_status'] as $row)
        if ($row['oid'] === $oid && $row['change_type'] === 'delivery_goods') $statusTimes[] = $row['change_time'];
    nhep_expect(count($statusTimes) === 1, 'NHEPMC_DATABASE_ONE_INDEPENDENTLY_NAMED_NEW_DELIVERY_STATUS_TIME');
    $statusMetadata = $beforeDB2['database']['tables']['eb_store_order_status']['metadata'];
    $statusTime = nhep_auth_db_time($statusMetadata, 'change_time', $statusTimes[0], $interval);
    $name = $context['express']['row']['name']; $code = $context['express']['row']['code']; $tracking = 'NHE' . $intent['run_id'];
    $expectedRows = [
        'eb_store_order' => nhep_auth_db_update($beforeDB2, 'eb_store_order', $context['order']['index'], [
            'status' => 1, 'delivery_type' => 'express', 'delivery_name' => $name,
            'delivery_code' => $code, 'delivery_id' => $tracking, 'fictitious_content' => '']),
        'eb_store_order_status' => $beforeDB2['rows']['eb_store_order_status'],
        'eb_system_log' => $beforeDB2['rows']['eb_system_log'],
    ];
    $expectedRows['eb_store_order_status'][] = m4lh_actor_expected_row($statusMetadata, ['oid' => $oid,
        'change_type' => 'delivery_goods', 'change_message' => '已发货 快递公司：' . $name . ' 快递单号：' . $tracking,
        'change_time' => $statusTime]);
    $expectedRows['eb_system_log'][] = $candidates[0];
    $expected = nhep_database_expected($beforeDB2, $expectedRows, ['eb_system_log' => 1]);
    nhep_expect($expected === $actualDB2,
        'NHEPMC_DATABASE_ALL_164_TABLES_ONLY_THREE_DECLARED_DELTAS_ONE_AI_TWO_NATIVE_TIMES');
    return $expected;
}

/** Complete normal28 Redis expected. Final equality is not a claim of no transient remember writes. */
function nhep_manual_courier_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepmc_context', 'nhepmc_before_guards', 'nhepmc_exchange',
        'nhep_auth_db_snapshot', 'nhepar_capture', 'nhepar_entry', 'nhepar_actor', 'nhepar_admin',
        'nhepar_remember', 'nhepar_bind', 'nhepar_tag', 'nhepcr_config_wire', 'nhep_redis_expected',
        'bcadd', 'bcsub', 'bcmul', 'bccomp', 'serialize'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPMC_REDIS_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    $context = nhepmc_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'admin', 'buyer', 'order', 'item', 'cart', 'express', 'visit_pages', 'query_cache_key'],
        'NHEPMC_REDIS_COMPLETE_CONTEXT_EXACT_NINE');
    nhepmc_before_guards($beforeDB2, $intent, $context);
    nhepmc_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhep_expect(nhepar_entry($beforeCapture, $context['query_cache_key']) === null
        && nhepar_entry($actualCapture, $context['query_cache_key']) === null,
        'NHEPMC_REDIS_EXACT_INDEPENDENT_SOURCE_GUID_COLD_BEFORE_AND_AFTER');
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']),
        'NHEPMC_REDIS_SAME_RUN_REAL_PRIVATE_ADMIN_AUTH_CONFIGURATION');
    $actor = nhepar_actor($beforeDB2['rows'], $intent, $privateRequest);
    nhep_expect($actor === $context['admin']['row'], 'NHEPMC_REDIS_REAL_ADMIN_NOT_THE_SAVED_ORDER_BUYER');
    $changes = []; $tagMembers = [];
    nhepar_admin($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);

    $title = $context['cart']['productInfo']['store_name'];
    nhep_expect(is_string($title) && $title === '旧历史商品-' . $intent['run_id'],
        'NHEPMC_REDIS_COMPLETE_INDEPENDENT_SAVED_TRUTHY_TITLE');
    $titleKey = 'c:' . md5('store_order_cart_product_title_' . $context['order']['row']['id']);
    $titleWire = serialize($title); $oldTitle = nhepar_entry($beforeCapture, $titleKey);
    $tag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('crmeb'));
    nhep_expect(is_array($tag) && $tag['type'] === 'set' && $tag['expires'] === -1
        && in_array($titleKey, $tag['value'], true)
        && is_array($oldTitle) && $oldTitle['type'] === 'string' && $oldTitle['expires'] === -1
        && $oldTitle['value'] === $titleWire, 'NHEPMC_REDIS_WARM_COMPLETE_ORIGINAL_TITLE_AND_TAG_MEMBER');
    $titleDescriptor = nhepar_bind($actualCapture, $titleKey, 'string', $titleWire, -1, $beforeCapture['snapshot']);
    nhep_expect($titleDescriptor === $beforeCapture['snapshot']['keys'][hash('sha256', $titleKey)],
        'NHEPMC_REDIS_TITLE_GET_ONLY_NO_RENEWAL_OR_TAG_APPEND');
    foreach (['param_filter_type' => null, 'param_filter_data' => null, 'order_shipping_open' => 0,
        'system_delivery_time' => '7', 'queue_open' => 0] as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    // Empty language tables independently determine all three values. Only these keys may expire/rebuild here.
    $interval = $privateResponse['actual_interval']; $ttlMs = '3600000';
    $getterLower = bcmul((string)$interval[0], '1000', 0);
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire) {
        $key = 'c:' . $name; $old = nhepar_entry($beforeCapture, $key);
        if ($old === null || bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) > 0) {
            nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
            if ($old === null) {
                $new = nhepar_entry($actualCapture, $key);
                $writeMs = bcsub((string)$new['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPMC_REDIS_LANGUAGE_COLD_WRITE_CLOCK_INSIDE_ACTUAL_HTTP_SECONDS_AND_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
        } elseif (bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) === 0
            && nhepar_entry($actualCapture, $key) !== null) {
            // Existing full-namespace algorithm expires only when A > E; E == A is not a rebuild.
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                'NHEPMC_REDIS_LANGUAGE_EQUAL_ACTUAL_DEADLINE_COMPATIBLE_WITH_SERIAL_WARM_GETTER');
            $descriptor = nhepar_bind($actualCapture, $key, 'string', $wire, $old['expires'], $beforeCapture['snapshot']);
            nhep_expect($descriptor === $beforeCapture['snapshot']['keys'][hash('sha256', $key)],
                'NHEPMC_REDIS_EQUAL_DEADLINE_COMPLETE_ORIGINAL_WARM_DESCRIPTOR_NOT_RENEWED');
            $tagMembers[] = $key;
        } else {
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $beforeCapture['snapshot']['time_ms'], 0) >= 0,
                'NHEPMC_REDIS_COMPLETE_BEFORE_LANGUAGE_VALUE_AND_NATURAL_DEADLINE');
            $now = nhepar_entry($actualCapture, $key);
            if ($now === null) {
                nhep_expect(bccomp((string)$old['expires'], bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                    'NHEPMC_REDIS_UNREBUILT_LANGUAGE_CAN_ONLY_EXPIRE_AFTER_A_SERIAL_POSSIBLE_REAL_GETTER');
            } else {
                $changes[$key] = nhepar_bind($actualCapture, $key, 'string', $wire, ['ttl' => 3600], $beforeCapture['snapshot']);
                $writeMs = bcsub((string)$now['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, (string)$old['expires'], 0) > 0
                    && bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPMC_REDIS_NATURAL_REBUILD_STRICTLY_AFTER_OLD_EXPIRY_AND_INSIDE_HTTP_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
            $tagMembers[] = $key;
        }
    }
    // Remember may SET N; again; this model proves full final values/deadlines/membership, not absence of writes.
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'],
        'NHEPMC_REDIS_FULL_NAMESPACE_WITHOUT_QUEUE_COUNTER_NEW_CHANNEL_OR_UNDECLARED_CACHE_DELTA');
    return $expected;
}

function nheptk_context(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_fixture', 'nhepcd_one',
        'nhepcd_id', 'nhepcv_native_row', 'm4lh_actor_native', 'm4lh_actor_expected_row',
        'bccomp', 'json_decode', 'json_encode', 'md5'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPTK_CONTEXT_PURE_DEPENDENCY_REQUIRED');
    nhep_expect(PHP_INT_SIZE === 8, 'NHEPTK_CONTEXT_ORIGINAL_NATIVE_64_BIT');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
