    nhep_expect(array_keys($order['metadata']['columns']) === ['id', 'pid', 'order_id', 'trade_no', 'uid', 'real_name', 'user_phone', 'user_address', 'cart_id', 'freight_price', 'total_num', 'total_price', 'total_postage', 'pay_price', 'pay_postage', 'deduction_price', 'coupon_id', 'coupon_price', 'paid', 'pay_time', 'pay_type', 'add_time', 'status', 'is_stock_up', 'refund_status', 'refund_type', 'refund_express', 'refund_express_name', 'refund_reason_wap_img', 'refund_reason_wap_explain', 'refund_reason_time', 'refund_reason_wap', 'refund_reason', 'refund_price', 'delivery_name', 'delivery_code', 'delivery_type', 'delivery_id', 'kuaidi_label', 'kuaidi_task_id', 'kuaidi_order_id', 'fictitious_content', 'delivery_uid', 'gain_integral', 'use_integral', 'back_integral', 'spread_uid', 'spread_two_uid', 'one_brokerage', 'two_brokerage', 'mark', 'is_del', 'is_cancel', 'unique', 'remark', 'mer_id', 'is_mer_check', 'combination_id', 'pink_id', 'cost', 'seckill_id', 'bargain_id', 'advance_id', 'verify_code', 'store_id', 'shipping_type', 'clerk_id', 'is_channel', 'is_remind', 'is_system_del', 'channel_type', 'province', 'express_dump', 'virtual_type', 'virtual_info', 'pay_uid', 'custom_form', 'staff_id', 'agent_id', 'division_id', 'staff_brokerage', 'agent_brokerage', 'division_brokerage', 'is_gift', 'gift_price', 'gift_uid', 'gift_mark'],
        'NHEPTK_CONTEXT_ORIGINAL_ORDERED_87_ROOT_COLUMNS_FOR_NATIVE_ROWS_AND_QUERY_FIELDS');
    nhep_expect($buyer === $fixture['user'] && $uid === $fixture['uid']
        && $productId === $fixture['product_id'] && $skuId === $fixture['sku_id']
        && $skuUnique === $fixture['sku_unique'] && count($root) === 87 && count($buyerRow) === 55
        && $privateRequest['body'] === ['uni' => $root['order_id']] && $root['fictitious_content'] === '',
