        $definition = $order['metadata']['columns'][$column];
        nhep_expect($definition['IS_NULLABLE'] === 'NO' && $definition['CHARACTER_SET_NAME'] === 'utf8mb4'
            && in_array($definition['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
                'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
            'NHEPTK_CONTEXT_ORIGINAL_DAO_STRING_EQUALITY_FINITE_COLLATIONS');
    }
    foreach ($beforeDB2['rows']['eb_store_order'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_order', $index);
        foreach (['order_id', 'unique'] as $column)
            nhep_expect(is_string($candidate[$column]) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate[$column]) === 1,
                'NHEPTK_CONTEXT_CANONICAL_ASCII_LOOKUP_VALUES_WITHOUT_COLLATION_ALIASES');
        if (strtolower($candidate['unique']) === $root['unique']) $uniqueMatches[] = $index;
        if ($candidate['is_del'] === 0 && ($candidate['uid'] === $uid || $candidate['gift_uid'] === $uid)
            && (strtolower($candidate['order_id']) === $number || strtolower($candidate['unique']) === $number))
            $visible[] = $index;
        nhep_expect($candidate['pid'] !== $oid, 'NHEPTK_CONTEXT_NO_ANY_SPLIT_CHILD_FOR_ORIGINAL_ROOT');
    }
    nhep_expect($visible === [$order['index']] && $uniqueMatches === [$order['index']],
        'NHEPTK_CONTEXT_BOTH_REAL_DAO_ORS_SELECT_ONLY_INDEPENDENT_BEFORE_ROOT');
    $itemMatches = [];
    foreach ($beforeDB2['rows']['eb_store_order_cart_info'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $index);
        nhep_expect(is_string($candidate['unique']) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate['unique']) === 1,
            'NHEPTK_CONTEXT_CANONICAL_SAVED_ITEM_UNIQUE_VALUES');
        if (strtolower($candidate['unique']) === $saved['unique']) $itemMatches[] = $index;
    }
    nhep_expect($itemMatches === [$item['index']], 'NHEPTK_CONTEXT_GLOBAL_UNAMBIGUOUS_ORIGINAL_SAVED_ITEM');
    foreach ($beforeDB2['rows']['eb_store_cart'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_cart', $index);
        nhep_expect($candidate['id'] !== $cartId, 'NHEPTK_CONTEXT_ORIGINAL_PERSISTENT_CART_ALREADY_CONSUMED');
    }
    $expressCode = $beforeDB2['database']['tables']['eb_express']['metadata']['columns']['code'];
    nhep_expect($expressCode['IS_NULLABLE'] === 'NO' && $expressCode['CHARACTER_SET_NAME'] === 'utf8mb4'
        && in_array($expressCode['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
            'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
        'NHEPTK_CONTEXT_EXPRESS_SQL_EQUALITY_SUPPORTED_CHARSET_AND_COLLATION');
    $express = nhepcd_one($beforeDB2, 'eb_express', ['code' => 'shunfeng']);
    $expressRow = nhepcv_native_row($beforeDB2, 'eb_express', $express['index']);
    nhep_expect($expressRow === $express['row'] && $expressRow === m4lh_actor_expected_row($express['metadata'], [
        'id' => nhepcd_id($expressRow['id']), 'code' => 'shunfeng', 'name' => '顺丰速运',
        'partner_id' => 1, 'is_show' => 1, 'status' => 0]),
        'NHEPTK_CONTEXT_COMPLETE_ORIGINAL_EXPRESS_FIXTURE_AND_DEFAULTS');
    foreach ($beforeDB2['rows']['eb_express'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_express', $index);
        nhep_expect(is_string($candidate['code']) && preg_match('/\A[\x20-\x7e]*\z/D', $candidate['code']) === 1
            && (strtolower(rtrim($candidate['code'], ' ')) !== 'shunfeng' || $candidate['code'] === 'shunfeng'),
            'NHEPTK_CONTEXT_NO_SQL_EQUIVALENT_EXPRESS_CODE_ALIAS');
    }
    nhep_expect($root['delivery_name'] === $expressRow['name'] && $root['delivery_code'] === $expressRow['code']
        && $root['delivery_id'] === 'NHE' . $intent['run_id'], 'NHEPTK_CONTEXT_DELIVERY_BOUND_TO_REAL_BEFORE_EXPRESS_FIXTURE');
