    $queryKey = 'c:think:audit_auth.eb_store_order|' . $oid;
    $mutexKey = 'redis:mutex:' . md5('order/take' . $uid);
    return ['family' => $family, 'fixture' => $fixture, 'order' => $order, 'item' => $item,
        'express' => $express, 'cart' => $cart, 'title' => $cart['productInfo']['store_name'],
        'query_cache_key' => $queryKey, 'mutex_key' => $mutexKey];
}

function nheptk_before_guards(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $context): void
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_one', 'nhepcd_id',
        'nhepcv_native_row', 'nhepcv_config', 'nhepcr_config_wire', 'nhep_funding_db_no_outpush',
        'm4lh_actor_expected_row', 'bccomp', 'json_decode', 'json_encode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPTK_GUARDS_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPTK_GUARDS_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'express', 'cart', 'title', 'query_cache_key', 'mutex_key'],
        'NHEPTK_GUARDS_COMPLETE_CONTEXT_EXACT_NINE');
    nhep_expect($context['family'] === 'review_family' && $intent['sequence'] === 30
        && $intent['step'] === 'customer_receipt' && $intent['actor'] === 'customer' && $intent['method'] === 'POST'
        && $intent['origin'] === 'http://127.0.0.1:8000' && $intent['path'] === '/api/order/take'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && $intent['actor_id'] === $context['fixture']['uid'], 'NHEPTK_GUARDS_TRUE_30_AND_ORIGINAL_OWNER');
    nhe_keys($context['fixture'], ['uid', 'user', 'product_id', 'sku_id', 'sku_unique', 'address_id'],
        'NHEPTK_GUARDS_ORIGINAL_CUSTOMER_FIXTURE_EXACT_SIX');
    foreach (['order' => ['eb_store_order', 'id'], 'item' => ['eb_store_order_cart_info', 'id'],
        'express' => ['eb_express', 'id']] as $name => [$table, $pk]) {
        $selection = $context[$name];
        nhe_keys($selection, ['index', 'row', 'metadata'], 'NHEPTK_GUARDS_COMPLETE_BEFORE_ENTITY_SELECTION');
        nhep_expect($selection === nhepcd_one($beforeDB2, $table, [$pk => $selection['row'][$pk]])
            && $selection['row'] === nhepcv_native_row($beforeDB2, $table, $selection['index']),
            'NHEPTK_GUARDS_EVERY_CONTEXT_ENTITY_IS_COMPLETE_ORIGINAL_NATIVE_BEFORE');
    }
    $user = $context['fixture']['user']; $uid = $context['fixture']['uid'];
    nhep_expect($user === nhepcd_one($beforeDB2, 'eb_user', ['uid' => $uid])
        && $user['row'] === nhepcv_native_row($beforeDB2, 'eb_user', $user['index']),
        'NHEPTK_GUARDS_COMPLETE_SAME_BEFORE_AUTHENTICATED_CUSTOMER');
    $root = $context['order']['row']; $oid = $root['id']; $saved = $context['item']['row'];
    $cart = json_decode($saved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $cart === $context['cart']
        && $context['title'] === $cart['productInfo']['store_name'] && $context['title'] === '旧历史商品-' . $intent['run_id']
        && $root['mark'] === $intent['run_id'] . '-review_family' && $root['uid'] === $uid && $root['pay_uid'] === $uid
        && $root['paid'] === 1 && $root['status'] === 1 && $root['refund_status'] === 0 && $root['refund_type'] === 0
        && $root['is_del'] === 0 && $root['pid'] === 0 && $root['shipping_type'] === 1
        && $root['delivery_type'] === 'express' && $root['delivery_name'] === $context['express']['row']['name']
        && $root['delivery_code'] === $context['express']['row']['code'] && $root['delivery_id'] === 'NHE' . $intent['run_id']
        && $saved['oid'] === $oid && $saved['uid'] === $uid && $saved['refund_num'] === 0
        && $context['query_cache_key'] === 'c:think:audit_auth.eb_store_order|' . $oid
        && $context['mutex_key'] === 'redis:mutex:' . md5('order/take' . $uid),
        'NHEPTK_GUARDS_SAVED_CART_REAL_PENDING_RECEIPT_AND_TWO_SOURCE_CACHE_IDENTITIES');
    foreach ($beforeDB2['rows']['eb_store_order_refund'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_order_refund', $index);
        nhep_expect(!($candidate['store_order_id'] === $oid && in_array($candidate['refund_type'], [1, 2, 4, 5], true)
            && $candidate['is_cancel'] === 0), 'NHEPTK_GUARDS_ACTUAL_REFUND_DAO_DOES_NOT_FILTER_IS_DEL');
    }
    $messages = ['cache_key_create_order' => '订单生成', 'pay_success' => '用户付款成功',
        'delivery_goods' => '已发货 快递公司：' . $context['express']['row']['name'] . ' 快递单号：NHE' . $intent['run_id']];
    $logs = [];
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
        $status = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
        if ($status['oid'] !== $oid) continue;
        $type = $status['change_type'];
        nhep_expect(is_string($type) && isset($messages[$type]) && !isset($logs[$type])
            && is_int($status['change_time']) && $status['change_time'] > 0
            && $status === m4lh_actor_expected_row($beforeDB2['database']['tables']['eb_store_order_status']['metadata'],
                ['oid' => $oid, 'change_type' => $type, 'change_message' => $messages[$type], 'change_time' => $status['change_time']]),
            'NHEPTK_GUARDS_THREE_COMPLETE_ORIGINAL_CREATE_PAY_DELIVERY_LOGS_ONLY');
        $logs[$type] = $status['change_time'];
    }
    nhep_expect(count($logs) === 3 && $logs['cache_key_create_order'] >= $root['add_time']
        && $logs['pay_success'] >= $root['pay_time'] && $logs['delivery_goods'] >= $logs['pay_success'],
        'NHEPTK_GUARDS_BEFORE_NATIVE_CREATE_PAY_DELIVERY_CAUSAL_TIMES');
    // The other original family is already refunded; retain it and its complete 24-column refund row.
    $other = nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-refund_family']);
    $otherRoot = nhepcv_native_row($beforeDB2, 'eb_store_order', $other['index']);
    nhep_expect($otherRoot === $other['row'] && $otherRoot['id'] !== $oid && $otherRoot['order_id'] !== $root['order_id']
        && $otherRoot['uid'] === $uid && $otherRoot['pay_uid'] === $uid && $otherRoot['paid'] === 1
        && $otherRoot['status'] === -2 && $otherRoot['refund_status'] === 2 && $otherRoot['refund_type'] === 6
        && $otherRoot['refund_price'] === '20.15' && $otherRoot['pay_price'] === '20.15'
        && $otherRoot['refund_reason_time'] === 0 && $otherRoot['refund_reason_wap_img'] === ''
        && $otherRoot['refund_reason_wap'] === 'normal-refund-' . $intent['run_id']
        && $otherRoot['pid'] === 0 && $otherRoot['is_del'] === 0 && $otherRoot['is_cancel'] === 0,
        'NHEPTK_GUARDS_ORIGINAL_OTHER_FAMILY_ALREADY_COMPLETED_REFUND');
    $otherItem = nhepcd_one($beforeDB2, 'eb_store_order_cart_info', ['oid' => $otherRoot['id']]);
    $otherSaved = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $otherItem['index']);
    $otherCart = json_decode($otherSaved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && is_array($otherCart) && !array_is_list($otherCart)
        && json_encode($otherCart) === $otherSaved['cart_info'] && $otherSaved['uid'] === $uid
        && $otherSaved['refund_num'] === 1 && $otherSaved['cart_num'] === 1
        && $otherRoot['cart_id'] === json_encode([nhepcd_id($otherSaved['cart_id'])]),
        'NHEPTK_GUARDS_KEEP_OTHER_FAMILY_COMPLETE_SAVED_CART_JSON');
    $refund = nhepcd_one($beforeDB2, 'eb_store_order_refund', ['store_order_id' => $otherRoot['id'], 'uid' => $uid]);
    $refundRow = nhepcv_native_row($beforeDB2, 'eb_store_order_refund', $refund['index']);
    nhep_expect(count($refundRow) === 24 && is_string($refundRow['order_id'])
        && preg_match('/\A[1-9][0-9]{0,18}\z/D', $refundRow['order_id']) === 1
        && bccomp($refundRow['order_id'], '9223372036854775807', 0) <= 0
        && is_int($refundRow['add_time']) && $refundRow['add_time'] >= $otherRoot['pay_time']
        && is_int($refundRow['refunded_time']) && $refundRow['refunded_time'] >= $refundRow['add_time']
        && $refundRow['refunded_time'] > 0
        && $refundRow === m4lh_actor_expected_row($refund['metadata'], [
            'id' => nhepcd_id($refundRow['id'], 2147483647), 'store_order_id' => $otherRoot['id'],
            'store_id' => 0, 'order_id' => $refundRow['order_id'], 'uid' => $uid,
            'refund_type' => 6, 'refund_num' => 1, 'refund_price' => '20.15', 'refunded_price' => '20.15',
            'refund_explain' => '', 'refund_img' => '[]', 'refund_reason' => 'normal-refund-' . $intent['run_id'],
            'add_time' => $refundRow['add_time'], 'refunded_time' => $refundRow['refunded_time'],
            'cart_info' => json_encode([$otherCart]), 'is_pink_cancel' => 0]),
        'NHEPTK_GUARDS_COMPLETE_OLD_REFUND_NOT_REPLAYED_OR_RECONSTRUCTED_FROM_AFTER');
    nhep_expect($user['row']['now_money'] === '79.85' && $user['row']['pay_count'] === 2
        && $user['row']['integral'] === 0 && $user['row']['is_money_level'] === 0
        && $user['row']['brokerage_price'] === '0.00' && $user['row']['level'] === 0
        && $beforeDB2['rows']['eb_user_bill'] === [], 'NHEPTK_GUARDS_NORMAL_BALANCE_NO_MEMBERSHIP_OR_TAKE_BILL_WRITES');
    foreach (['combination_id' => 0, 'seckill_id' => 0, 'bargain_id' => 0, 'pink_id' => 0, 'advance_id' => 0,
        'gain_integral' => '0.00', 'staff_id' => 0, 'agent_id' => 0, 'division_id' => 0,
        'staff_brokerage' => '0.00', 'agent_brokerage' => '0.00', 'division_brokerage' => '0.00'] as $field => $wanted)
        nhep_expect($root[$field] === $wanted, 'NHEPTK_GUARDS_ACTUAL_INTEGRAL_AND_DIVISION_BRANCHES_ARE_CLOSED');
    foreach (['station_open' => 1, 'offline_pay_status' => 2, 'order_give_integral' => 0,
        'brokerage_func_status' => 0, 'member_func_status' => 0] as $name => $value)
        nhepcv_config($beforeDB2, $intent, $name, $value);
    foreach (['param_filter_type', 'param_filter_data'] as $name)
        nhep_expect(nhepcr_config_wire($beforeDB2, $name, null) === 'N;', 'NHEPTK_GUARDS_BOTH_REAL_ABSENT_FILTER_CONFIGS');
    foreach (['order_cancel_time', 'order_activity_time', 'order_bargain_time', 'order_seckill_time', 'order_pink_time'] as $name)
        nhepcv_config($beforeDB2, $intent, $name, '0');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($beforeDB2['rows'][$table] === [], 'NHEPTK_GUARDS_ALL_ORIGINAL_LANGUAGE_TABLES_EMPTY');
    nhep_funding_db_no_outpush($beforeDB2);
    foreach ([['eb_system_notification', 'mark', 'order_take'],
        ['eb_system_notification', 'mark', 'send_admin_confirm_take_over'],
        ['eb_system_notification', 'custom_trigger', 'order_take'],
        ['eb_system_event', 'mark', 'order_take']] as [$table, $field, $wanted]) {
        $definition = $beforeDB2['database']['tables'][$table]['metadata']['columns'][$field];
        nhep_expect($definition['CHARACTER_SET_NAME'] === 'utf8mb4'
            && in_array($definition['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
                'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
            'NHEPTK_GUARDS_REAL_TECHNICAL_SELECTOR_CHARSET_AND_FINITE_COLLATIONS');
        foreach ($beforeDB2['rows'][$table] as $index => $unused) {
            $candidate = nhepcv_native_row($beforeDB2, $table, $index); $value = $candidate[$field];
            nhep_expect($value === null || (is_string($value) && preg_match('/\A[\x20-\x7e]*\z/D', $value) === 1
                && (strtolower(rtrim($value, ' ')) !== $wanted || $value === $wanted)),
                'NHEPTK_GUARDS_CANONICAL_COMPLETE_SQL_TECHNICAL_SELECTOR_VALUES');
            if ($value !== $wanted) continue;
            if ($field === 'custom_trigger') {
                foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat'] as $flag)
                    nhep_expect($candidate[$flag] === 0, 'NHEPTK_GUARDS_ALL_MATCHING_CUSTOM_NOTICE_FIVE_CHANNELS_DISABLED');
            } elseif ($table === 'eb_system_event') nhep_expect(!($candidate['is_del'] === 0 && $candidate['is_open'] === 1),
                'NHEPTK_GUARDS_NO_ENABLED_MATCHING_RECEIPT_SCRIPT');
        }
    }
    foreach (['order_take' => 1, 'send_admin_confirm_take_over' => 2] as $mark => $type) {
        $notice = nhepcd_one($beforeDB2, 'eb_system_notification', ['mark' => $mark]);
        nhep_expect($notice['row'] === nhepcv_native_row($beforeDB2, 'eb_system_notification', $notice['index'])
            && $notice['row']['type'] === $type && $notice['row']['name'] === 'normal-' . $intent['run_id']
            && $notice['row']['title'] === 'synthetic normal ' . $intent['run_id'],
            'NHEPTK_GUARDS_UNIQUE_ORIGINAL_RUN_RECEIPT_NOTIFICATION');
        foreach (['is_system', 'is_sms', 'is_wechat', 'is_routine', 'is_ent_wechat', 'is_app'] as $flag)
            nhep_expect($notice['row'][$flag] === 0, 'NHEPTK_GUARDS_ALL_SIX_ORDINARY_NOTICE_CHANNELS_DISABLED');
    }
    foreach ($beforeDB2['rows']['eb_store_service'] as $index => $unused) {
        $service = nhepcv_native_row($beforeDB2, 'eb_store_service', $index);
        nhep_expect(!($service['status'] === 1 && $service['notify'] === 1),
            'NHEPTK_GUARDS_REAL_ADMIN_RECEIPT_KUEFU_QUERY_HAS_NO_CANDIDATES');
    }
}

function nheptk_exchange(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse): void
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepar_capture', 'nhepar_entry', 'bcadd', 'bcmul', 'bccomp', 'json_decode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPTK_EXCHANGE_PURE_DEPENDENCY_REQUIRED');
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPTK_EXCHANGE_ORIGINAL_COMPLETE_INTENT');
    nhep_expect(PHP_INT_SIZE === 8 && $intent['sequence'] === 30 && $intent['step'] === 'customer_receipt'
        && $intent['method'] === 'POST' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && $intent['path'] === '/api/order/take'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1,
        'NHEPTK_EXCHANGE_TRUE_30_CUSTOMER_POST_AND_ORIGIN');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPTK_EXCHANGE_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect(is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['body']) && is_array($privateRequest['actor_identity']),
        'NHEPTK_EXCHANGE_REAL_EXISTING_CUSTOMER_TOKEN_BODY_AND_IDENTITY');
    nhe_keys($privateRequest['body'], ['uni'], 'NHEPTK_EXCHANGE_ORIGINAL_BODY_EXACT_ONE');
    nhep_expect(is_string($privateRequest['body']['uni'])
        && preg_match('/\Acp([1-9][0-9]{0,18})\z/D', $privateRequest['body']['uni'], $cp) === 1
        && bccomp($cp[1], '9223372036854775807', 0) <= 0,
        'NHEPTK_EXCHANGE_CANONICAL_NATIVE_ORIGINAL_CP_REQUEST');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPTK_EXCHANGE_PRIVATE_CUSTOMER_IDENTITY_EXACT_TWO');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 2147483647
        && $privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account'])
        && preg_match('/\A[a-z0-9_]{10,32}\z/D', $privateRequest['actor_identity']['account']) === 1,
        'NHEPTK_EXCHANGE_ORIGINAL_NATIVE_CUSTOMER_IDENTITY');
    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHEPTK_EXCHANGE_COMPLETE_ORIGINAL_PRIVATE_RESPONSE_EXACT_ELEVEN');
    $interval = $privateResponse['actual_interval'];
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $privateResponse['http'] === 200 && $privateResponse['transport_errno'] === 0
        && $privateResponse['transport_failure_class'] === null && $privateResponse['primary_ip'] === '127.0.0.1'
        && $privateResponse['primary_port'] === 8000 && $privateResponse['local_ip'] === '127.0.0.1'
        && is_int($privateResponse['local_port']) && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw']) && $privateResponse['raw'] !== '' && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json']) && !array_is_list($privateResponse['json']) && is_array($privateResponse['headers']),
        'NHEPTK_EXCHANGE_ONE_REAL_LOCAL_SUCCESS_AND_HTTP_SECONDS_INSIDE_SIGNED_TIME_RANGE');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHEPTK_EXCHANGE_ORIGINAL_HEADER_CALLBACK_EXACT_FIVE');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] > 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false
        && count($privateResponse['headers']['blocks']) === 1
        && $privateResponse['headers']['blocks'][0] === $privateResponse['headers']['lines'],
        'NHEPTK_EXCHANGE_ORIGINAL_COMPLETE_NONTRUNCATED_HEADERS');
    $lines = $privateResponse['headers']['lines']; $headerBytes = 0;
    nhep_expect(count($lines) >= 3 && in_array($lines[0], ["HTTP/1.0 200 OK\r\n", "HTTP/1.1 200 OK\r\n"], true)
        && $lines[count($lines) - 1] === "\r\n", 'NHEPTK_EXCHANGE_REAL_STATUS_AND_FINAL_HEADER_CRLF');
    foreach ($lines as $line) {
        nhep_expect(is_string($line) && str_ends_with($line, "\r\n"), 'NHEPTK_EXCHANGE_EVERY_ORIGINAL_HEADER_LINE_COMPLETE');
        $headerBytes += strlen($line);
    }
    nhep_expect($headerBytes === $privateResponse['headers']['bytes'], 'NHEPTK_EXCHANGE_COMPLETE_HEADER_BYTE_SUM');
    $json = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $json === $privateResponse['json'],
        'NHEPTK_EXCHANGE_ORIGINAL_COMPLETE_RAW_JSON_STRICT_JOIN');
    nhe_keys($json, ['status', 'msg'], 'NHEPTK_EXCHANGE_COMPLETE_SUCCESS_EXACT_TWO_WITH_NO_DATA');
    nhep_expect($json === ['status' => 200, 'msg' => '收货成功'],
        'NHEPTK_EXCHANGE_ORIGINAL_CHINESE_RECEIPT_SUCCESS_WITHOUT_DATA');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPTK_EXCHANGE_BOTH_NATIVE_CAPTURES_SAME_ORIGINAL_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $afterUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($afterUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPTK_EXCHANGE_REAL_HTTP_WINDOW_ENCLOSED_BY_MONOTONIC_NATIVE_REDIS_TIME');
}

function nhep_customer_receipt_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse, #[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nheptk_context', 'nheptk_before_guards', 'nheptk_exchange',
        'nhep_auth_db_snapshot', 'nhep_auth_db_index', 'nhep_auth_db_time', 'nhep_auth_db_update',
        'nhep_database_expected', 'nhepcv_native_row', 'nhepar_entry', 'm4lh_actor_native',
        'm4lh_actor_expected_row'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPTK_DATABASE_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    $context = nheptk_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'express', 'cart', 'title', 'query_cache_key', 'mutex_key'],
        'NHEPTK_DATABASE_COMPLETE_CONTEXT_EXACT_NINE');
    nheptk_before_guards($beforeDB2, $intent, $context);
    nheptk_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    foreach (['query_cache_key', 'mutex_key'] as $name)
        nhep_expect(nhepar_entry($beforeCapture, $context[$name]) === null
            && nhepar_entry($actualCapture, $context[$name]) === null,
            'NHEPTK_DATABASE_REAL_LOADED_PK_AND_RAW_MUTEX_COLD_BEFORE_AND_AFTER');
    $interval = $privateResponse['actual_interval']; $root = $context['order']['row']; $oid = $root['id'];
    $user = $context['fixture']['user']; $uid = $context['fixture']['uid'];
    nhep_expect($root['add_time'] <= $interval[0] && $root['pay_time'] <= $interval[0]
        && $user['row']['last_time'] <= $interval[0], 'NHEPTK_DATABASE_ORIGINAL_BEFORE_TIMES_PRECEDE_RECEIPT_HTTP');
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $row)
        if ($row['oid'] === $oid) nhep_expect($row['change_time'] <= $interval[0],
            'NHEPTK_DATABASE_ALL_THREE_ORIGINAL_HISTORY_TIMES_PRECEDE_RECEIPT');
    $table = $beforeDB2['database']['tables']['eb_store_order_status']; $metadata = $table['metadata'];
    $fields = ['oid' => ['int unsigned', 0], 'change_type' => ['varchar(32)', ''],
        'change_message' => ['varchar(256)', ''], 'change_time' => ['int unsigned', 0]];
    nhep_expect(array_keys($metadata['columns']) === array_keys($fields)
        && $metadata['checks'] === [] && $metadata['foreign'] === [] && $metadata['triggers'] === []
        && $metadata['table']['AUTO_INCREMENT'] === null && !isset($metadata['indexes']['PRIMARY'])
        && $metadata['constraints'] === [], 'NHEPTK_DATABASE_COMPLETE_FOUR_COLUMN_STATUS_NO_ID_PK_AI_OR_HIDDEN_WRITES');
    foreach ($fields as $column => [$wantedType, $default]) {
        $definition = $metadata['columns'][$column];
        $type = preg_replace('/\A(tinyint|int)(?:\([0-9]+\))?( unsigned)?\z/D', '$1$2', strtolower($definition['COLUMN_TYPE']));
        nhep_expect($type === $wantedType && $definition['COLUMN_NAME'] === $column
            && $definition['IS_NULLABLE'] === 'NO' && $definition['GENERATION_EXPRESSION'] === ''
            && $definition['EXTRA'] === '' && m4lh_actor_native($definition, $definition['COLUMN_DEFAULT']) === $default,
            'NHEPTK_DATABASE_EACH_STATUS_NATIVE_TYPE_DEFAULT_AND_EXTRA');
    }
    foreach ([$context['order']['metadata'], $user['metadata']] as $definition)
        nhep_expect($definition['triggers'] === [] && $definition['checks'] === [] && $definition['foreign'] === [],
            'NHEPTK_DATABASE_ROOT_AND_USER_HAVE_NO_HIDDEN_DATABASE_WRITES');
    $userIndex = nhep_auth_db_index($actualDB2['rows']['eb_user'], $user['metadata'], 'uid', $uid);
    $authTime = nhep_auth_db_time($user['metadata'], 'last_time',
        $actualDB2['rows']['eb_user'][$userIndex]['last_time'], $interval, $user['row']['last_time']);
    $times = [];
    foreach ($actualDB2['rows']['eb_store_order_status'] as $row)
        if ($row['oid'] === $oid && $row['change_type'] === 'take_delivery') $times[] = $row['change_time'];
    nhep_expect(count($times) === 1, 'NHEPTK_DATABASE_ONE_NAMED_NEW_RECEIPT_STATUS_TIME');
    $statusTime = nhep_auth_db_time($metadata, 'change_time', $times[0], $interval);
    $expectedRows = [
        'eb_user' => nhep_auth_db_update($beforeDB2, 'eb_user', $user['index'], ['last_time' => $authTime]),
        'eb_store_order' => nhep_auth_db_update($beforeDB2, 'eb_store_order', $context['order']['index'], ['status' => 2]),
        'eb_store_order_status' => $beforeDB2['rows']['eb_store_order_status'],
    ];
    $expectedRows['eb_store_order_status'][] = m4lh_actor_expected_row($metadata,
        ['oid' => $oid, 'change_type' => 'take_delivery', 'change_message' => '已收货', 'change_time' => $statusTime]);
    $expected = nhep_database_expected($beforeDB2, $expectedRows);
    nhep_expect($expected === $actualDB2, 'NHEPTK_DATABASE_ALL_164_TABLES_ONLY_THREE_DECLARED_DELTAS_ZERO_AI_TWO_NATIVE_TIMES');
    return $expected;
}

function nhep_customer_receipt_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nheptk_context', 'nheptk_before_guards', 'nheptk_exchange',
        'nhep_auth_db_snapshot', 'nhepar_capture', 'nhepar_entry', 'nhepar_actor', 'nhepar_customer',
        'nhepar_remember', 'nhepar_bind', 'nhepar_tag', 'nhepcr_config_wire', 'nhep_redis_expected',
        'bcadd', 'bcsub', 'bcmul', 'bccomp', 'serialize'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPTK_REDIS_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    $context = nheptk_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'express', 'cart', 'title', 'query_cache_key', 'mutex_key'],
        'NHEPTK_REDIS_COMPLETE_CONTEXT_EXACT_NINE');
    nheptk_before_guards($beforeDB2, $intent, $context);
    nheptk_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    foreach (['query_cache_key', 'mutex_key'] as $name)
        nhep_expect(nhepar_entry($beforeCapture, $context[$name]) === null
            && nhepar_entry($actualCapture, $context[$name]) === null,
            'NHEPTK_REDIS_LOADED_ROOT_PK_AND_RAW_NO_TTL_MUTEX_COLD_BEFORE_AND_AFTER');
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']),
        'NHEPTK_REDIS_SAME_RUN_REAL_PRIVATE_CUSTOMER_AUTH_CONFIGURATION');
    $actor = nhepar_actor($beforeDB2['rows'], $intent, $privateRequest);
    nhep_expect($actor === $context['fixture']['user']['row'], 'NHEPTK_REDIS_REAL_SAME_COMPLETE_BEFORE_CUSTOMER');
    $changes = []; $tagMembers = [];
    $apiTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('api'));
    nhep_expect(is_array($apiTag) && $apiTag['type'] === 'set' && $apiTag['expires'] === -1
        && in_array('c:' . md5($privateRequest['token']), $apiTag['value'], true),
        'NHEPTK_REDIS_REAL_EXISTING_CUSTOMER_WHITELIST_API_TAG_MEMBERSHIP');
    nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);

    $title = $context['title'];
    nhep_expect(is_string($title) && $title === '旧历史商品-' . $intent['run_id'],
        'NHEPTK_REDIS_COMPLETE_INDEPENDENT_SAVED_TRUTHY_TITLE');
    $titleKey = 'c:' . md5('store_order_cart_product_title_' . $context['order']['row']['id']);
    $titleWire = serialize($title); $oldTitle = nhepar_entry($beforeCapture, $titleKey);
    $tag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('crmeb'));
    nhep_expect(is_array($tag) && $tag['type'] === 'set' && $tag['expires'] === -1
        && in_array($titleKey, $tag['value'], true)
        && is_array($oldTitle) && $oldTitle['type'] === 'string' && $oldTitle['expires'] === -1
        && $oldTitle['value'] === $titleWire, 'NHEPTK_REDIS_WARM_COMPLETE_ORIGINAL_TITLE_AND_TAG_MEMBER');
    $titleDescriptor = nhepar_bind($actualCapture, $titleKey, 'string', $titleWire, -1, $beforeCapture['snapshot']);
    nhep_expect($titleDescriptor === $beforeCapture['snapshot']['keys'][hash('sha256', $titleKey)],
        'NHEPTK_REDIS_TITLE_GET_ONLY_NO_RENEWAL_OR_TAG_APPEND');
    foreach (['station_open' => 1, 'param_filter_type' => null, 'param_filter_data' => null,
        'offline_pay_status' => 2, 'order_give_integral' => 0, 'brokerage_func_status' => 0,
        'member_func_status' => 0] as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    $cancel = ['order_cancel_time' => '0', 'order_activity_time' => '0', 'order_bargain_time' => '0',
        'order_seckill_time' => '0', 'order_pink_time' => '0'];
    foreach ($cancel as $name => $value)
        nhep_expect(nhepcr_config_wire($beforeDB2, $name, $value) === '0', 'NHEPTK_REDIS_FIVE_ORIGINAL_CANCEL_JSON_STRINGS');
    nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . md5(implode(',', array_keys($cancel))),
        serialize($cancel), 0, $changes, $tagMembers);
    // Empty language tables independently determine all three values. Only these keys may expire/rebuild here.
    $interval = $privateResponse['actual_interval']; $ttlMs = '3600000';
    $getterLower = bcmul((string)$interval[0], '1000', 0);
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire) {
        $key = 'c:' . $name; $old = nhepar_entry($beforeCapture, $key);
        if ($old === null || bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) > 0) {
            nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
            if ($old === null) {
                $new = nhepar_entry($actualCapture, $key);
                $writeMs = bcsub((string)$new['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPTK_REDIS_LANGUAGE_COLD_WRITE_CLOCK_INSIDE_ACTUAL_HTTP_SECONDS_AND_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
        } elseif (bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) === 0
            && nhepar_entry($actualCapture, $key) !== null) {
            // Existing full-namespace algorithm expires only when A > E; E == A is not a rebuild.
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                'NHEPTK_REDIS_LANGUAGE_EQUAL_ACTUAL_DEADLINE_COMPATIBLE_WITH_SERIAL_WARM_GETTER');
            $descriptor = nhepar_bind($actualCapture, $key, 'string', $wire, $old['expires'], $beforeCapture['snapshot']);
            nhep_expect($descriptor === $beforeCapture['snapshot']['keys'][hash('sha256', $key)],
                'NHEPTK_REDIS_EQUAL_DEADLINE_COMPLETE_ORIGINAL_WARM_DESCRIPTOR_NOT_RENEWED');
            $tagMembers[] = $key;
        } else {
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $beforeCapture['snapshot']['time_ms'], 0) >= 0,
                'NHEPTK_REDIS_COMPLETE_BEFORE_LANGUAGE_VALUE_AND_NATURAL_DEADLINE');
            $now = nhepar_entry($actualCapture, $key);
            if ($now === null) {
                nhep_expect(bccomp((string)$old['expires'], bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                    'NHEPTK_REDIS_UNREBUILT_LANGUAGE_CAN_ONLY_EXPIRE_AFTER_A_SERIAL_POSSIBLE_REAL_GETTER');
            } else {
                $changes[$key] = nhepar_bind($actualCapture, $key, 'string', $wire, ['ttl' => 3600], $beforeCapture['snapshot']);
                $writeMs = bcsub((string)$now['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, (string)$old['expires'], 0) > 0
                    && bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPTK_REDIS_NATURAL_REBUILD_STRICTLY_AFTER_OLD_EXPIRY_AND_INSIDE_HTTP_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
            $tagMembers[] = $key;
        }
    }
    // Remember may SET N; again; this model proves full final values/deadlines/membership, not absence of writes.
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'],
        'NHEPTK_REDIS_FULL_NAMESPACE_WITHOUT_QUEUE_COUNTER_NEW_CHANNEL_OR_UNDECLARED_CACHE_DELTA');
    return $expected;
}

function nhepcm_context(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_fixture', 'nhepcd_one',
        'nhepcd_id', 'nhepcv_native_row', 'm4lh_actor_native', 'm4lh_actor_expected_row', 'm4lh_actor_next',
        'bccomp', 'json_decode', 'json_encode', 'md5', 'serialize', 'var_export'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPCM_CONTEXT_PURE_DEPENDENCY_REQUIRED');
    nhep_expect(PHP_INT_SIZE === 8, 'NHEPCM_CONTEXT_ORIGINAL_NATIVE_64_BIT');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPCM_CONTEXT_ORIGINAL_COMPLETE_INTENT');
    nhep_expect($intent['sequence'] === 32 && $intent['step'] === 'customer_purchased_item_comment'
        && $intent['method'] === 'POST' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && $intent['path'] === '/api/order/comment'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1,
        'NHEPCM_CONTEXT_TRUE_32_CUSTOMER_ORIGINAL_POST_AND_ORIGIN');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPCM_CONTEXT_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect(is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['body']) && is_array($privateRequest['actor_identity']),
        'NHEPCM_CONTEXT_EXISTING_CUSTOMER_TOKEN_NATIVE_BODY_AND_IDENTITY');
    nhe_keys($privateRequest['body'], ['unique', 'comment', 'pics', 'product_score', 'service_score'],
        'NHEPCM_CONTEXT_ORIGINAL_POST_BODY_EXACT_FIVE');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPCM_CONTEXT_CUSTOMER_IDENTITY_EXACT_TWO');
    $fixture = nhepcd_fixture($beforeDB2, $intent, $privateRequest);
    $uid = $fixture['uid'];
    $family = 'review_family';
    $order = nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-' . $family]);
    $root = nhepcv_native_row($beforeDB2, 'eb_store_order', $order['index']);
    $oid = nhepcd_id($root['id'], 2147483647); $uid = nhepcd_id($root['uid'], 2147483647);
    nhep_expect($root === $order['row'] && nhepcd_one($beforeDB2, 'eb_store_order', ['id' => $oid]) === $order
        && $root['uid'] === $uid && $root['pay_uid'] === $uid && $root['paid'] === 1
        && $root['pay_type'] === 'yue' && $root['channel_type'] === 'h5'
        && is_string($root['order_id']) && preg_match('/\Acp([1-9][0-9]{0,18})\z/D', $root['order_id'], $cp) === 1
        && bccomp($cp[1], '9223372036854775807', 0) <= 0
        && is_string($root['unique']) && preg_match('/\A[1-9][0-9]{0,18}\z/D', $root['unique']) === 1
        && bccomp($root['unique'], '9223372036854775807', 0) <= 0,
        'NHEPCM_CONTEXT_BEFORE_RUN_ROOT_PK_BUYER_PAY_OWNER_AND_SAVED_KEYS');
    foreach (['pid' => 0, 'mer_id' => 0, 'status' => 2, 'refund_status' => 0, 'refund_type' => 0,
        'is_del' => 0, 'is_system_del' => 0, 'is_cancel' => 0, 'is_stock_up' => 0,
        'shipping_type' => 1, 'total_num' => 1, 'store_id' => 0, 'delivery_uid' => 0, 'clerk_id' => 0,
        'is_channel' => 2, 'virtual_type' => 0, 'is_gift' => 0, 'gift_uid' => 0,
        'combination_id' => 0, 'pink_id' => 0, 'seckill_id' => 0, 'bargain_id' => 0, 'advance_id' => 0,
        'coupon_id' => 0, 'spread_uid' => 0, 'spread_two_uid' => 0, 'staff_id' => 0, 'agent_id' => 0, 'division_id' => 0,
        'verify_code' => '', 'delivery_type' => 'express', 'delivery_id' => 'NHE' . $intent['run_id'],
        'delivery_name' => '顺丰速运', 'delivery_code' => 'shunfeng',
        'gift_mark' => '', 'custom_form' => '[]', 'refund_express' => '', 'refund_express_name' => '',
        'refund_reason_wap_img' => '', 'refund_reason_wap_explain' => '', 'refund_reason_time' => 0, 'refund_reason_wap' => '',
        'total_price' => '20.15', 'pay_price' => '20.15', 'cost' => '7.45', 'freight_price' => '0.00',
        'total_postage' => '0.00', 'pay_postage' => '0.00', 'deduction_price' => '0.00', 'coupon_price' => '0.00',
        'gift_price' => '0.00', 'refund_price' => '0.00', 'use_integral' => '0.00', 'gain_integral' => '0.00',
        'back_integral' => '0.00', 'one_brokerage' => '0.00', 'two_brokerage' => '0.00',
        'staff_brokerage' => '0.00', 'agent_brokerage' => '0.00', 'division_brokerage' => '0.00'] as $column => $value)
