        && $root['fictitious_content'] === '', 'NHEPCM_CONTEXT_REAL_CUSTOMER_FIXTURE_AND_COMPLETE_RECEIVED_ROOT');
    $body = ['unique' => $saved['unique'], 'comment' => 'normal-history-' . $intent['run_id'],
        'pics' => '', 'product_score' => 5, 'service_score' => 5];
    nhep_expect($privateRequest['body'] === $body, 'NHEPCM_CONTEXT_ALL_FIVE_BODY_VALUES_FROM_BEFORE_SAVED_ITEM_AND_RUN');
    $uniqueColumn = $item['metadata']['columns']['unique'];
    nhep_expect($uniqueColumn['IS_NULLABLE'] === 'NO' && $uniqueColumn['CHARACTER_SET_NAME'] === 'utf8mb4'
        && in_array($uniqueColumn['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
            'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
        'NHEPCM_CONTEXT_ORIGINAL_GLOBAL_ITEM_SQL_EQUALITY_FINITE_COLLATIONS');
    $itemMatches = [];
    foreach ($beforeDB2['rows']['eb_store_order_cart_info'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $index);
        nhep_expect(is_string($candidate['unique']) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate['unique']) === 1,
            'NHEPCM_CONTEXT_GLOBAL_CANONICAL_ITEM_UNIQUE_WITHOUT_SQL_COLLATION_ALIASES');
        if (strtolower($candidate['unique']) === $saved['unique']) $itemMatches[] = $index;
    }
    nhep_expect($itemMatches === [$item['index']], 'NHEPCM_CONTEXT_REAL_GLOBAL_GETONE_SELECTS_ONLY_INDEPENDENT_SAVED_ITEM');
    foreach ($beforeDB2['rows']['eb_store_cart'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_cart', $index);
        nhep_expect($candidate['id'] !== $cartId, 'NHEPCM_CONTEXT_ORIGINAL_PERSISTENT_CART_ALREADY_CONSUMED');
    }
    foreach ($beforeDB2['rows']['eb_store_order_invoice'] as $index => $unused) {
        $invoice = nhepcv_native_row($beforeDB2, 'eb_store_order_invoice', $index);
        nhep_expect($invoice['order_id'] !== $oid, 'NHEPCM_CONTEXT_ORIGINAL_NORMAL_ROOT_WITHOUT_INVOICE');
    }
    $replyTable = $beforeDB2['database']['tables']['eb_store_product_reply'];
    $idColumn = $replyTable['metadata']['columns']['id'];
    nhep_expect(preg_match('/\Aint(?:\([0-9]+\))?\z/D', strtolower($idColumn['COLUMN_TYPE'])) === 1
        && $idColumn['IS_NULLABLE'] === 'NO' && $idColumn['COLUMN_DEFAULT'] === null
        && $idColumn['GENERATION_EXPRESSION'] === '' && $idColumn['EXTRA'] === 'auto_increment',
        'NHEPCM_CONTEXT_ORIGINAL_SIGNED_REPLY_AUTO_ID');
    $replyId = m4lh_actor_next($replyTable, 'id');
    nhep_expect(is_int($replyId) && $replyId > 0 && $replyId <= 2147483647
        && m4lh_actor_native($idColumn, $replyId) === $replyId, 'NHEPCM_CONTEXT_REPLY_ID_ONLY_BEFORE_NATIVE_SIGNED_NEXT_PK');
    $replyUnique = $replyTable['metadata']['columns']['unique'];
    nhep_expect($replyUnique['IS_NULLABLE'] === 'NO' && $replyUnique['CHARACTER_SET_NAME'] === 'utf8mb4'
        && in_array($replyUnique['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
            'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
        'NHEPCM_CONTEXT_REAL_REPLY_BE_SQL_EQUALITY_SUPPORTED_COLLATIONS');
    $orderCount = 0; $inventoryCount = 0; $commentCount = 0; $extractCount = 0;
    foreach ($beforeDB2['rows']['eb_store_order'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_order', $index);
        nhep_expect($candidate['pid'] !== $oid, 'NHEPCM_CONTEXT_NO_ANY_SPLIT_CHILD_FOR_ORIGINAL_REVIEW_ROOT');
        if ($candidate['paid'] === 1 && $candidate['status'] === 0 && in_array($candidate['refund_status'], [0, 3], true)
            && $candidate['shipping_type'] === 1 && $candidate['is_del'] === 0) {
            nhep_expect($orderCount < PHP_INT_MAX, 'NHEPCM_CONTEXT_ORDER_COUNT_NATIVE_INTEGER_RANGE'); ++$orderCount;
        }
    }
    foreach ($beforeDB2['rows']['eb_store_product'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_product', $index);
        if ($candidate['is_show'] === 1 && $candidate['is_del'] === 0 && $candidate['stock'] > 0) {
            nhep_expect($inventoryCount < PHP_INT_MAX, 'NHEPCM_CONTEXT_INVENTORY_COUNT_NATIVE_INTEGER_RANGE'); ++$inventoryCount;
        }
    }
    foreach ($beforeDB2['rows']['eb_store_product_reply'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_store_product_reply', $index);
        nhep_expect($candidate['id'] !== $replyId && is_string($candidate['unique'])
            && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate['unique']) === 1,
            'NHEPCM_CONTEXT_NEXT_REPLY_PK_ABSENT_AND_CANONICAL_EXISTING_UNIQUE_VALUES');
        nhep_expect(!($candidate['oid'] === $oid && strtolower($candidate['unique']) === $saved['unique']),
            'NHEPCM_CONTEXT_REAL_BE_HAS_NO_PREVIOUS_REPLY_WITHOUT_STATUS_OR_DELETE_FILTER');
        if ($candidate['is_reply'] === 0) {
            nhep_expect($commentCount < PHP_INT_MAX, 'NHEPCM_CONTEXT_EXISTING_COMMENT_COUNT_NATIVE_INTEGER_RANGE'); ++$commentCount;
        }
    }
    // The independent new complete reply has native default is_reply=0 even while status=0 (pending).
    nhep_expect($commentCount < PHP_INT_MAX, 'NHEPCM_CONTEXT_NEW_PENDING_REPLY_ADDS_EXACTLY_ONE_NATIVE_COMMENT'); ++$commentCount;
    foreach ($beforeDB2['rows']['eb_user_extract'] as $index => $unused) {
        $candidate = nhepcv_native_row($beforeDB2, 'eb_user_extract', $index);
        if ($candidate['status'] === 0) {
            nhep_expect($extractCount < PHP_INT_MAX, 'NHEPCM_CONTEXT_EXTRACT_COUNT_NATIVE_INTEGER_RANGE'); ++$extractCount;
        }
    }
    $total = 0;
    foreach ([$orderCount, $inventoryCount, $commentCount, $extractCount] as $count) {
        nhep_expect(is_int($count) && $count >= 0 && $count <= PHP_INT_MAX - $total,
            'NHEPCM_CONTEXT_ALL_REAL_COUNTERS_AND_SUM_NATIVE_INTEGERS_WITHOUT_OVERFLOW');
        $total += $count;
    }
    $packet = ['channel' => 'crmeb', 'data' => ['type' => 'ADMIN_NEW_PUSH', 'data' => [
        'ordernum' => $orderCount, 'inventory' => $inventoryCount, 'commentnum' => $commentCount,
        'reflectnum' => $extractCount, 'msgcount' => $total]]];
    $options = ['json' => [], 'json_assoc' => false, 'field_type' => [],
        'where' => ['AND' => [['id', '=', $oid], ['status', '=', 2]]], 'strict' => false,
        'cache' => [true, null, null], 'key' => null, 'field' => array_keys($order['metadata']['columns']),
        'data' => ['status' => 3], 'table' => 'eb_store_order', 'order' => [], 'join' => [], 'union' => [],
        'master' => true, 'lock' => false, 'fetch_sql' => false, 'array' => false, 'distinct' => false,
        'procedure' => false, 'group' => '', 'having' => '', 'limit' => '', 'force' => '', 'comment' => '',
        'partition' => '', 'duplicate' => '', 'extra' => ''];
    $queryKey = 'c:' . md5('audit_auth' . serialize(var_export($options, true)) . serialize([]));
    return ['family' => $family, 'fixture' => $fixture, 'order' => $order, 'item' => $item, 'cart' => $cart,
        'reply_id' => $replyId, 'query_cache_key' => $queryKey, 'channel_packet' => $packet];
}

function nhepcm_before_guards(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $context): void
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_one', 'nhepcd_id',
        'nhepcv_native_row', 'nhepcv_config', 'nhepcr_config_wire', 'm4lh_actor_expected_row',
        'bccomp', 'json_decode', 'json_encode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPCM_GUARDS_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPCM_GUARDS_ORIGINAL_COMPLETE_INTENT');
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'cart', 'reply_id', 'query_cache_key', 'channel_packet'],
        'NHEPCM_GUARDS_COMPLETE_CONTEXT_EXACT_EIGHT');
    nhep_expect($context['family'] === 'review_family' && $intent['sequence'] === 32
        && $intent['step'] === 'customer_purchased_item_comment' && $intent['actor'] === 'customer'
        && $intent['method'] === 'POST' && $intent['origin'] === 'http://127.0.0.1:8000'
        && $intent['path'] === '/api/order/comment' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && $intent['actor_id'] === $context['fixture']['uid'] && is_int($context['reply_id'])
        && $context['reply_id'] > 0 && $context['reply_id'] <= 2147483647
        && is_string($context['query_cache_key']) && preg_match('/\Ac:[a-f0-9]{32}\z/D', $context['query_cache_key']) === 1,
        'NHEPCM_GUARDS_TRUE_32_BEFORE_OWNER_SIGNED_REPLY_ID_AND_EXACT_GUID_SHAPE');
    nhe_keys($context['fixture'], ['uid', 'user', 'product_id', 'sku_id', 'sku_unique', 'address_id'],
        'NHEPCM_GUARDS_ORIGINAL_CUSTOMER_FIXTURE_EXACT_SIX');
    foreach (['order' => ['eb_store_order', 'id'], 'item' => ['eb_store_order_cart_info', 'id']] as $name => [$table, $pk]) {
        $selection = $context[$name];
        nhe_keys($selection, ['index', 'row', 'metadata'], 'NHEPCM_GUARDS_COMPLETE_BEFORE_ENTITY_SELECTION');
        nhep_expect($selection === nhepcd_one($beforeDB2, $table, [$pk => $selection['row'][$pk]])
            && $selection['row'] === nhepcv_native_row($beforeDB2, $table, $selection['index']),
            'NHEPCM_GUARDS_CONTEXT_ENTITIES_ARE_COMPLETE_ORIGINAL_NATIVE_BEFORE');
    }
    $user = $context['fixture']['user']; $uid = $context['fixture']['uid'];
    nhep_expect($user === nhepcd_one($beforeDB2, 'eb_user', ['uid' => $uid])
        && $user['row'] === nhepcv_native_row($beforeDB2, 'eb_user', $user['index'])
        && $user['row']['now_money'] === '79.85' && $user['row']['pay_count'] === 2,
        'NHEPCM_GUARDS_COMPLETE_SAME_BEFORE_CUSTOMER_AND_ORIGINAL_TWO_PAYMENTS_ONE_REFUND_BALANCE');
    $root = $context['order']['row']; $oid = $root['id']; $saved = $context['item']['row'];
    $cart = json_decode($saved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $cart === $context['cart']
        && $root['mark'] === $intent['run_id'] . '-review_family' && $root['uid'] === $uid && $root['pay_uid'] === $uid
        && $root['paid'] === 1 && $root['status'] === 2 && $root['refund_status'] === 0 && $root['refund_type'] === 0
        && $root['pid'] === 0 && $root['is_del'] === 0 && $root['is_gift'] === 0 && $root['gift_uid'] === 0
        && $root['delivery_type'] === 'express' && $root['delivery_name'] === '顺丰速运'
        && $root['delivery_code'] === 'shunfeng' && $root['delivery_id'] === 'NHE' . $intent['run_id']
        && $saved['oid'] === $oid && $saved['uid'] === $uid && $saved['refund_num'] === 0
        && $saved['product_id'] === $context['fixture']['product_id']
        && $cart['productInfo']['attrInfo']['suk'] === '普通',
        'NHEPCM_GUARDS_COMPLETE_SAVED_HISTORY_AND_NORMAL_RECEIVED_OWNED_ITEM');
    $messages = ['cache_key_create_order' => '订单生成', 'pay_success' => '用户付款成功',
        'delivery_goods' => '已发货 快递公司：顺丰速运 快递单号：NHE' . $intent['run_id'], 'take_delivery' => '已收货'];
    $logs = [];
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
        $status = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
        if ($status['oid'] !== $oid) continue;
        $type = $status['change_type'];
        nhep_expect(is_string($type) && isset($messages[$type]) && !isset($logs[$type])
            && is_int($status['change_time']) && $status['change_time'] > 0 && $status['change_time'] <= 2147483647
            && $status === m4lh_actor_expected_row($beforeDB2['database']['tables']['eb_store_order_status']['metadata'],
                ['oid' => $oid, 'change_type' => $type, 'change_message' => $messages[$type], 'change_time' => $status['change_time']]),
            'NHEPCM_GUARDS_EXACT_FOUR_COMPLETE_ORIGINAL_HISTORY_LOGS');
        $logs[$type] = $status['change_time'];
    }
    nhep_expect(count($logs) === 4 && $logs['cache_key_create_order'] >= $root['add_time']
        && $logs['cache_key_create_order'] <= $logs['pay_success'] && $logs['pay_success'] >= $root['pay_time']
        && $logs['pay_success'] <= $logs['delivery_goods'] && $logs['delivery_goods'] <= $logs['take_delivery'],
        'NHEPCM_GUARDS_FOUR_INDEPENDENT_NATIVE_HISTORY_TIMES_HAVE_ORIGINAL_CAUSAL_ORDER');
    // The other original family is already refunded; retain it and its complete 24-column refund row.
    $other = nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-refund_family']);
    $otherRoot = nhepcv_native_row($beforeDB2, 'eb_store_order', $other['index']);
    nhep_expect($otherRoot === $other['row'] && $otherRoot['id'] !== $oid && $otherRoot['order_id'] !== $root['order_id']
        && $otherRoot['uid'] === $uid && $otherRoot['pay_uid'] === $uid && $otherRoot['paid'] === 1
        && $otherRoot['status'] === -2 && $otherRoot['refund_status'] === 2 && $otherRoot['refund_type'] === 6
        && $otherRoot['refund_price'] === '20.15' && $otherRoot['pay_price'] === '20.15'
        && $otherRoot['refund_reason_time'] === 0 && $otherRoot['refund_reason_wap_img'] === ''
        && $otherRoot['refund_reason_wap'] === 'normal-refund-' . $intent['run_id']
        && $otherRoot['pid'] === 0 && $otherRoot['is_del'] === 0 && $otherRoot['is_cancel'] === 0,
        'NHEPCM_GUARDS_ORIGINAL_OTHER_FAMILY_ALREADY_COMPLETED_REFUND');
    $otherItem = nhepcd_one($beforeDB2, 'eb_store_order_cart_info', ['oid' => $otherRoot['id']]);
    $otherSaved = nhepcv_native_row($beforeDB2, 'eb_store_order_cart_info', $otherItem['index']);
    $otherCart = json_decode($otherSaved['cart_info'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && is_array($otherCart) && !array_is_list($otherCart)
        && json_encode($otherCart) === $otherSaved['cart_info'] && $otherSaved['uid'] === $uid
        && $otherSaved['refund_num'] === 1 && $otherSaved['cart_num'] === 1
        && $otherRoot['cart_id'] === json_encode([nhepcd_id($otherSaved['cart_id'])]),
        'NHEPCM_GUARDS_KEEP_OTHER_FAMILY_COMPLETE_SAVED_CART_JSON');
    $refund = nhepcd_one($beforeDB2, 'eb_store_order_refund', ['store_order_id' => $otherRoot['id'], 'uid' => $uid]);
    $refundRow = nhepcv_native_row($beforeDB2, 'eb_store_order_refund', $refund['index']);
    nhep_expect(count($refundRow) === 24 && is_string($refundRow['order_id'])
        && preg_match('/\A[1-9][0-9]{0,18}\z/D', $refundRow['order_id']) === 1
        && bccomp($refundRow['order_id'], '9223372036854775807', 0) <= 0
        && is_int($refundRow['add_time']) && $refundRow['add_time'] >= $otherRoot['pay_time']
        && is_int($refundRow['refunded_time']) && $refundRow['refunded_time'] >= $refundRow['add_time']
        && $refundRow['refunded_time'] > 0
        && $refundRow === m4lh_actor_expected_row($refund['metadata'], [
            'id' => nhepcd_id($refundRow['id'], 2147483647), 'store_order_id' => $otherRoot['id'],
            'store_id' => 0, 'order_id' => $refundRow['order_id'], 'uid' => $uid,
            'refund_type' => 6, 'refund_num' => 1, 'refund_price' => '20.15', 'refunded_price' => '20.15',
            'refund_explain' => '', 'refund_img' => '[]', 'refund_reason' => 'normal-refund-' . $intent['run_id'],
            'add_time' => $refundRow['add_time'], 'refunded_time' => $refundRow['refunded_time'],
            'cart_info' => json_encode([$otherCart]), 'is_pink_cancel' => 0]),
        'NHEPCM_GUARDS_COMPLETE_OLD_REFUND_NOT_REPLAYED_OR_RECONSTRUCTED_FROM_AFTER');
    foreach (['station_open' => 1, 'product_reply_examine' => 1] as $name => $value)
        nhepcv_config($beforeDB2, $intent, $name, $value);
    foreach (['param_filter_type', 'param_filter_data'] as $name)
        nhep_expect(nhepcr_config_wire($beforeDB2, $name, null) === 'N;', 'NHEPCM_GUARDS_BOTH_REAL_ABSENT_PARAMETER_FILTERS');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($beforeDB2['rows'][$table] === [], 'NHEPCM_GUARDS_COMPLETE_THREE_LANGUAGE_TABLES_EMPTY');
    foreach (['eb_luck_lottery', 'eb_luck_lottery_record', 'eb_luck_prize'] as $table)
        nhep_expect($beforeDB2['rows'][$table] === [], 'NHEPCM_GUARDS_BOTH_REAL_FACTOR_QUERIES_EMPTY_WITHOUT_FAKE_IS_USE_FILTER');
    $definition = $beforeDB2['database']['tables']['eb_system_event']['metadata']['columns']['mark'];
    nhep_expect($definition['CHARACTER_SET_NAME'] === 'utf8mb4'
        && in_array($definition['COLLATION_NAME'], ['utf8mb4_0900_ai_ci', 'utf8mb4_general_ci',
            'utf8mb4_unicode_ci', 'utf8mb4_unicode_520_ci', 'utf8mb4_bin'], true),
        'NHEPCM_GUARDS_CUSTOM_EVENT_SQL_EQUALITY_FINITE_COLLATIONS');
    foreach ($beforeDB2['rows']['eb_system_event'] as $index => $unused) {
        $event = nhepcv_native_row($beforeDB2, 'eb_system_event', $index); $value = $event['mark'];
        nhep_expect($value === null || (is_string($value) && preg_match('/\A[\x20-\x7e]*\z/D', $value) === 1
            && (strtolower(rtrim($value, ' ')) !== 'order_comment' || $value === 'order_comment')),
            'NHEPCM_GUARDS_CANONICAL_REAL_CUSTOM_EVENT_MARKS_WITHOUT_SQL_ALIASES');
        nhep_expect(!($value === 'order_comment' && $event['is_del'] === 0 && $event['is_open'] === 1),
            'NHEPCM_GUARDS_NO_ACTUAL_ENABLED_ORDER_COMMENT_SCRIPT');
    }
    nhe_keys($context['channel_packet'], ['channel', 'data'], 'NHEPCM_GUARDS_COMPLETE_CHANNEL_PACKET');
    nhe_keys($context['channel_packet']['data'], ['type', 'data'], 'NHEPCM_GUARDS_COMPLETE_CHANNEL_MESSAGE');
    nhe_keys($context['channel_packet']['data']['data'], ['ordernum', 'inventory', 'commentnum', 'reflectnum', 'msgcount'],
        'NHEPCM_GUARDS_COMPLETE_FIVE_ORDERED_COUNTERS');
    nhep_expect($context['channel_packet']['channel'] === 'crmeb'
        && $context['channel_packet']['data']['type'] === 'ADMIN_NEW_PUSH', 'NHEPCM_GUARDS_REAL_CHANNEL_AND_EVENT');
    foreach ($context['channel_packet']['data']['data'] as $value)
        nhep_expect(is_int($value) && $value >= 0, 'NHEPCM_GUARDS_ALL_CHANNEL_COUNTERS_NATIVE_NONNEGATIVE_INTEGERS');
}

function nhepcm_exchange(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepar_capture', 'nhepar_entry', 'bcadd', 'bcmul', 'bccomp', 'json_decode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPCM_EXCHANGE_PURE_DEPENDENCY_REQUIRED');
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPCM_EXCHANGE_ORIGINAL_COMPLETE_INTENT');
    nhep_expect(PHP_INT_SIZE === 8 && $intent['sequence'] === 32 && $intent['step'] === 'customer_purchased_item_comment'
        && $intent['method'] === 'POST' && $intent['actor'] === 'customer'
        && $intent['origin'] === 'http://127.0.0.1:8000' && $intent['path'] === '/api/order/comment'
        && is_string($intent['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1,
        'NHEPCM_EXCHANGE_TRUE_32_CUSTOMER_POST_AND_ORIGIN');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPCM_EXCHANGE_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect(is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && is_array($privateRequest['body']) && is_array($privateRequest['actor_identity']),
        'NHEPCM_EXCHANGE_REAL_EXISTING_CUSTOMER_TOKEN_BODY_AND_IDENTITY');
    nhe_keys($privateRequest['body'], ['unique', 'comment', 'pics', 'product_score', 'service_score'],
        'NHEPCM_EXCHANGE_ORIGINAL_BODY_EXACT_FIVE');
    $body = $privateRequest['body'];
    nhep_expect(is_string($body['unique']) && preg_match('/\A[a-f0-9]{32}\z/D', $body['unique']) === 1
        && $body === ['unique' => $body['unique'], 'comment' => 'normal-history-' . $intent['run_id'],
            'pics' => '', 'product_score' => 5, 'service_score' => 5],
        'NHEPCM_EXCHANGE_FIVE_REAL_NATIVE_NORMAL_COMMENT_INPUTS');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPCM_EXCHANGE_PRIVATE_CUSTOMER_IDENTITY_EXACT_TWO');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 2147483647
        && $privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account'])
        && preg_match('/\A[a-z0-9_]{10,32}\z/D', $privateRequest['actor_identity']['account']) === 1,
        'NHEPCM_EXCHANGE_ORIGINAL_NATIVE_CUSTOMER_IDENTITY');
    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHEPCM_EXCHANGE_COMPLETE_ORIGINAL_PRIVATE_RESPONSE_EXACT_ELEVEN');
    $interval = $privateResponse['actual_interval'];
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $privateResponse['http'] === 200 && $privateResponse['transport_errno'] === 0
        && $privateResponse['transport_failure_class'] === null && $privateResponse['primary_ip'] === '127.0.0.1'
        && $privateResponse['primary_port'] === 8000 && $privateResponse['local_ip'] === '127.0.0.1'
        && is_int($privateResponse['local_port']) && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw']) && $privateResponse['raw'] !== '' && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json']) && !array_is_list($privateResponse['json']) && is_array($privateResponse['headers']),
        'NHEPCM_EXCHANGE_ONE_REAL_LOCAL_SUCCESS_AND_HTTP_SECONDS_INSIDE_SIGNED_TIME_RANGE');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHEPCM_EXCHANGE_ORIGINAL_HEADER_CALLBACK_EXACT_FIVE');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] > 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false
        && count($privateResponse['headers']['blocks']) === 1
        && $privateResponse['headers']['blocks'][0] === $privateResponse['headers']['lines'],
        'NHEPCM_EXCHANGE_ORIGINAL_COMPLETE_NONTRUNCATED_HEADERS');
    $lines = $privateResponse['headers']['lines']; $headerBytes = 0;
    nhep_expect(count($lines) >= 3 && in_array($lines[0], ["HTTP/1.0 200 OK\r\n", "HTTP/1.1 200 OK\r\n"], true)
        && $lines[count($lines) - 1] === "\r\n", 'NHEPCM_EXCHANGE_REAL_STATUS_AND_FINAL_HEADER_CRLF');
    foreach ($lines as $line) {
        nhep_expect(is_string($line) && str_ends_with($line, "\r\n"), 'NHEPCM_EXCHANGE_EVERY_ORIGINAL_HEADER_LINE_COMPLETE');
        $headerBytes += strlen($line);
    }
    nhep_expect($headerBytes === $privateResponse['headers']['bytes'], 'NHEPCM_EXCHANGE_COMPLETE_HEADER_BYTE_SUM');
    $json = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $json === $privateResponse['json'],
        'NHEPCM_EXCHANGE_ORIGINAL_COMPLETE_RAW_JSON_STRICT_JOIN');
    nhe_keys($json, ['status', 'msg', 'data'], 'NHEPCM_EXCHANGE_COMPLETE_SUCCESS_EXACT_THREE');
    nhep_expect($json === ['status' => 200, 'msg' => 'success', 'data' => ['to_lottery' => false]],
        'NHEPCM_EXCHANGE_ORIGINAL_NORMAL_SUCCESS_WITH_EXACT_FALSE_LOTTERY_DATA');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPCM_EXCHANGE_BOTH_NATIVE_CAPTURES_SAME_ORIGINAL_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $afterUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($afterUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPCM_EXCHANGE_REAL_HTTP_WINDOW_ENCLOSED_BY_MONOTONIC_NATIVE_REDIS_TIME');
    return $json;
}

function nhep_customer_comment_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse, #[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepcm_context', 'nhepcm_before_guards', 'nhepcm_exchange',
        'nhep_auth_db_snapshot', 'nhep_auth_db_index', 'nhep_auth_db_time', 'nhep_auth_db_update',
        'nhep_database_expected', 'nhepar_entry', 'm4lh_actor_native', 'm4lh_actor_expected_row'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPCM_DATABASE_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    $context = nhepcm_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'cart', 'reply_id', 'query_cache_key', 'channel_packet'],
        'NHEPCM_DATABASE_COMPLETE_CONTEXT_EXACT_EIGHT');
    nhepcm_before_guards($beforeDB2, $intent, $context);
    nhepcm_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhep_expect(nhepar_entry($beforeCapture, $context['query_cache_key']) === null
        && nhepar_entry($actualCapture, $context['query_cache_key']) === null,
        'NHEPCM_DATABASE_EXACT_SOURCE_CONDITIONAL_QUERY_GUID_COLD_BEFORE_AND_FINAL');
    $interval = $privateResponse['actual_interval']; $root = $context['order']['row']; $oid = $root['id'];
    $user = $context['fixture']['user']; $uid = $context['fixture']['uid'];
    nhep_expect($root['add_time'] <= $interval[0] && $root['pay_time'] <= $interval[0]
        && $user['row']['last_time'] <= $interval[0], 'NHEPCM_DATABASE_ORIGINAL_BEFORE_TIMES_PRECEDE_COMMENT_HTTP');
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $row)
        if ($row['oid'] === $oid) nhep_expect($row['change_time'] <= $interval[0],
            'NHEPCM_DATABASE_ALL_FOUR_SAVED_HISTORY_TIMES_PRECEDE_THIS_HTTP');
    $contracts = [
        'eb_store_product_reply' => [
            'id' => ['int', null, false], 'uid' => ['int', 0, false], 'oid' => ['int', 0, false],
            'unique' => ['char(32)', '', false], 'product_id' => ['int', 0, false],
            'reply_type' => ['varchar(32)', 'product', false], 'product_score' => ['tinyint', 0, false],
            'service_score' => ['tinyint', 0, false], 'comment' => ['varchar(512)', '', false],
            'pics' => ['text', null, true], 'add_time' => ['int', 0, false],
            'merchant_reply_content' => ['varchar(300)', '', false], 'merchant_reply_time' => ['int', 0, false],
            'is_del' => ['tinyint unsigned', 0, false], 'is_reply' => ['tinyint', 0, false],
            'nickname' => ['varchar(64)', '', false], 'avatar' => ['varchar(255)', '', false],
            'suk' => ['varchar(255)', '', false], 'status' => ['tinyint', 0, false]],
        'eb_store_order_status' => [
            'oid' => ['int unsigned', 0, false], 'change_type' => ['varchar(32)', '', false],
            'change_message' => ['varchar(256)', '', false], 'change_time' => ['int unsigned', 0, false]],
    ];
    foreach ($contracts as $table => $fields) {
        $metadata = $beforeDB2['database']['tables'][$table]['metadata']; $hasId = $table === 'eb_store_product_reply';
        nhep_expect(array_keys($metadata['columns']) === array_keys($fields)
            && $metadata['checks'] === [] && $metadata['foreign'] === [] && $metadata['triggers'] === [],
            'NHEPCM_DATABASE_ALL_ORIGINAL_REPLY_STATUS_COLUMNS_NO_HIDDEN_WRITES');
        foreach ($fields as $column => [$wantedType, $default, $nullable]) {
            $definition = $metadata['columns'][$column];
            $type = preg_replace('/\A(tinyint|int)(?:\([0-9]+\))?( unsigned)?\z/D', '$1$2', strtolower($definition['COLUMN_TYPE']));
            nhep_expect($type === $wantedType && $definition['COLUMN_NAME'] === $column
                && $definition['IS_NULLABLE'] === ($nullable ? 'YES' : 'NO') && $definition['GENERATION_EXPRESSION'] === ''
                && $definition['EXTRA'] === ($hasId && $column === 'id' ? 'auto_increment' : ''),
                'NHEPCM_DATABASE_EACH_NATIVE_TYPE_NULLABILITY_GENERATION_AND_EXTRA');
            if ($default === null) nhep_expect($definition['COLUMN_DEFAULT'] === null, 'NHEPCM_DATABASE_ORIGINAL_NULL_DEFAULT');
            else nhep_expect(m4lh_actor_native($definition, $definition['COLUMN_DEFAULT']) === $default,
                'NHEPCM_DATABASE_EACH_ORIGINAL_NATIVE_COLUMN_DEFAULT');
        }
        if ($hasId) {
            $indexes = $metadata['indexes'];
            nhep_expect(isset($indexes['PRIMARY'], $indexes['order_id_2'])
                && count($indexes['PRIMARY']) === 1 && $indexes['PRIMARY'][0]['COLUMN_NAME'] === 'id'
                && (string)$indexes['PRIMARY'][0]['NON_UNIQUE'] === '0'
                && count($indexes['order_id_2']) === 2
                && $indexes['order_id_2'][0]['COLUMN_NAME'] === 'oid'
                && $indexes['order_id_2'][1]['COLUMN_NAME'] === 'unique'
                && (string)$indexes['order_id_2'][0]['NON_UNIQUE'] === '0'
                && (string)$indexes['order_id_2'][1]['NON_UNIQUE'] === '0'
                && count($metadata['constraints']) === 2, 'NHEPCM_DATABASE_ORIGINAL_REPLY_AUTO_PK_AND_OID_UNIQUE_PAIR');
        } else nhep_expect($metadata['table']['AUTO_INCREMENT'] === null && !isset($metadata['indexes']['PRIMARY'])
            && $metadata['constraints'] === [], 'NHEPCM_DATABASE_STATUS_NO_ID_PK_OR_AI');
    }
    foreach ([$context['order']['metadata'], $user['metadata']] as $definition)
        nhep_expect($definition['triggers'] === [] && $definition['checks'] === [] && $definition['foreign'] === [],
            'NHEPCM_DATABASE_ROOT_USER_NO_HIDDEN_DATABASE_WRITES');
    $userIndex = nhep_auth_db_index($actualDB2['rows']['eb_user'], $user['metadata'], 'uid', $uid);
    $authTime = nhep_auth_db_time($user['metadata'], 'last_time',
        $actualDB2['rows']['eb_user'][$userIndex]['last_time'], $interval, $user['row']['last_time']);
    $replyTable = $beforeDB2['database']['tables']['eb_store_product_reply']; $replyMeta = $replyTable['metadata'];
    $replyIndex = nhep_auth_db_index($actualDB2['rows']['eb_store_product_reply'], $replyMeta, 'id', $context['reply_id']);
    $replyTime = $actualDB2['rows']['eb_store_product_reply'][$replyIndex]['add_time'];
    $timeColumn = $replyMeta['columns']['add_time'];
    nhep_expect(preg_match('/\Aint(?:\([0-9]+\))?\z/D', strtolower($timeColumn['COLUMN_TYPE'])) === 1
        && $timeColumn['IS_NULLABLE'] === 'NO' && is_int($replyTime) && $replyTime > 0 && $replyTime <= 2147483647
        && m4lh_actor_native($timeColumn, $replyTime) === $replyTime
        && $replyTime >= $interval[0] && $replyTime <= $interval[1],
        'NHEPCM_DATABASE_INDEPENDENT_SIGNED_REPLY_TIME_ONLY_AT_BEFORE_NEXT_PK_AND_REAL_HTTP_WINDOW');
    $times = [];
    foreach ($actualDB2['rows']['eb_store_order_status'] as $row)
        if ($row['oid'] === $oid && $row['change_type'] === 'check_order_over') $times[] = $row['change_time'];
    nhep_expect(count($times) === 1, 'NHEPCM_DATABASE_ONE_NAMED_NEW_COMPLETION_STATUS_TIME');
    $statusMetadata = $beforeDB2['database']['tables']['eb_store_order_status']['metadata'];
    $statusTime = nhep_auth_db_time($statusMetadata, 'change_time', $times[0], $interval);
    $body = $privateRequest['body'];
    nhep_expect($body['comment'] === 'normal-history-' . $intent['run_id']
        && preg_match('/\A[a-z0-9-]+\z/D', $body['comment']) === 1,
        'NHEPCM_DATABASE_FIXED_ASCII_COMMENT_UNCHANGED_BY_TRIM_AND_HTMLSPECIALCHARS');
    $reply = m4lh_actor_expected_row($replyMeta, ['id' => $context['reply_id'], 'uid' => $uid, 'oid' => $oid,
        'unique' => $context['item']['row']['unique'], 'product_id' => $context['item']['row']['product_id'],
        'reply_type' => 'product', 'product_score' => 5, 'service_score' => 5,
        'comment' => $body['comment'], 'pics' => '', 'add_time' => $replyTime,
        'nickname' => $user['row']['nickname'], 'avatar' => $user['row']['avatar'],
        'suk' => $context['cart']['productInfo']['attrInfo']['suk'], 'status' => 0]);
    nhep_expect(count($reply) === 19 && $reply['is_reply'] === 0 && $reply['is_del'] === 0,
        'NHEPCM_DATABASE_FULL_INDEPENDENT_REPLY_DEFAULTS_INCLUDE_PENDING_UNREPLIED_ROW');
    $expectedRows = [
        'eb_user' => nhep_auth_db_update($beforeDB2, 'eb_user', $user['index'], ['last_time' => $authTime]),
        'eb_store_order' => nhep_auth_db_update($beforeDB2, 'eb_store_order', $context['order']['index'], ['status' => 3]),
        'eb_store_product_reply' => $beforeDB2['rows']['eb_store_product_reply'],
        'eb_store_order_status' => $beforeDB2['rows']['eb_store_order_status'],
    ];
    $expectedRows['eb_store_product_reply'][] = $reply;
    $expectedRows['eb_store_order_status'][] = m4lh_actor_expected_row($statusMetadata,
        ['oid' => $oid, 'change_type' => 'check_order_over', 'change_message' => '用户评价', 'change_time' => $statusTime]);
    $expected = nhep_database_expected($beforeDB2, $expectedRows, ['eb_store_product_reply' => 1]);
    nhep_expect($expected === $actualDB2, 'NHEPCM_DATABASE_ALL_164_TABLES_FOUR_DELTAS_ONE_AI_THREE_NATIVE_TIMES_ONLY');
    return $expected;
}

function nhep_customer_comment_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepcm_context', 'nhepcm_before_guards', 'nhepcm_exchange',
        'nhep_auth_db_snapshot', 'nhepar_capture', 'nhepar_entry', 'nhepar_actor', 'nhepar_customer',
        'nhepar_remember', 'nhepar_bind', 'nhepar_tag', 'nhepcr_config_wire', 'nhep_redis_expected',
        'bcadd', 'bcsub', 'bcmul', 'bccomp', 'serialize'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPCM_REDIS_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    $context = nhepcm_context($beforeDB2, $intent, $privateRequest);
    nhe_keys($context, ['family', 'fixture', 'order', 'item', 'cart', 'reply_id', 'query_cache_key', 'channel_packet'],
        'NHEPCM_REDIS_COMPLETE_CONTEXT_EXACT_EIGHT');
    nhepcm_before_guards($beforeDB2, $intent, $context);
    nhepcm_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    nhep_expect(nhepar_entry($beforeCapture, $context['query_cache_key']) === null
        && nhepar_entry($actualCapture, $context['query_cache_key']) === null,
        'NHEPCM_REDIS_EXACT_INDEPENDENT_CONDITIONAL_QUERY_GUID_COLD_BEFORE_AND_FINAL');
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']),
        'NHEPCM_REDIS_SAME_RUN_REAL_PRIVATE_CUSTOMER_AUTH_CONFIGURATION');
    $actor = nhepar_actor($beforeDB2['rows'], $intent, $privateRequest);
    nhep_expect($actor === $context['fixture']['user']['row'], 'NHEPCM_REDIS_REAL_SAME_COMPLETE_BEFORE_CUSTOMER');
    $changes = []; $tagMembers = [];
    $apiTag = nhepar_entry($beforeCapture, 'c:CRMEB:' . md5('api'));
    nhep_expect(is_array($apiTag) && $apiTag['type'] === 'set' && $apiTag['expires'] === -1
        && in_array('c:' . md5($privateRequest['token']), $apiTag['value'], true),
        'NHEPCM_REDIS_REAL_EXISTING_CUSTOMER_WHITELIST_API_TAG_MEMBERSHIP');
    nhepar_customer($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);

    foreach (['station_open' => 1, 'param_filter_type' => null, 'param_filter_data' => null,
        'product_reply_examine' => 1] as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    // Empty language tables independently determine all three values. Only these keys may expire/rebuild here.
    $interval = $privateResponse['actual_interval']; $ttlMs = '3600000';
    $getterLower = bcmul((string)$interval[0], '1000', 0);
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire) {
        $key = 'c:' . $name; $old = nhepar_entry($beforeCapture, $key);
        if ($old === null || bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) > 0) {
            nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
            if ($old === null) {
                $new = nhepar_entry($actualCapture, $key);
                $writeMs = bcsub((string)$new['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPCM_REDIS_LANGUAGE_COLD_WRITE_CLOCK_INSIDE_ACTUAL_HTTP_SECONDS_AND_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
        } elseif (bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) === 0
            && nhepar_entry($actualCapture, $key) !== null) {
            // Existing full-namespace algorithm expires only when A > E; E == A is not a rebuild.
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                'NHEPCM_REDIS_LANGUAGE_EQUAL_ACTUAL_DEADLINE_COMPATIBLE_WITH_SERIAL_WARM_GETTER');
            $descriptor = nhepar_bind($actualCapture, $key, 'string', $wire, $old['expires'], $beforeCapture['snapshot']);
            nhep_expect($descriptor === $beforeCapture['snapshot']['keys'][hash('sha256', $key)],
                'NHEPCM_REDIS_EQUAL_DEADLINE_COMPLETE_ORIGINAL_WARM_DESCRIPTOR_NOT_RENEWED');
            $tagMembers[] = $key;
        } else {
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $beforeCapture['snapshot']['time_ms'], 0) >= 0,
                'NHEPCM_REDIS_COMPLETE_BEFORE_LANGUAGE_VALUE_AND_NATURAL_DEADLINE');
            $now = nhepar_entry($actualCapture, $key);
            if ($now === null) {
                nhep_expect(bccomp((string)$old['expires'], bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                    'NHEPCM_REDIS_UNREBUILT_LANGUAGE_CAN_ONLY_EXPIRE_AFTER_A_SERIAL_POSSIBLE_REAL_GETTER');
            } else {
                $changes[$key] = nhepar_bind($actualCapture, $key, 'string', $wire, ['ttl' => 3600], $beforeCapture['snapshot']);
                $writeMs = bcsub((string)$now['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, (string)$old['expires'], 0) > 0
                    && bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPCM_REDIS_NATURAL_REBUILD_STRICTLY_AFTER_OLD_EXPIRY_AND_INSIDE_HTTP_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
            $tagMembers[] = $key;
        }
    }
    // Remember may SET N; again; this model proves full final values/deadlines/membership, not absence of writes.
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'],
        'NHEPCM_REDIS_FULL_NAMESPACE_ONLY_REAL_CONFIG_AND_LANGUAGE_DELTAS_WITH_ORIGINAL_JWT_TAGS');
    return $expected;
}


function nhepal_context(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepar_actor', 'nhepcd_one',
        'nhepcd_id', 'nhepcv_native_row', 'm4lh_actor_native', 'm4lh_actor_expected_row',
        'bccomp', 'json_decode', 'json_encode', 'md5', 'hash'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPAL_CONTEXT_PURE_DEPENDENCY_REQUIRED');
    nhep_expect(PHP_INT_SIZE === 8, 'NHEPAL_CONTEXT_ORIGINAL_NATIVE_64_BIT');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPAL_CONTEXT_ORIGINAL_COMPLETE_INTENT');
    nhep_expect((($intent['sequence'] === 33 && $intent['step'] === 'platform_pending_review_identity')
        || ($intent['sequence'] === 36 && $intent['step'] === 'platform_approved_replied_read'))
        && $intent['method'] === 'GET' && $intent['actor'] === 'admin'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['path'])
        && preg_match('~\A/adminapi/product/reply\?product_id=([1-9][0-9]{0,9})&page=1&limit=20\z~D', $intent['path'], $path) === 1
        && bccomp($path[1], '2147483647', 0) <= 0,
        'NHEPAL_CONTEXT_TRUE_33_ADMIN_ORIGINAL_GET_EXACT_QUERY_AND_ORIGIN');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPAL_CONTEXT_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect(is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && $privateRequest['body'] === null && is_array($privateRequest['actor_identity']),
        'NHEPAL_CONTEXT_EXISTING_ADMIN_TOKEN_AND_ORIGINAL_NULL_GET_BODY');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPAL_CONTEXT_REAL_ADMIN_IDENTITY_EXACT_TWO');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 4294967295
        && $privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account']), 'NHEPAL_CONTEXT_REAL_NATIVE_ADMIN_IDENTITY');
    $sentinels = $beforeDB2['rows']['audit_sentinel'];
    nhep_expect(count($sentinels) === 1 && ($sentinels[0]['run_id'] ?? null) === $intent['run_id'],
        'NHEPAL_CONTEXT_COMPLETE_BEFORE_SAME_RUN');
    // No customer fixture or fabricated earlier intent is used for this real admin request.
    $actor = nhepar_actor($beforeDB2['rows'], $intent, $privateRequest);
    $admin = nhepcd_one($beforeDB2, 'eb_system_admin', ['id' => $intent['actor_id']]);
    $adminRow = nhepcv_native_row($beforeDB2, 'eb_system_admin', $admin['index']);
    nhep_expect($adminRow === $admin['row'] && $actor === $adminRow
        && $adminRow['real_name'] === '隔离平台管理员' && $adminRow['level'] === 0
        && $adminRow['status'] === 1 && $adminRow['is_del'] === 0,
        'NHEPAL_CONTEXT_GENUINE_HIGHEST_ADMIN_BOUND_TO_REQUEST');
    $family = 'review_family';
