            && count($replyRow) === 19 && $replyRow['is_del'] === 0,
            'NHEPAL36_CONTEXT_ONE_COMPLETE_BEFORE_APPROVED_REPLIED_NATIVE_ROW');
    } else {
        nhep_expect(is_int($replyTime) && $replyTime > 0 && $replyTime <= 2147483647
            && $replyTime >= $root['pay_time']
            && $replyRow === $reply['row']
            && $replyRow === m4lh_actor_expected_row($reply['metadata'], [
                'id' => $replyId, 'uid' => $uid, 'oid' => $oid, 'unique' => $saved['unique'],
                'product_id' => $productId, 'reply_type' => 'product', 'product_score' => 5, 'service_score' => 5,
                'comment' => 'normal-history-' . $intent['run_id'], 'pics' => '', 'add_time' => $replyTime,
                'nickname' => $buyerRow['nickname'], 'avatar' => $buyerRow['avatar'],
                'suk' => $cart['productInfo']['attrInfo']['suk'], 'status' => 0])
            && count($replyRow) === 19 && $replyRow['is_reply'] === 0 && $replyRow['is_del'] === 0,
            'NHEPAL_CONTEXT_ONE_EXISTING_COMPLETE_NATIVE_PENDING_REPLY_FROM_BEFORE_SAVED_ITEM');
    }
    // The real SQL applies only is_del0 and product_id, with a LEFT JOIN on the numeric product PK.
    // Preserve other products/buyers/history; inspect the complete visible set for this product.
    $visible = [];
    foreach ($beforeDB2['rows']['eb_store_product_reply'] as $index => $unused) {
        $row = nhepcv_native_row($beforeDB2, 'eb_store_product_reply', $index);
