            && (strtolower(rtrim($menu['api_url'], ' ')) !== $rule || $menu['api_url'] === $rule),
            'NHEPAL_CONTEXT_ASCII_MENU_URLS_NO_NONCANONICAL_SQL_EQUIVALENT_ROUTE_ALIAS');
        if ($menu['api_url'] === $rule) {
            $page = $menu['menu_name'] ?: '未知';
            if (!in_array($page, $pages, true)) $pages[] = $page;
        }
    }
    if ($pages === []) $pages[] = '未知';
    return ['family' => $family, 'admin' => $admin, 'buyer' => $buyer, 'order' => $order,
        'item' => $item, 'reply' => $reply, 'product' => $product, 'visit_pages' => $pages];
