function nhepal_before_guards(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $context): void
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepcd_one', 'nhepcv_native_row',
        'm4lh_actor_native', 'm4lh_actor_expected_row', 'nhepcr_config_wire'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPAL_GUARDS_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    $keys = ['family', 'admin', 'buyer', 'order', 'item', 'reply', 'product', 'visit_pages'];
    nhe_keys($context, $keys, 'NHEPAL_GUARDS_COMPLETE_CONTEXT_EXACT_EIGHT');
    nhep_expect(array_keys($context) === $keys && $context['family'] === 'review_family'
        && (($intent['sequence'] === 33 && $intent['step'] === 'platform_pending_review_identity')
        || ($intent['sequence'] === 36 && $intent['step'] === 'platform_approved_replied_read'))
        && $intent['actor'] === 'admin' && $intent['method'] === 'GET'
        && $intent['origin'] === 'http://127.0.0.1:8000',
        'NHEPAL_GUARDS_ORIGINAL_CONTEXT_ORDER_AND_TRUE_ADMIN_READ');
    foreach (['admin' => ['eb_system_admin', 'id'], 'buyer' => ['eb_user', 'uid'],
        'order' => ['eb_store_order', 'id'], 'item' => ['eb_store_order_cart_info', 'id'],
        'reply' => ['eb_store_product_reply', 'id'], 'product' => ['eb_store_product', 'id']] as $key => [$table, $pk]) {
        $selection = $context[$key];
        nhe_keys($selection, ['index', 'row', 'metadata'], 'NHEPAL_GUARDS_ORIGINAL_COMPLETE_BEFORE_SELECTION');
        nhep_expect($selection === nhepcd_one($beforeDB2, $table, [$pk => $selection['row'][$pk]])
            && $selection['row'] === nhepcv_native_row($beforeDB2, $table, $selection['index']),
            'NHEPAL_GUARDS_EVERY_SELECTION_FROM_THIS_COMPLETE_BEFORE_ONLY');
    }
    $root = $context['order']['row']; $oid = $root['id']; $buyer = $context['buyer']['row'];
    $reply = $context['reply']['row']; $item = $context['item']['row']; $admin = $context['admin']['row'];
    nhep_expect($context['order'] === nhepcd_one($beforeDB2, 'eb_store_order', ['mark' => $intent['run_id'] . '-review_family'])
        && $root['pid'] === 0 && $root['paid'] === 1 && $root['status'] === 3
        && $root['uid'] === $buyer['uid'] && $root['pay_uid'] === $buyer['uid']
        && $buyer['now_money'] === '79.85' && $buyer['pay_count'] === 2
        && $item['oid'] === $oid && $item['uid'] === $buyer['uid'] && $item['refund_num'] === 0
        && $reply['oid'] === $oid && $reply['uid'] === $buyer['uid'] && $reply['unique'] === $item['unique']
        && $reply['product_id'] === $context['product']['row']['id']
        && $reply['status'] === ($intent['sequence'] === 36 ? 1 : 0)
        && $reply['is_reply'] === ($intent['sequence'] === 36 ? 1 : 0) && $reply['is_del'] === 0
        && $admin['id'] === $intent['actor_id'] && $admin['level'] === 0
        && $intent['path'] === '/adminapi/product/reply?product_id=' . $context['product']['row']['id'] . '&page=1&limit=20',
        'NHEPAL_GUARDS_REAL_ADMIN_AND_SEPARATE_BUYER_PURCHASED_PENDING_REPLY');
    if ($intent['sequence'] === 36)
        nhep_expect($reply['merchant_reply_content'] === 'normal-reply-' . $intent['run_id']
            && is_int($reply['merchant_reply_time']) && $reply['merchant_reply_time'] > 0
            && $reply['merchant_reply_time'] <= 2147483647,
            'NHEPAL36_GUARDS_SAME_COMPLETE_BEFORE_REPLY_FROM_ORIGINAL35');

    $messages = ['cache_key_create_order' => '订单生成', 'pay_success' => '用户付款成功',
        'delivery_goods' => '已发货 快递公司：顺丰速运 快递单号：NHE' . $intent['run_id'],
        'take_delivery' => '已收货', 'check_order_over' => '用户评价'];
    $logs = [];
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $index => $unused) {
        $row = nhepcv_native_row($beforeDB2, 'eb_store_order_status', $index);
        if ($row['oid'] !== $oid) continue;
        $kind = $row['change_type'];
        nhep_expect(is_string($kind) && isset($messages[$kind]) && !isset($logs[$kind])
            && is_int($row['change_time']) && $row['change_time'] > 0 && $row['change_time'] <= 2147483647
            && $row === m4lh_actor_expected_row($beforeDB2['database']['tables']['eb_store_order_status']['metadata'],
                ['oid' => $oid, 'change_type' => $kind, 'change_message' => $messages[$kind], 'change_time' => $row['change_time']]),
            'NHEPAL_GUARDS_ALL_FIVE_COMPLETE_ORIGINAL_REVIEW_FAMILY_STATUS_ROWS');
        $logs[$kind] = $row['change_time'];
    }
    nhep_expect(count($logs) === 5 && $logs['cache_key_create_order'] >= $root['add_time']
        && $logs['cache_key_create_order'] <= $logs['pay_success'] && $logs['pay_success'] >= $root['pay_time']
        && $logs['pay_success'] <= $logs['delivery_goods'] && $logs['delivery_goods'] <= $logs['take_delivery']
        && $logs['take_delivery'] <= $reply['add_time'] && $reply['add_time'] <= $logs['check_order_over'],
        'NHEPAL_GUARDS_SAVED_NATIVE_PURCHASE_SHIP_RECEIVE_COMMENT_HISTORY_ORDER');
    foreach (['param_filter_type', 'param_filter_data'] as $name)
        nhep_expect(nhepcr_config_wire($beforeDB2, $name, null) === 'N;', 'NHEPAL_GUARDS_TWO_REAL_MISSING_FILTER_CONFIGS');
    foreach (['eb_lang_code', 'eb_lang_country', 'eb_lang_type'] as $table)
        nhep_expect($beforeDB2['rows'][$table] === [], 'NHEPAL_GUARDS_ALL_THREE_LANGUAGE_TABLES_EMPTY');
    nhep_expect(is_array($context['visit_pages']) && array_is_list($context['visit_pages'])
        && $context['visit_pages'] !== [] && count(array_unique($context['visit_pages'], SORT_STRING)) === count($context['visit_pages']),
        'NHEPAL_GUARDS_INDEPENDENT_NONEMPTY_DEDUPLICATED_MENU_PAGES');
    foreach ($context['visit_pages'] as $page)
        nhep_expect(is_string($page) && $page !== '', 'NHEPAL_GUARDS_EACH_PREBUILT_MENU_PAGE_STRING');
    $contracts = [
        'eb_store_product_reply' => [
            'id' => ['int', null, false], 'uid' => ['int', 0, false], 'oid' => ['int', 0, false],
            'unique' => ['char(32)', '', false], 'product_id' => ['int', 0, false],
            'reply_type' => ['varchar(32)', 'product', false], 'product_score' => ['tinyint', 0, false],
            'service_score' => ['tinyint', 0, false], 'comment' => ['varchar(512)', '', false],
            'pics' => ['text', null, true], 'add_time' => ['int', 0, false],
            'merchant_reply_content' => ['varchar(300)', '', false], 'merchant_reply_time' => ['int', 0, false],
            'is_del' => ['tinyint unsigned', 0, false], 'is_reply' => ['tinyint', 0, false],
            'nickname' => ['varchar(64)', '', false], 'avatar' => ['varchar(255)', '', false],
            'suk' => ['varchar(255)', '', false], 'status' => ['tinyint', 0, false]],
        'eb_system_log' => [
            'id' => ['int unsigned', null, false], 'admin_id' => ['int unsigned', 0, false],
            'admin_name' => ['varchar(64)', '', false], 'path' => ['varchar(128)', '', false],
            'page' => ['varchar(64)', '', false], 'method' => ['varchar(12)', '', false],
            'ip' => ['varchar(16)', '', false], 'type' => ['varchar(32)', '', false],
            'add_time' => ['int unsigned', 0, false], 'merchant_id' => ['int unsigned', 0, false]],
    ];
    foreach ($contracts as $table => $fields) {
        $metadata = $beforeDB2['database']['tables'][$table]['metadata'];
        nhep_expect(array_keys($metadata['columns']) === array_keys($fields)
            && $metadata['checks'] === [] && $metadata['foreign'] === [] && $metadata['triggers'] === [],
            'NHEPAL_GUARDS_COMPLETE_REPLY_AND_LOG_DDL_WITHOUT_HIDDEN_WRITES');
        foreach ($fields as $column => [$wantedType, $default, $nullable]) {
            $definition = $metadata['columns'][$column];
            $type = preg_replace('/\A(tinyint|int)(?:\([0-9]+\))?( unsigned)?\z/D', '$1$2', strtolower($definition['COLUMN_TYPE']));
            nhep_expect($type === $wantedType && $definition['COLUMN_NAME'] === $column
                && $definition['IS_NULLABLE'] === ($nullable ? 'YES' : 'NO') && $definition['GENERATION_EXPRESSION'] === ''
                && $definition['EXTRA'] === ($column === 'id' ? 'auto_increment' : ''),
                'NHEPAL_GUARDS_EACH_ORIGINAL_NATIVE_COLUMN_TYPE_NULLABILITY_AND_EXTRA');
            if ($default === null) nhep_expect($definition['COLUMN_DEFAULT'] === null, 'NHEPAL_GUARDS_ORIGINAL_NULL_DEFAULT');
            else nhep_expect(m4lh_actor_native($definition, $definition['COLUMN_DEFAULT']) === $default,
                'NHEPAL_GUARDS_ORIGINAL_NATIVE_COLUMN_DEFAULT');
        }
        nhep_expect(isset($metadata['indexes']['PRIMARY']) && count($metadata['indexes']['PRIMARY']) === 1
            && $metadata['indexes']['PRIMARY'][0]['COLUMN_NAME'] === 'id'
            && (string)$metadata['indexes']['PRIMARY'][0]['NON_UNIQUE'] === '0',
            'NHEPAL_GUARDS_ORIGINAL_SINGLE_AUTO_ID_PRIMARY_KEY');
    }
}

function nhepal_response_envelopes(#[SensitiveParameter] array $context, array $interval): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepodv_date', 'json_encode', 'json_decode', 'intdiv'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPAL_ENVELOPES_PURE_DEPENDENCY_REQUIRED');
    nhe_keys($context, ['family', 'admin', 'buyer', 'order', 'item', 'reply', 'product', 'visit_pages'],
        'NHEPAL_ENVELOPES_COMPLETE_BEFORE_CONTEXT_EIGHT');
    nhep_expect($context['family'] === 'review_family' && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647,
        'NHEPAL_ENVELOPES_REAL_SIGNED_NATIVE_HTTP_INTERVAL');
    $reply = $context['reply']['row']; $product = $context['product']['row'];
    $columns = ['id', 'uid', 'oid', 'unique', 'product_id', 'reply_type', 'product_score',
        'service_score', 'comment', 'pics', 'add_time', 'merchant_reply_content', 'merchant_reply_time',
        'is_del', 'is_reply', 'nickname', 'avatar', 'suk', 'status'];
    nhep_expect(array_keys($reply) === $columns && is_int($reply['add_time']) && $reply['add_time'] > 0
        && $reply['add_time'] <= $interval[0] && $reply['product_id'] === $product['id']
        && $reply['pics'] === '' && $reply['product_score'] === 5 && $reply['service_score'] === 5
        && is_string($product['store_name']) && is_string($product['image']),
        'NHEPAL_ENVELOPES_COMPLETE_NATIVE_BEFORE_REPLY_AND_MATCHED_LEFT_JOIN_PRODUCT');
    if ($reply['status'] === 1 && $reply['is_reply'] === 1)
        nhep_expect(is_int($reply['merchant_reply_time']) && $reply['merchant_reply_time'] > 0
            && $reply['merchant_reply_time'] <= $interval[0],
            'NHEPAL36_ENVELOPES_SAVED_NATIVE_REPLY_TIME_PRECEDES_REAL_HTTP_WITHOUT_RESPONSE_FILL');

    $d0 = $interval[0] - $reply['add_time']; $d1 = $interval[1] - $reply['add_time'];
    $ages = [];
    if ($d0 === 0) $ages[] = null; // The real function has no return at d=0.
    $units = [[31536000, '年'], [2592000, '个月'], [604800, '星期'],
        [86400, '天'], [3600, '小时'], [60, '分钟'], [1, '秒']];
    $previous = null;
    foreach ($units as [$unit, $label]) {
        $left = max($d0, $unit);
        $right = min($d1, $previous === null ? $d1 : $previous - 1);
        if ($left <= $right) {
            $first = intdiv($left, $unit); $last = intdiv($right, $unit);
            for ($q = $first; $q <= $last; ++$q) $ages[] = (string)$q . $label . '前';
        }
        $previous = $unit;
    }
    nhep_expect($ages !== [] && count(array_unique($ages, SORT_REGULAR)) === count($ages),
        'NHEPAL_ENVELOPES_ALL_AND_ONLY_INTERSECTING_RELATIVE_TIME_BUCKET_VALUES');
    $formatted = nhepodv_date('Y-m-d H:i:s', $reply['add_time']); $envelopes = [];
    foreach ($ages as $age) {
        $row = $reply;
        $row['pics'] = null; // StoreProductReply::getPicsAttr('') is null.
        $row['add_time'] = $formatted;
        $row['store_name'] = $product['store_name'];
        $row['image'] = $product['image'];
        $row['account'] = $reply['nickname'];
        $row['score'] = 5; // sysPage overwrites SUM; normal JSON number is 5, not the SQL SUM string.
        $row['time'] = $age;
        $row['create_time'] = $formatted;
        nhep_expect(array_keys($row) === array_merge($columns,
            ['store_name', 'image', 'account', 'score', 'time', 'create_time']) && count($row) === 25,
            'NHEPAL_ENVELOPES_COMPLETE_ORIGINAL_25_DTO_FIELDS_IN_REAL_QUERY_AND_APPEND_ORDER');
        $json = ['status' => 200, 'msg' => 'success', 'data' => ['list' => [$row], 'count' => 1]];
        $wire = json_encode($json);
        nhep_expect(is_string($wire), 'NHEPAL_ENVELOPES_COMPLETE_NORMAL_JSON_ENCODING');
        $normalized = json_decode($wire, true);
        nhep_expect(json_last_error() === JSON_ERROR_NONE && $normalized === $json,
            'NHEPAL_ENVELOPES_ORIGINAL_JSON_NATIVE_TYPES_WITHOUT_RESPONSE_COPY');
        $envelopes[] = $normalized;
    }
    return $envelopes;
}

function nhepal_exchange(#[SensitiveParameter] array $beforeCapture, #[SensitiveParameter] array $actualCapture,
    array $intent, #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepar_capture', 'nhepar_entry', 'bcadd', 'bcmul', 'bccomp', 'json_decode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPAL_EXCHANGE_PURE_DEPENDENCY_REQUIRED');
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPAL_EXCHANGE_ORIGINAL_COMPLETE_INTENT');
    nhep_expect(PHP_INT_SIZE === 8 && (($intent['sequence'] === 33 && $intent['step'] === 'platform_pending_review_identity')
        || ($intent['sequence'] === 36 && $intent['step'] === 'platform_approved_replied_read'))
        && $intent['method'] === 'GET' && $intent['actor'] === 'admin'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['path'])
        && preg_match('~\A/adminapi/product/reply\?product_id=([1-9][0-9]{0,9})&page=1&limit=20\z~D', $intent['path'], $path) === 1
        && bccomp($path[1], '2147483647', 0) <= 0,
        'NHEPAL_EXCHANGE_TRUE_33_ADMIN_GET_EXACT_QUERY_AND_ORIGIN');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPAL_EXCHANGE_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect(is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && $privateRequest['body'] === null && is_array($privateRequest['actor_identity']),
        'NHEPAL_EXCHANGE_EXISTING_ADMIN_TOKEN_AND_NULL_GET_BODY');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPAL_EXCHANGE_PRIVATE_ADMIN_IDENTITY_EXACT_TWO');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 4294967295
        && $privateRequest['actor_identity']['id'] === $intent['actor_id']
        && is_string($privateRequest['actor_identity']['account']),
        'NHEPAL_EXCHANGE_ORIGINAL_NATIVE_ADMIN_IDENTITY');
    nhe_keys($privateResponse, ['http', 'raw', 'json', 'actual_interval', 'transport_errno', 'primary_ip',
        'primary_port', 'transport_failure_class', 'headers', 'local_ip', 'local_port'],
        'NHEPAL_EXCHANGE_COMPLETE_ORIGINAL_PRIVATE_RESPONSE_EXACT_ELEVEN');
    $interval = $privateResponse['actual_interval'];
    nhep_expect(is_array($interval) && array_is_list($interval) && count($interval) === 2
        && is_int($interval[0]) && is_int($interval[1]) && $interval[0] > 0
        && $interval[0] <= $interval[1] && $interval[1] <= 2147483647
        && $privateResponse['http'] === 200 && $privateResponse['transport_errno'] === 0
        && $privateResponse['transport_failure_class'] === null && $privateResponse['primary_ip'] === '127.0.0.1'
        && $privateResponse['primary_port'] === 8000 && $privateResponse['local_ip'] === '127.0.0.1'
        && is_int($privateResponse['local_port']) && $privateResponse['local_port'] > 0 && $privateResponse['local_port'] <= 65535
        && is_string($privateResponse['raw']) && $privateResponse['raw'] !== '' && strlen($privateResponse['raw']) <= 6291456
        && is_array($privateResponse['json']) && !array_is_list($privateResponse['json']) && is_array($privateResponse['headers']),
        'NHEPAL_EXCHANGE_ONE_REAL_LOCAL_SUCCESS_AND_HTTP_SECONDS_INSIDE_SIGNED_TIME_RANGE');
    nhe_keys($privateResponse['headers'], ['lines', 'blocks', 'bytes', 'complete', 'limit_exceeded'],
        'NHEPAL_EXCHANGE_ORIGINAL_HEADER_CALLBACK_EXACT_FIVE');
    nhep_expect(is_array($privateResponse['headers']['lines']) && array_is_list($privateResponse['headers']['lines'])
        && is_array($privateResponse['headers']['blocks']) && array_is_list($privateResponse['headers']['blocks'])
        && is_int($privateResponse['headers']['bytes']) && $privateResponse['headers']['bytes'] > 0
        && $privateResponse['headers']['bytes'] <= 65536 && $privateResponse['headers']['complete'] === true
        && $privateResponse['headers']['limit_exceeded'] === false
        && count($privateResponse['headers']['blocks']) === 1
        && $privateResponse['headers']['blocks'][0] === $privateResponse['headers']['lines'],
        'NHEPAL_EXCHANGE_ORIGINAL_COMPLETE_NONTRUNCATED_HEADERS');
    $lines = $privateResponse['headers']['lines']; $headerBytes = 0;
    nhep_expect(count($lines) >= 3 && in_array($lines[0], ["HTTP/1.0 200 OK\r\n", "HTTP/1.1 200 OK\r\n"], true)
        && $lines[count($lines) - 1] === "\r\n", 'NHEPAL_EXCHANGE_REAL_STATUS_AND_FINAL_HEADER_CRLF');
    foreach ($lines as $line) {
        nhep_expect(is_string($line) && str_ends_with($line, "\r\n"), 'NHEPAL_EXCHANGE_EVERY_ORIGINAL_HEADER_LINE_COMPLETE');
        $headerBytes += strlen($line);
    }
    nhep_expect($headerBytes === $privateResponse['headers']['bytes'], 'NHEPAL_EXCHANGE_COMPLETE_HEADER_BYTE_SUM');
    $json = json_decode($privateResponse['raw'], true);
    nhep_expect(json_last_error() === JSON_ERROR_NONE && $json === $privateResponse['json'],
        'NHEPAL_EXCHANGE_ORIGINAL_COMPLETE_RAW_JSON_STRICT_JOIN');
    nhe_keys($json, ['status', 'msg', 'data'], 'NHEPAL_EXCHANGE_COMPLETE_SUCCESS_EXACT_THREE');
    nhep_expect($json['status'] === 200 && $json['msg'] === 'success' && is_array($json['data']),
        'NHEPAL_EXCHANGE_ORIGINAL_ADMIN_SUCCESS_ENVELOPE');
    nhe_keys($json['data'], ['list', 'count'], 'NHEPAL_EXCHANGE_ORIGINAL_COMPLETE_LIST_COUNT_KEYS');
    nhep_expect(is_array($json['data']['list']) && array_is_list($json['data']['list'])
        && count($json['data']['list']) === 1 && $json['data']['count'] === 1,
        'NHEPAL_EXCHANGE_REAL_ONE_VISIBLE_PRODUCT_REPLY_NATIVE_COUNT');
    nhepar_capture($beforeCapture); nhepar_capture($actualCapture);
    foreach ([$beforeCapture, $actualCapture] as $capture) {
        $sentinel = nhepar_entry($capture, 'audit:sentinel');
        nhep_expect(is_array($sentinel) && $sentinel['type'] === 'string' && $sentinel['expires'] === -1
            && $sentinel['value'] === $intent['run_id'], 'NHEPAL_EXCHANGE_BOTH_NATIVE_CAPTURES_SAME_ORIGINAL_RUN');
    }
    $beforeUs = bcadd(bcmul($beforeCapture['snapshot']['time'][0], '1000000', 0), $beforeCapture['snapshot']['time'][1], 0);
    $afterUs = bcadd(bcmul($actualCapture['snapshot']['time'][0], '1000000', 0), $actualCapture['snapshot']['time'][1], 0);
    nhep_expect(bccomp($afterUs, $beforeUs, 0) >= 0
        && bccomp($beforeCapture['snapshot']['time'][0], (string)$interval[0], 0) <= 0
        && bccomp((string)$interval[1], $actualCapture['snapshot']['time'][0], 0) <= 0,
        'NHEPAL_EXCHANGE_REAL_HTTP_WINDOW_ENCLOSED_BY_MONOTONIC_NATIVE_REDIS_TIME');
    return $json;
}

function nhep_platform_review_list_database_model(#[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $actualDB2, array $intent, #[SensitiveParameter] array $privateRequest,
    #[SensitiveParameter] array $privateResponse, #[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepal_context', 'nhepal_before_guards', 'nhepal_exchange',
        'nhepal_response_envelopes', 'nhep_auth_db_snapshot', 'nhep_auth_db_index', 'nhep_auth_db_time',
        'nhep_database_expected', 'm4lh_actor_next', 'm4lh_actor_expected_row'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPAL_DATABASE_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2); nhep_auth_db_snapshot($actualDB2);
    $context = nhepal_context($beforeDB2, $intent, $privateRequest);
    nhepal_before_guards($beforeDB2, $intent, $context);
    $json = nhepal_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    $interval = $privateResponse['actual_interval'];
    $envelopes = nhepal_response_envelopes($context, $interval);
    nhep_expect(in_array($json, $envelopes, true), 'NHEPAL_DATABASE_WHOLE_JSON_ONE_INDEPENDENT_COMPLETE_25_FIELD_TIME_BUCKET_ENVELOPE');
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $row)
        if ($row['oid'] === $context['order']['row']['id'])
            nhep_expect($row['change_time'] <= $interval[0], 'NHEPAL_DATABASE_ALL_FIVE_SAVED_STATUS_TIMES_BEFORE_REAL_HTTP');
    nhep_expect($context['order']['row']['add_time'] <= $interval[0]
        && $context['order']['row']['pay_time'] <= $interval[0]
        && $context['buyer']['row']['last_time'] <= $interval[0]
        && $context['admin']['row']['last_time'] <= $interval[0],
        'NHEPAL_DATABASE_EXISTING_BEFORE_ACTOR_BUYER_AND_ORDER_TIMES_PRECEDE_THIS_READ');
    $table = $beforeDB2['database']['tables']['eb_system_log'];
    $id = m4lh_actor_next($table, 'id'); $metadata = $table['metadata'];
    foreach ($beforeDB2['rows']['eb_system_log'] as $row)
        nhep_expect($row['id'] !== $id, 'NHEPAL_DATABASE_BEFORE_NEXT_LOG_ID_NOT_ALREADY_PRESENT');
    $index = nhep_auth_db_index($actualDB2['rows']['eb_system_log'], $metadata, 'id', $id);
    // The only AFTER scalar adopted is this independently named row's native bounded log time.
    $time = nhep_auth_db_time($metadata, 'add_time', $actualDB2['rows']['eb_system_log'][$index]['add_time'], $interval);
    $candidates = [];
    foreach ($context['visit_pages'] as $page) {
        $log = m4lh_actor_expected_row($metadata, ['id' => $id, 'admin_id' => $context['admin']['row']['id'],
            'admin_name' => $context['admin']['row']['account'], 'path' => 'product/reply', 'page' => $page,
            'method' => 'adminapi', 'ip' => '127.0.0.1', 'type' => 'system', 'add_time' => $time, 'merchant_id' => 0]);
        nhep_expect(count($log) === 10, 'NHEPAL_DATABASE_EACH_INDEPENDENT_COMPLETE_ORIGINAL_TEN_COLUMN_LOG_CANDIDATE');
        if ($log === $actualDB2['rows']['eb_system_log'][$index]) $candidates[] = $log;
    }
    nhep_expect(count($candidates) === 1, 'NHEPAL_DATABASE_EXACTLY_ONE_PREBUILT_WHOLE_LOG_MATCH_NO_ACTUAL_PAGE_FILL');
    $logs = $beforeDB2['rows']['eb_system_log']; $logs[] = $candidates[0];
    $expected = nhep_database_expected($beforeDB2, ['eb_system_log' => $logs], ['eb_system_log' => 1]);
    nhep_expect($expected === $actualDB2,
        'NHEPAL_DATABASE_ALL_164_TABLES_COMPLETE_HISTORY_DDL_METADATA_ONE_LOG_AI_ONLY_NO_ADMIN_OR_BUYER_UPDATE');
    return $expected;
}

function nhep_platform_review_list_redis_model(#[SensitiveParameter] array $beforeCapture,
    #[SensitiveParameter] array $actualCapture, #[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest, #[SensitiveParameter] array $privateResponse,
    #[SensitiveParameter] array $privateAuthConfiguration): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhepal_context', 'nhepal_before_guards', 'nhepal_exchange',
        'nhepal_response_envelopes', 'nhep_auth_db_snapshot', 'nhepar_capture', 'nhepar_entry', 'nhepar_actor',
        'nhepar_admin', 'nhepar_remember', 'nhepar_bind', 'nhepar_tag', 'nhepcr_config_wire', 'nhep_redis_expected',
        'bcadd', 'bcsub', 'bcmul', 'bccomp', 'serialize', 'hash_equals'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPAL_REDIS_PURE_DEPENDENCY_REQUIRED');
    nhep_auth_db_snapshot($beforeDB2);
    $context = nhepal_context($beforeDB2, $intent, $privateRequest);
    nhepal_before_guards($beforeDB2, $intent, $context);
    $json = nhepal_exchange($beforeCapture, $actualCapture, $intent, $privateRequest, $privateResponse);
    $interval = $privateResponse['actual_interval'];
    nhep_expect(in_array($json, nhepal_response_envelopes($context, $interval), true),
        'NHEPAL_REDIS_WHOLE_JSON_ONE_INDEPENDENT_COMPLETE_25_FIELD_TIME_BUCKET_ENVELOPE');
    foreach ($beforeDB2['rows']['eb_store_order_status'] as $row)
        if ($row['oid'] === $context['order']['row']['id'])
            nhep_expect($row['change_time'] <= $interval[0], 'NHEPAL_REDIS_ALL_FIVE_BEFORE_STATUS_TIMES_PRECEDE_THIS_HTTP');
    nhep_expect($context['order']['row']['add_time'] <= $interval[0] && $context['order']['row']['pay_time'] <= $interval[0]
        && $context['buyer']['row']['last_time'] <= $interval[0] && $context['admin']['row']['last_time'] <= $interval[0],
        'NHEPAL_REDIS_EXISTING_BEFORE_IDENTITIES_AND_TIMES');
    $config = $privateAuthConfiguration;
    nhep_expect(($config['run_id'] ?? null) === $intent['run_id'] && is_array($config['auth'] ?? null)
        && ($config['auth']['session_epoch'] ?? null) === 'audit-http-' . $intent['run_id']
        && ($config['auth']['issuer'] ?? null) === 'tianli-mall'
        && is_string($config['signing_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['signing_key']) === 1
        && is_string($config['auth']['stamp_key'] ?? null) && preg_match('/\A[a-f0-9]{64}\z/D', $config['auth']['stamp_key']) === 1
        && !hash_equals($config['signing_key'], $config['auth']['stamp_key']),
        'NHEPAL_REDIS_SAME_RUN_REAL_PRIVATE_ADMIN_AUTH_CONFIGURATION');
    $actor = nhepar_actor($beforeDB2['rows'], $intent, $privateRequest);
    nhep_expect($actor === $context['admin']['row'], 'NHEPAL_REDIS_REAL_COMPLETE_BEFORE_ADMIN_NOT_BUYER_SUBSTITUTION');
    $changes = []; $tagMembers = [];
    nhepar_admin($beforeCapture, $actualCapture, $actor, $intent, $privateRequest, $privateResponse, $config, $changes);
    foreach (['param_filter_type' => null, 'param_filter_data' => null] as $name => $value) {
        $wire = nhepcr_config_wire($beforeDB2, $name, $value);
        nhep_expect($wire === 'N;', 'NHEPAL_REDIS_TWO_MISSING_CONFIG_VALUES_HAVE_EXACT_NULL_SERIALIZATION');
        nhepar_remember($beforeCapture, $actualCapture, 'system_config_' . $name, $wire, 0, $changes, $tagMembers);
    }
    // Empty language tables independently determine all three values. Only these keys may expire/rebuild here.
    $interval = $privateResponse['actual_interval']; $ttlMs = '3600000';
    $getterLower = bcmul((string)$interval[0], '1000', 0);
    foreach (['sys_lang_source_map' => 'a:0:{}', 'type_id_zh-CN' => '1', 'lang_type_data' => 'a:0:{}'] as $name => $wire) {
        $key = 'c:' . $name; $old = nhepar_entry($beforeCapture, $key);
        if ($old === null || bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) > 0) {
            nhepar_remember($beforeCapture, $actualCapture, $name, $wire, 3600, $changes, $tagMembers);
            if ($old === null) {
                $new = nhepar_entry($actualCapture, $key);
                $writeMs = bcsub((string)$new['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPAL_REDIS_LANGUAGE_COLD_WRITE_CLOCK_INSIDE_ACTUAL_HTTP_SECONDS_AND_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
        } elseif (bccomp((string)$old['expires'], $actualCapture['snapshot']['time_ms'], 0) === 0
            && nhepar_entry($actualCapture, $key) !== null) {
            // Existing full-namespace algorithm expires only when A > E; E == A is not a rebuild.
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                'NHEPAL_REDIS_LANGUAGE_EQUAL_ACTUAL_DEADLINE_COMPATIBLE_WITH_SERIAL_WARM_GETTER');
            $descriptor = nhepar_bind($actualCapture, $key, 'string', $wire, $old['expires'], $beforeCapture['snapshot']);
            nhep_expect($descriptor === $beforeCapture['snapshot']['keys'][hash('sha256', $key)],
                'NHEPAL_REDIS_EQUAL_DEADLINE_COMPLETE_ORIGINAL_WARM_DESCRIPTOR_NOT_RENEWED');
            $tagMembers[] = $key;
        } else {
            nhep_expect($old['type'] === 'string' && $old['value'] === $wire && is_int($old['expires'])
                && $old['expires'] > 0 && bccomp((string)$old['expires'], $beforeCapture['snapshot']['time_ms'], 0) >= 0,
                'NHEPAL_REDIS_COMPLETE_BEFORE_LANGUAGE_VALUE_AND_NATURAL_DEADLINE');
            $now = nhepar_entry($actualCapture, $key);
            if ($now === null) {
                nhep_expect(bccomp((string)$old['expires'], bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp((string)$old['expires'], $getterLower, 0) >= 0,
                    'NHEPAL_REDIS_UNREBUILT_LANGUAGE_CAN_ONLY_EXPIRE_AFTER_A_SERIAL_POSSIBLE_REAL_GETTER');
            } else {
                $changes[$key] = nhepar_bind($actualCapture, $key, 'string', $wire, ['ttl' => 3600], $beforeCapture['snapshot']);
                $writeMs = bcsub((string)$now['expires'], $ttlMs, 0);
                nhep_expect(bccomp($writeMs, (string)$old['expires'], 0) > 0
                    && bccomp($writeMs, bcmul((string)$interval[0], '1000', 0), 0) >= 0
                    && bccomp($writeMs, bcmul((string)($interval[1] + 1), '1000', 0), 0) < 0
                    && bccomp($writeMs, $getterLower, 0) >= 0,
                    'NHEPAL_REDIS_NATURAL_REBUILD_STRICTLY_AFTER_OLD_EXPIRY_AND_INSIDE_HTTP_SERIAL_ORDER');
                $getterLower = $writeMs;
            }
            $tagMembers[] = $key;
        }
    }
    // Remember may SET N; again; this model proves full final values/deadlines/membership, not absence of writes.
    nhepar_tag($beforeCapture, $actualCapture, 'crmeb', $tagMembers, $changes);
    $expected = nhep_redis_expected($beforeCapture['snapshot'], $changes, $actualCapture['snapshot']['time']);
    nhep_expect($expected === $actualCapture['snapshot'],
        'NHEPAL_REDIS_FULL_NAMESPACE_ONLY_REAL_CONFIG_AND_LANGUAGE_DELTAS_WITH_ORIGINAL_JWT_TAGS');
    return $expected;
}


function nheprw_context(#[SensitiveParameter] array $beforeDB2, array $intent,
    #[SensitiveParameter] array $privateRequest): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhepar_actor', 'nhepcd_one',
        'nhepcd_id', 'nhepcv_native_row', 'm4lh_actor_native', 'm4lh_actor_expected_row',
        'bccomp', 'json_decode', 'json_encode', 'md5', 'hash'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHEPRW_CONTEXT_PURE_DEPENDENCY_REQUIRED');
    nhep_expect(PHP_INT_SIZE === 8, 'NHEPRW_CONTEXT_ORIGINAL_NATIVE_64_BIT');
    nhep_auth_db_snapshot($beforeDB2);
    nhe_keys($intent, ['run_id', 'sequence', 'step', 'origin', 'method', 'path', 'actor', 'actor_id'],
        'NHEPRW_CONTEXT_ORIGINAL_COMPLETE_INTENT');
    $approve = $intent['sequence'] === 34;
    nhep_expect(in_array($intent['sequence'], [34, 35], true)
        && $intent['step'] === ($approve ? 'platform_review_approve' : 'platform_review_reply')
        && $intent['method'] === 'PUT' && $intent['actor'] === 'admin'
        && $intent['origin'] === 'http://127.0.0.1:8000' && is_string($intent['run_id'])
        && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $intent['run_id']) === 1
        && is_string($intent['path'])
        && preg_match($approve ? '~\A/adminapi/product/reply/set_status/([1-9][0-9]{0,9})/1\z~D'
            : '~\A/adminapi/product/reply/set_reply/([1-9][0-9]{0,9})\z~D', $intent['path'], $path) === 1
        && bccomp($path[1], '2147483647', 0) <= 0,
        'NHEPRW_CONTEXT_ONLY_TRUE_34_OR_35_ADMIN_PUT_CANONICAL_RID_AND_ORIGIN');
    nhe_keys($privateRequest, ['token', 'body', 'actor_identity'], 'NHEPRW_CONTEXT_PRIVATE_REQUEST_EXACT_THREE');
    nhep_expect(is_string($privateRequest['token'])
        && preg_match('/\A[A-Za-z0-9._~-]{16,4096}\z/D', $privateRequest['token']) === 1
        && $privateRequest['body'] === ($approve ? [] : ['content' => 'normal-reply-' . $intent['run_id']])
        && is_array($privateRequest['actor_identity']),
        'NHEPRW_CONTEXT_REAL_ADMIN_TOKEN_AND_ORIGINAL_EXACT_PUT_BODY');
    nhe_keys($privateRequest['actor_identity'], ['id', 'account'], 'NHEPRW_CONTEXT_REAL_ADMIN_IDENTITY_EXACT_TWO');
    nhep_expect(is_int($intent['actor_id']) && $intent['actor_id'] > 0 && $intent['actor_id'] <= 4294967295
