            && $baseCart === m4lh_actor_expected_row($cartMetadata, ['id' => $cartId, 'uid' => $uid,
                'type' => '0', 'product_id' => $pid, 'product_attr_unique' => $fixture['sku_unique'],
                'cart_num' => 1, 'add_time' => $baseCart['add_time']])
            && is_array($cart['productInfo'] ?? null) && is_array($cart['attrInfo'] ?? null)
            && ($cart['productInfo']['attrInfo'] ?? null) === $cart['attrInfo'],
            'NHE_HISTORY_IDENTITIES_ORIGINAL_OWNED_CART_AND_TWO_SAVED_SKU_RELATIONS');
        $historicalSku = $sku; $historicalProduct = $product;
        $historicalSku['stock'] = $refunded ? 10 : 9; $historicalSku['sales'] = $refunded ? 0 : 1;
        $historicalProduct['stock'] = $historicalSku['stock']; $historicalProduct['sales'] = $historicalSku['sales'];
        $slides = json_decode($product['slider_image'], true);
        nhep_expect(json_last_error() === JSON_ERROR_NONE && $slides === [$fixture['public_image_path']],
            'NHE_HISTORY_IDENTITIES_ORIGINAL_PRODUCT_SLIDER_GETTER');
        $historicalProduct['slider_image'] = $slides; $historicalProduct['express_delivery'] = true;
        $historicalProduct['store_mention'] = false; $historicalProduct['attrInfo'] = $historicalSku;
        nhep_expect($cart['attrInfo'] === $historicalSku && $cart['productInfo'] === $historicalProduct,
            'NHE_HISTORY_IDENTITIES_COMPLETE_SAVED_PRODUCT_SKU_WITH_CREATE_TIME_INVENTORY_NOT_CURRENT_STOCK');
        $expectedCart = $baseCart;
        $expectedCart['productInfo'] = $historicalProduct; $expectedCart['attrInfo'] = $historicalSku;
        $expectedCart['min_qty'] = 1; $expectedCart['attrStatus'] = true; $expectedCart['vip_truePrice'] = 0;
        $expectedCart['costPrice'] = '7.45'; $expectedCart['trueStock'] = $historicalSku['stock'];
        $expectedCart['truePrice'] = 20.15; $expectedCart['sum_price'] = '20.15';
        $expectedCart['price_type'] = 'level'; $expectedCart['is_valid'] = 1; $expectedCart['postage_price'] = 0;
        $expectedCart['use_integral'] = 0; $expectedCart['integral_price'] = 0; $expectedCart['coupon_price'] = 0;
        $expectedCart['sum_true_price'] = '20.15'; $expectedCart['one_brokerage'] = '0'; $expectedCart['two_brokerage'] = '0';
        $expectedCart['staff_brokerage'] = '0.00'; $expectedCart['agent_brokerage'] = '0.00';
        $expectedCart['division_brokerage'] = '0.00';
        nhep_expect($expectedCart === $cart, 'NHE_HISTORY_IDENTITIES_ALL_SAVED_CART_KEYS_TYPES_PRICES_AND_ORDER');

        $messages = ['cache_key_create_order' => '订单生成', 'pay_success' => '用户付款成功'];
        $messages += $refunded ? ['integral_back' => '商品退积分', 'refund_price' => '退款给用户：20.15元']
            : ['delivery_goods' => '已发货 快递公司：顺丰速运 快递单号：NHE' . $run,
                'take_delivery' => '已收货', 'check_order_over' => '用户评价'];
        $statusTable = $expectedDB2['database']['tables']['eb_store_order_status'];
        nhep_expect(array_keys($statusTable['metadata']['columns']) === ['oid', 'change_type', 'change_message', 'change_time']
            && $statusTable['metadata']['table']['AUTO_INCREMENT'] === null,
            'NHE_HISTORY_IDENTITIES_ORIGINAL_FOUR_FIELD_STATUS_WITHOUT_AI');
        $logs = [];
        foreach ($expectedDB2['rows']['eb_store_order_status'] as $index => $unused) {
            $status = nhepcv_native_row($expectedDB2, 'eb_store_order_status', $index);
            if ($status['oid'] !== $oid) continue;
            nhep_expect(is_string($status['change_type']) && isset($messages[$status['change_type']])
                && !array_key_exists($status['change_type'], $logs) && is_int($status['change_time'])
                && $status['change_time'] >= $root['add_time'] && $status['change_time'] <= 2147483647
                && $status === m4lh_actor_expected_row($statusTable['metadata'], ['oid' => $oid,
                    'change_type' => $status['change_type'], 'change_message' => $messages[$status['change_type']],
                    'change_time' => $status['change_time']]), 'NHE_HISTORY_IDENTITIES_EACH_COMPLETE_ORIGINAL_STATUS_ROW');
            $logs[$status['change_type']] = $status['change_time'];
        }
        nhe_keys($logs, array_keys($messages), 'NHE_HISTORY_IDENTITIES_EXACT_REFUND_FOUR_OR_COMPLETED_FIVE_HISTORY_LOGS');
        nhep_expect($logs['cache_key_create_order'] <= $logs['pay_success']
            && $logs['pay_success'] >= $root['pay_time'], 'NHE_HISTORY_IDENTITIES_NATIVE_CREATE_PAY_LOG_ORDER');
        $roots[$family] = $root; $items[$family] = $item; $savedCarts[$family] = $cart; $historyTimes[$family] = $logs;
        $rootIdentities[$family] = ['id' => $oid, 'order_no' => $root['order_id'],
            'order_unique' => $root['unique'], 'item_unique' => $item['unique'], 'cart_id' => $cartId,
            'paid' => $root['paid'], 'status' => $root['status'], 'refund_status' => $root['refund_status']];
    }
    foreach (['id', 'order_no', 'order_unique', 'item_unique', 'cart_id'] as $key)
        nhep_expect($rootIdentities['refund_family'][$key] !== $rootIdentities['review_family'][$key],
            'NHE_HISTORY_IDENTITIES_TWO_DISTINCT_ORIGINAL_FAMILIES');
    $refundRoot = $roots['refund_family']; $reviewRoot = $roots['review_family'];
    nhep_expect($refundRoot['pay_time'] <= $roots['review_family']['add_time'],
        'NHE_HISTORY_IDENTITIES_ORIGINAL_REFUND_FAMILY_PAID_BEFORE_SECOND_CREATE');

    $refund = nhepcd_one($expectedDB2, 'eb_store_order_refund', ['store_order_id' => $refundRoot['id'], 'uid' => $uid]);
    $refundRow = nhepcv_native_row($expectedDB2, 'eb_store_order_refund', $refund['index']);
    nhep_expect(array_keys($refund['metadata']['columns']) === ['id', 'store_order_id', 'store_id', 'order_id',
        'uid', 'refund_type', 'refund_num', 'refund_price', 'refunded_price', 'refund_phone', 'refund_express',
        'refund_express_name', 'refund_explain', 'refund_img', 'refund_reason', 'refuse_reason', 'remark',
        'refunded_time', 'cart_info', 'is_cancel', 'is_pink_cancel', 'is_del', 'add_time', 'is_system_del'],
        'NHE_HISTORY_IDENTITIES_ORIGINAL_COMPLETE_TWENTY_FOUR_REFUND_COLUMNS');
    $rid = nhepcd_id($refundRow['id'], 2147483647); $refundNumber = $refundRow['order_id'];
    nhep_expect(is_string($refundNumber) && preg_match('/\A[1-9][0-9]{0,18}\z/D', $refundNumber) === 1
        && bccomp($refundNumber, '9223372036854775807', 0) <= 0
        && is_int($refundRow['add_time']) && $refundRow['add_time'] >= $reviewRoot['pay_time']
        && is_int($refundRow['refunded_time']) && $refundRow['refunded_time'] >= $refundRow['add_time']
        && $refundRow['refunded_time'] <= 2147483647
        && $refundRow === m4lh_actor_expected_row($refund['metadata'], ['id' => $rid,
            'store_order_id' => $refundRoot['id'], 'store_id' => 0, 'order_id' => $refundNumber, 'uid' => $uid,
            'refund_type' => 6, 'refund_num' => 1, 'refund_price' => '20.15', 'refunded_price' => '20.15',
            'refund_img' => '[]', 'refund_reason' => 'normal-refund-' . $run,
            'refunded_time' => $refundRow['refunded_time'], 'cart_info' => json_encode([$savedCarts['refund_family']]),
            'add_time' => $refundRow['add_time'], 'is_pink_cancel' => 0]),
        'NHE_HISTORY_IDENTITIES_COMPLETE_ORIGINAL_COMPLETED_REFUND_FROM_EXPECTED_ROOT_AND_SAVED_CART');
    $refundNumbers = [];
    foreach ($expectedDB2['rows']['eb_store_order_refund'] as $index => $unused) {
        $candidate = nhepcv_native_row($expectedDB2, 'eb_store_order_refund', $index); $number = $candidate['order_id'];
        nhep_expect(is_string($number) && preg_match('/\A[\x20-\x7e]*\z/D', $number) === 1
            && (strtolower(rtrim($number, ' ')) !== $refundNumber || $number === $refundNumber),
            'NHE_HISTORY_IDENTITIES_NO_SQL_EQUIVALENT_REFUND_NUMBER_ALIAS');
        if ($number === $refundNumber) $refundNumbers[] = $index;
    }
    nhep_expect($refundNumbers === [$refund['index']], 'NHE_HISTORY_IDENTITIES_GLOBAL_ORIGINAL_REFUND_NUMBER_UNIQUE');

    $replyMatches = [];
    foreach ($expectedDB2['rows']['eb_store_product_reply'] as $index => $unused) {
        $candidate = nhepcv_native_row($expectedDB2, 'eb_store_product_reply', $index);
        nhep_expect(is_string($candidate['unique']) && preg_match('/\A[A-Za-z0-9]*\z/D', $candidate['unique']) === 1,
            'NHE_HISTORY_IDENTITIES_CANONICAL_GLOBAL_REPLY_UNIQUE_SELECTOR');
        if (strtolower($candidate['unique']) === $items['review_family']['unique'])
            $replyMatches[] = ['index' => $index, 'row' => $candidate];
    }
    nhep_expect(count($replyMatches) === 1, 'NHE_HISTORY_IDENTITIES_SELECT_REPLY_BY_GLOBAL_ITEM_UNIQUE_BEFORE_ANY_OWNER_FILTER');
    $reply = $replyMatches[0]['row']; $replyMetadata = $expectedDB2['database']['tables']['eb_store_product_reply']['metadata'];
    $replyId = nhepcd_id($reply['id'], 2147483647);
    nhep_expect(array_keys($replyMetadata['columns']) === ['id', 'uid', 'oid', 'unique', 'product_id',
        'reply_type', 'product_score', 'service_score', 'comment', 'pics', 'add_time',
        'merchant_reply_content', 'merchant_reply_time', 'is_del', 'is_reply', 'nickname', 'avatar', 'suk', 'status']
        && is_int($reply['add_time']) && $reply['add_time'] > 0 && $reply['add_time'] <= 2147483647
        && is_int($reply['merchant_reply_time']) && $reply['merchant_reply_time'] >= $reply['add_time']
        && $reply['merchant_reply_time'] <= 2147483647
        && $reply === m4lh_actor_expected_row($replyMetadata, ['id' => $replyId, 'uid' => $uid,
            'oid' => $reviewRoot['id'], 'unique' => $items['review_family']['unique'], 'product_id' => $pid,
            'reply_type' => 'product', 'product_score' => 5, 'service_score' => 5,
            'comment' => 'normal-history-' . $run, 'pics' => '', 'add_time' => $reply['add_time'],
            'merchant_reply_content' => 'normal-reply-' . $run, 'merchant_reply_time' => $reply['merchant_reply_time'],
            'is_del' => 0, 'is_reply' => 1, 'nickname' => $user['nickname'], 'avatar' => $user['avatar'],
            'suk' => $fixture['sku_suk'], 'status' => 1]),
        'NHE_HISTORY_IDENTITIES_COMPLETE_NINETEEN_NATIVE_APPROVED_REPLIED_ORIGINAL_PURCHASE');
    $logs = $historyTimes['review_family'];
    nhep_expect($logs['pay_success'] <= $logs['delivery_goods']
        && $logs['delivery_goods'] >= $reviewRoot['pay_time']
        && $logs['delivery_goods'] <= $logs['take_delivery']
        && $logs['take_delivery'] <= $reply['add_time'] && $reply['add_time'] <= $logs['check_order_over']
        && $user['last_time'] >= $reply['merchant_reply_time'] && $user['last_time'] >= $logs['check_order_over']
        && $user['last_time'] >= $refundRow['refunded_time'],
        'NHE_HISTORY_IDENTITIES_FIVE_INDEPENDENT_REVIEW_HISTORY_TIMES_AND_FINAL_CUSTOMER_READ');

    $identities = ['refund_family' => $rootIdentities['refund_family'], 'review_family' => $rootIdentities['review_family'],
        'refund' => ['id' => $rid, 'order_no' => $refundNumber, 'root_id' => $refundRoot['id'], 'refund_type' => $refundRow['refund_type']],
        'review' => ['id' => $replyId, 'root_id' => $reply['oid'], 'status' => $reply['status'], 'is_reply' => $reply['is_reply']]];
    // HTTP IDs never select the expected rows above. This is the final counterpart-only join.
    nhe_keys($httpSummary, ['schema', 'scope', 'run_id', 'legacy_source_sha', 'buyer_uid', 'admin_id',
        'product_id', 'sku_id', 'refund_family', 'review_family', 'refund', 'review', 'http_steps',
        'business_acceptance', 'native_children_close_and_independent_zero'],
        'NHE_HISTORY_IDENTITIES_ORIGINAL_COMPLETE_HTTP_SUMMARY');
    nhep_expect($httpSummary['schema'] === 1 && $httpSummary['scope'] === 'legacy_http_ids_and_observed_states_only'
        && $httpSummary['run_id'] === $run && $httpSummary['legacy_source_sha'] === $fixture['legacy_source_sha']
        && $httpSummary['buyer_uid'] === $uid && $httpSummary['admin_id'] === $fixture['admin_id']
        && $httpSummary['product_id'] === $pid && $httpSummary['sku_id'] === $fixture['sku_id']
        && $httpSummary['business_acceptance'] === 'NOT SIGNED'
        && $httpSummary['native_children_close_and_independent_zero'] === 'REQUIRED_BY_OUTER_PRODUCER',
        'NHE_HISTORY_IDENTITIES_HTTP_SAME_RUN_FIXTURE_AND_ORIGINAL_SCOPE_ONLY');
    foreach ($identities as $key => $identity)
        nhep_expect($httpSummary[$key] === $identity, 'NHE_HISTORY_IDENTITIES_INDEPENDENT_EXPECTED_IDENTITY_EQUALS_HTTP_COUNTERPART');
    $steps = ['admin_login', 'admin_identity', 'platform_self_merchant_review', 'platform_self_merchant_accept_orders',
        'customer_login', 'customer_identity', 'platform_system_balance_add', 'funded_balance_read',
        'refund_family_cart', 'refund_family_confirm', 'refund_family_create', 'refund_family_unpaid_read',
        'refund_family_pay', 'refund_family_paid_read', 'review_family_cart', 'review_family_confirm',
        'review_family_create', 'review_family_unpaid_read', 'review_family_pay', 'review_family_paid_read',
        'two_paid_balance_read', 'unshipped_refund_apply', 'owned_refund_identity', 'platform_refund_approve',
        'owned_refund_completed_read', 'owned_refunded_root_read', 'refunded_balance_read',
        'platform_manual_courier', 'owned_shipped_read', 'customer_receipt', 'owned_received_read',
        'customer_purchased_item_comment', 'platform_pending_review_identity', 'platform_review_approve',
        'platform_review_reply', 'platform_approved_replied_read', 'owned_commented_completed_read'];
    nhep_expect(is_array($httpSummary['http_steps']) && array_is_list($httpSummary['http_steps'])
        && count($httpSummary['http_steps']) === 37, 'NHE_HISTORY_IDENTITIES_COMPLETE_THIRTY_SEVEN_HTTP_RECEIPTS');
    foreach ($steps as $index => $step)
        nhep_expect($httpSummary['http_steps'][$index] === ['step' => $step, 'http' => 200],
            'NHE_HISTORY_IDENTITIES_EACH_REAL_ORIGINAL_STEP_IN_EXACT_ORDER');
    return $identities;
}

function nhep_migration_snapshot_expected(#[SensitiveParameter] array $expectedDB2,
    #[SensitiveParameter] array $expectedRedis): array
{
    foreach (['nhep_expect', 'nhe_keys', 'nhep_auth_db_snapshot', 'nhep_redis_snapshot',
        'nhepcv_native_row', 'json_encode', 'hash', 'sort', 'ksort', 'implode'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_MIGRATION_BRIDGE_PURE_DEPENDENCIES_REQUIRED');
    nhep_expect(PHP_INT_SIZE === 8, 'NHE_MIGRATION_BRIDGE_NATIVE_64_BIT_REQUIRED');
    nhep_auth_db_snapshot($expectedDB2);
    nhep_redis_snapshot($expectedRedis);

    $originalModes = $expectedDB2['database']['modes'];
    nhep_expect(array_is_list($originalModes) && count($originalModes) === 1
        && is_array($originalModes[0]), 'NHE_MIGRATION_BRIDGE_ONE_COMPLETE_NATIVE_MODE_ROW');
    $mode = $originalModes[0];
    nhe_keys($mode, ['session_mode', 'global_mode', 'session_innodb', 'global_innodb',
        'session_stats_expiry', 'global_stats_expiry', 'session_increment', 'global_increment',
        'session_offset', 'global_offset'], 'NHE_MIGRATION_BRIDGE_ALL_ORIGINAL_MODE_FIELDS');
    nhep_expect(is_string($mode['session_mode']) && is_string($mode['global_mode']),
        'NHE_MIGRATION_BRIDGE_ORIGINAL_SQL_MODE_NATIVE_STRINGS');
    foreach (['session_innodb', 'global_innodb', 'session_increment', 'global_increment',
        'session_offset', 'global_offset'] as $name)
        nhep_expect($mode[$name] === 1, 'NHE_MIGRATION_BRIDGE_ORIGINAL_STRICT_UNIT_COUNTER_MODES');
    foreach (['session_stats_expiry', 'global_stats_expiry'] as $name)
        nhep_expect($mode[$name] === 0, 'NHE_MIGRATION_BRIDGE_ORIGINAL_IMMEDIATE_METADATA_MODES');

    // This second projection retains the private serialize projection unchanged.
    $snapshot = ['names' => $expectedDB2['database']['names'], 'tables' => [], 'redis' => [],
        'modes' => [['session_mode' => $mode['session_mode'], 'global_mode' => $mode['global_mode'],
            'session_innodb' => $mode['session_innodb'], 'global_innodb' => $mode['global_innodb']]]];
    foreach ($snapshot['names'] as $name) {
        nhep_expect(is_string($name) && preg_match('/\A(?:eb_[a-z0-9_]+|audit_sentinel)\z/D', $name) === 1,
            'NHE_MIGRATION_BRIDGE_ONLY_ORIGINAL_COMPLETE_TABLE_NAMES');
        $table = $expectedDB2['database']['tables'][$name];
        $metadata = $table['metadata']; $columns = $table['projected_columns'];
        nhe_keys($metadata, ['table', 'columns', 'indexes', 'constraints', 'checks', 'foreign', 'triggers'],
            'NHE_MIGRATION_BRIDGE_COMPLETE_ORIGINAL_METADATA_FIELDS');
        foreach (['table', 'columns', 'indexes', 'constraints', 'checks', 'foreign', 'triggers'] as $part)
            nhep_expect(is_array($metadata[$part]), 'NHE_MIGRATION_BRIDGE_ORIGINAL_METADATA_ARRAYS');
        nhe_keys($metadata['table'], ['TABLE_TYPE', 'ENGINE', 'ROW_FORMAT', 'TABLE_COLLATION',
            'TABLE_COMMENT', 'CREATE_OPTIONS', 'AUTO_INCREMENT'], 'NHE_MIGRATION_BRIDGE_ORIGINAL_TABLE_METADATA');
        $counter = $metadata['table']['AUTO_INCREMENT'];
        nhep_expect($counter === null || (is_int($counter) && $counter > 0)
            || (is_string($counter) && preg_match('/\A[1-9][0-9]*\z/D', $counter) === 1),
            'NHE_MIGRATION_BRIDGE_ORIGINAL_NATIVE_AUTO_INCREMENT_WITHOUT_CAST');
        nhep_expect(array_is_list($columns) && $columns !== [] && $columns === array_keys($metadata['columns']),
            'NHE_MIGRATION_BRIDGE_COMPLETE_ORIGINAL_PROJECTED_COLUMN_ORDER');
        foreach ($columns as $column)
            nhep_expect(is_string($column) && preg_match('/\A[A-Za-z0-9_]{1,64}\z/D', $column) === 1,
                'NHE_MIGRATION_BRIDGE_ORIGINAL_COLUMN_IDENTIFIER');

        $hashes = [];
        foreach ($expectedDB2['rows'][$name] as $index => $unused) {
            // The existing pure helper rejects a non-native cast or incomplete original row.
            $nativeRow = nhepcv_native_row($expectedDB2, $name, $index); $ordered = [];
            foreach ($columns as $column) $ordered[$column] = $nativeRow[$column];
            $hashes[] = hash('sha256', json_encode($ordered, JSON_THROW_ON_ERROR));
        }
        // Duplicate rows stay duplicate; there is no final LF, including for an empty table.
        sort($hashes, SORT_STRING);
        $snapshot['tables'][$name] = ['metadata' => $metadata, 'ddl_sha256' => hash('sha256', $table['ddl']),
            'projection' => ['rows' => count($expectedDB2['rows'][$name]),
                'sha256' => hash('sha256', implode("\n", $hashes))],
            'projected_columns' => $columns];
    }
    foreach ($expectedRedis['keys'] as $keyHash => $descriptor)
        $snapshot['redis'][$keyHash] = ['sha256' => $descriptor['sha256'], 'expires' => $descriptor['expires']];
    ksort($snapshot['redis'], SORT_STRING);
    return $snapshot;
}

function nhep_channel_no_extra(array &$children): array
{
    foreach (['nhep_expect', 'nhe_keys', 'audit_app_proc_stat', 'audit_app_group_members',
        'nhep_child_listener', 'nhep_child_observation', 'nhep_channel_observe',
        'hrtime', 'stream_select', 'stream_get_meta_data', 'stream_socket_get_name', 'feof',
        'get_resource_id', 'get_resource_type'] as $dependency)
        if (!function_exists($dependency)) throw new RuntimeException('NHE_CHANNEL_NO_EXTRA_NATIVE_DEPENDENCY_REQUIRED');
    nhep_expect(PHP_SAPI === 'cli' && PHP_INT_SIZE === 8 && defined('SIGKILL') && defined('SIGTERM'),
        'NHE_CHANNEL_NO_EXTRA_ORIGINAL_NATIVE_PARENT');
    nhe_keys($children, ['channel', 'http'], 'NHE_CHANNEL_NO_EXTRA_TWO_ORIGINAL_CHILDREN');
    nhep_expect(is_array($children['http']) && is_array($children['channel']),
        'NHE_CHANNEL_NO_EXTRA_ORIGINAL_CHILD_RECORDS');
    $http =& $children['http']; $channelChild =& $children['channel'];
    nhep_expect(is_array($channelChild['subscriber'] ?? null), 'NHE_CHANNEL_NO_EXTRA_REGISTERED_SUBSCRIBER');
    $subscriber =& $channelChild['subscriber'];
    nhe_keys($subscriber, ['socket', 'socket_id', 'local_endpoint', 'state'],
        'NHE_CHANNEL_NO_EXTRA_ORIGINAL_SUBSCRIBER_FOUR_KEYS');
    nhep_expect(is_array($subscriber['state']), 'NHE_CHANNEL_NO_EXTRA_REGISTERED_STATE_REFERENCE');
    $state =& $subscriber['state'];
    $quietNs = 10000000000; $startedNs = null; $endedNs = null; $zeroReturns = 0;
    $socketId = null; $localEndpoint = null; $runId = null; $httpClosedProof = null;
    $channelProofs = []; $metadataProofs = [];
    foreach (['before', 'after'] as $phase) {
        nhep_expect(array_key_exists('process', $http) && $http['process'] === null
            && ($http['kind'] ?? null) === 'http' && ($http['phase'] ?? null) === 'native_closed'
            && is_array($http['closed'] ?? null) && is_array($http['group'] ?? null)
            && is_array($http['first_terminal'] ?? null) && is_array($http['first_native'] ?? null)
            && is_array($http['observation'] ?? null) && is_array($http['supervisor'] ?? null),
            'NHE_CHANNEL_NO_EXTRA_HTTP_ORIGINAL_CLOSE_COMPLETED');
        $closed = $http['closed']; $terminal = $http['first_terminal']; $group = $http['group'];
        nhe_keys($closed, ['stopped', 'group', 'remaining_members', 'listener_open', 'first_terminal',
            'term_attempted', 'stop_signal', 'proc_close_exit', 'streams', 'waits'],
            'NHE_CHANNEL_NO_EXTRA_HTTP_FULL_ORIGINAL_CLOSE_RECEIPT');
        nhe_keys($group, ['leader_pid', 'pgid', 'sid', 'leader_starttime'],
            'NHE_CHANNEL_NO_EXTRA_HTTP_REGISTERED_GROUP');
        nhe_keys($terminal, ['pid', 'running', 'signaled', 'stopped', 'exitcode', 'termsig', 'stopsig'],
            'NHE_CHANNEL_NO_EXTRA_HTTP_FIRST_NATIVE_TERMINAL');
        nhep_expect(is_int($terminal['pid']) && $terminal['pid'] > 1 && $terminal['running'] === false
            && is_bool($terminal['signaled']) && is_bool($terminal['stopped']) && is_int($terminal['exitcode'])
            && is_int($terminal['termsig']) && $terminal['termsig'] !== SIGKILL && is_int($terminal['stopsig'])
            && ($http['native_pid'] ?? null) === $terminal['pid']
            && ($http['first_native']['pid'] ?? null) === $terminal['pid']
            && ($http['first_native']['running'] ?? null) === true
            && $group['leader_pid'] === $terminal['pid'] && $group['pgid'] === $terminal['pid']
            && $group['sid'] === $terminal['pid'] && is_string($group['leader_starttime'])
            && ctype_digit($group['leader_starttime']) && $group['leader_starttime'] !== ''
            && ($http['observation']['group'] ?? null) === $group
            && ($http['observation']['native']['pid'] ?? null) === $terminal['pid']
            && is_array($http['observation']['members'] ?? null) && count($http['observation']['members']) === 1
            && ($http['observation']['members'][0]['pid'] ?? null) === $terminal['pid']
            && ($http['observation']['members'][0]['ppid'] ?? null) === getmypid()
            && ($http['observation']['members'][0]['starttime'] ?? null) === $group['leader_starttime'],
            'NHE_CHANNEL_NO_EXTRA_HTTP_SAME_HANDLE_GROUP_AND_FIRST_TERMINAL');
        nhep_expect($closed['stopped'] === true && $closed['group'] === $group
            && $closed['remaining_members'] === [] && $closed['listener_open'] === false
            && $closed['first_terminal'] === $terminal && is_int($closed['proc_close_exit'])
            && is_bool($http['term_attempted'] ?? null) && is_bool($http['term_sent'] ?? null)
            && $closed['term_attempted'] === $http['term_attempted']
            && $closed['stop_signal'] === ($http['term_sent'] ? SIGTERM : null)
            && is_array($http['waits'] ?? null) && $closed['waits'] === $http['waits']
            && is_array($closed['streams']) && is_array($http['streams'] ?? null),
            'NHE_CHANNEL_NO_EXTRA_HTTP_CLOSE_FROM_ORIGINAL_NATIVE_LIFECYCLE');
        nhe_keys($closed['streams'], ['stdout', 'stderr'], 'NHE_CHANNEL_NO_EXTRA_HTTP_BOTH_COMPLETE_STREAMS');
        foreach (['stdout', 'stderr'] as $name) {
            $complete = $closed['streams'][$name];
            nhep_expect(is_array($complete) && is_array($http['streams'][$name] ?? null),
                'NHE_CHANNEL_NO_EXTRA_HTTP_ORIGINAL_STREAM_RECORD');
            nhe_keys($complete, ['bytes', 'sha256'], 'NHE_CHANNEL_NO_EXTRA_HTTP_COMPLETE_STREAM_DESCRIPTOR');
            nhep_expect(is_int($complete['bytes']) && $complete['bytes'] >= 0 && $complete['bytes'] <= 16777216
                && is_string($complete['sha256']) && preg_match('/\A[a-f0-9]{64}\z/D', $complete['sha256']) === 1
                && ($http['streams'][$name]['complete'] ?? null) === $complete
                && array_key_exists('handle', $http['streams'][$name]) && $http['streams'][$name]['handle'] === null,
                'NHE_CHANNEL_NO_EXTRA_HTTP_FULL_STREAM_SEALED_AND_HANDLE_CLOSED');
        }
        $parent = audit_app_proc_stat(getmypid());
        foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
            nhep_expect(is_array($parent) && array_key_exists($key, $parent)
                && $parent[$key] === ($http['supervisor'][$key] ?? null)
                && $parent[$key] === ($channelChild['supervisor'][$key] ?? null),
                'NHE_CHANNEL_NO_EXTRA_SAME_ORIGINAL_NATIVE_PARENT');
        $remaining = audit_app_group_members($group, $http['supervisor']);
        $httpListener = nhep_child_listener('http');
        nhep_expect($remaining === [] && $httpListener === ['open' => false, 'rows' => []],
            'NHE_CHANNEL_NO_EXTRA_FRESH_HTTP_ORIGINAL_GROUP_AND_LISTENER_EMPTY');
        $httpProof = ['group' => $group, 'first_terminal' => $terminal,
            'proc_close_exit' => $closed['proc_close_exit'], 'remaining_members' => $remaining,
            'listener_open' => $httpListener['open']];
        if ($phase === 'before') $httpClosedProof = $httpProof;
        else nhep_expect($httpProof === $httpClosedProof, 'NHE_CHANNEL_NO_EXTRA_HTTP_CLOSE_IDENTITY_UNCHANGED');

        nhep_expect(($channelChild['kind'] ?? null) === 'channel' && ($channelChild['phase'] ?? null) === 'native_ready'
            && array_key_exists('closed', $channelChild) && $channelChild['closed'] === null
            && array_key_exists('first_terminal', $channelChild) && $channelChild['first_terminal'] === null
            && is_resource($channelChild['process'] ?? null)
            && ($channelChild['observe'] ?? null) instanceof Closure,
            'NHE_CHANNEL_NO_EXTRA_ORIGINAL_CHANNEL_STILL_LIVE');
        nhe_keys($state, ['socket', 'socket_id', 'local_endpoint', 'observe', 'proof', 'run_id',
            'self_operated_mer_id', 'readiness_packet', 'closed'], 'NHE_CHANNEL_NO_EXTRA_ORIGINAL_READY_STATE_NINE_KEYS');
        nhep_expect($state['closed'] === false && $state['observe'] === $channelChild['observe']
            && $state['run_id'] === ($channelChild['run_id'] ?? null) && $state['run_id'] === ($http['run_id'] ?? null)
            && is_string($state['run_id']) && preg_match('/\A[0-9]{14}[a-f0-9]{6}\z/D', $state['run_id']) === 1
            && is_int($state['self_operated_mer_id']) && $state['self_operated_mer_id'] > 0
            && $state['self_operated_mer_id'] <= 4294967295 && is_array($state['proof'])
            && is_resource($state['socket']) && get_resource_type($state['socket']) === 'stream'
            && $state['socket'] === $subscriber['socket'] && is_int($state['socket_id']) && $state['socket_id'] > 0
            && get_resource_id($state['socket']) === $state['socket_id']
            && $state['socket_id'] === $subscriber['socket_id']
            && is_string($state['local_endpoint']) && $state['local_endpoint'] === $subscriber['local_endpoint']
            && stream_socket_get_name($state['socket'], false) === $state['local_endpoint']
            && stream_socket_get_name($state['socket'], true) === '127.0.0.1:40003',
            'NHE_CHANNEL_NO_EXTRA_SAME_REGISTERED_REFERENCE_SOCKET_ENDPOINTS_OBSERVER_AND_RUN');
        if ($phase === 'before') {
            $socketId = $state['socket_id']; $localEndpoint = $state['local_endpoint']; $runId = $state['run_id'];
        } else {
            nhep_expect($state['socket_id'] === $socketId && $state['local_endpoint'] === $localEndpoint
                && $state['run_id'] === $runId, 'NHE_CHANNEL_NO_EXTRA_ORIGINAL_SUBSCRIBER_IDENTITY_UNCHANGED');
        }
        $proof = nhep_child_observation($children, 'channel');
        $socketProof = nhep_channel_observe($state['observe'], $state['proof']);
        nhep_expect($proof['native'] === $socketProof['native'] && $proof['group'] === $socketProof['group']
            && $proof['group'] === $channelChild['group']
            && $proof['native']['pid'] === $channelChild['native_pid']
            && $proof['listener']['inode'] === $socketProof['listener']['inode'],
            'NHE_CHANNEL_NO_EXTRA_SAME_NATIVE_CHANNEL_MASTER_WORKER_AND_LISTENER');
        foreach ($proof['members'] as $index => $member)
            foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
                nhep_expect(isset($socketProof['members'][$index])
                    && $member[$key] === $socketProof['members'][$index][$key],
                    'NHE_CHANNEL_NO_EXTRA_SAME_TWO_REGISTERED_MEMBER_IDENTITIES');
        if ($phase === 'after') {
            nhep_expect($proof['native'] === $channelProofs['before']['native']
                && $proof['group'] === $channelProofs['before']['group']
                && $proof['listener']['inode'] === $channelProofs['before']['listener']['inode'],
                'NHE_CHANNEL_NO_EXTRA_ORIGINAL_CHANNEL_IDENTITY_AFTER_FINITE_WINDOW');
            foreach ($proof['members'] as $index => $member)
                foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key)
                    nhep_expect($member[$key] === $channelProofs['before']['members'][$index][$key],
                        'NHE_CHANNEL_NO_EXTRA_NO_WORKER_RESTART_DURING_FINITE_WINDOW');
        }
        $channelProofs[$phase] = $proof;
        $metadata = stream_get_meta_data($state['socket']);
        nhep_expect(is_array($metadata) && ($metadata['unread_bytes'] ?? null) === 0
            && ($metadata['eof'] ?? null) === false && ($metadata['blocked'] ?? null) === false
            && ($metadata['timed_out'] ?? null) === false && feof($state['socket']) === false,
            'NHE_CHANNEL_NO_EXTRA_NATIVE_UNBUFFERED_NONEOF_NONBLOCKING_SOCKET');
        $metadataProofs[$phase] = ['unread_bytes' => $metadata['unread_bytes'], 'eof' => $metadata['eof'],
            'blocked' => $metadata['blocked'], 'timed_out' => $metadata['timed_out']];
        if ($phase === 'before') {
            $startedNs = hrtime(true);
            nhep_expect(is_int($startedNs) && $startedNs > 0 && $startedNs <= PHP_INT_MAX - $quietNs,
                'NHE_CHANNEL_NO_EXTRA_NATIVE_MONOTONIC_DEADLINE');
            $deadline = $startedNs + $quietNs;
            do {
                $now = hrtime(true);
                nhep_expect(is_int($now) && $now >= $startedNs, 'NHE_CHANNEL_NO_EXTRA_MONOTONIC_CLOCK');
                $left = max(0, $deadline - $now); $microseconds = intdiv($left + 999, 1000);
                $seconds = intdiv($microseconds, 1000000); $micros = $microseconds % 1000000;
                $reads = [$state['socket']]; $writes = []; $except = [];
                $selected = stream_select($reads, $writes, $except, $seconds, $micros);
                nhep_expect($selected === 0, 'NHE_CHANNEL_NO_EXTRA_ANY_READABILITY_EOF_OR_SELECT_FAILURE');
                nhep_expect($reads === [] && $writes === [] && $except === [],
                    'NHE_CHANNEL_NO_EXTRA_NORMAL_ZERO_EMPTY_NATIVE_READSET');
                $zeroReturns++;
                $endedNs = hrtime(true);
                nhep_expect(is_int($endedNs) && $endedNs >= $now, 'NHE_CHANNEL_NO_EXTRA_MONOTONIC_ZERO_COMPLETION');
            } while ($endedNs < $deadline);
            nhep_expect($zeroReturns > 0 && $endedNs - $startedNs >= $quietNs,
                'NHE_CHANNEL_NO_EXTRA_FULL_TEN_SECOND_NORMAL_ZERO_WINDOW');
        }
    }
    return ['schema' => 1, 'scope' => 'nonempty_history_original_channel_finite_no_extra', 'run_id' => $runId,
        'quiet_ns' => $quietNs, 'started_ns' => $startedNs, 'ended_ns' => $endedNs, 'zero_returns' => $zeroReturns,
        'http_closed' => $httpClosedProof, 'channel_before' => $channelProofs['before'],
        'channel_after' => $channelProofs['after'],
        'subscriber' => ['socket_id' => $socketId, 'local_endpoint' => $localEndpoint,
            'remote_endpoint' => '127.0.0.1:40003', 'metadata_before' => $metadataProofs['before'],
            'metadata_after' => $metadataProofs['after']]];
}

/** Private RAM plan built from complete BEFORE only; never infer allowed writes from AFTER. */
function nhep_pre37_getter_plan(#[SensitiveParameter] array $beforeDB2, #[SensitiveParameter] array $beforeRedis,
    string $runId, array $normalInputs): array
{
    foreach (['nhep_auth_db_snapshot', 'nhepar_capture', 'm4lh_cfg_values', 'nhepcr_config_wire', 'nhepar_entry'] as $dependency)
        nhep_expect(function_exists($dependency), 'NHE_PRE37_GETTER_EXISTING_PURE_DEPENDENCIES');
    nhep_auth_db_snapshot($beforeDB2); nhepar_capture($beforeRedis);
    $values = m4lh_cfg_values($runId, $normalInputs);
    nhep_expect(count($values) === 29 && count(array_unique(array_keys($values), SORT_STRING)) === 29,
        'NHE_PRE37_GETTER_COMPLETE_ORIGINAL_TWENTY_NINE');
    $entries = []; $members = [];
    foreach ($values as $name => $value) {
        $logical = 'system_config_' . $name; $key = 'c:' . $logical;
        $wire = nhepcr_config_wire($beforeDB2, $name, $value); $old = nhepar_entry($beforeRedis, $key);
        nhep_expect($old === null || ($old['type'] === 'string' && $old['value'] === $wire && $old['expires'] === -1),
            'NHE_PRE37_GETTER_ORIGINAL_NORMAL_MISS_OR_CORRECT_PERMANENT_HIT');
        nhep_expect(nhepar_entry($beforeRedis, $key . '_lock') === null, 'NHE_PRE37_GETTER_NO_PREEXISTING_TARGET_LOCK');
        $entries[$key] = ['logical' => $logical, 'wire' => $wire]; $members[] = $key;
    }
    $tagKey = 'c:CRMEB:' . md5('crmeb'); $tag = nhepar_entry($beforeRedis, $tagKey);
    nhep_expect($tag === null || ($tag['type'] === 'set' && $tag['expires'] === -1 && is_array($tag['value'])),
        'NHE_PRE37_GETTER_ORIGINAL_PERMANENT_CRMeB_TAG');
    return ['run_id' => $runId, 'normal_inputs' => $normalInputs, 'values' => $values,
        'entries' => $entries, 'tag_members' => $members];
}

/** Validate real native values first; only then bind their opaque DUMP descriptors. */
function nhep_pre37_getter_redis_expected(#[SensitiveParameter] array $beforeRedis,
    #[SensitiveParameter] array $actualRedis, #[SensitiveParameter] array $beforeDB2,
    #[SensitiveParameter] array $plan): array
{
    nhe_keys($plan, ['run_id', 'normal_inputs', 'values', 'entries', 'tag_members'], 'NHE_PRE37_GETTER_COMPLETE_BEFORE_PLAN');
    nhepar_capture($actualRedis);
    nhep_expect($plan === nhep_pre37_getter_plan($beforeDB2, $beforeRedis, $plan['run_id'], $plan['normal_inputs']),
        'NHE_PRE37_GETTER_SAME_INDEPENDENT_BEFORE_PLAN');
    $changes = []; $members = [];
    foreach ($plan['entries'] as $key => $entry) {
        nhepar_remember($beforeRedis, $actualRedis, $entry['logical'], $entry['wire'], 0, $changes, $members);
        nhep_expect(nhepar_entry($actualRedis, $key . '_lock') === null, 'NHE_PRE37_GETTER_NORMAL_TARGET_LOCK_REMOVED');
    }
    nhep_expect($members === $plan['tag_members'], 'NHE_PRE37_GETTER_COMPLETE_ORIGINAL_TAG_APPENDS');
    nhepar_tag($beforeRedis, $actualRedis, 'crmeb', $members, $changes);
    $expected = nhep_redis_expected($beforeRedis['snapshot'], $changes, $actualRedis['snapshot']['time']);
    nhep_expect($actualRedis['snapshot'] === $expected, 'NHE_PRE37_GETTER_FULL_REDIS_NAMESPACE_VALUE_TYPE_AND_DEADLINE');
    return $expected;
}

/** Execute only the original complete getter stage after earlier preparation was independently proved. */
function nhep_pre37_configuration_getters(#[SensitiveParameter] array $qualified, PDO $observer, Redis $redis,
    #[SensitiveParameter] object $oldApp, #[SensitiveParameter] array $configReceipt): array
{
    $previousIgnoreArgs = ini_set('zend.exception_ignore_args', '1');
    nhep_expect($previousIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
        'NHE_PRE37_GETTER_REAL_PRIVATE_EXCEPTION_ARGUMENT_BOUNDARY');
    nhep_observation_parent($qualified); $runId = $qualified['context']['run_id'];
    nhep_expect(get_class($oldApp) === 'think\\App' && function_exists('app') && app() === $oldApp
        && $oldApp->initialized() === true && $oldApp->getRootPath() === '/legacy-workspace/crmeb/'
        && $oldApp->getRuntimePath() === '/legacy-runtime/'
        && $oldApp->config->get('database.connections.mysql.hostname') === 'audit-mysql'
        && $oldApp->config->get('database.connections.mysql.database') === 'audit_auth'
        && $oldApp->config->get('database.connections.mysql.username') === 'audit_app',
        'NHE_PRE37_GETTER_UNIQUE_REAL_OLD_DML_APP');
    $writer = $oldApp->db->connect()->getPdo();
    nhep_expect($writer instanceof PDO && $observer !== $writer, 'NHE_PRE37_GETTER_INDEPENDENT_OBSERVER_AND_REAL_WRITER');
    m4lh_actor_identity($observer, $runId); m4lh_actor_identity($writer, $runId);
    $store = $oldApp->config->get('cache.stores.redis');
    nhep_expect($oldApp->config->get('cache.default') === 'redis' && is_array($store)
        && ($store['type'] ?? null) === 'redis' && ($store['host'] ?? null) === 'audit-redis'
        && in_array($store['port'] ?? null, [6379, '6379'], true) && ($store['select'] ?? null) === 0
        && ($store['prefix'] ?? null) === 'c:' && ($store['tag_prefix'] ?? null) === 'CRMEB:'
        && ($store['expire'] ?? null) === 0 && ($store['serialize'] ?? null) === [],
        'NHE_PRE37_GETTER_ACTUAL_ORIGINAL_REDIS_STORE');
    nhep_expect(($configReceipt['schema'] ?? null) === 1 && ($configReceipt['run_id'] ?? null) === $runId
        && ($configReceipt['scope'] ?? null) === 'legacy_normal_config_fixture_only'
        && is_array($configReceipt['normal_inputs'] ?? null), 'NHE_PRE37_GETTER_ORIGINAL_CONFIGURATION_RECEIPT');
    $files = static function (): array {
        return ['private' => ['app' => nhep_file_tree('/run/audit-app'), 'fixtures' => nhep_file_tree('/run/audit-fixtures')],
            'public' => ['legacy_public' => nhep_file_tree('/legacy-workspace/crmeb/public')],
            'logs' => ['runtime' => nhep_file_tree('/legacy-runtime'),
                'legacy_root_runtime' => nhep_file_tree('/legacy-workspace/crmeb/runtime')]];
    };
    $beforeDB2 = nhep_database_capture($observer, $runId);
    $beforeRedis = nhep_redis_capture($redis, $runId); $beforeFiles = $files();
    $plan = nhep_pre37_getter_plan($beforeDB2, $beforeRedis, $runId, $configReceipt['normal_inputs']);
    nhep_expect($plan['values'] === ($configReceipt['getter_values'] ?? null),
        'NHE_PRE37_GETTER_RECEIPT_EQUALS_BEFORE_INDEPENDENT_VALUES');
    // The sole real producer is the existing helper: all 29 cached and all 29 uncached calls.
    $receipt = m4lh_config_verify_getters($observer, $runId, '/legacy-source', $configReceipt);
    $actualRedis = nhep_redis_capture($redis, $runId);
    $actualDB2 = nhep_database_capture($observer, $runId); $actualFiles = $files();
    $expectedRedis = nhep_pre37_getter_redis_expected($beforeRedis, $actualRedis, $beforeDB2, $plan);
    nhep_expect($actualDB2 === $beforeDB2, 'NHE_PRE37_GETTER_ALL_164_TABLES_NATIVE_ROWS_METADATA_DDL_AND_MODES_PRESERVED');
    nhep_expect($actualFiles === $beforeFiles, 'NHE_PRE37_GETTER_BOTH_PRIVATE_PUBLIC_AND_BOTH_RUNTIME_TREES_PRESERVED');
    nhe_keys($receipt, ['scope', 'run_id', 'keys', 'getter_count', 'database_rows_metadata_ddl_unchanged',
        'cache_effects_require_separate_observation', 'business_or_migration_pass'], 'NHE_PRE37_GETTER_ORIGINAL_COMPLETE_RECEIPT');
    nhep_expect($receipt['scope'] === 'legacy_normal_real_configuration_getters_only' && $receipt['run_id'] === $runId
        && $receipt['keys'] === array_keys($plan['values']) && $receipt['getter_count'] === 58
        && $receipt['database_rows_metadata_ddl_unchanged'] === true
        && $receipt['cache_effects_require_separate_observation'] === true && $receipt['business_or_migration_pass'] === false,
        'NHE_PRE37_GETTER_ALL_ORIGINAL_CALLS_AND_LIMITS');
    nhep_observation_parent($qualified);
    // Entire return value is caller-owned private RAM; it is not a public proof or a whole-pre37 result.
    return ['scope' => 'pre37_real_configuration_getters_only', 'database' => $beforeDB2,
        'redis' => $expectedRedis, 'files' => $beforeFiles, 'getter_receipt' => $receipt];
}

/** One original App factory stage. Earlier configuration effects must already be independently proved. */
function nhep_pre37_initialize_business_app(#[SensitiveParameter] array $qualified, PDO $observer, Redis $redis): array
{
    $previousIgnoreArgs = ini_set('zend.exception_ignore_args', '1');
    nhep_expect($previousIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
        'NHE_PRE37_APP_REAL_PRIVATE_EXCEPTION_ARGUMENT_BOUNDARY');
    nhep_observation_parent($qualified); $runId = $qualified['context']['run_id'];
    m4lh_actor_identity($observer, $runId);
    nhep_expect(!class_exists('think\\App', false) && !function_exists('app'),
        'NHE_PRE37_APP_ORIGINAL_UNINITIALIZED_APPLICATION');
    $files = static function (): array {
        return ['private' => ['app' => nhep_file_tree('/run/audit-app'), 'fixtures' => nhep_file_tree('/run/audit-fixtures')],
            'public' => ['legacy_public' => nhep_file_tree('/legacy-workspace/crmeb/public')],
            'logs' => ['runtime' => nhep_file_tree('/legacy-runtime'),
                'legacy_root_runtime' => nhep_file_tree('/legacy-workspace/crmeb/runtime')]];
    };
    $beforeDB2 = nhep_database_capture($observer, $runId);
    $beforeRedis = nhep_redis_capture($redis, $runId); $beforeFiles = $files();
    nhep_expect(is_array($beforeFiles['logs']['runtime'])
        && !array_key_exists('route.php', $beforeFiles['logs']['runtime']),
        'NHE_PRE37_APP_NO_UNKNOWN_RUNTIME_ROUTE_SCRIPT_BEFORE_INITIALIZE');
    // These complete expectations and the empty allowed-change set precede the real factory call.
    $expectedDB2 = $beforeDB2; $expectedFiles = $beforeFiles; $expectedRedisChanges = [];
    $oldApp = nhe_business_app($qualified);
    $writer = $oldApp->db->connect()->getPdo();
    nhep_expect($writer instanceof PDO && $writer !== $observer
        && get_class($oldApp) === 'think\\App' && app() === $oldApp && $oldApp->initialized() === true,
        'NHE_PRE37_APP_REAL_UNIQUE_APP_AND_DISTINCT_WRITER_PDO');
    m4lh_actor_identity($writer, $runId);
    $actualDB2 = nhep_database_capture($observer, $runId);
    $actualRedis = nhep_redis_capture($redis, $runId); $actualFiles = $files();
    $expectedRedis = nhep_redis_expected($beforeRedis['snapshot'], $expectedRedisChanges, $actualRedis['snapshot']['time']);
    nhep_expect($actualDB2 === $expectedDB2, 'NHE_PRE37_APP_ALL_164_TABLES_ROWS_METADATA_DDL_AND_MODES_PRESERVED');
    nhep_expect($actualRedis['snapshot'] === $expectedRedis, 'NHE_PRE37_APP_FULL_REDIS_NAMESPACE_AND_ORIGINAL_DEADLINES_PRESERVED');
    nhep_expect($actualFiles === $expectedFiles, 'NHE_PRE37_APP_BOTH_PRIVATE_PUBLIC_AND_BOTH_RUNTIME_TREES_PRESERVED');
    nhep_observation_parent($qualified);
    // App/PDO and every native comparison body stay private in the caller; never publish this return value.
    return ['scope' => 'pre37_unique_real_old_app_initialization_only', 'app' => $oldApp, 'writer' => $writer,
        'database' => $expectedDB2, 'redis' => $expectedRedis, 'files' => $expectedFiles];
}


/** Original actor inserts and real service reset, each with an independent complete BEFORE expectation. */
function nhep_pre37_prepare_actors(#[SensitiveParameter] array $qualified, PDO $observer, Redis $redis,
    #[SensitiveParameter] object $oldApp, #[SensitiveParameter] array $configReceipt,
    #[SensitiveParameter] array $private): array
{
    $previousIgnoreArgs = ini_set('zend.exception_ignore_args', '1');
    nhep_expect($previousIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
        'NHE_PRE37_ACTORS_REAL_PRIVATE_EXCEPTION_ARGUMENT_BOUNDARY');
    nhep_observation_parent($qualified); $runId = $qualified['context']['run_id'];
    m4lh_actor_private($private);
    nhep_expect(get_class($oldApp) === 'think\\App' && function_exists('app') && app() === $oldApp
        && $oldApp->initialized() === true && $oldApp->getRootPath() === '/legacy-workspace/crmeb/'
        && $oldApp->getRuntimePath() === '/legacy-runtime/'
        && $oldApp->config->get('database.connections.mysql.hostname') === 'audit-mysql'
        && $oldApp->config->get('database.connections.mysql.database') === 'audit_auth'
        && $oldApp->config->get('database.connections.mysql.username') === 'audit_app',
        'NHE_PRE37_ACTORS_UNIQUE_REAL_OLD_DML_APP');
    $writer = $oldApp->db->connect()->getPdo();
    nhep_expect($writer instanceof PDO && $writer !== $observer, 'NHE_PRE37_ACTORS_DISTINCT_REAL_APP_AND_OBSERVER_PDOS');
    m4lh_actor_identity($observer, $runId); m4lh_actor_identity($writer, $runId);
    $store = $oldApp->config->get('cache.stores.redis');
    nhep_expect($oldApp->db->getConfig('cache_store') === null && $oldApp->config->get('cache.default') === 'redis'
        && is_array($store) && ($store['type'] ?? null) === 'redis' && ($store['host'] ?? null) === 'audit-redis'
        && in_array($store['port'] ?? null, [6379, '6379'], true) && ($store['select'] ?? null) === 0
        && ($store['prefix'] ?? null) === 'c:' && ($store['tag_prefix'] ?? null) === 'CRMEB:'
        && ($store['expire'] ?? null) === 0 && ($store['serialize'] ?? null) === [],
        'NHE_PRE37_ACTORS_ACTUAL_ORIGINAL_SHARED_DEFAULT_ORM_REDIS_STORE');
    nhep_expect($oldApp->db->connect()->getConfig('fields_cache') === false
        && $oldApp->db->getConfig('time_query_rule') === []
        && $oldApp->config->get('log.level') === ['error', 'warning', 'fail', 'success', 'info', 'notice',
            'crontab', 'crmeb', 'listener'], 'NHE_PRE37_ACTORS_REAL_ORIGINAL_NO_SCHEMA_CACHE_QUERY_RULE_OR_SQL_LOG_WRITES');
    $self = nhe_business_self_id($qualified);
    $files = static function (): array {
        return ['private' => ['app' => nhep_file_tree('/run/audit-app'), 'fixtures' => nhep_file_tree('/run/audit-fixtures')],
            'public' => ['legacy_public' => nhep_file_tree('/legacy-workspace/crmeb/public')],
            'logs' => ['runtime' => nhep_file_tree('/legacy-runtime'),
                'legacy_root_runtime' => nhep_file_tree('/legacy-workspace/crmeb/runtime')]];
    };
    $beforeDB2 = nhep_database_capture($observer, $runId);
    nhep_expect(nhep_database_modes($writer) === $beforeDB2['database']['modes'],
        'NHE_PRE37_ACTORS_ORIGINAL_WRITER_COMPLETE_NATIVE_MODES_MATCH_OBSERVER');
    $beforeRedis = nhep_redis_capture($redis, $runId); $beforeFiles = $files();
    $expectedDB2 = null; $expectedFiles = $beforeFiles; $expectedRedisChanges = [];
    $beforeDml = static function (#[SensitiveParameter] array $actorBefore, #[SensitiveParameter] array $planned,
        #[SensitiveParameter] array $counts) use ($beforeDB2, &$expectedDB2): void {
        nhep_expect($expectedDB2 === null, 'NHE_PRE37_ACTORS_ONE_BEFORE_DML_CALLBACK');
        $modeKeys = array_flip(['session_mode', 'global_mode', 'session_innodb', 'global_innodb',
            'session_increment', 'global_increment', 'session_offset', 'global_offset']);
        $originalBefore = ['names' => $beforeDB2['database']['names'],
            'modes' => [array_intersect_key($beforeDB2['database']['modes'][0], $modeKeys)],
            'tables' => [], 'private_rows' => []];
        foreach ($beforeDB2['database']['names'] as $name) {
            $table = $beforeDB2['database']['tables'][$name];
            $originalBefore['tables'][$name] = ['metadata' => $table['metadata'], 'columns' => $table['projected_columns'],
                'ddl' => $table['ddl'], 'projection' => $table['projection']];
            if (in_array($name, m4lh_actor_tables(), true)) $originalBefore['private_rows'][$name] = $beforeDB2['rows'][$name];
        }
        nhep_expect($actorBefore === $originalBefore, 'NHE_PRE37_ACTORS_ALL_164_WRITER_BEFORE_EQUALS_INDEPENDENT_OBSERVER');
        $seven = ['eb_user', 'eb_system_admin', 'eb_user_address', 'eb_store_product',
            'eb_store_product_attr', 'eb_store_product_attr_value', 'eb_express'];
        nhe_keys($planned, $seven, 'NHE_PRE37_ACTORS_EXACT_ORIGINAL_SEVEN_PLANNED_ROWS');
        nhe_keys($counts, $seven, 'NHE_PRE37_ACTORS_EXACT_ORIGINAL_SEVEN_INSERT_COUNTS');
        $rows = [];
        foreach ($planned as $table => $row) {
            nhep_expect($counts[$table] === 1, 'NHE_PRE37_ACTORS_ONE_ORIGINAL_NATURAL_INSERT_PER_TABLE');
            $rows[$table] = $beforeDB2['rows'][$table]; $rows[$table][] = $row;
        }
        // Original time, bcrypt and native IDs are the existing helper's pre-SQL inputs, never AFTER values.
        $expectedDB2 = nhep_database_expected($beforeDB2, $rows, $counts);
    };
    $fixture = m4lh_actors_prepare($writer, $runId, $self, $configReceipt,
        $configReceipt['normal_inputs'], $private, '/legacy-source', $beforeDml);
    nhep_expect(is_array($expectedDB2), 'NHE_PRE37_ACTORS_EXPECTATION_COMPLETED_BEFORE_ORIGINAL_DML');
    $actualDB2 = nhep_database_capture($observer, $runId);
    $actualRedis = nhep_redis_capture($redis, $runId); $actualFiles = $files();
    $expectedRedis = nhep_redis_expected($beforeRedis['snapshot'], $expectedRedisChanges, $actualRedis['snapshot']['time']);
    nhep_expect($actualDB2 === $expectedDB2, 'NHE_PRE37_ACTORS_FULL_164_NATIVE_ROWS_METADATA_DDL_COUNTERS_AND_MODES');
    nhep_expect($actualRedis['snapshot'] === $expectedRedis, 'NHE_PRE37_ACTORS_FULL_REDIS_NAMESPACE_AND_ORIGINAL_DEADLINES');
    nhep_expect($actualFiles === $expectedFiles, 'NHE_PRE37_ACTORS_BOTH_PRIVATE_PUBLIC_AND_BOTH_RUNTIME_TREES');
    nhep_expect(($fixture['schema'] ?? null) === 1 && ($fixture['scope'] ?? null) === 'legacy_normal_actors_fixture_only'
        && ($fixture['run_id'] ?? null) === $runId
        && ($fixture['legacy_source_sha'] ?? null) === '477732e3e03ed4ba1dbb6b44a94dbba75f7e1978'
        && ($fixture['self_operated_mer_id'] ?? null) === $self && ($fixture['business_or_migration_pass'] ?? null) === false,
        'NHE_PRE37_ACTORS_ORIGINAL_FIXTURE_RECEIPT_SCOPE');
    nhep_observation_parent($qualified);

    // Reset is a distinct stage. Its complete expected rows and allowed external changes precede the real service.
    $resetBeforeDB2 = nhep_database_capture($observer, $runId);
    $resetBeforeRedis = nhep_redis_capture($redis, $runId); $resetBeforeFiles = $files();
    nhep_expect($resetBeforeDB2 === $expectedDB2 && $resetBeforeFiles === $expectedFiles,
        'NHE_PRE37_RESET_SAME_INDEPENDENTLY_ACCEPTED_PREPARED_DATABASE_AND_FILES');
    nhep_expect($resetBeforeRedis['snapshot'] === nhep_redis_expected($expectedRedis, [], $resetBeforeRedis['snapshot']['time']),
        'NHE_PRE37_RESET_SAME_INDEPENDENTLY_ACCEPTED_REDIS_AND_ORIGINAL_NATURAL_EXPIRY');
    $rows = $resetBeforeDB2['rows']['eb_user']; $seen = 0;
    foreach ($rows as &$row) if ($row['uid'] === ($fixture['uid'] ?? null)) {
        nhep_expect($row['account'] === $private['user_account'] && $row['pwd'] === '' && $row['now_money'] === '0.00',
            'NHE_PRE37_RESET_ORIGINAL_NEW_SUBJECT_BEFORE_REAL_SERVICE');
        $row['pwd'] = md5($private['user_password']); ++$seen;
    }
    unset($row); nhep_expect($seen === 1, 'NHE_PRE37_RESET_EXACT_ONE_NATIVE_SUBJECT');
    $resetExpectedDB2 = nhep_database_expected($resetBeforeDB2, ['eb_user' => $rows]);
    $resetExpectedFiles = $resetBeforeFiles;
    // Exact old Model update options after native bind consumption, derived only from BEFORE and private inputs.
    // cache(true) has tag=null; it can only conditionally delete this precise physical key, never clear a tag.
    $resetOptions = ['json' => [], 'json_assoc' => false, 'field_type' => [],
        'where' => ['AND' => [['uid', '=', $fixture['uid']]]], 'strict' => false,
        'cache' => [true, null, null], 'key' => null,
        'field' => $resetBeforeDB2['database']['tables']['eb_user']['projected_columns'],
        'data' => ['pwd' => md5($private['user_password'])], 'table' => 'eb_user',
        'order' => [], 'join' => [], 'union' => [], 'master' => true,
        'lock' => false, 'fetch_sql' => false, 'array' => false, 'distinct' => false, 'procedure' => false,
        'group' => '', 'having' => '', 'limit' => '', 'force' => '', 'comment' => '',
        'partition' => '', 'duplicate' => '', 'extra' => ''];
    $resetOrmCacheKey = 'c:' . md5('audit_auth' . serialize(var_export($resetOptions, true)) . serialize([]));
    $resetExpectedRedisChanges = [$resetOrmCacheKey => null];
    $resetReceipt = m4lh_actors_reset_password($oldApp, $writer, $runId, $fixture, $private, '/legacy-source');
    $resetActualDB2 = nhep_database_capture($observer, $runId);
    $resetActualRedis = nhep_redis_capture($redis, $runId); $resetActualFiles = $files();
    $resetExpectedRedis = nhep_redis_expected($resetBeforeRedis['snapshot'], $resetExpectedRedisChanges,
        $resetActualRedis['snapshot']['time']);
    nhep_expect($resetActualDB2 === $resetExpectedDB2, 'NHE_PRE37_RESET_ONLY_ORIGINAL_SUBJECT_PWD_FULL_164_NATIVE_DATABASE');
    nhep_expect($resetActualRedis['snapshot'] === $resetExpectedRedis, 'NHE_PRE37_RESET_FULL_REDIS_NAMESPACE_AND_ORIGINAL_DEADLINES');
    nhep_expect($resetActualFiles === $resetExpectedFiles, 'NHE_PRE37_RESET_BOTH_PRIVATE_PUBLIC_AND_BOTH_RUNTIME_TREES');
    nhe_keys($resetReceipt, ['schema', 'scope', 'run_id', 'legacy_source_sha', 'uid', 'production_reset_executed',
        'full_other_database_preserved', 'HTTP_reset_executed', 'HTTP_login_executed',
        'redis_and_files_observation', 'business_or_migration_pass'], 'NHE_PRE37_RESET_ORIGINAL_COMPLETE_RECEIPT');
    nhep_expect($resetReceipt['schema'] === 1 && $resetReceipt['scope'] === 'legacy_real_customer_password_reset_only'
        && $resetReceipt['run_id'] === $runId && $resetReceipt['legacy_source_sha'] === $fixture['legacy_source_sha']
        && $resetReceipt['uid'] === $fixture['uid'] && $resetReceipt['production_reset_executed'] === true
        && $resetReceipt['full_other_database_preserved'] === true && $resetReceipt['HTTP_reset_executed'] === false
        && $resetReceipt['HTTP_login_executed'] === false && $resetReceipt['redis_and_files_observation'] === 'CALLER_REQUIRED'
        && $resetReceipt['business_or_migration_pass'] === false, 'NHE_PRE37_RESET_ORIGINAL_SERVICE_AND_SCOPE');
    m4lh_actor_identity($writer, $runId);
    nhep_expect(nhep_database_modes($writer) === $resetExpectedDB2['database']['modes'],
        'NHE_PRE37_ACTORS_ORIGINAL_WRITER_COMPLETE_NATIVE_MODES_PRESERVED');
    nhep_observation_parent($qualified);
    // Complete comparison bodies remain private RAM. The fixture itself retains all original 36 public fields.
    return ['scope' => 'pre37_original_actors_and_real_password_reset_only', 'fixture_receipt' => $fixture,
        'reset_receipt' => $resetReceipt, 'database' => $resetExpectedDB2, 'redis' => $resetExpectedRedis,
        'files' => $resetExpectedFiles];
}


/** Complete original configuration insert stage before loading the only old App. */
function nhep_pre37_prepare_configuration(#[SensitiveParameter] array $qualified, PDO $observer, Redis $redis,
    array $normalInputs): array
{
    $previousIgnoreArgs = ini_set('zend.exception_ignore_args', '1');
    nhep_expect($previousIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
        'NHE_PRE37_CONFIGURATION_REAL_PRIVATE_EXCEPTION_ARGUMENT_BOUNDARY');
    nhep_observation_parent($qualified); $runId = $qualified['context']['run_id'];
    m4lh_actor_identity($observer, $runId);
    nhep_expect(!class_exists('think\\App', false) && !function_exists('app'),
        'NHE_PRE37_CONFIGURATION_BEFORE_UNIQUE_OLD_APP');
    $files = static function (): array {
        return ['private' => ['app' => nhep_file_tree('/run/audit-app'), 'fixtures' => nhep_file_tree('/run/audit-fixtures')],
            'public' => ['legacy_public' => nhep_file_tree('/legacy-workspace/crmeb/public')],
            'logs' => ['runtime' => nhep_file_tree('/legacy-runtime'),
                'legacy_root_runtime' => nhep_file_tree('/legacy-workspace/crmeb/runtime')]];
    };
    $beforeDB2 = nhep_database_capture($observer, $runId);
    $beforeRedis = nhep_redis_capture($redis, $runId); $beforeFiles = $files();
    $expectedDB2 = null; $expectedFiles = $beforeFiles; $expectedRedisChanges = [];
    $beforeDml = static function (#[SensitiveParameter] array $configBefore, #[SensitiveParameter] array $plans)
        use ($beforeDB2, &$expectedDB2): void {
        nhep_expect($expectedDB2 === null, 'NHE_PRE37_CONFIGURATION_ONE_ORIGINAL_BEFORE_DML_CALLBACK');
        $four = ['eb_system_config', 'eb_system_notification', 'eb_category', 'eb_user_label'];
        $modeKeys = array_flip(['session_mode', 'global_mode', 'session_innodb', 'global_innodb']);
        $originalBefore = ['names' => $beforeDB2['database']['names'],
            'modes' => [array_intersect_key($beforeDB2['database']['modes'][0], $modeKeys)],
            'tables' => [], 'mutable_rows' => []];
        foreach ($beforeDB2['database']['names'] as $name) {
            $table = $beforeDB2['database']['tables'][$name];
            $ddl = preg_replace('/ AUTO_INCREMENT=[0-9]+/', '', $table['ddl'], -1, $changes);
            nhep_expect(is_string($ddl) && $changes <= 1, 'NHE_PRE37_CONFIGURATION_ORIGINAL_DDL_COUNTER_SLOT');
            $originalBefore['tables'][$name] = ['metadata' => $table['metadata'], 'columns' => $table['projected_columns'],
                'ddl_without_counter_sha256' => hash('sha256', $ddl),
                'projection' => m4lh_cfg_projection($beforeDB2['rows'][$name])];
            if (in_array($name, $four, true)) {
                $rows = array_map('m4lh_cfg_text_row', $beforeDB2['rows'][$name]);
                usort($rows, static fn(array $a, array $b): int => strcmp(serialize($a), serialize($b)));
                $originalBefore['mutable_rows'][$name] = $rows;
            }
        }
        nhe_keys($configBefore, ['names', 'modes', 'tables', 'mutable_rows'], 'NHE_PRE37_CONFIGURATION_ORIGINAL_FULL_BEFORE_KEYS');
        nhe_keys($configBefore['mutable_rows'], $four, 'NHE_PRE37_CONFIGURATION_ORIGINAL_FOUR_MUTABLE_ROW_TABLES');
        foreach ($configBefore['mutable_rows'] as &$rows)
            usort($rows, static fn(array $a, array $b): int => strcmp(serialize($a), serialize($b)));
        unset($rows);
        nhep_expect($configBefore === $originalBefore, 'NHE_PRE37_CONFIGURATION_ALL_164_ORIGINAL_BEFORE_EQUALS_NATIVE_OBSERVER');
        nhe_keys($plans, $four, 'NHE_PRE37_CONFIGURATION_EXACT_FOUR_ORIGINAL_PLANS');
        $expectedCounts = ['eb_system_config' => 29, 'eb_system_notification' => 7, 'eb_category' => 1, 'eb_user_label' => 1];
        $expectedRows = []; $counts = [];
        foreach ($plans as $table => $plan) {
            nhe_keys($plan, ['before_next', 'after_next', 'rows'], 'NHE_PRE37_CONFIGURATION_ORIGINAL_PLAN_KEYS');
            $metadata = $beforeDB2['database']['tables'][$table]['metadata'];
            nhep_expect(array_is_list($plan['rows']) && count($plan['rows']) === $expectedCounts[$table]
                && $plan['before_next'] === m4lh_actor_next($beforeDB2['database']['tables'][$table], 'id')
                && $plan['after_next'] === $plan['before_next'] + $expectedCounts[$table],
                'NHE_PRE37_CONFIGURATION_ORIGINAL_29_7_1_1_NATIVE_INSERT_COUNTS_AND_ALLOCATION');
            $expectedRows[$table] = $beforeDB2['rows'][$table]; $counts[$table] = $expectedCounts[$table];
            foreach ($plan['rows'] as $index => $row) {
                nhe_keys($row, ['input', 'expected'], 'NHE_PRE37_CONFIGURATION_ORIGINAL_BEFORE_INSERT_ROW_PLAN');
                nhep_expect(array_keys($row['expected']) === array_keys($metadata['columns']),
                    'NHE_PRE37_CONFIGURATION_ORIGINAL_COMPLETE_EXPECTED_COLUMN_ORDER');
                $native = m4lh_actor_expected_row($metadata, $row['expected']);
                nhep_expect($native['id'] === $plan['before_next'] + $index,
                    'NHE_PRE37_CONFIGURATION_INDEPENDENT_NATIVE_ID_BEFORE_INSERT');
                $expectedRows[$table][] = $native;
            }
        }
        // This pure full native expectation completes inside the original transaction, before its first INSERT.
        $expectedDB2 = nhep_database_expected($beforeDB2, $expectedRows, $counts);
    };
    $receipt = m4lh_config_prepare($observer, $runId, '/legacy-source', $normalInputs, $beforeDml);
    nhep_expect(is_array($expectedDB2), 'NHE_PRE37_CONFIGURATION_COMPLETE_EXPECTATION_BEFORE_ORIGINAL_DML');
    $actualDB2 = nhep_database_capture($observer, $runId);
    $actualRedis = nhep_redis_capture($redis, $runId); $actualFiles = $files();
    $expectedRedis = nhep_redis_expected($beforeRedis['snapshot'], $expectedRedisChanges, $actualRedis['snapshot']['time']);
    nhep_expect($actualDB2 === $expectedDB2, 'NHE_PRE37_CONFIGURATION_FULL_164_NATIVE_ROWS_METADATA_DDL_COUNTERS_AND_MODES');
    nhep_expect($actualRedis['snapshot'] === $expectedRedis, 'NHE_PRE37_CONFIGURATION_FULL_REDIS_AND_ORIGINAL_DEADLINES');
    nhep_expect($actualFiles === $expectedFiles, 'NHE_PRE37_CONFIGURATION_BOTH_PRIVATE_PUBLIC_AND_BOTH_RUNTIME_TREES');
    nhep_expect(($receipt['schema'] ?? null) === 1 && ($receipt['scope'] ?? null) === 'legacy_normal_config_fixture_only'
        && ($receipt['run_id'] ?? null) === $runId && ($receipt['normal_inputs'] ?? null) === $normalInputs
        && ($receipt['getter_values'] ?? null) === m4lh_cfg_values($runId, $normalInputs)
        && ($receipt['notification_marks'] ?? null) === array_keys(m4lh_cfg_marks())
        && ($receipt['native_insert_counts'] ?? null) === ['eb_system_config' => 29, 'eb_system_notification' => 7,
            'eb_category' => 1, 'eb_user_label' => 1]
        && ($receipt['business_or_migration_pass'] ?? null) === false,
        'NHE_PRE37_CONFIGURATION_ORIGINAL_COMPLETE_NORMAL_INPUTS_AND_RECEIPT_LIMITS');
    nhep_observation_parent($qualified);
    return ['scope' => 'pre37_original_configuration_inserts_only', 'configuration_receipt' => $receipt,
        'database' => $expectedDB2, 'redis' => $expectedRedis, 'files' => $expectedFiles];
}

/** Original fixed preparation sequence. This private RAM result is not a public seal or a full37 result. */
function nhep_pre37_fixed_preparation(#[SensitiveParameter] array $qualified, PDO $observer, Redis $redis): array
{
    $previousIgnoreArgs = ini_set('zend.exception_ignore_args', '1');
    nhep_expect($previousIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
        'NHE_PRE37_FIXED_REAL_PRIVATE_EXCEPTION_ARGUMENT_BOUNDARY');
    nhep_observation_parent($qualified); $runId = $qualified['context']['run_id'];
    m4lh_actor_identity($observer, $runId);
    $files = static function (): array {
        return ['private' => ['app' => nhep_file_tree('/run/audit-app'), 'fixtures' => nhep_file_tree('/run/audit-fixtures')],
            'public' => ['legacy_public' => nhep_file_tree('/legacy-workspace/crmeb/public')],
            'logs' => ['runtime' => nhep_file_tree('/legacy-runtime'),
                'legacy_root_runtime' => nhep_file_tree('/legacy-workspace/crmeb/runtime')]];
    };
    // Fixed adjacent-stage observation only: no writer, hook, files, public result, or substitute baseline is produced.
    $join = static function (#[SensitiveParameter] array $stage) use ($observer, $redis, $runId, $files): void {
        $db = nhep_database_capture($observer, $runId); $cache = nhep_redis_capture($redis, $runId);
        nhep_expect($db === $stage['database'] && $files() === $stage['files'],
            'NHE_PRE37_FIXED_ADJACENT_COMPLETE_164_DATABASE_AND_FIVE_TREES_JOIN');
        nhep_expect($cache['snapshot'] === nhep_redis_expected($stage['redis'], [], $cache['snapshot']['time']),
            'NHE_PRE37_FIXED_ADJACENT_COMPLETE_REDIS_AND_ONLY_ORIGINAL_NATURAL_EXPIRY_JOIN');
    };
    $normalInputs = ['site_url' => 'http://127.0.0.1:8000'];
    $configuration = nhep_pre37_prepare_configuration($qualified, $observer, $redis, $normalInputs);
    $join($configuration);
    $application = nhep_pre37_initialize_business_app($qualified, $observer, $redis);
    nhep_expect($application['database'] === $configuration['database'] && $application['files'] === $configuration['files'],
        'NHE_PRE37_FIXED_CONFIGURATION_TO_ONE_ORIGINAL_APP_DATABASE_FILES_JOIN');
    nhep_expect($application['redis'] === nhep_redis_expected($configuration['redis'], [], $application['redis']['time']),
        'NHE_PRE37_FIXED_CONFIGURATION_TO_ONE_ORIGINAL_APP_REDIS_JOIN');
    $join($application);
    $getters = nhep_pre37_configuration_getters($qualified, $observer, $redis, $application['app'],
        $configuration['configuration_receipt']);
    nhep_expect($getters['database'] === $application['database'] && $getters['files'] === $application['files'],
        'NHE_PRE37_FIXED_ONE_ORIGINAL_APP_TO_COMPLETE_58_GETTERS_DATABASE_FILES_JOIN');
    $join($getters);
    $private = nhe_actor_private($qualified);
    $actors = nhep_pre37_prepare_actors($qualified, $observer, $redis, $application['app'],
        $configuration['configuration_receipt'], $private);
    $join($actors);
    $fixture = $actors['fixture_receipt'];
    $httpActors = ['admin' => ['id' => $fixture['admin_id'], 'account' => $private['admin_account'],
        'password' => $private['admin_password']],
        'customer' => ['id' => $fixture['uid'], 'account' => $private['user_account'], 'password' => $private['user_password']]];
    unset($private); nhep_observation_parent($qualified);
    // Every row, key, password, App/PDO, file/body digest and private stage receipt remains solely in caller RAM.
    return ['scope' => 'pre37_fixed_original_preparation_only', 'origin' => $normalInputs['site_url'],
        'configuration_receipt' => $configuration['configuration_receipt'], 'getter_receipt' => $getters['getter_receipt'],
        'fixture_receipt' => $fixture, 'reset_receipt' => $actors['reset_receipt'], 'actors' => $httpActors,
        'old_app' => $application['app'], 'writer' => $application['writer'],
        'database' => $actors['database'], 'redis' => $actors['redis'], 'files' => $actors['files']];
}

function nhep_close_private_file(#[SensitiveParameter] array $runtime, string $leaf): array
{
    nhep_expect(in_array($leaf, ['legacy-http.stdout', 'legacy-http.stderr', 'legacy-channel.stdout',
        'legacy-channel.stderr', 'channel/workerman.log'], true), 'NHE_CLOSE_ONLY_ORIGINAL_NATIVE_PRIVATE_LEAVES');
    $row = $runtime[$leaf] ?? null; $path = '/legacy-runtime/' . $leaf;
    nhep_expect(is_array($row) && ($row['kind'] ?? null) === 'file' && is_array($row['stat'] ?? null),
        'NHE_CLOSE_COMPLETE_ORIGINAL_PRIVATE_FILE_ROW');
    nhep_auth_files_stat($row['stat']); clearstatcache(true, $path); $before = lstat($path);
    nhep_expect(is_array($before) && nhep_file_stat($before) === $row['stat'] && !is_link($path)
        && realpath($path) === $path && $row['stat']['nlink'] === 1,
        'NHE_CLOSE_SAME_NATIVE_PRIVATE_FILE_BEFORE_FULL_READ');
    $raw = nhe_file($path, ['path' => $path, 'bytes' => $row['bytes'], 'sha256' => $row['sha256']]);
    clearstatcache(true, $path); $after = lstat($path);
    nhep_expect(is_array($after) && !is_link($path) && realpath($path) === $path
        && nhep_file_stat($after) === $row['stat'], 'NHE_CLOSE_SAME_NATIVE_PRIVATE_FILE_AFTER_FULL_READ');
    return ['path' => $path, 'stat' => $row['stat'], 'bytes' => $row['bytes'], 'sha256' => $row['sha256'], 'raw' => $raw];
}

function nhep_normal_close_files_expected(#[SensitiveParameter] array $before7,
    #[SensitiveParameter] array $beforePrivate, #[SensitiveParameter] array $beforeLog,
    #[SensitiveParameter] array $actualFiles, #[SensitiveParameter] array $afterStreams,
    #[SensitiveParameter] array $afterLog, #[SensitiveParameter] array $closed, array $channelWindow): array
{
    nheh_snapshot($before7);
    nhe_keys($actualFiles, ['private', 'public', 'logs'], 'NHE_CLOSE_COMPLETE_FIVE_TREE_OBSERVATION_KEYS');
    nhe_keys($closed, ['http', 'channel'], 'NHE_CLOSE_BOTH_ORIGINAL_NATIVE_RECEIPTS');
    nhep_expect(array_is_list($channelWindow) && count($channelWindow) === 2
        && is_int($channelWindow[0]) && is_int($channelWindow[1]) && $channelWindow[0] > 0
        && $channelWindow[0] <= $channelWindow[1] && $channelWindow[1] <= 4294967295,
        'NHE_CLOSE_ACTUAL_CHANNEL_TERM_TO_FINAL_WALL_WINDOW');
    $before = $before7['logs']['runtime']; $actual = $actualFiles['logs']['runtime'];
    nhep_expect(is_array($before) && is_array($actual), 'NHE_CLOSE_ORIGINAL_COMPLETE_RUNTIME_TREES');
    nhep_auth_files_tree($before); nhep_auth_files_tree($actual);
    nhep_auth_files_streams($beforePrivate, $before);
    nhep_auth_files_streams(['native_streams' => $afterStreams], $actual);
    $expected = ['private' => $before7['private'], 'public' => $before7['public'], 'logs' => $before7['logs']];
    nhep_expect($actualFiles['private'] === $expected['private'] && $actualFiles['public'] === $expected['public']
        && $actualFiles['logs']['legacy_root_runtime'] === $expected['logs']['legacy_root_runtime'],
        'NHE_CLOSE_BOTH_PRIVATE_PUBLIC_AND_OLD_ROOT_RUNTIME_COMPLETE_PRESERVATION');
    $master = $before7['native']['channel']['pid']; $proof = $beforePrivate['native_after']['channel'];
    $workers = array_values(array_filter($proof['members'], static fn(array $row): bool => $row['pid'] !== $master));
    nhep_expect(is_int($master) && $master > 1 && $proof['native'] === $before7['native']['channel']
        && count($proof['members']) === 2 && count($workers) === 1 && $workers[0]['ppid'] === $master
        && $workers[0]['pgid'] === $master && $workers[0]['sid'] === $master
        && is_int($workers[0]['pid']) && $workers[0]['pid'] > 1 && $workers[0]['pid'] !== $master
        && $closed['channel']['group'] === $proof['group'] && $proof['group']['leader_pid'] === $master
        && $closed['channel']['first_terminal']['pid'] === $master
        && $closed['channel']['stopped'] === true && $closed['http']['stopped'] === true,
        'NHE_CLOSE_SAME_ORIGINAL_CHANNEL_MASTER_WORKER_AND_BOTH_STOPPED_CHILDREN');
    $worker = $workers[0]['pid'];
    $channelPaths = array_values(array_filter(array_keys($before), static fn(string $path): bool =>
        $path === 'channel' || str_starts_with($path, 'channel/')));
    nhep_expect($channelPaths === ['channel', 'channel/workerman.log', 'channel/workerman.pid']
        && $before['channel']['kind'] === 'directory' && $before['channel']['stat']['mode'] === (0040000 | 0700)
        && $before['channel/workerman.log']['stat']['mode'] === (0100000 | 0622),
        'NHE_CLOSE_ORIGINAL_NONDAEMON_CHANNEL_RUNTIME_ONLY_LOG_AND_PID');
    $pid = $before['channel/workerman.pid']; $pidRaw = (string)$master;
    nhep_expect($pid['kind'] === 'file' && $pid['stat']['mode'] === (0100000 | 0600)
        && $pid['stat']['uid'] === $before['channel']['stat']['uid'] && $pid['stat']['gid'] === $before['channel']['stat']['gid']
        && $pid['bytes'] === strlen($pidRaw) && $pid['sha256'] === hash('sha256', $pidRaw),
        'NHE_CLOSE_ORIGINAL_COMPLETE_MASTER_PID_FILE_NO_NEWLINE');
    $wanted = array_values(array_filter(array_keys($before), static fn(string $path): bool => $path !== 'channel/workerman.pid'));
    nhep_expect(array_keys($actual) === $wanted, 'NHE_CLOSE_COMPLETE_RUNTIME_NAMESPACE_ONLY_ORIGINAL_PID_UNLINK');
    unset($expected['logs']['runtime']['channel/workerman.pid']);
    foreach (['stdout', 'stderr'] as $name)
        nhep_expect($afterStreams['http'][$name] === $beforePrivate['native_streams']['http'][$name],
            'NHE_CLOSE_HTTP_OUTPUT_COMPLETE_ORIGINAL_BYTES_AND_STAT9');
    foreach (['before' => $beforeLog, 'after' => $afterLog] as $phase => $log) {
        $tree = $phase === 'before' ? $before : $actual;
        nhe_keys($log, ['path', 'stat', 'bytes', 'sha256', 'raw'], 'NHE_CLOSE_PRIVATE_WORKERMAN_LOG_FULL_READBACK_KEYS');
        nhep_expect($log['path'] === '/legacy-runtime/channel/workerman.log' && is_string($log['raw'])
            && strlen($log['raw']) === $log['bytes'] && hash('sha256', $log['raw']) === $log['sha256']
            && $tree['channel/workerman.log'] === ['kind' => 'file', 'stat' => $log['stat'],
                'bytes' => $log['bytes'], 'sha256' => $log['sha256']],
            'NHE_CLOSE_PRIVATE_WORKERMAN_LOG_SAME_COMPLETE_TREE_AND_BODY');
    }

    // This fixed test-entry callback record precedes the first graceful destructor.
    // It is private BEFORE-effect evidence, never a count selected from progress lines.
    $oldError = $beforePrivate['native_streams']['channel']['stderr']['raw'];
    $newError = $afterStreams['channel']['stderr']['raw'];
    nhep_expect(str_starts_with($newError, $oldError), 'NHE_CLOSE_CHANNEL_STDERR_COMPLETE_ORIGINAL_PREFIX');
    $metaSuffix = substr($newError, strlen($oldError)); $prefix = 'NHE_CHANNEL_NORMAL_CLOSE_META ';
    nhep_expect(str_starts_with($metaSuffix, $prefix) && str_ends_with($metaSuffix, "\n")
        && substr_count($metaSuffix, "\n") === 1, 'NHE_CLOSE_EXACT_ONE_ORIGINAL_WORKER_PREDESTRUCT_METADATA_LINE');
    $meta = json_decode(substr($metaSuffix, strlen($prefix), -1), true, 16, JSON_THROW_ON_ERROR);
    nhep_expect(is_array($meta), 'NHE_CLOSE_PRIVATE_NORMAL_METADATA_OBJECT');
    nhe_keys($meta, ['schema', 'scope', 'run_id', 'master_pid', 'worker_pid', 'connection_count',
        'graceful_stop', 'utc_second', 'timezone'], 'NHE_CLOSE_PRIVATE_NORMAL_METADATA_CLOSED_KEYS');
    nhep_expect($meta['schema'] === 1 && $meta['scope'] === 'channel_original_normal_stop_native_before_destruct'
        && $meta['run_id'] === ($before7['rows']['audit_sentinel'][0]['run_id'] ?? null)
        && $meta['master_pid'] === $master && $meta['worker_pid'] === $worker
        && is_int($meta['connection_count']) && $meta['connection_count'] >= 0 && $meta['graceful_stop'] === true
        && is_int($meta['utc_second']) && $meta['utc_second'] >= $channelWindow[0]
        && $meta['utc_second'] <= $channelWindow[1] && $meta['timezone'] === 'UTC',
        'NHE_CLOSE_REAL_SINGLE_BEFORE_DESTRUCT_COUNT_NATIVE_IDENTITIES_RUN_GRACEFUL_AND_UTC_WINDOW');
    $metaExpected = $prefix . json_encode($meta, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . "\n";
    nhep_expect($metaSuffix === $metaExpected, 'NHE_CLOSE_PRIVATE_METADATA_EXACT_CANONICAL_SOURCE_ENCODING');
    $stderrExpected = $oldError . $metaExpected;

    $progress = []; $count = $meta['connection_count'];
    if ($count > 0) {
        $mod = (int)ceil($count / 3);
        nhep_expect($mod > 0 && $mod <= $count, 'NHE_CLOSE_ORIGINAL_VENDOR_POSITIVE_MODULUS');
        $remaining = intdiv($count - 1, $mod) * $mod;
        do {
            $progress[] = 'worker[' . $worker . '] remains ' . $remaining . ' connection(s)';
            nhep_expect(count($progress) <= 3, 'NHE_CLOSE_VENDOR_COUNT_DERIVED_AT_MOST_THREE_PROGRESS_RECORDS');
            $remaining -= $mod;
        } while ($remaining >= 0);
    }
    $stopping = 'Workerman[legacy-history-channel.php] stopping ...';
    $stopped = 'Workerman[legacy-history-channel.php] has been stopped';
    $orders = [];
    for ($position = 0; $position <= count($progress); ++$position)
        $orders[] = array_merge(array_slice($progress, 0, $position), [$stopping],
            array_slice($progress, $position), [$stopped]);
    $oldOutput = $beforePrivate['native_streams']['channel']['stdout']['raw'];
    $newOutput = $afterStreams['channel']['stdout']['raw']; $stdoutPosition = null; $stdoutExpected = null;
    foreach ($orders as $position => $messages) {
        $candidate = $oldOutput . implode("\n", $messages) . "\n";
        if ($newOutput === $candidate) { $stdoutPosition = $position; $stdoutExpected = $candidate; }
    }
    nhep_expect(is_int($stdoutPosition) && is_string($stdoutExpected),
        'NHE_CLOSE_STDOUT_COMPLETE_PREFIX_EXACT_INDEPENDENT_MESSAGES_PER_PROCESS_ORDER_AND_STOPPED_LAST');
    nhep_expect(str_starts_with($afterLog['raw'], $beforeLog['raw']), 'NHE_CLOSE_WORKERMAN_LOG_ORIGINAL_COMPLETE_PREFIX');
    $suffix = substr($afterLog['raw'], strlen($beforeLog['raw'])); $logPosition = null; $logExpected = null;
    foreach ($orders as $position => $messages) {
        $pattern = '~\A';
        foreach ($messages as $message) {
            $messagePid = in_array($message, [$stopping, $stopped], true) ? $master : $worker;
            $pattern .= '([0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}) pid:'
                . $messagePid . ' ' . preg_quote($message, '~') . "\n";
        }
        if (preg_match($pattern . '\\z~D', $suffix, $matches) !== 1) continue;
        $lastTime = [$master => null, $worker => null]; $rebuilt = $beforeLog['raw'];
        foreach ($messages as $index => $message) {
            $stamp = $matches[$index + 1];
            $parsed = DateTimeImmutable::createFromFormat('!Y-m-d H:i:s', $stamp, new DateTimeZone('UTC'));
            nhep_expect($parsed instanceof DateTimeImmutable && DateTimeImmutable::getLastErrors() === false,
                'NHE_CLOSE_EACH_ORIGINAL_LOG_NATIVE_UTC_DATE_VALID');
            $epoch = $parsed->getTimestamp(); $messagePid = in_array($message, [$stopping, $stopped], true) ? $master : $worker;
            nhep_expect($epoch >= $channelWindow[0] && $epoch <= $channelWindow[1]
                && gmdate('Y-m-d H:i:s', $epoch) === $stamp
                && ($lastTime[$messagePid] === null || $epoch >= $lastTime[$messagePid])
                && ($message === $stopping || $epoch >= $meta['utc_second']),
                'NHE_CLOSE_REAL_TERM_WINDOW_PER_PROCESS_TIME_ORDER_AND_WORKER_BEFORE_EFFECT_BOUNDARY');
            $lastTime[$messagePid] = $epoch;
            $rebuilt .= gmdate('Y-m-d H:i:s', $epoch) . ' pid:' . $messagePid . ' ' . $message . "\n";
        }
        $logPosition = $position; $logExpected = $rebuilt;
    }
    nhep_expect(is_int($logPosition) && is_string($logExpected) && $afterLog['raw'] === $logExpected
        && $logPosition >= max(0, $stdoutPosition - 1),
        'NHE_CLOSE_LOG_INDEPENDENT_COMPLETE_BYTES_AND_REAL_STDOUT_THEN_LOG_CROSS_FILE_PARTIAL_ORDER');
    $append = static function (array $old, array $observed, #[SensitiveParameter] string $expectedRaw)
        use ($channelWindow): array {
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
            nhep_expect($observed['stat'][$key] === $old['stat'][$key], 'NHE_CLOSE_APPEND_SAME_ORIGINAL_FILE_IDENTITY_MODE_OWNER_LINK');
        nhep_expect($observed['stat']['size'] === strlen($expectedRaw) && strlen($expectedRaw) > $old['bytes'],
            'NHE_CLOSE_APPEND_EXACT_SOURCE_EXPECTED_NATIVE_SIZE');
        foreach (['mtime', 'ctime'] as $key)
            nhep_expect($observed['stat'][$key] >= $old['stat'][$key] && $observed['stat'][$key] >= $channelWindow[0]
                && $observed['stat'][$key] <= $channelWindow[1], 'NHE_CLOSE_APPEND_NATIVE_TIMES_IN_ACTUAL_CHANNEL_TERM_WINDOW');
        $stat = $old['stat'];
        foreach (['size', 'mtime', 'ctime'] as $key) $stat[$key] = $observed['stat'][$key];
        return ['kind' => 'file', 'stat' => $stat, 'bytes' => strlen($expectedRaw), 'sha256' => hash('sha256', $expectedRaw)];
    };
    $expected['logs']['runtime']['legacy-channel.stdout'] = $append($before['legacy-channel.stdout'], $actual['legacy-channel.stdout'], $stdoutExpected);
    $expected['logs']['runtime']['legacy-channel.stderr'] = $append($before['legacy-channel.stderr'], $actual['legacy-channel.stderr'], $stderrExpected);
    $expected['logs']['runtime']['channel/workerman.log'] = $append($before['channel/workerman.log'], $actual['channel/workerman.log'], $logExpected);
    $oldDirectory = $before['channel']['stat']; $newDirectory = $actual['channel']['stat'];
    foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
        nhep_expect($newDirectory[$key] === $oldDirectory[$key], 'NHE_CLOSE_UNLINK_SAME_ORIGINAL_CHANNEL_DIRECTORY_AND_LINKS');
    nhep_expect($newDirectory['size'] <= $oldDirectory['size'], 'NHE_CLOSE_UNLINK_KERNEL_DIRECTORY_SIZE_CANNOT_GROW');
    foreach (['mtime', 'ctime'] as $key)
        nhep_expect($newDirectory[$key] >= $oldDirectory[$key] && $newDirectory[$key] >= $channelWindow[0]
            && $newDirectory[$key] <= $channelWindow[1], 'NHE_CLOSE_ONLY_PID_UNLINK_DIRECTORY_TIME_IN_ACTUAL_TERM_WINDOW');
    foreach (['size', 'mtime', 'ctime'] as $key) $expected['logs']['runtime']['channel']['stat'][$key] = $newDirectory[$key];
    nhep_expect($actualFiles === $expected, 'NHE_CLOSE_COMPLETE_FIVE_TREES_EQUAL_INDEPENDENT_NORMAL_CLOSE_MODEL');
    return $expected;
}

function nhep_normal_close_writers(#[SensitiveParameter] array $qualified, PDO $observer, Redis $redis,
    array &$children, #[SensitiveParameter] array $accepted37): array
{
    $previousIgnoreArgs = ini_set('zend.exception_ignore_args', '1');
    nhep_expect($previousIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
        'NHE_CLOSE_REAL_PRIVATE_EXCEPTION_ARGUMENT_BOUNDARY');
    nheh_snapshot($accepted37); nhep_observation_parent($qualified); $runId = $qualified['context']['run_id'];
    $beforePrivate = []; $before7 = nhep_observation($qualified, $observer, $redis, $children, $beforePrivate);
    $beforeExpected = $accepted37;
    $beforeExpected['redis'] = nhep_redis_expected($accepted37['redis'], [], $before7['redis']['time']);
    nhep_expect($before7 === $beforeExpected, 'NHE_CLOSE_FULL37_ACCEPTED_TO_LAST_LIVE_BEFORE_ONLY_NATURAL_EXPIRY_JOIN');
    $beforeLog = nhep_close_private_file($before7['logs']['runtime'], 'channel/workerman.log');
    $statistics = '/tmp/_run_nonempty_legacy-history-channel.php.status';
    clearstatcache(true, $statistics);
    nhep_expect(!file_exists($statistics) && !is_link($statistics), 'NHE_CLOSE_NO_UNMODELED_WORKERMAN_STATISTICS_FILE_BEFORE_TERM');
    $httpStarted = time(); $httpClosed = nhep_child_close($children, 'http'); $httpEnded = time();
    nhep_expect($httpEnded >= $httpStarted && ($httpClosed['stopped'] ?? null) === true,
        'NHE_CLOSE_ORIGINAL_HTTP_COMPLETE_BEFORE_CHANNEL_QUIET');
    $noExtra = nhep_channel_no_extra($children);
    $state =& $children['channel']['subscriber']['state']; nhep_channel_close($state); unset($state);
    $channelStarted = time(); $channelClosed = nhep_child_close($children, 'channel');
    nhep_expect(($channelClosed['stopped'] ?? null) === true, 'NHE_CLOSE_ORIGINAL_CHANNEL_NORMAL_GROUP_STOPPED');
    $closed = nhep_children_closed($children); $channelEnded = time();
    nhep_expect($channelEnded >= $channelStarted && $closed['http'] === $httpClosed && $closed['channel'] === $channelClosed,
        'NHE_CLOSE_SAME_ORIGINAL_BOTH_NATIVE_CLOSE_RECEIPTS_AND_REAL_WINDOW');
    clearstatcache(true, $statistics);
    nhep_expect(!file_exists($statistics) && !is_link($statistics), 'NHE_CLOSE_NO_UNMODELED_WORKERMAN_STATISTICS_FILE_AFTER_TERM');
    $actualFiles = ['private' => ['app' => nhep_file_tree('/run/audit-app'), 'fixtures' => nhep_file_tree('/run/audit-fixtures')],
        'public' => ['legacy_public' => nhep_file_tree('/legacy-workspace/crmeb/public')],
        'logs' => ['runtime' => nhep_file_tree('/legacy-runtime'),
            'legacy_root_runtime' => nhep_file_tree('/legacy-workspace/crmeb/runtime')]];
    $afterStreams = [];
    foreach (['http', 'channel'] as $kind) foreach (['stdout', 'stderr'] as $name) {
        $readback = nhep_close_private_file($actualFiles['logs']['runtime'], 'legacy-' . $kind . '.' . $name);
        $stream = $children[$kind]['streams'][$name];
        nhep_expect($stream['handle'] === null && $stream['complete'] === $closed[$kind]['streams'][$name]
            && $stream['complete'] === ['bytes' => $readback['bytes'], 'sha256' => $readback['sha256']],
            'NHE_CLOSE_FULL_PRIVATE_READBACK_EQUALS_ORIGINAL_OWNED_HANDLE_CLOSED_STREAM');
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
            nhep_expect($readback['stat'][$key] === $stream['created'][$key], 'NHE_CLOSE_FINAL_STREAM_SAME_ORIGINAL_CREATED_NATIVE_IDENTITY');
        $afterStreams[$kind][$name] = $readback;
    }
    $afterLog = nhep_close_private_file($actualFiles['logs']['runtime'], 'channel/workerman.log');
    $expectedFiles = nhep_normal_close_files_expected($before7, $beforePrivate, $beforeLog, $actualFiles,
        $afterStreams, $afterLog, $closed, [$channelStarted, $channelEnded]);
    $actualDB2 = nhep_database_capture($observer, $runId); $actualRedis = nhep_redis_capture($redis, $runId);
    $expectedDB2 = ['database' => $accepted37['database'], 'rows' => $accepted37['rows']];
    $expectedRedis = nhep_redis_expected($accepted37['redis'], [], $actualRedis['snapshot']['time']);
    nhep_expect($actualDB2 === $expectedDB2, 'NHE_CLOSE_STOPPED_WRITERS_FULL_164_DATABASE_EQUALS_ORIGINAL_ACCEPTED37');
    nhep_expect($actualRedis['snapshot'] === $expectedRedis, 'NHE_CLOSE_STOPPED_WRITERS_FULL_REDIS_ONLY_ORIGINAL_NATURAL_EXPIRY');
    $expectedM4m = nhep_migration_snapshot_expected($expectedDB2, $expectedRedis);
    nhep_children_closed($children); nhep_parent_qualified($qualified); nhep_observation_parent($qualified);
    // This return includes private body digests/raws and original receipts. It must never be serialized to Run.
    return ['scope' => 'original_full37_normal_writers_closed_independent_baseline_only',
        'closed_receipts' => $closed, 'no_extra_receipt' => $noExtra, 'files' => $expectedFiles,
        'private_native_streams' => $afterStreams, 'private_workerman_log' => $afterLog,
        'database' => $expectedDB2, 'redis' => $expectedRedis, 'expected_m4m' => $expectedM4m,
        'wall_windows' => ['http' => [$httpStarted, $httpEnded], 'channel' => [$channelStarted, $channelEnded]]];
}

function nhep_normal_close_public_view(#[SensitiveParameter] array $qualified, array &$children,
    #[SensitiveParameter] array $close): array
{
    $previousIgnoreArgs = ini_set('zend.exception_ignore_args', '1');
    nhep_expect($previousIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
        'NHE_CLOSE_PUBLIC_VIEW_REAL_PRIVATE_EXCEPTION_ARGUMENT_BOUNDARY');
    nhep_observation_parent($qualified);
    nhep_expect(($close['scope'] ?? null) === 'original_full37_normal_writers_closed_independent_baseline_only',
        'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_COMPLETE_PRIVATE_SCOPE');
    $actualClosed = nhep_children_closed($children);
    nhep_expect($actualClosed === $close['closed_receipts'], 'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_NATIVE_RECEIPTS_STILL_COMPLETE');
    $groupView = static function (array $group): array {
        nhe_keys($group, ['leader_pid', 'pgid', 'sid', 'leader_starttime'], 'NHE_CLOSE_PUBLIC_GROUP_FIXED_FOUR_NATIVE_FIELDS');
        foreach (['leader_pid', 'pgid', 'sid'] as $key)
            nhep_expect(is_int($group[$key]) && $group[$key] > 1, 'NHE_CLOSE_PUBLIC_GROUP_NATIVE_PID');
        nhep_expect($group['leader_pid'] === $group['pgid'] && $group['pgid'] === $group['sid']
            && is_string($group['leader_starttime']) && ctype_digit($group['leader_starttime'])
            && $group['leader_starttime'] !== '', 'NHE_CLOSE_PUBLIC_ORIGINAL_SETSID_GROUP');
        return ['leader_pid' => $group['leader_pid'], 'pgid' => $group['pgid'], 'sid' => $group['sid'],
            'leader_starttime' => $group['leader_starttime']];
    };
    $terminalView = static function (array $terminal): array {
        nhe_keys($terminal, ['pid', 'running', 'signaled', 'stopped', 'exitcode', 'termsig', 'stopsig'],
            'NHE_CLOSE_PUBLIC_TERMINAL_FIXED_SEVEN_NATIVE_FIELDS');
        nhep_expect(is_int($terminal['pid']) && $terminal['pid'] > 1 && is_bool($terminal['running'])
            && is_bool($terminal['signaled']) && is_bool($terminal['stopped']) && is_int($terminal['exitcode'])
            && is_int($terminal['termsig']) && is_int($terminal['stopsig']), 'NHE_CLOSE_PUBLIC_TERMINAL_NATIVE_TYPES');
        return ['pid' => $terminal['pid'], 'running' => $terminal['running'], 'signaled' => $terminal['signaled'],
            'stopped' => $terminal['stopped'], 'exitcode' => $terminal['exitcode'],
            'termsig' => $terminal['termsig'], 'stopsig' => $terminal['stopsig']];
    };
    $views = [];
    foreach (['http', 'channel'] as $kind) {
        $receipt = $actualClosed[$kind]; $child = $children[$kind];
        nhe_keys($receipt, ['stopped', 'group', 'remaining_members', 'listener_open', 'first_terminal',
            'term_attempted', 'stop_signal', 'proc_close_exit', 'streams', 'waits'],
            'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_TEN_KEY_PRIVATE_RECEIPT');
        nhep_expect($receipt === $child['closed'] && $child['process'] === null && $receipt['stopped'] === true
            && $receipt['remaining_members'] === [] && $receipt['listener_open'] === false
            && is_bool($receipt['term_attempted']) && in_array($receipt['stop_signal'], [null, SIGTERM], true)
            && is_int($receipt['proc_close_exit']) && is_array($receipt['waits']) && array_is_list($receipt['waits']),
            'NHE_CLOSE_PUBLIC_VIEW_ACTUAL_COMPLETE_NATIVE_CLOSE_AND_UNALTERED_EXIT_FACTS');
        nhep_expect($receipt['first_terminal'] === $child['first_terminal']
            && $receipt['first_terminal']['running'] === false && $receipt['first_terminal']['termsig'] !== SIGKILL,
            'NHE_CLOSE_PUBLIC_VIEW_SAME_FIRST_NATIVE_TERMINAL_NO_ESCALATION');
        nhe_keys($receipt['streams'], ['stdout', 'stderr'], 'NHE_CLOSE_PUBLIC_VIEW_BOTH_ORIGINAL_PRIVATE_STREAMS');
        $streamViews = [];
        foreach (['stdout', 'stderr'] as $name) {
            $stream = $child['streams'][$name]; $raw = $close['private_native_streams'][$kind][$name];
            nhe_keys($receipt['streams'][$name], ['bytes', 'sha256'], 'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_PRIVATE_STREAM_DESCRIPTOR');
            nhe_keys($raw, ['path', 'stat', 'bytes', 'sha256', 'raw'], 'NHE_CLOSE_PUBLIC_VIEW_COMPLETE_PRIVATE_STREAM_READBACK');
            nhep_expect($stream['handle'] === null && $stream['complete'] === $receipt['streams'][$name]
                && is_string($raw['raw']) && $raw['bytes'] === strlen($raw['raw'])
                && $raw['sha256'] === hash('sha256', $raw['raw'])
                && $stream['complete'] === ['bytes' => $raw['bytes'], 'sha256' => $raw['sha256']]
                && ($close['files']['logs']['runtime']['legacy-' . $kind . '.' . $name] ?? null)
                    === ['kind' => 'file', 'stat' => $raw['stat'], 'bytes' => $raw['bytes'], 'sha256' => $raw['sha256']],
                'NHE_CLOSE_PUBLIC_VIEW_FULL_PRIVATE_BODY_AND_ORIGINAL_HANDLE_RECEIPT_VERIFIED_FIRST');
            foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
                nhep_expect($raw['stat'][$key] === $stream['created'][$key], 'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_CREATED_STREAM_IDENTITY');
            $streamViews[$name] = ['bytes' => $raw['bytes'], 'complete_verified' => true];
        }
        $waitViews = [];
        foreach ($receipt['waits'] as $wait) {
            nhe_keys($wait, ['pid', 'status'], 'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_WAIT_NATIVE_TWO_FIELDS');
            nhep_expect(is_int($wait['pid']) && $wait['pid'] > 1 && is_int($wait['status']),
                'NHE_CLOSE_PUBLIC_VIEW_ACTUAL_NATIVE_WAIT_TYPES');
            $waitViews[] = ['pid' => $wait['pid'], 'status' => $wait['status']];
        }
        $views[$kind] = ['stopped' => $receipt['stopped'], 'group' => $groupView($receipt['group']),
            'remaining_members' => $receipt['remaining_members'], 'listener_open' => $receipt['listener_open'],
            'first_terminal' => $terminalView($receipt['first_terminal']), 'term_attempted' => $receipt['term_attempted'],
            'stop_signal' => $receipt['stop_signal'], 'proc_close_exit' => $receipt['proc_close_exit'],
            'streams' => $streamViews, 'waits' => $waitViews];
    }
    $quiet = $close['no_extra_receipt'];
    nhe_keys($quiet, ['schema', 'scope', 'run_id', 'quiet_ns', 'started_ns', 'ended_ns', 'zero_returns',
        'http_closed', 'channel_before', 'channel_after', 'subscriber'], 'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_FULL_NO_EXTRA_KEYS');
    nhep_expect($quiet['schema'] === 1 && $quiet['scope'] === 'nonempty_history_original_channel_finite_no_extra'
        && $quiet['run_id'] === $qualified['context']['run_id'] && $quiet['quiet_ns'] === 10000000000
        && is_int($quiet['started_ns']) && is_int($quiet['ended_ns']) && $quiet['started_ns'] > 0
        && $quiet['ended_ns'] - $quiet['started_ns'] >= $quiet['quiet_ns']
        && is_int($quiet['zero_returns']) && $quiet['zero_returns'] > 0,
        'NHE_CLOSE_PUBLIC_VIEW_ACTUAL_ORIGINAL_FINITE_QUIET_WINDOW');
    $httpProof = $quiet['http_closed'];
    nhe_keys($httpProof, ['group', 'first_terminal', 'proc_close_exit', 'remaining_members', 'listener_open'],
        'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_NO_EXTRA_HTTP_PROOF_KEYS');
    nhep_expect($httpProof['group'] === $actualClosed['http']['group']
        && $httpProof['first_terminal'] === $actualClosed['http']['first_terminal']
        && $httpProof['proc_close_exit'] === $actualClosed['http']['proc_close_exit']
        && $httpProof['remaining_members'] === [] && $httpProof['listener_open'] === false,
        'NHE_CLOSE_PUBLIC_VIEW_SAME_ORIGINAL_HTTP_NATIVE_CLOSE_BEFORE_NO_EXTRA');
    $safeHttp = ['group' => $groupView($httpProof['group']), 'first_terminal' => $terminalView($httpProof['first_terminal']),
        'proc_close_exit' => $httpProof['proc_close_exit'], 'remaining_members' => [], 'listener_open' => false];
    $channelViews = [];
    foreach (['channel_before', 'channel_after'] as $key) {
        $proof = $quiet[$key];
        $members = [];
        foreach ($proof['members'] as $member) {
            $native = [];
            foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $field) {
                nhep_expect(array_key_exists($field, $member), 'NHE_CLOSE_PUBLIC_VIEW_REAL_NATIVE_MEMBER_FIELD');
                $native[$field] = $member[$field];
            }
            $members[] = $native;
        }
        $owners = array_values(array_unique(array_column($proof['listener']['owners'], 'pid'))); sort($owners, SORT_NUMERIC);
        nhep_expect($proof['group'] === $actualClosed['channel']['group'] && count($members) === 2
            && $proof['listener']['address'] === '127.0.0.1' && $proof['listener']['port'] === 40003,
            'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_CHANNEL_MASTER_WORKER_AND_LISTENER');
        $channelViews[$key] = ['native' => $terminalView($proof['native']), 'group' => $groupView($proof['group']),
            'members' => $members, 'listener' => ['address' => '127.0.0.1', 'port' => 40003,
                'inode' => $proof['listener']['inode'], 'owner_pids' => $owners]];
    }
    $subscriber = $quiet['subscriber'];
    nhe_keys($subscriber, ['socket_id', 'local_endpoint', 'remote_endpoint', 'metadata_before', 'metadata_after'],
        'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_NO_EXTRA_SUBSCRIBER_KEYS');
    $safeSubscriber = ['socket_id' => $subscriber['socket_id'], 'local_endpoint' => $subscriber['local_endpoint'],
        'remote_endpoint' => $subscriber['remote_endpoint']];
    foreach (['metadata_before', 'metadata_after'] as $key) {
        $meta = $subscriber[$key];
        nhe_keys($meta, ['unread_bytes', 'eof', 'blocked', 'timed_out'], 'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_SOCKET_METADATA_FOUR_FIELDS');
        nhep_expect($meta === ['unread_bytes' => 0, 'eof' => false, 'blocked' => false, 'timed_out' => false],
            'NHE_CLOSE_PUBLIC_VIEW_ORIGINAL_UNBUFFERED_NONBLOCKING_NONEOF_SOCKET');
        $safeSubscriber[$key] = $meta;
    }
    $safeQuiet = ['schema' => $quiet['schema'], 'scope' => $quiet['scope'], 'run_id' => $quiet['run_id'],
        'quiet_ns' => $quiet['quiet_ns'], 'started_ns' => $quiet['started_ns'], 'ended_ns' => $quiet['ended_ns'],
        'zero_returns' => $quiet['zero_returns'], 'http_closed' => $safeHttp,
        'channel_before' => $channelViews['channel_before'], 'channel_after' => $channelViews['channel_after'],
        'subscriber' => $safeSubscriber];
    nhep_observation_parent($qualified);
    return ['private_native_receipt_complete_verified' => true, 'children_views' => $views,
        'no_extra_view' => $safeQuiet, 'files_complete_verified' => true, 'only_parent_and_no_listeners_verified' => true];
}


/** Original full37 finish -> independent identities -> real normal close -> the adopted safe exact13. */
function nhep_normal_history_seal(#[SensitiveParameter] array $qualified, PDO $observer, Redis $redis,
    array &$children, array $http, #[SensitiveParameter] array $fixture, #[SensitiveParameter] Closure $finish): array
{
    $oldIgnoreArgs = ini_set('zend.exception_ignore_args', '1');
    nhep_expect($oldIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
        'NHE_NORMAL_SEAL_REAL_PRIVATE_ARGUMENT_BOUNDARY');
    nhep_observation_parent($qualified);
    $reflection = new ReflectionFunction($finish);
    nhep_expect(!$reflection->isInternal() && $reflection->getFileName() === __FILE__
        && $reflection->getNumberOfRequiredParameters() === 0 && $reflection->getNumberOfParameters() === 0,
        'NHE_NORMAL_SEAL_ORIGINAL_PRIVATE_FINISH_SAME_FROZEN_PRODUCER');
    $accepted37 = $finish(); nheh_snapshot($accepted37);
    $identities = nhep_history_identities(['database' => $accepted37['database'], 'rows' => $accepted37['rows']],
        $fixture, $http);
    nhep_expect($fixture['run_id'] === $qualified['context']['run_id'], 'NHE_NORMAL_SEAL_ACTUAL_ORIGINAL_RUN');
    $close = nhep_normal_close_writers($qualified, $observer, $redis, $children, $accepted37);
    $normalClose = nhep_normal_close_public_view($qualified, $children, $close);
    nhep_expect($close['expected_m4m'] === nhep_migration_snapshot_expected($close['database'], $close['redis']),
        'NHE_NORMAL_SEAL_SAME_ORIGINAL_INDEPENDENT_COMPLETE_BASELINE_BRIDGE');
    $createdPath = '/run/audit/evidence/audit-legacy-history-producer-container-created.json';
    $bindingPath = '/run/audit/evidence/audit-legacy-history-producer-source-binding.json';
    $created = ['path' => $createdPath, 'bytes' => strlen($qualified['created_raw']),
        'sha256' => hash('sha256', $qualified['created_raw'])];
    $binding = ['path' => $bindingPath, 'bytes' => strlen($qualified['binding_raw']),
        'sha256' => hash('sha256', $qualified['binding_raw'])];
    nhep_expect(nhe_file($createdPath, $created) === $qualified['created_raw']
        && nhe_file($bindingPath, $binding) === $qualified['binding_raw'],
        'NHE_NORMAL_SEAL_SAME_ORIGINAL_PUBLIC_CREATED_AND_SOURCE_BINDING');
    $parent = [];
    foreach (['pid', 'ppid', 'pgid', 'sid', 'starttime'] as $key) $parent[$key] = $qualified['process'][$key];
    $frames = [];
    // These four facts follow only the original whole37 finish and original full
    // native/frame/whole7 accept path above; there is no caller-provided ack/count.
    foreach ([13 => 'refund_family_pay', 19 => 'review_family_pay', 22 => 'unshipped_refund_apply',
        32 => 'customer_purchased_item_comment'] as $sequence => $step) {
        nhep_expect($http['http_steps'][$sequence - 1] === ['step' => $step, 'http' => 200],
            'NHE_NORMAL_SEAL_SAME_FOUR_ORIGINAL_COMPLETE_FRAME_ACCEPTANCE_SITES');
        $frames[] = ['sequence' => $sequence, 'step' => $step, 'complete_original_frame_verified' => true];
    }
    $seal = ['schema' => 1, 'status' => 'LEGACY_NORMAL_HISTORY_COMPLETE_ONLY',
        'run_id' => $qualified['context']['run_id'], 'source_sha' => $qualified['context']['source_sha'],
        'legacy_source_sha' => $qualified['authority']['legacy_source_sha'], 'freeze' => $qualified['freeze_pin'],
        'producer' => ['container_id' => $qualified['container_id'], 'created' => $created, 'source_binding' => $binding,
            'control_files' => $qualified['authority']['control_files'], 'native_parent' => $parent],
        'http' => $http, 'identities' => $identities, 'business_frames' => $frames, 'normal_close' => $normalClose,
        'expected_m4m' => $close['expected_m4m'], 'seal_redis_time' => $close['redis']['time']];
    nhe_keys($seal, ['schema', 'status', 'run_id', 'source_sha', 'legacy_source_sha', 'freeze', 'producer',
        'http', 'identities', 'business_frames', 'normal_close', 'expected_m4m', 'seal_redis_time'],
        'NHE_NORMAL_SEAL_ADOPTED_UNIQUE_EXACT_THIRTEEN_FIELDS');
    nhep_children_closed($children); nhep_parent_qualified($qualified); nhep_observation_parent($qualified);
    // All original accepted rows, values, private file/body hashes and original
    // receipts remain RAM; only the separately verified fixed safe view escapes.
    unset($accepted37, $close, $fixture); return $seal;
}

/** Create only the one fixed safe result; native same-handle full write/readback, no private inputs. */
function nhep_normal_history_publish(array $qualified, array $seal): array
{
    nhep_observation_parent($qualified);
    nhe_keys($seal, ['schema', 'status', 'run_id', 'source_sha', 'legacy_source_sha', 'freeze', 'producer',
        'http', 'identities', 'business_frames', 'normal_close', 'expected_m4m', 'seal_redis_time'],
        'NHE_NORMAL_PUBLISH_ONLY_ADOPTED_EXACT_THIRTEEN_FIELDS');
    nhep_expect($seal['schema'] === 1 && $seal['status'] === 'LEGACY_NORMAL_HISTORY_COMPLETE_ONLY'
        && $seal['run_id'] === $qualified['context']['run_id'] && $seal['source_sha'] === $qualified['context']['source_sha']
        && $seal['legacy_source_sha'] === $qualified['authority']['legacy_source_sha']
        && $seal['freeze'] === $qualified['freeze_pin'], 'NHE_NORMAL_PUBLISH_SAME_ACTUAL_FROZEN_SOURCE_RUN');
    $root = '/run/audit/evidence'; $path = $root . '/legacy-history-producer-result.json';
    clearstatcache(true, $root); $directory = lstat($root);
    nhep_expect(is_array($directory) && is_dir($root) && !is_link($root) && realpath($root) === $root
        && ($directory['mode'] & 07777) === 0700 && $directory['uid'] === posix_geteuid()
        && !file_exists($path) && !is_link($path), 'NHE_NORMAL_PUBLISH_CREATE_ONLY_ORIGINAL_PRIVATE_EVIDENCE_DIRECTORY');
    $raw = nhe_json($seal); $mask = umask(0077);
    try { $stream = fopen($path, 'x+b'); } finally { umask($mask); }
    nhep_expect(is_resource($stream), 'NHE_NORMAL_PUBLISH_ACTUAL_CREATE_ONLY_RESULT_HANDLE');
    $failure = null;
    try {
        $opened = fstat($stream); clearstatcache(true, $path); $named = lstat($path);
        nhep_expect(is_array($opened) && is_array($named) && !is_link($path) && realpath($path) === $path
            && ($opened['mode'] & 0170000) === 0100000 && ($opened['mode'] & 07777) === 0600
            && $opened['uid'] === posix_geteuid() && $opened['nlink'] === 1 && $opened['size'] === 0
            && $opened['dev'] === $directory['dev'], 'NHE_NORMAL_PUBLISH_ORIGINAL_OWN_REGULAR_SINGLE_LINK_RESULT');
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid', 'size', 'mtime', 'ctime'] as $key)
            nhep_expect($opened[$key] === $named[$key], 'NHE_NORMAL_PUBLISH_SAME_NAMED_AND_OPENED_NATIVE_STAT9');
        $offset = 0;
        while ($offset < strlen($raw)) {
            $written = fwrite($stream, substr($raw, $offset));
            nhep_expect(is_int($written) && $written > 0, 'NHE_NORMAL_PUBLISH_FULL_ACTUAL_SAFE_BYTES_WRITE');
            $offset += $written;
        }
        nhep_expect(fflush($stream) && fseek($stream, 0) === 0, 'NHE_NORMAL_PUBLISH_FLUSH_AND_SAME_HANDLE_REWIND');
        $readback = stream_get_contents($stream);
        nhep_expect(is_string($readback) && $readback === $raw && feof($stream),
            'NHE_NORMAL_PUBLISH_COMPLETE_SAFE_RESULT_SAME_HANDLE_READBACK_AND_EOF');
        $sealed = fstat($stream); clearstatcache(true, $path); $after = lstat($path);
        nhep_expect(is_array($sealed) && is_array($after) && $sealed['size'] === strlen($raw)
            && !is_link($path) && realpath($path) === $path, 'NHE_NORMAL_PUBLISH_COMPLETE_NATIVE_RESULT_SIZE');
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid'] as $key)
            nhep_expect($sealed[$key] === $opened[$key], 'NHE_NORMAL_PUBLISH_ORIGINAL_HANDLE_IDENTITY_PRESERVED');
        foreach (['dev', 'ino', 'mode', 'nlink', 'uid', 'gid', 'size', 'mtime', 'ctime'] as $key)
            nhep_expect($sealed[$key] === $after[$key], 'NHE_NORMAL_PUBLISH_FINAL_SAME_NATIVE_PATH_HANDLE_STAT9');
    } catch (Throwable $error) { $failure = $error; throw $error;
    } finally {
        try { nhep_expect(fclose($stream), 'NHE_NORMAL_PUBLISH_REAL_ORIGINAL_HANDLE_CLOSED');
        } catch (Throwable $closeError) { if ($failure === null) throw $closeError; }
    }
    $pin = ['path' => $path, 'bytes' => strlen($raw), 'sha256' => hash('sha256', $raw)];
    nhep_expect(nhe_file($path, $pin) === $raw, 'NHE_NORMAL_PUBLISH_COMPLETE_CLOSED_NAMED_RESULT_READBACK');
    return $pin;
}

/** Full fixed parent algorithm. Direct admission remains refused until all original Source gaps close. */
function nhep_normal_history_main(): int
{
    $children = []; $channel = null; $failure = null; $cleanup = [];
    try {
        ini_set('display_errors', '0'); ini_set('log_errors', '0');
        $oldIgnoreArgs = ini_set('zend.exception_ignore_args', '1'); umask(0077);
        nhep_expect($oldIgnoreArgs !== false && ini_get('zend.exception_ignore_args') === '1',
            'NHE_NORMAL_MAIN_REAL_PRIVATE_ARGUMENT_BOUNDARY');
        set_error_handler(static function (int $severity, string $message, string $file, int $line): never {
            throw new RuntimeException('NHE_NORMAL_MAIN_PHP_RUNTIME_WARNING');
        });
        nhep_expect(PHP_SAPI === 'cli' && PHP_INT_SIZE >= 8 && PHP_VERSION_ID >= 80200 && PHP_VERSION_ID < 80300
            && __FILE__ === '/run/nonempty/legacy-history-producer.php' && realpath(__FILE__) === __FILE__
            && realpath($_SERVER['SCRIPT_FILENAME'] ?? '') === __FILE__ && getcwd() === '/legacy-workspace/crmeb',
            'NHE_NORMAL_MAIN_ORIGINAL_REAL_DIRECT_ENTRY');
        global $argv; $arguments = $_SERVER['argv'] ?? null;
        nhep_expect(is_array($arguments) && $arguments === $argv && array_is_list($arguments) && count($arguments) === 4
            && $arguments[0] === __FILE__ && $arguments[1] === 'normal'
            && preg_match('/\A--freeze-bytes=([1-9][0-9]{0,9})\z/D', $arguments[2], $bytes) === 1
            && preg_match('/\A--freeze-sha256=([a-f0-9]{64})\z/D', $arguments[3], $sha) === 1,
            'NHE_NORMAL_MAIN_EXACT_ORIGINAL_NORMAL_AND_FREEZE_ARGUMENTS');
        // Named real Source gaps, before loading App, writing parent or connecting
        // resources. They are intentionally absent in this not-yet-admitted Source.
        foreach (['nhep_normal_startup_plan', 'nhep_normal_startup_accept'] as $dependency) {
            nhep_expect(function_exists($dependency), 'NHE_NORMAL_MAIN_COMPLETE_STARTUP_EFFECTS_SOURCE_UNBOUND');
            $reflection = new ReflectionFunction($dependency);
            nhep_expect(!$reflection->isInternal() && $reflection->getFileName() === __FILE__,
                'NHE_NORMAL_MAIN_STARTUP_ORACLE_SAME_FROZEN_PRODUCER_REQUIRED');
        }
        nhep_expect(spl_autoload_functions() === [] && !function_exists('app'), 'NHE_NORMAL_MAIN_NO_PRELOADED_VENDOR');
        foreach (get_declared_classes() as $class)
            nhep_expect(preg_match('/\A(?:app|think|crmeb|Channel|Workerman|Composer)\\\\/i', $class) !== 1
                && !str_starts_with($class, 'ComposerAutoloaderInit'), 'NHE_NORMAL_MAIN_NO_PRELOADED_APP_CLASS');
        require_once __DIR__ . '/legacy-app.php';
        $freeze = ['path' => '/run/audit/preparation-source-binding.json', 'bytes' => (int)$bytes[1], 'sha256' => $sha[1]];
        $qualified = nhe_qualify($freeze, 'audit-legacy-history-producer');
        nhep_parent_qualified($qualified); nhep_parent_write($qualified);
        $observer = audit_db(); $redis = audit_redis();
        $prepared = nhep_pre37_fixed_preparation($qualified, $observer, $redis);
        $startupPlan = nhep_normal_startup_plan($qualified, $prepared);
        nhep_child_start($qualified, $children, 'channel');
        $channel = nhep_channel_open($qualified, $children['channel']['observe']);
        nhep_child_subscriber($children, $channel);
        nhep_child_start($qualified, $children, 'http');
        $startupPrivate = []; $startupActual = nhep_observation($qualified, $observer, $redis, $children, $startupPrivate);
        $startupExpected = nhep_normal_startup_accept($qualified, $observer, $redis, $children, $prepared,
            $startupPlan, $startupActual, $startupPrivate);
        nheh_snapshot($startupExpected);
        nhep_expect($startupActual === $startupExpected, 'NHE_NORMAL_MAIN_COMPLETE_INDEPENDENT_STARTUP_SEVEN_PARTS');
        $oracles = nhep_auth_observers($qualified, $observer, $redis, $children);
        nhe_keys($oracles, ['before', 'after', 'finish'], 'NHE_NORMAL_MAIN_ORIGINAL_WHOLE37_THREE_CLOSURES');
        $http = nhe_history_http_run($qualified, $prepared['origin'], $qualified['context']['run_id'],
            $prepared['actors'], $prepared['fixture_receipt'], $oracles['before'], $oracles['after']);
        $seal = nhep_normal_history_seal($qualified, $observer, $redis, $children, $http,
            $prepared['fixture_receipt'], $oracles['finish']);
        nhep_normal_history_publish($qualified, $seal);
        unset($prepared, $startupPlan, $startupPrivate, $startupActual, $startupExpected, $oracles, $channel);
    } catch (Throwable $error) { $failure = $error;
    } finally {
        // A cleanup failure never replaces the first business failure. These are
        // the same original normal calls/handles, with no restart/force/escalation.
        if ($failure !== null) {
            if (isset($children['http'])) {
                try { $receipt = nhep_child_close($children, 'http'); $cleanup['http_stopped'] = $receipt['stopped'] === true;
                } catch (Throwable $error) { $cleanup['http_stopped'] = false; }
            }
            if (is_array($channel) && ($channel['closed'] ?? null) === false) {
                try { nhep_channel_close($channel); $cleanup['same_subscriber_closed'] = true;
                } catch (Throwable $error) { $cleanup['same_subscriber_closed'] = false; }
            }
            if (isset($children['channel'])) {
                try { $receipt = nhep_child_close($children, 'channel'); $cleanup['channel_stopped'] = $receipt['stopped'] === true;
                } catch (Throwable $error) { $cleanup['channel_stopped'] = false; }
            }
        }
    }
    if ($failure !== null) {
        $code = $failure instanceof RuntimeException ? $failure->getMessage() : '';
        if (preg_match('/\A(?:NHE|NHEH)_[A-Z0-9_]+\z/D', $code) !== 1) $code = 'NHE_NORMAL_MAIN_ORIGINAL_HISTORY_FAILED';
        $class = get_class($failure);
        if (preg_match('/\A(?:[A-Za-z_][A-Za-z0-9_]*\\\\)*[A-Za-z_][A-Za-z0-9_]*\z/D', $class) !== 1) $class = 'Throwable';
        fwrite(STDERR, json_encode(['status' => 'FAIL', 'code' => $code, 'class' => $class,
            'normal_cleanup' => $cleanup], JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . "\n");
        return 1;
    }
    return 0;
}


if (realpath($_SERVER['SCRIPT_FILENAME'] ?? '') === __FILE__) {
    fwrite(STDERR, "{\"status\":\"FAIL\",\"code\":\"NHE_PRODUCER_NOT_IMPLEMENTED\"}\n");
    exit(1);
}
